  ds74469_modules_builtin="${ds74469_root}lib/modules/${ds74469_kernel}/modules.builtin"
  if [ -z "$ds74469_sctp_state" ] \
    && grep -Eq '(^|/)sctp\.ko(\.(gz|xz|zst))?:' "$ds74469_modules_dep" 2>/dev/null; then
