    if [ "$CF31_MAJ" -eq 6 ]; then
        case "$CF31_MIN" in
            19) [ "$CF31_PAT" -ge 12 ] && return 0 ;;
            18) [ "$CF31_PAT" -ge 22 ] && return 0 ;;
            12) [ "$CF31_PAT" -ge 85 ] && return 0 ;;
            6) [ "$CF31_PAT" -ge 137 ] && return 0 ;;
            1) [ "$CF31_PAT" -ge 170 ] && return 0 ;;
