  if printf '%s' "$ab20938_kernel" | grep -Eq '^5\.(4|10)\.[0-9]+-android[0-9]+-[0-9]+([.-].*)?$' \
    || printf '%s' "$ab20938_kernel" | grep -Eqi '(^|[.-])gki([.-]|$)'; then
    ab20938_gki="detected"
  fi
  echo "GKI evidence: $ab20938_gki"
  ab20938_devices=""
  ab20938_rw_devices=""
