        runc_version=$(runc --version 2>/dev/null | grep -i "version" | grep -Eo "[0-9]+\.[0-9]+\.[0-9]+")
        if [ "$runc_version" ]; then
            print_list "Runc CVE-2019-5736 ........... "$NC
            if [ "$(echo $runc_version | awk -F. '{ if ($1 < 1 || ($1 == 1 && $2 < 0) || ($1 == 1 && $2 == 0 && $3 < 7)) print "Yes"; else print "No"; }')" = "Yes" ]; then
                echo "Yes - Vulnerable" | sed -${E} "s,Yes,${SED_RED},"
            else
                echo "No"
            fi
        fi
    fi
    if [ "$(command -v containerd || echo -n '')" ]; then
        print_list "Containerd version ........... "$NC
        warn_exec containerd --version
        # Check for specific containerd vulnerabilities
        containerd_version=$(containerd --version 2>/dev/null | grep -Eo "[0-9]+\.[0-9]+\.[0-9]+")
        if [ "$containerd_version" ]; then
            print_list "Containerd CVE-2020-15257 ..... "$NC
            if [ "$(echo $containerd_version | awk -F. '{ if ($1 < 1 || ($1 == 1 && $2 < 4) || ($1 == 1 && $2 == 4 && $3 < 3)) print "Yes"; else print "No"; }')" = "Yes" ]; then
                echo "Yes - Vulnerable" | sed -${E} "s,Yes,${SED_RED},"
            else
                echo "No"
            fi
        fi
    fi
    # Mount, procfs and sysfs escape surfaces
    print_3title "Mount, procfs & sysfs surfaces" "T1611"
    print_info "https://book.hacktricks.wiki/en/linux-hardening/containers-namespaces/container-security/sensitive-host-mounts.html"
    checkProcSysBreakouts
    root_mount_mode="$(awk '$5=="/"{print $6; exit}' /proc/self/mountinfo 2>/dev/null | cut -d',' -f1)"
    print_list "/proc heavily populated ........ $proc_mounted\n" | sed -${E} "s,Yes,${SED_RED_YELLOW},"
    print_list "/dev heavily populated ......... $dev_mounted\n" | sed -${E} "s,Yes,${SED_RED_YELLOW},"
    print_list "Root filesystem mode ........... ${root_mount_mode:-unknown}\n" | sed -${E} "s,rw,${SED_RED_YELLOW}," | sed -${E} "s,ro,${SED_GREEN},"
    print_list "Run unshare .................... $run_unshare\n" | sed -${E} "s,Yes,${SED_RED},"
    print_list "release_agent surface 1 ........ $release_agent_breakout1\n" | sed -${E} "s,Yes,${SED_RED},"
    print_list "release_agent surface 2 ........ $release_agent_breakout2\n" | sed -${E} "s,Yes,${SED_RED_YELLOW},"
    print_list "release_agent surface 3 ........ $release_agent_breakout3\n" | sed -${E} "s,Yes,${SED_RED_YELLOW},"
    print_list "Writable core_pattern .......... $core_pattern_breakout\n" | sed -${E} "s,Yes,${SED_RED_YELLOW},"
    print_list "Writable binfmt_misc/register .. $binfmt_misc_breakout\n" | sed -${E} "s,Yes,${SED_RED_YELLOW},"
    print_list "Writable uevent_helper ......... $uevent_helper_breakout\n" | sed -${E} "s,Yes,${SED_RED_YELLOW},"
    # Additional mount checks
    print_list "Mounted runtime sockets ........ "$NC
    (mount | grep -E "docker.sock|containerd.sock|crio.sock|podman.sock|buildkitd.sock|kubelet.sock|firecracker-containerd.sock" || echo "No") | sed -${E} "s,docker.sock|containerd.sock|crio.sock|podman.sock|buildkitd.sock|kubelet.sock|firecracker-containerd.sock,${SED_RED},g"
    print_list "Common host filesystem mounted?  "$NC
    (mount | grep -E "host|/host|/mnt/host|/rootfs" || echo "No") | sed -${E} "s,host|/host|/mnt/host|/rootfs,${SED_RED},g"
    print_list "Interesting mounts ............. "$NC
    mount | grep -E "docker|container|overlay|kubelet|buildkit|crio|podman|/host|/rootfs" | grep -v "proc" | sed -${E} "s,docker.sock|containerd.sock|crio.sock|podman.sock|kubelet.sock|buildkitd.sock|host|rootfs|privileged,${SED_RED},g"
    # Check for writable mount points
    print_list "Writable mount points ......... "$NC
    mount | grep -E "rw," | grep -v "ro," | sed -${E} "s,docker.sock|host|privileged,${SED_RED},g"
    # Check for shared mount points
    print_list "Shared mount points ........... "$NC
    mount | grep -E "shared|slave" | sed -${E} "s,docker.sock|host|privileged,${SED_RED},g"
    # Capability checks
    print_3title "Capability Checks" "T1611"
    print_info "https://book.hacktricks.wiki/en/linux-hardening/containers-namespaces/container-security/protections/capabilities.html"
    print_list "Dangerous capabilities ......... "$NC
    if [ "$(command -v capsh || echo -n '')" ]; then 
        capsh --print 2>/dev/null | sed -${E} "s,$containercapsB,${SED_RED},g"
    else
        defautl_docker_caps="00000000a80425fb=cap_chown,cap_dac_override,cap_fowner,cap_fsetid,cap_kill,cap_setgid,cap_setuid,cap_setpcap,cap_net_bind_service,cap_net_raw,cap_sys_chroot,cap_mknod,cap_audit_write,cap_setfcap"
        cat /proc/self/status | tr '\t' ' ' | grep Cap | sed -${E} "s, .*,${SED_RED},g" | sed -${E} "s/00000000a80425fb/$defautl_docker_caps/g" | sed -${E} "s,0000000000000000|00000000a80425fb,${SED_GREEN},g"
        echo $ITALIC"Run capsh --decode=<hex> to decode the capabilities"$NC
    fi
    print_list "Ambient capabilities ........... "$NC
    (grep "CapAmb:" /proc/self/status 2>/dev/null | grep -v "0000000000000000" | sed "s,CapAmb:.,," || echo "No") | sed -${E} "s,No,${SED_GREEN}," | sed -${E} "s,[0-9a-fA-F]\+,${SED_RED}&,"
    # Additional capability checks
    print_list "ptrace_scope (host) ........... "$NC
    if [ -f "/proc/sys/kernel/yama/ptrace_scope" ]; then
        (cat /proc/sys/kernel/yama/ptrace_scope 2>/dev/null || echo "Not found") | sed -${E} "s,0,${SED_RED},"
    else
        echo "Not found"
    fi
    # Namespace checks. From inside a container we often cannot prove host namespace sharing directly,
    # so prefer raw namespace handles and practical indicators over misleading "host namespace = yes/no" guesses.
    print_3title "Namespaces & sharing indicators" "T1611"
    print_info "https://book.hacktricks.wiki/en/linux-hardening/containers-namespaces/container-security/protections/namespaces/index.html"
    print_list "Current namespaces ............. "$NC
    ls -l /proc/self/ns/
    if ps -e -o pid= >/dev/null 2>&1; then
        host_process_count="$(ps -e -o pid= 2>/dev/null | wc -l | tr -d ' ')"
        host_process_indicators="$(ps -eo comm= 2>/dev/null | grep -E '^(systemd|init|kthreadd|dockerd|containerd|kubelet|sshd|udevd|NetworkManager|dbus-daemon)$' | sort -u)"
    else
        host_process_count="$(ls -d /proc/[0-9]* 2>/dev/null | wc -l | tr -d ' ')"
        host_process_indicators="$(for proc_comm in /proc/[0-9]*/comm; do cat "$proc_comm" 2>/dev/null; done | grep -E '^(systemd|init|kthreadd|dockerd|containerd|kubelet|sshd|udevd|NetworkManager|dbus-daemon)$' | sort -u)"
    fi
    print_list "Processes visible .............. $host_process_count\n" | sed -${E} "s,^[^0-9]*([5-9][0-9]|[1-9][0-9]{2,}).*,${SED_RED_YELLOW}&,"
    print_list "Host-like processes visible .... "$NC
    if [ "$host_process_indicators" ]; then
        printf "%s\n" "$host_process_indicators" | sed -${E} "s,.*,${SED_RED_YELLOW}&,"
    else
        echo "No obvious host daemons"
    fi
    print_list "Network interfaces ............. "$NC
    if command -v ip >/dev/null 2>&1; then
        ip -o link show 2>/dev/null | awk -F': ' '{print $2}'
    else
        ls /sys/class/net 2>/dev/null
    fi
    print_list "Namespace inode summary ........ "$NC
    for ns in cgroup ipc mnt net pid time user uts; do
        if [ -L "/proc/self/ns/$ns" ]; then
            printf "%s -> %s\n" "$ns" "$(readlink "/proc/self/ns/$ns" 2>/dev/null)"
        fi
    done
    print_list "Looking and enumerating runtime sockets:\n"$NC
    enumerateDockerSockets
    # Additional breakout vectors
    print_3title "Writable kernel helper paths" "T1611"
    print_list "modprobe helper binary ......... $modprobe_binary\n" | sed -${E} "s,/.*,${SED_RED},"
    print_list "modprobe path writable ......... $modprobe_config_writable\n" | sed -${E} "s,Yes,${SED_RED},"
    print_list "panic_on_oom writable .......... $panic_on_oom_dos\n" | sed -${E} "s,Yes,${SED_RED},"
    print_list "suid_dumpable writable ......... $panic_sys_fs_dos\n" | sed -${E} "s,Yes,${SED_RED},"
    print_list "DoS via sysreq_trigger_dos ..... $sysreq_trigger_dos\n" | sed -${E} "s,Yes,${SED_RED},"
    print_3title "Sensitive procfs/sysfs exposure" "T1611"
    print_list "/proc/config.gz readable ....... $proc_configgz_readable\n" | sed -${E} "s,Yes,${SED_RED},"
    print_list "/proc/sched_debug readable ..... $sched_debug_readable\n" | sed -${E} "s,Yes,${SED_RED},"
    print_list "/proc/*/mountinfo readable ..... $mountinfo_readable\n" | sed -${E} "s,Yes,${SED_RED},"
    print_list "/proc/keys readable ............ $proc_keys_readable\n" | sed -${E} "s,Yes,${SED_RED},"
    print_list "/proc/timer_list readable ...... $proc_timer_list_readable\n" | sed -${E} "s,Yes,${SED_RED},"
    print_list "/proc/kmsg readable ............ $kmsg_readable\n" | sed -${E} "s,Yes,${SED_RED},"
    print_list "/proc/kallsyms readable ........ $kallsyms_readable\n" | sed -${E} "s,Yes,${SED_RED},"
    print_list "/proc/self/mem readable ........ $self_mem_readable\n" | sed -${E} "s,Yes,${SED_RED},"
    print_list "/proc/kcore readable ........... $kcore_readable\n" | sed -${E} "s,Yes,${SED_RED},"
    print_list "/proc/kmem readable ............ $kmem_readable\n" | sed -${E} "s,Yes,${SED_RED},"
    print_list "/proc/kmem writable ............ $kmem_writable\n" | sed -${E} "s,Yes,${SED_RED},"
    print_list "/proc/mem readable ............. $mem_readable\n" | sed -${E} "s,Yes,${SED_RED},"
    print_list "/proc/mem writable ............. $mem_writable\n" | sed -${E} "s,Yes,${SED_RED},"
    print_list "/sys/firmware readable ......... $sys_firmware_readable\n" | sed -${E} "s,Yes,${SED_RED},"
    print_list "/sys/kernel/debug present ...... $debugfs_present\n" | sed -${E} "s,Yes,${SED_RED},"
    print_list "/sys/kernel/debug readable ..... $debugfs_readable\n" | sed -${E} "s,Yes,${SED_RED},"
    print_list "/sys/class/thermal present ..... $thermal_present\n" | sed -${E} "s,Yes,${SED_RED_YELLOW},"
    print_list "/sys/class/thermal readable .... $thermal_readable\n" | sed -${E} "s,Yes,${SED_RED_YELLOW},"
    print_list "/sys/kernel/security present ... $security_present\n" | sed -${E} "s,Yes,${SED_RED},"
    print_list "/sys/kernel/security writable .. $security_writable\n" | sed -${E} "s,Yes,${SED_RED},"
    print_list "/sys/kernel/vmcoreinfo readable  $vmcoreinfo_readable\n" | sed -${E} "s,Yes,${SED_RED},"
    print_list "/sys/firmware/efi/vars writable  $efi_vars_writable\n" | sed -${E} "s,Yes,${SED_RED},"
    print_list "/sys/firmware/efi/efivars writable $efi_efivars_writable\n" | sed -${E} "s,Yes,${SED_RED},"
    # Additional kernel checks
    print_list "Kernel version .............. "$NC
    uname -a | sed -${E} "s,$(uname -r),${SED_RED},"
    print_list "Kernel modules ............. "$NC
    if command -v lsmod >/dev/null 2>&1; then
        lsmod | grep -E "overlay|aufs|btrfs|device_mapper|floppy|loop|squashfs|udf|veth|vbox|vmware|kvm|xen|docker|containerd|runc|crio" | sed -${E} "s,overlay|aufs|btrfs|device_mapper|floppy|loop|squashfs|udf|veth|vbox|vmware|kvm|xen|docker|containerd|runc|crio,${SED_RED},g"
    elif [ -r /proc/modules ]; then
        cat /proc/modules | grep -E "overlay|aufs|btrfs|device_mapper|floppy|loop|squashfs|udf|veth|vbox|vmware|kvm|xen|docker|containerd|runc|crio" | sed -${E} "s,overlay|aufs|btrfs|device_mapper|floppy|loop|squashfs|udf|veth|vbox|vmware|kvm|xen|docker|containerd|runc|crio,${SED_RED},g"
    else
        echo_not_found "lsmod and /proc/modules"
    fi
    # Additional container runtime checks
    print_list "Container runtime sockets .. "$NC
    (find /var/run /run -name "*.sock" 2>/dev/null | grep -E "docker|containerd|crio|podman|lxc|rkt|kubelet|buildkit|firecracker" || echo "No") | sed -${E} "s,docker|containerd|crio|podman|lxc|rkt|kubelet|buildkit|firecracker,${SED_RED},g"
    print_list "Container runtime configs .. "$NC
    (find /etc -name "*.conf" -o -name "*.json" 2>/dev/null | grep -E "docker|containerd|crio|podman|lxc|rkt|kubelet|buildkit|firecracker" || echo "No") | sed -${E} "s,docker|containerd|crio|podman|lxc|rkt|kubelet|buildkit|firecracker,${SED_RED},g"
    # Kubernetes-specific checks. API requests are opt-in (-a/-e), read-only,
    # short-lived, and never print the projected bearer token.
    if echo "$containerType" | grep -qi "kubernetes"; then
        print_3title "Kubernetes container escape checks" "T1611"
        print_info "https://cloud.hacktricks.wiki/en/pentesting-cloud/kubernetes-security/attacking-kubernetes-from-inside-a-pod.html"
        k8s_sa_dir=""
        for k8s_sa_dir in /var/run/secrets/kubernetes.io/serviceaccount /run/secrets/kubernetes.io/serviceaccount /secrets/kubernetes.io/serviceaccount; do
            if [ -r "$k8s_sa_dir/token" ]; then break; fi
        done
        k8s_sa_token="$k8s_sa_dir/token"
        k8s_sa_ca="$k8s_sa_dir/ca.crt"
        k8s_namespace="$(cat "$k8s_sa_dir/namespace" 2>/dev/null)"
        k8s_pod_name=""
        k8s_service_account=""
        # Bound service-account tokens contain pod and service-account names in
        # their local JWT payload. Decode only the payload and never display it.
        if [ -r "$k8s_sa_token" ] && command -v base64 >/dev/null 2>&1; then
            k8s_token_payload_b64="$(cut -d. -f2 < "$k8s_sa_token" 2>/dev/null | tr '_-' '/+')"
            case $((${#k8s_token_payload_b64} % 4)) in
                2) k8s_token_payload_b64="${k8s_token_payload_b64}==" ;;
                3) k8s_token_payload_b64="${k8s_token_payload_b64}=" ;;
            esac
            k8s_token_payload="$(printf "%s" "$k8s_token_payload_b64" | base64 -d 2>/dev/null)"
            k8s_pod_name="$(printf "%s" "$k8s_token_payload" | grep -o '"pod"[[:space:]]*:[[:space:]]*{[^}]*}' | sed -n 's/.*"name"[[:space:]]*:[[:space:]]*"\([^"]*\)".*/\1/p' | head -n 1)"
            k8s_service_account="$(printf "%s" "$k8s_token_payload" | grep -o '"serviceaccount"[[:space:]]*:[[:space:]]*{[^}]*}' | sed -n 's/.*"name"[[:space:]]*:[[:space:]]*"\([^"]*\)".*/\1/p' | head -n 1)"
            if [ -z "$k8s_service_account" ]; then
                k8s_service_account="$(printf "%s" "$k8s_token_payload" | sed -n 's/.*"sub"[[:space:]]*:[[:space:]]*"system:serviceaccount:[^:"]*:\([^"]*\)".*/\1/p')"
            fi
            k8s_token_payload=""
            k8s_token_payload_b64=""
        fi
        if [ -z "$k8s_pod_name" ]; then k8s_pod_name="$(hostname 2>/dev/null)"; fi
        print_list "Namespace ...................... ${k8s_namespace:-unknown}\n"
        print_list "Pod name ....................... ${k8s_pod_name:-unknown}\n"
        if [ -r "$k8s_sa_token" ]; then
            print_list "Projected API token ............ present and readable (contents suppressed)\n" | sed -${E} "s,present and readable,${SED_RED_YELLOW},"
        else
            print_list "Projected API token ............ not readable\n" | sed -${E} "s,not readable,${SED_GREEN},"
        fi
        if [ -r "$k8s_sa_ca" ]; then
            print_list "Projected cluster CA ........... present and readable\n"
        else
            print_list "Projected cluster CA ........... not readable\n"
        fi
        k8s_api_host="${KUBERNETES_SERVICE_HOST:-}"
        case "$k8s_api_host" in *:*) k8s_api_host="[$k8s_api_host]" ;; esac
        if [ "$k8s_api_host" ]; then
            k8s_api_base="https://${k8s_api_host}:${KUBERNETES_SERVICE_PORT_HTTPS:-443}"
            print_list "Cluster API endpoint ........... $k8s_api_base\n"
        else
            k8s_api_base=""
            print_list "Cluster API endpoint ........... unknown\n"
        fi
        k8s_host_mounts="$(awk '$4=="/" && ($5=="/host" || $5=="/rootfs" || $5=="/mnt/host") {print $5 " (" $6 ")"}' /proc/self/mountinfo 2>/dev/null)"
        print_list "Possible host-root mounts ...... "$NC
        if [ "$k8s_host_mounts" ]; then
            printf "%s\n" "$k8s_host_mounts" | sed -${E} "s,.*,${SED_RED}&,"
        else
            echo "None at common mount points"
        fi
        k8s_can_create_pods="Unknown"
        k8s_can_exec_pods="Unknown"
        k8s_can_list_pods="Unknown"
        k8s_can_proxy_nodes="Unknown"
        k8s_can_read_secrets="Unknown"
        k8s_can_request_tokens="Unknown"
        k8s_pod_risks=""
        k8s_chain_risk=""
        if [ "$dev_mounted" = "Yes" ]; then k8s_pod_risks="${k8s_pod_risks}hostDevices "; fi
        if command -v capsh >/dev/null 2>&1 && capsh --print 2>/dev/null | grep '^Current:' | grep -qw 'cap_sys_admin'; then
            k8s_pod_risks="${k8s_pod_risks}CAP_SYS_ADMIN "
        fi
        if [ "$EXTRA_CHECKS" ] && command -v curl >/dev/null 2>&1 && [ -r "$k8s_sa_token" ] && [ -r "$k8s_sa_ca" ] && [ "$k8s_api_base" ] && [ "$k8s_namespace" ]; then
            k8s_api_curl() {
                printf 'header = "Authorization: Bearer %s"\n' "$(tr -d '\r\n' < "$k8s_sa_token")" |
                    curl -sS --connect-timeout 1 --max-time 3 --cacert "$k8s_sa_ca" --config - "$@" 2>/dev/null
            }
            k8s_rules_allow() {
                printf "%s\n" "$k8s_ssrr_rules" |
                    grep -E "\"resources\"[[:space:]]*:[[:space:]]*\[[^]]*\"($1|\\*)\"([[:space:]]*,|[[:space:]]*\])" |
                    grep -E '"apiGroups"[[:space:]]*:[[:space:]]*\[[^]]*"(\*)?"' |
                    grep -E "\"verbs\"[[:space:]]*:[[:space:]]*\[[^]]*\"($2)\"" >/dev/null 2>&1
            }
            # SelfSubjectRulesReview evaluates permissions without creating,
            # modifying, or requesting any workload or credential.
            k8s_ssrr_request="{\"apiVersion\":\"authorization.k8s.io/v1\",\"kind\":\"SelfSubjectRulesReview\",\"spec\":{\"namespace\":\"$k8s_namespace\"}}"
            k8s_ssrr_response="$(k8s_api_curl -X POST -H 'Content-Type: application/json' --data "$k8s_ssrr_request" "$k8s_api_base/apis/authorization.k8s.io/v1/selfsubjectrulesreviews")"
            if printf "%s" "$k8s_ssrr_response" | grep -q '"resourceRules"[[:space:]]*:'; then
                # ResourceRule JSON objects begin with "verbs" in Kubernetes'
                # response. Split them before matching so verbs from one rule
                # cannot be combined with resources from another rule.
                k8s_ssrr_rules="$(printf "%s" "$k8s_ssrr_response" | tr '\n' ' ' | sed -${E} 's/}[[:space:]]*,[[:space:]]*\{[[:space:]]*"verbs"/}|{"verbs"/g' | tr '|' '\n')"
                if k8s_rules_allow "pods" 'create|\*'; then k8s_can_create_pods="Yes"; else k8s_can_create_pods="No"; fi
                if k8s_rules_allow "pods/(exec|\\*)" 'create|\*'; then k8s_can_exec_pods="Yes"; else k8s_can_exec_pods="No"; fi
                if k8s_rules_allow "pods" 'list|\*'; then k8s_can_list_pods="Yes"; else k8s_can_list_pods="No"; fi
                if k8s_rules_allow "nodes/(proxy|\\*)" 'get|\*'; then k8s_can_proxy_nodes="Yes"; else k8s_can_proxy_nodes="No"; fi
                if k8s_rules_allow "secrets" 'get|list|watch|\*'; then k8s_can_read_secrets="Yes"; else k8s_can_read_secrets="No"; fi
                if k8s_rules_allow "serviceaccounts/token" 'create|\*'; then k8s_can_request_tokens="Yes"; else k8s_can_request_tokens="No"; fi
            fi
            # Fetch only this pod to inspect the submitted security context.
            if [ "$k8s_pod_name" ]; then
                k8s_pod_json="$(k8s_api_curl "$k8s_api_base/api/v1/namespaces/$k8s_namespace/pods/$k8s_pod_name")"
                if printf "%s" "$k8s_pod_json" | grep -q '"kind"[[:space:]]*:[[:space:]]*"Pod"'; then
                    if [ -z "$k8s_service_account" ]; then
                        k8s_service_account="$(printf "%s" "$k8s_pod_json" | sed -n 's/.*"serviceAccountName"[[:space:]]*:[[:space:]]*"\([^"]*\)".*/\1/p')"
                    fi
                    if printf "%s" "$k8s_pod_json" | grep -Eq '"hostPID"[[:space:]]*:[[:space:]]*true'; then k8s_pod_risks="${k8s_pod_risks}hostPID "; fi
                    if printf "%s" "$k8s_pod_json" | grep -Eq '"hostIPC"[[:space:]]*:[[:space:]]*true'; then k8s_pod_risks="${k8s_pod_risks}hostIPC "; fi
                    if printf "%s" "$k8s_pod_json" | grep -Eq '"hostNetwork"[[:space:]]*:[[:space:]]*true'; then k8s_pod_risks="${k8s_pod_risks}hostNetwork "; fi
                    if printf "%s" "$k8s_pod_json" | grep -Eq '"privileged"[[:space:]]*:[[:space:]]*true'; then k8s_pod_risks="${k8s_pod_risks}privileged "; fi
                    if printf "%s" "$k8s_pod_json" | grep -Eq '"allowPrivilegeEscalation"[[:space:]]*:[[:space:]]*true'; then k8s_pod_risks="${k8s_pod_risks}allowPrivilegeEscalation "; fi
                    if printf "%s" "$k8s_pod_json" | grep -Eq '"add"[[:space:]]*:[[:space:]]*\[[^]]*"SYS_ADMIN"' && ! printf "%s" "$k8s_pod_risks" | grep -q 'CAP_SYS_ADMIN'; then k8s_pod_risks="${k8s_pod_risks}CAP_SYS_ADMIN "; fi
                    if printf "%s" "$k8s_pod_json" | grep -Eq '"hostPath"[[:space:]]*:[[:space:]]*\{[^}]*"path"[[:space:]]*:[[:space:]]*"/"'; then
                        k8s_pod_risks="${k8s_pod_risks}hostPath:/ "
                    elif printf "%s" "$k8s_pod_json" | grep -Eq '"hostPath"[[:space:]]*:[[:space:]]*\{[^}]*"path"[[:space:]]*:[[:space:]]*"/(etc|proc|sys|dev|var/run|var/lib/kubelet)(/|\")'; then
                        k8s_pod_risks="${k8s_pod_risks}sensitiveHostPath "
                    elif printf "%s" "$k8s_pod_json" | grep -Eq '"hostPath"[[:space:]]*:[[:space:]]*\{'; then
                        k8s_pod_risks="${k8s_pod_risks}hostPath "
                    fi
                fi
            fi
        else
            print_list "API permission/pod checks ...... skipped (use -a or -e; requires curl, token and CA)\n"
        fi
        print_list "Service account ................ ${k8s_service_account:-unknown}\n"
        print_list "RBAC create pods ............... $k8s_can_create_pods\n" | sed -${E} "s,Yes,${SED_RED_YELLOW}," | sed -${E} "s,No,${SED_GREEN},"
        print_list "RBAC create pods/exec .......... $k8s_can_exec_pods\n" | sed -${E} "s,Yes,${SED_RED_YELLOW}," | sed -${E} "s,No,${SED_GREEN},"
        print_list "RBAC list pods ................. $k8s_can_list_pods\n" | sed -${E} "s,Yes,${SED_RED_YELLOW}," | sed -${E} "s,No,${SED_GREEN},"
        print_list "RBAC get nodes/proxy ........... $k8s_can_proxy_nodes\n" | sed -${E} "s,Yes,${SED_RED_YELLOW}," | sed -${E} "s,No,${SED_GREEN},"
        print_list "RBAC read secrets .............. $k8s_can_read_secrets\n" | sed -${E} "s,Yes,${SED_RED_YELLOW}," | sed -${E} "s,No,${SED_GREEN},"
        print_list "RBAC create serviceaccounts/token $k8s_can_request_tokens\n" | sed -${E} "s,Yes,${SED_RED_YELLOW}," | sed -${E} "s,No,${SED_GREEN},"
        print_list "Current pod escape settings .... "$NC
        if [ "$k8s_pod_risks" ]; then
            printf "%s\n" "$k8s_pod_risks" | sed -${E} "s,.*,${SED_RED}&,"
        else
            echo "None found or pod object is not readable"
        fi
        if { [ "$k8s_pod_risks" ] || [ "$k8s_host_mounts" ]; } && { [ "$k8s_can_create_pods" = "Yes" ] || [ "$k8s_can_exec_pods" = "Yes" ]; }; then
            k8s_chain_risk="HIGH - dangerous pod/host exposure combined with workload-control RBAC"
        elif [ "$k8s_can_create_pods" = "Yes" ] && { [ "$k8s_can_exec_pods" = "Yes" ] || [ "$k8s_can_read_secrets" = "Yes" ] || [ "$k8s_can_request_tokens" = "Yes" ]; }; then
            k8s_chain_risk="Dangerous RBAC chain; admission controls still determine privileged-pod creation"
        fi
        if [ "$k8s_chain_risk" ]; then
            print_list "Kubernetes escape chain ........ $k8s_chain_risk\n" | sed -${E} "s,.*,${SED_RED_YELLOW},"
        fi
    fi
    # Interesting files and mounts
    print_3title "Interesting Files & Mounts" "T1611"
    print_list "Interesting files mounted ........ "$NC
    (mount -l || cat /proc/self/mountinfo || cat /proc/1/mountinfo || cat /proc/mounts || cat /proc/self/mounts || cat /proc/1/mounts )2>/dev/null | grep -Ev "$GREP_IGNORE_MOUNTS" | sed -${E} "s,.sock,${SED_RED}," | sed -${E} "s,docker.sock,${SED_RED_YELLOW}," | sed -${E} "s,/dev/,${SED_RED},g"
    print_list "Possible entrypoints ........... "$NC
    ls -lah /*.sh /*entrypoint* /**/entrypoint* /**/*.sh /deploy* 2>/dev/null | sort | uniq
    echo ""
fi

fi

if check_mitre_filter "T1613,T1611,T1552.007"; then
k8s_show_file() {
  [ -e "$1" ] || [ -L "$1" ] || return
  k8s_readable=no
  k8s_writable=no
  [ -r "$1" ] && k8s_readable=yes
  [ -w "$1" ] && k8s_writable=yes
  printf '  %s (readable=%s, writable=%s)\n' "$1" "$k8s_readable" "$k8s_writable"
}
k8s_has_mounted_node_root() {
  [ -r "$1" ] || return 1
  awk '$4 == "/" && $5 != "/" {print $5}' "$1" 2>/dev/null | head -n 100 |
  {
    while IFS= read -r k8s_root; do
      [ -d "$k8s_root/var/lib/kubelet" ] || [ -d "$k8s_root/etc/kubernetes" ] ||
        [ -d "$k8s_root/etc/rancher/rke2" ] || [ -d "$k8s_root/var/lib/k0s" ] || continue
      exit 0
    done
    exit 1
  }
}
k8s_has_kubelet_mount() {
  [ -r "$1" ] || return 1
  awk '$4 ~ "^/var/lib/kubelet(/|$)" {found=1; exit} END {exit !found}' "$1" 2>/dev/null
}
k8s_context_present() {
  for k8s_cfg in /home/*/.kube/config; do
    [ -f "$k8s_cfg" ] && return 0
  done
  [ -n "$KUBERNETES_SERVICE_HOST" ] ||
  [ -f "$HOME/.kube/config" ] ||
  [ -f /root/.kube/config ] ||
  [ -d /var/run/secrets/kubernetes.io/serviceaccount ] ||
  [ -d /run/secrets/kubernetes.io/serviceaccount ] ||
  [ -d /secrets/kubernetes.io/serviceaccount ] ||
  [ -d /var/lib/kubelet/pods ] ||
  [ -d /etc/kubernetes ] ||
  [ -d /etc/rancher/k3s ] ||
  [ -d /etc/rancher/rke2 ] ||
  [ -d /var/lib/k0s ] ||
  [ -d /var/snap/microk8s/current/credentials ] ||
  k8s_has_mounted_node_root /proc/self/mountinfo ||
  k8s_has_kubelet_mount /proc/self/mountinfo ||
  [ -n "$(env | sed -n 's/^KUBECONFIG=//p' | head -n 1)" ] ||
  printf '%s' "$containerType" | grep -qi kubernetes
}
k8s_scan_kubeconfigs() {
  k8s_cfg_env="$(env | sed -n 's/^KUBECONFIG=//p' | head -n 1)"
  if [ "$k8s_cfg_env" ]; then
    printf '%s\n' "$k8s_cfg_env" | tr ':' '\n' | while IFS= read -r k8s_cfg; do
      k8s_show_file "$k8s_cfg"
    done
  fi
  for k8s_cfg in "$HOME/.kube/config" /root/.kube/config /home/*/.kube/config \
    /etc/kubernetes/admin.conf /etc/kubernetes/kubelet.conf \
    /etc/kubernetes/bootstrap-kubelet.conf \
    /etc/kubernetes/controller-manager.conf /etc/kubernetes/scheduler.conf \
    /etc/kubernetes/kubeconfig /var/lib/kubelet/kubeconfig \
    /var/lib/kubelet/bootstrap-kubeconfig \
    /var/lib/kubelet/config.yaml /etc/rancher/k3s/k3s.yaml \
    /etc/rancher/k3s/config.yaml /etc/rancher/rke2/rke2.yaml \
    /etc/rancher/rke2/config.yaml \
    /var/lib/rancher/rke2/server/cred/admin.kubeconfig \
    /var/lib/rancher/rke2/server/node-token \
    /var/lib/rancher/rke2/agent/etc/crictl.yaml \
    /var/lib/rancher/k3s/server/node-token /var/lib/k0s/pki/admin.conf \
    /var/snap/microk8s/current/credentials/*.config; do
    k8s_show_file "$k8s_cfg"
  done
  for k8s_dir in /etc/kubernetes/pki /var/lib/kubelet/pki \
    /var/lib/rancher/k3s/server/tls /var/lib/k0s/pki \
    /var/lib/rancher/rke2/server/tls /var/snap/microk8s/current/certs; do
    [ -d "$k8s_dir" ] || continue
    printf '  Certificate/key directory: %s\n' "$k8s_dir"
    find "$k8s_dir" -maxdepth 2 -type f \( -name '*.key' -o -name '*.crt' -o -name '*.pem' \) \
      -print 2>/dev/null | head -n 30
  done
  if [ -d /etc/kubernetes/manifests ]; then
    echo '  Static pod manifests:'
    find /etc/kubernetes/manifests -maxdepth 1 -type f -print 2>/dev/null | head -n 20
  fi
  if [ -d /var/lib/rancher/rke2/agent/etc/kubelet.conf.d ]; then
    echo '  RKE2 kubelet configuration files:'
    find /var/lib/rancher/rke2/agent/etc/kubelet.conf.d -maxdepth 1 -type f \
      -print 2>/dev/null | head -n 20
  fi
}
k8s_scan_kubelet_config() {
  [ -r "$1" ] || return
  printf '  Kubelet access settings from %s:\n' "$1"
  grep -E '^[[:space:]]*(readOnlyPort|port|address|authentication|anonymous|enabled|authorization|mode|clientCAFile|rotateCertificates|serverTLSBootstrap):' \
    "$1" 2>/dev/null | head -n 25 | sed 's/^/    /'
}
k8s_scan_pod_volumes() {
  [ -d "$1" ] || return
  k8s_count=0
  for k8s_dir in "$1"/*/volumes/kubernetes.io~secret/* \
    "$1"/*/volumes/kubernetes.io~projected/*; do
    [ -d "$k8s_dir" ] || continue
    printf '  %s\n' "$k8s_dir"
    ls -A "$k8s_dir" 2>/dev/null | head -n 40 | sed 's/^/    /'
    k8s_show_file "$k8s_dir/token"
    k8s_count=$((k8s_count + 1))
    [ "$k8s_count" -lt 60 ] || break
  done
  [ "$k8s_count" -lt 60 ] || echo '  Volume listing stopped at 60 directories'
}
k8s_scan_host_roots() {
  [ -r "$1" ] || return
  k8s_root_count=0
  # A host root may be mounted at an arbitrary path. Restrict candidates to
  # mounts rooted at / that expose kubelet or Kubernetes directories.
  awk '$4 == "/" && $5 != "/" {print $5}' "$1" 2>/dev/null | head -n 100 |
  while IFS= read -r k8s_root; do
    [ -d "$k8s_root/var/lib/kubelet" ] || [ -d "$k8s_root/etc/kubernetes" ] ||
      [ -d "$k8s_root/etc/rancher/rke2" ] || [ -d "$k8s_root/var/lib/k0s" ] || continue
    printf '  Possible mounted node root: %s\n' "$k8s_root"
    for k8s_file in "$k8s_root/etc/kubernetes/admin.conf" \
      "$k8s_root/etc/kubernetes/kubelet.conf" \
      "$k8s_root/var/lib/kubelet/kubeconfig" \
      "$k8s_root/var/lib/kubelet/config.yaml" \
      "$k8s_root/etc/rancher/k3s/k3s.yaml" \
      "$k8s_root/etc/rancher/k3s/config.yaml" \
      "$k8s_root/etc/rancher/rke2/rke2.yaml" \
      "$k8s_root/etc/rancher/rke2/config.yaml" \
      "$k8s_root/var/lib/rancher/rke2/server/cred/admin.kubeconfig" \
      "$k8s_root/var/lib/rancher/rke2/server/node-token" \
      "$k8s_root/var/lib/rancher/k3s/server/node-token" \
      "$k8s_root/var/lib/k0s/pki/admin.conf"; do
      k8s_show_file "$k8s_file"
    done
    k8s_scan_kubelet_config "$k8s_root/var/lib/kubelet/config.yaml"
    if [ -d "$k8s_root/var/lib/rancher/rke2/agent/etc/kubelet.conf.d" ]; then
      find "$k8s_root/var/lib/rancher/rke2/agent/etc/kubelet.conf.d" \
        -maxdepth 1 -type f -print 2>/dev/null | head -n 20
    fi
    k8s_scan_pod_volumes "$k8s_root/var/lib/kubelet/pods"
    k8s_root_count=$((k8s_root_count + 1))
    if [ "$k8s_root_count" -ge 10 ]; then
      echo '  Mounted node-root listing stopped at 10 directories'
      break
    fi
  done
}
k8s_scan_kubelet_mounts() {
  [ -r "$1" ] || return
  awk '$4 ~ "^/var/lib/kubelet(/|$)" {print $4 "|" $5}' "$1" 2>/dev/null |
    head -n 40 |
  while IFS='|' read -r k8s_mount_root k8s_mount; do
    case "$k8s_mount" in /var/lib/kubelet|/var/lib/kubelet/pods) continue ;; esac
    [ -d "$k8s_mount" ] || continue
    printf '  Kubelet source %s mounted at %s\n' "$k8s_mount_root" "$k8s_mount"
    case "$k8s_mount_root" in
      /var/lib/kubelet)
        k8s_show_file "$k8s_mount/kubeconfig"
        k8s_show_file "$k8s_mount/config.yaml"
        k8s_scan_kubelet_config "$k8s_mount/config.yaml"
        k8s_scan_pod_volumes "$k8s_mount/pods"
        ;;
      /var/lib/kubelet/pods)
        k8s_scan_pod_volumes "$k8s_mount"
        ;;
      *'/volumes/kubernetes.io~secret/'*|*'/volumes/kubernetes.io~projected/'*)
        ls -A "$k8s_mount" 2>/dev/null | head -n 40 | sed 's/^/    /'
        k8s_show_file "$k8s_mount/token"
        ;;
    esac
  done
}
k8s_scan_mountinfo() {
  [ -r "$1" ] || return
  awk '$4 ~ "^/var/log(/|$)" || $5 == "/var/log" ||
       $4 ~ "^/var/lib/kubelet(/|$)" || $5 ~ "^/var/lib/kubelet(/|$)" ||
       $4 ~ "^/etc/kubernetes(/|$)" || $5 ~ "^/etc/kubernetes(/|$)" ||
       $5 ~ "^/(host|hostroot|rootfs|node|hostproc|mnt/host|mnt/node)(/|$)" {
         print $4 "|" $5 "|" $6
       }' "$1" 2>/dev/null | head -n 80 |
  while IFS='|' read -r k8s_mount_root k8s_mount k8s_mount_options; do
    k8s_writable=no
    case "$k8s_mount_options" in
      rw|rw,*)
        [ -w "$k8s_mount" ] && [ -x "$k8s_mount" ] && k8s_writable=yes
        ;;
    esac
    printf '  source-root=%s mount=%s options=%s write+search=%s\n' \
      "$k8s_mount_root" "$k8s_mount" "$k8s_mount_options" "$k8s_writable"
    case "$k8s_mount_root:$k8s_mount_options:$k8s_writable" in
      /var/log*:rw,*:yes)
        echo '    Potential writable host-log mount; node origin and nodes/proxy access need confirmation' ;;
    esac
    if [ "$k8s_mount" = /var/log ] && [ "$k8s_writable" = yes ]; then
      echo '    Writable /var/log mount; hostPath origin needs confirmation'
    fi
  done
}
k8s_scan_kernel_mounts() {
  [ -r "$1" ] || return
  awk '$0 ~ / - proc / {print $5}' "$1" 2>/dev/null | head -n 20 |
  while IFS= read -r k8s_mount; do
    k8s_show_file "$k8s_mount/sys/kernel/core_pattern"
  done
  awk '$0 ~ / - cgroup / {print $5}' "$1" 2>/dev/null | head -n 20 |
  while IFS= read -r k8s_mount; do
    k8s_show_file "$k8s_mount/release_agent"
    k8s_show_file "$k8s_mount/notify_on_release"
  done
}
k8s_cap_has() {
  case "$1" in ''|*[!0-9a-fA-F]*) return 1 ;; esac
  k8s_cap_low="$(printf '%s' "$1" | sed 's/.*\(........\)$/\1/')"
  [ "$((0x$k8s_cap_low & (1 << $2)))" -ne 0 ]
}
k8s_scan_escape_prereqs() {
  [ -r /proc/self/status ] || return
  k8s_cap_eff="$(awk '/^CapEff:/ {print $2; exit}' /proc/self/status 2>/dev/null)"
  printf '  Effective UID: %s\n' "$(id -u 2>/dev/null)"
  for k8s_file in 'CAP_SYS_ADMIN:21' 'CAP_SYS_CHROOT:18' 'CAP_SYS_PTRACE:19'; do
    if k8s_cap_has "$k8s_cap_eff" "${k8s_file#*:}"; then
      printf '  %s: present\n' "${k8s_file%%:*}"
    else
      printf '  %s: absent or unknown\n' "${k8s_file%%:*}"
    fi
  done
  for k8s_file in pid user mnt net ipc uts cgroup; do
    k8s_ns_self="$(readlink "/proc/self/ns/$k8s_file" 2>/dev/null)"
    k8s_ns_one="$(readlink "/proc/1/ns/$k8s_file" 2>/dev/null)"
    [ "$k8s_ns_self" ] && [ "$k8s_ns_one" ] || continue
    if [ "$k8s_ns_self" = "$k8s_ns_one" ]; then
      printf '  %s namespace matches visible PID 1\n' "$k8s_file"
    else
      printf '  %s namespace differs from visible PID 1\n' "$k8s_file"
    fi
  done
  # Matching visible PID 1 is not proof that it is the physical node's init.
  if command -v stat >/dev/null 2>&1; then
    k8s_ns_self="$(stat -Lc '%d:%i' /proc/self/root 2>/dev/null)"
    k8s_ns_one="$(stat -Lc '%d:%i' /proc/1/root 2>/dev/null)"
    if [ "$k8s_ns_self" ] && [ "$k8s_ns_one" ] && [ "$k8s_ns_self" != "$k8s_ns_one" ]; then
      echo '  Visible PID 1 has a distinct filesystem root'
      [ -x /proc/1/root/bin/sh ] && echo '  /bin/sh is executable in visible PID 1 root'
    fi
  fi
}
k8s_runc_21626_upstream_range() {
  case "$1" in
    1.0.0-rc*)
      k8s_rc="${1#1.0.0-rc}"
      case "$k8s_rc" in ''|*[!0-9]*) return 1 ;; esac
      [ "$k8s_rc" -ge 93 ]
      return
      ;;
    *-*) return 1 ;;
  esac
  printf '%s\n' "$1" |
    awk -F. '$1 == 1 && ($2 == 0 || ($2 == 1 && $3 ~ /^[0-9]+$/ && $3 < 12)) {found=1}
      END {exit !found}'
}
k8s_scan_runc_21626() {
  command -v runc >/dev/null 2>&1 || return
  k8s_runc_version="$(runc --version 2>/dev/null | sed -n 's/^runc version \([0-9][0-9A-Za-z.+-]*\).*/\1/p' | head -n 1)"
  [ "$k8s_runc_version" ] || return
  printf '  Visible runc version: %s\n' "$k8s_runc_version"
  if k8s_runc_21626_upstream_range "$k8s_runc_version"; then
    echo '  CVE-2024-21626: upstream version is in the affected range; vendor backports need confirmation'
  fi
}
k8s_scan_sockets() {
  k8s_docker_host="$(env | sed -n 's/^DOCKER_HOST=//p' | head -n 1)"
  case "$k8s_docker_host" in
    unix://*)
      k8s_socket="${k8s_docker_host#unix://}"
      [ -S "$k8s_socket" ] && k8s_show_file "$k8s_socket"
      ;;
  esac
  for k8s_socket in /run/docker.sock /var/run/docker.sock \
    /run/containerd/containerd.sock /var/run/containerd/containerd.sock \
    /run/k3s/containerd/containerd.sock /run/crio/crio.sock \
    /var/run/crio/crio.sock /run/cri-dockerd.sock \
    /var/run/dockershim.sock /run/podman/podman.sock; do
    [ -S "$k8s_socket" ] && k8s_show_file "$k8s_socket"
  done
  for k8s_dir in /run /var/run; do
    [ -d "$k8s_dir" ] || continue
    find "$k8s_dir" -maxdepth 4 -type s \( -name '*kubelet*.sock' -o \
      -name '*containerd*.sock' -o -name '*crio*.sock' -o \
      -name '*docker*.sock' -o -name '*podman*.sock' \) \
      -print 2>/dev/null | head -n 40
  done
}
k8s_scan_kubelet_processes() {
  for k8s_pid in $(ps -eo pid=,comm= 2>/dev/null | awk '$2 == "kubelet" {print $1}' | head -n 5); do
    [ -r "/proc/$k8s_pid/cmdline" ] || continue
    printf '  kubelet PID %s:\n' "$k8s_pid"
    tr '\000' '\n' < "/proc/$k8s_pid/cmdline" 2>/dev/null |
      awk '
        pending { print "    " pending "=" $0; pending=""; next }
        /^--(kubeconfig|bootstrap-kubeconfig|config|cert-dir|root-dir|read-only-port|port|address|anonymous-auth|authorization-mode|client-ca-file|node-ip)$/ {
          pending=$0; next
        }
        /^--(kubeconfig|bootstrap-kubeconfig|config|cert-dir|root-dir|read-only-port|port|address|anonymous-auth|authorization-mode|client-ca-file|node-ip)=/ {
          print "    " $0
        }
      '
  done
}
k8s_direct_api_ready() {
  command -v curl >/dev/null 2>&1 && command -v jq >/dev/null 2>&1 || return 1
  k8s_direct_token_file=''
  k8s_direct_ca=''
  [ "$#" -gt 0 ] || set -- /var/run/secrets/kubernetes.io/serviceaccount \
    /run/secrets/kubernetes.io/serviceaccount /secrets/kubernetes.io/serviceaccount
  for k8s_dir do
    if [ -r "$k8s_dir/token" ] && [ -r "$k8s_dir/ca.crt" ]; then
      k8s_direct_token_file="$k8s_dir/token"
      k8s_direct_ca="$k8s_dir/ca.crt"
      break
    fi
  done
  [ "$k8s_direct_token_file" ] || return 1
  if [ -r "$k8s_dir/namespace" ] && [ ! "$k8s_namespace" ]; then
    k8s_namespace="$(head -n 1 "$k8s_dir/namespace" 2>/dev/null)"
  fi
  [ "$k8s_namespace" ] || k8s_namespace=default
  case "$k8s_namespace" in ''|*[!a-z0-9-]*) return 1 ;; esac
  k8s_direct_host="${KUBERNETES_SERVICE_HOST:-kubernetes.default.svc}"
  case "$k8s_direct_host" in ''|*[!A-Za-z0-9.:-]*) return 1 ;; esac
  case "$k8s_direct_host" in *:*) k8s_direct_host="[$k8s_direct_host]" ;; esac
  k8s_direct_port="${KUBERNETES_SERVICE_PORT_HTTPS:-443}"
  case "$k8s_direct_port" in ''|*[!0-9]*) return 1 ;; esac
  k8s_direct_base="https://$k8s_direct_host:$k8s_direct_port"
  k8s_direct_token="$(tr -d '\r\n' < "$k8s_direct_token_file" 2>/dev/null)"
  case "$k8s_direct_token" in ''|*[!A-Za-z0-9._~-]*) k8s_direct_token=''; return 1 ;; esac
}
k8s_sa_api_get() {
  # Ignore curlrc: inherited tracing or credentials must not affect discovery.
  printf 'header = "Authorization: Bearer %s"\n' "$k8s_direct_token" |
    curl -q --config - -fsS --connect-timeout 2 --max-time 5 \
      --cacert "$k8s_direct_ca" -H 'Accept: application/json' \
      "$k8s_direct_base$1" 2>/dev/null
}
# Bound captured bytes even on curl versions whose --max-filesize only checks
# Content-Length. Keep curl's exit status in-band because head owns the pipeline
# status. A final dot preserves trailing newlines in command substitutions.
# Callers reserve 15 bytes: HTTP status (4), exit trailer (up to 10), and
# one over-limit byte. Reject that extra byte before parsing any response.
k8s_bounded_curl() (
  k8s_curl_limit=$1
  shift
  { curl "$@"; printf '\nexit=%s\n' "$?"; } | head -c "$k8s_curl_limit"
  printf '.'
)
k8s_sa_kube_system_secret_access() {
  # SelfSubjectAccessReview evaluates the mounted token without reading Secrets.
  k8s_access_response="$(printf 'header = "Authorization: Bearer %s"\n' "$k8s_direct_token" |
    k8s_bounded_curl 4111 -q --config - -fsS --connect-timeout 2 --max-time 5 --max-filesize 4096 \
      --cacert "$k8s_direct_ca" -H 'Accept: application/json' \
      -H 'Content-Type: application/json' \
      --data-binary '{"apiVersion":"authorization.k8s.io/v1","kind":"SelfSubjectAccessReview","spec":{"resourceAttributes":{"namespace":"kube-system","verb":"list","resource":"secrets"}}}' \
      -w '\n%{http_code}' \
      "$k8s_direct_base/apis/authorization.k8s.io/v1/selfsubjectaccessreviews" 2>/dev/null)"
  k8s_access_response=${k8s_access_response%.}
  if [ "$(printf '%s' "$k8s_access_response" | wc -c)" -gt 4110 ]; then
    echo unknown
    return
  fi
  k8s_access_exit="$(printf '%s' "$k8s_access_response" | tail -n 1)"
  k8s_access_exit=${k8s_access_exit#exit=}
  k8s_access_response=${k8s_access_response%exit=*}
  k8s_access_response=${k8s_access_response%?}
  k8s_access_http="$(printf '%s' "$k8s_access_response" | tail -c 3)"
  case "$k8s_access_exit:$k8s_access_http" in 0:200|0:201) ;; *) echo unknown; return ;; esac
  k8s_access_json="${k8s_access_response%????}"
  k8s_access_result="$(printf '%s' "$k8s_access_json" | jq -r '
    if (.status | type) != "object" or
       (.status.allowed | type) != "boolean" or
       ((.status.evaluationError // "") != "") or
       (.status.allowed == true and .status.denied == true)
    then "unknown"
    elif .status.allowed then "allowed"
    else "denied"
    end
  ' 2>/dev/null | head -n 1)"
  case "$k8s_access_result" in allowed|denied) echo "$k8s_access_result" ;; *) echo unknown ;; esac
}
k8s_scan_sa_secrets() {
  # The API response contains values; keep it in memory and emit only selected metadata.
  # Bound the capture independently of Content-Length and curl version.
  k8s_secret_response="$(printf 'header = "Authorization: Bearer %s"\n' "$k8s_direct_token" |
    k8s_bounded_curl 1048591 -q --config - -fsS --connect-timeout 2 --max-time 5 --max-filesize 1048576 \
      --cacert "$k8s_direct_ca" -H 'Accept: application/json' -w '\n%{http_code}' \
      "$k8s_direct_base/api/v1/namespaces/$k8s_namespace/secrets?limit=40" 2>/dev/null)"
  k8s_secret_response=${k8s_secret_response%.}
  if [ "$(printf '%s' "$k8s_secret_response" | wc -c)" -gt 1048590 ]; then
    echo '    secrets: response exceeded 1 MiB; inventory skipped'
    return
  fi
  k8s_secret_exit="$(printf '%s' "$k8s_secret_response" | tail -n 1)"
  k8s_secret_exit=${k8s_secret_exit#exit=}
  k8s_secret_response=${k8s_secret_response%exit=*}
  k8s_secret_response=${k8s_secret_response%?}
  k8s_secret_http="$(printf '%s' "$k8s_secret_response" | tail -c 3)"
  case "$k8s_secret_exit:$k8s_secret_http" in
    0:200) ;;
    22:403) echo '    secrets: access denied (RBAC)' ; return ;;
    22:401) echo '    secrets: authentication denied' ; return ;;
    22:404) echo '    secrets: namespace unavailable' ; return ;;
    28:*) echo '    secrets: request timed out' ; return ;;
    63:*) echo '    secrets: response exceeded 1 MiB; inventory skipped' ; return ;;
    *) echo '    secrets: API request failed or returned an unexpected status' ; return ;;
  esac
  k8s_secret_json="${k8s_secret_response%????}"
  k8s_secret_summary="$(printf '%s' "$k8s_secret_json" | jq -r '
    if type != "object" or (.items | type) != "array" or
       any(.items[]; type != "object" or (.metadata.name | type) != "string" or
           ((.type // "") | type) != "string" or
           ((.data // {}) | type) != "object" or
           ((.stringData // {}) | type) != "object")
    then error("invalid Secret list")
    else
      (.items | length) as $count |
      ((.metadata["continue"] // "") != "") as $continued |
      if $count == 0 then "    secrets: none (accessible list)"
      else
        .items[:40][] |
        ((.data // {} | keys) + (.stringData // {} | keys) | unique) as $keys |
        "    secrets: name=\(.metadata.name | @json) type=\((.type // "unknown") | @json) keys=\($keys[:20] | @json)\(if ($keys | length) > 20 then " (additional keys omitted)" else "" end)"
      end,
      if $count > 40 or $continued then "    secrets: additional results omitted (40 shown; no pagination)" else empty end
    end
  ' 2>/dev/null)" || {
    echo '    secrets: malformed API response; inventory unknown'
    return
  }
  printf '%s\n' "$k8s_secret_summary"
}
k8s_scan_sa_api() {
  if ! command -v curl >/dev/null 2>&1 || ! command -v jq >/dev/null 2>&1; then
    echo '  Kubernetes API discovery skipped (curl or jq unavailable)'
    return
  fi
  k8s_direct_api_ready "$@" || return
  echo '  Kubernetes API discovery with mounted service account (names and settings only):'
  k8s_sa_api_get '/api/v1/namespaces?limit=100' |
    jq -r '.items[]?.metadata.name // empty' 2>/dev/null | head -n 40 | sed 's/^/    namespace: /'
  k8s_sa_api_get "/api/v1/namespaces/$k8s_namespace/pods?limit=100" |
    jq -r '.items[]? | (
      "\(.metadata.name) sa=\(.spec.serviceAccountName // "default") hostPID=\(.spec.hostPID // false) hostIPC=\(.spec.hostIPC // false) hostNetwork=\(.spec.hostNetwork // false)",
      (.spec.containers[]? | "  container \(.name) privileged=\(.securityContext.privileged // false) allowPE=\((.securityContext.allowPrivilegeEscalation | if . == null then "default" else . end)) caps=\((.securityContext.capabilities.add // []) | join(","))"),
      (.spec.volumes[]? | select(.hostPath.path != null) | "  hostPath \(.hostPath.path)")
    )' 2>/dev/null | head -n 100 | sed 's/^/    pod: /'
  for k8s_file in services serviceaccounts; do
    k8s_sa_api_get "/api/v1/namespaces/$k8s_namespace/$k8s_file?limit=100" |
      jq -r '.items[]? | .metadata.name // empty' 2>/dev/null | head -n 40 |
      sed "s/^/    $k8s_file: /"
  done
  k8s_scan_sa_secrets
  printf '  kube-system secrets list authorization (mounted identity): %s\n' \
    "$(k8s_sa_kube_system_secret_access)"
  k8s_sa_api_get '/api/v1/nodes?limit=100' |
    jq -r '.items[]?.metadata.name // empty' 2>/dev/null | head -n 40 | sed 's/^/    node: /'
  k8s_direct_token=''
}
k8s_kubectl() {
  # Request timeouts do not bound credential plugins or all paginated requests.
  # Skip kubectl when a process-wide deadline cannot be enforced.
  command -v timeout >/dev/null 2>&1 || return 1
  timeout -s KILL 5 kubectl "$@"
}
k8s_scan_kubectl() {
  if ! command -v kubectl >/dev/null 2>&1; then
    [ "$EXTRA_CHECKS" ] && k8s_scan_sa_api
    return 0
  fi
  echo '  Local kubeconfig contexts:'
  k8s_kubectl config get-contexts -o name 2>/dev/null | head -n 30 | sed 's/^/    /'
  [ "$EXTRA_CHECKS" ] || return 0
  k8s_current_context="$(k8s_kubectl config current-context 2>/dev/null | head -n 1)"
  if [ ! "$k8s_current_context" ] && k8s_direct_api_ready; then
    k8s_direct_token=''
    k8s_scan_sa_api
    return 0
  fi
  k8s_context_name="$(k8s_kubectl config view --minify -o 'jsonpath={..namespace}' 2>/dev/null | head -c 200)"
  [ "$k8s_context_name" ] && k8s_namespace="$k8s_context_name"
  [ "$k8s_namespace" ] || k8s_namespace=default
  echo '  Current context authorization rules:'
  k8s_kubectl --request-timeout=5s auth can-i --list -n "$k8s_namespace" \
    2>/dev/null | head -n 80
  k8s_access_result="$(k8s_kubectl --request-timeout=5s auth can-i list secrets \
    -n kube-system 2>/dev/null | head -n 1)"
  case "$k8s_access_result" in yes) k8s_access_result=allowed ;; no) k8s_access_result=denied ;; *) k8s_access_result=unknown ;; esac
  printf '  kube-system secrets list authorization (current context): %s\n' "$k8s_access_result"
  echo '  Other configured context authorization rules (up to five):'
  k8s_kubectl config get-contexts -o name 2>/dev/null | head -n 5 |
  while IFS= read -r k8s_context_name; do
    [ "$k8s_context_name" = "$k8s_current_context" ] && continue
    printf '    Context: %s\n' "$k8s_context_name"
    k8s_kubectl --context="$k8s_context_name" --request-timeout=5s auth can-i --list \
      2>/dev/null | head -n 40 | sed 's/^/      /'
  done
  echo '  Accessible namespace names:'
  k8s_kubectl --request-timeout=5s get namespaces -o name 2>/dev/null | head -n 40
  printf '  Accessible object names in namespace %s:\n' "$k8s_namespace"
  k8s_kubectl --request-timeout=5s get pods,services,serviceaccounts,secrets \
    -n "$k8s_namespace" -o name 2>/dev/null | head -n 80
  echo '  Accessible node names:'
  k8s_kubectl --request-timeout=5s get nodes -o name 2>/dev/null | head -n 40
  echo '  Node-specific get nodes/proxy authorization (up to eight nodes):'
  k8s_kubectl --request-timeout=5s get nodes -o name 2>/dev/null | head -n 8 |
  while IFS= read -r k8s_node_name; do
    case "$k8s_node_name" in node/*|nodes/*) k8s_node_name="${k8s_node_name#*/}" ;; *) continue ;; esac
    k8s_probe_status="$(k8s_kubectl --request-timeout=5s auth can-i get \
      "nodes/$k8s_node_name" --subresource=proxy 2>/dev/null)"
    case "$k8s_probe_status" in
      yes|no) printf '    %s: %s\n' "$k8s_node_name" "$k8s_probe_status" ;;
    esac
  done
  echo '  Pod service accounts, host namespaces and container security settings:'
  k8s_kubectl --request-timeout=5s get pods -n "$k8s_namespace" \
    -o 'jsonpath={range .items[*]}{.metadata.name}{" sa="}{.spec.serviceAccountName}{" hostPID="}{.spec.hostPID}{" hostIPC="}{.spec.hostIPC}{" hostNetwork="}{.spec.hostNetwork}{" containers="}{range .spec.containers[*]}{.name}{"(privileged="}{.securityContext.privileged}{",allowPE="}{.securityContext.allowPrivilegeEscalation}{",caps="}{.securityContext.capabilities.add}{") "}{end}{"\n"}{end}' \
    2>/dev/null | head -n 60
  echo '  Pod hostPath sources:'
  k8s_kubectl --request-timeout=5s get pods -n "$k8s_namespace" \
    -o 'jsonpath={range .items[*]}{.metadata.name}{": "}{range .spec.volumes[*]}{.hostPath.path}{" "}{end}{"\n"}{end}' \
    2>/dev/null | grep -E ': /' | head -n 60
}
k8s_probe_kubelet() {
  command -v curl >/dev/null 2>&1 || return
  case "$1" in ''|*[!0-9a-fA-F:.]*) return ;; esac
  k8s_probe_host="$1"
  case "$k8s_probe_host" in *:*) k8s_probe_host="[$k8s_probe_host]" ;; esac
  for k8s_probe_port in 10250 10255; do
    k8s_probe_scheme=https
    [ "$k8s_probe_port" = 10255 ] && k8s_probe_scheme=http
    # No credentials are sent. An HTTP status only establishes reachability;
    # it does not prove kubelet authentication or authorization.
    k8s_probe_status="$(curl -q -ksS --noproxy '*' --connect-timeout 1 --max-time 2 \
      -o /dev/null -w '%{http_code}' \
      "$k8s_probe_scheme://$k8s_probe_host:$k8s_probe_port/healthz" 2>/dev/null)"
    case "$k8s_probe_status" in
      [1-5][0-9][0-9])
        printf '  Kubelet %s://%s:%s responded HTTP %s\n' \
          "$k8s_probe_scheme" "$k8s_probe_host" "$k8s_probe_port" "$k8s_probe_status"
        ;;
    esac
  done
}
k8s_scan_kubelet_network() {
  echo '  Reachability of node kubelet ports (up to eight addresses; status only):'
  k8s_node_addresses=''
  if command -v kubectl >/dev/null 2>&1; then
    k8s_node_addresses="$(k8s_kubectl --request-timeout=5s get nodes \
      -o 'jsonpath={range .items[*]}{range .status.addresses[*]}{.address}{"\n"}{end}{end}' \
      2>/dev/null)"
  fi
  if [ ! "$k8s_node_addresses" ] && k8s_direct_api_ready; then
    k8s_node_addresses="$(k8s_sa_api_get '/api/v1/nodes?limit=100' |
      jq -r '.items[]?.status.addresses[]? | select(.type == "InternalIP" or .type == "ExternalIP") | .address' \
        2>/dev/null)"
    k8s_direct_token=''
  fi
  printf '%s\n' "$k8s_node_addresses" | awk 'NF && !seen[$0]++' | head -n 8 |
  while IFS= read -r k8s_node_address; do
    k8s_probe_kubelet "$k8s_node_address"
  done
}
k8s_scan_service_dns() {
  command -v dig >/dev/null 2>&1 || return
  echo '  Kubernetes service SRV records:'
  dig +time=2 +tries=1 +short SRV any.any.svc.cluster.local 2>/dev/null | head -n 40
}
k8s_scan_kops_storage() {
  command -v timeout >/dev/null 2>&1 || return
  if command -v aws >/dev/null 2>&1; then
    echo '  Accessible S3 buckets (up to 10) and candidate kOps Secret keys (first 100 objects each):'
    AWS_MAX_ATTEMPTS=1 timeout -s KILL 12 aws s3api list-buckets \
      --max-items 10 --query 'Buckets[].Name' --output text \
      --cli-connect-timeout 2 --cli-read-timeout 5 \
      2>/dev/null | tr '\t' '\n' | head -n 10 |
    while IFS= read -r k8s_aws_bucket; do
      case "$k8s_aws_bucket" in ''|*[!a-z0-9.-]*) continue ;; esac
      printf '    s3://%s\n' "$k8s_aws_bucket"
      AWS_MAX_ATTEMPTS=1 timeout -s KILL 12 aws s3api list-objects-v2 \
        --bucket "$k8s_aws_bucket" --max-items 100 \
        --query 'Contents[].Key' --output text \
        --cli-connect-timeout 2 --cli-read-timeout 5 \
        2>/dev/null | tr '\t' '\n' | grep -E '(^|/)secrets/' | head -n 20 |
        sed 's/^/      candidate key: /'
    done
  fi
  if command -v gcloud >/dev/null 2>&1; then
    echo '  Accessible GCS buckets (up to 10) and candidate kOps Secret objects (first 100 each):'
    timeout -s KILL 12 gcloud --quiet storage buckets list --limit=10 \
      --format='value(name)' 2>/dev/null | head -n 10 |
    while IFS= read -r k8s_gcs_bucket; do
      k8s_gcs_bucket="${k8s_gcs_bucket#gs://}"
      case "$k8s_gcs_bucket" in ''|*[!a-z0-9._-]*) continue ;; esac
      printf '    gs://%s\n' "$k8s_gcs_bucket"
      timeout -s KILL 12 gcloud --quiet storage objects list \
        "gs://$k8s_gcs_bucket/**" --limit=100 --format='value(name)' \
        2>/dev/null | grep -E '(^|/)secrets/' | head -n 20 |
        sed 's/^/      candidate object: /'
    done
  fi
}
if k8s_context_present; then
  print_2title 'Kubernetes credentials and escape surfaces' 'T1613,T1611,T1552.007'
  print_3title 'Pod identity and projected credentials' 'T1552.007'
  k8s_namespace=''
  for k8s_dir in /var/run/secrets/kubernetes.io/serviceaccount \
    /run/secrets/kubernetes.io/serviceaccount /secrets/kubernetes.io/serviceaccount; do
    [ -d "$k8s_dir" ] || continue
    k8s_show_file "$k8s_dir/token"
    k8s_show_file "$k8s_dir/ca.crt"
    k8s_show_file "$k8s_dir/namespace"
    if [ -r "$k8s_dir/namespace" ]; then
      k8s_namespace="$(head -n 1 "$k8s_dir/namespace" 2>/dev/null)"
    fi
  done
  for k8s_file in $(env | sed -n -E 's/^(AWS_WEB_IDENTITY_TOKEN_FILE|AZURE_FEDERATED_TOKEN_FILE|GOOGLE_APPLICATION_CREDENTIALS)=//p'); do
    k8s_show_file "$k8s_file"
  done
  [ "$k8s_namespace" ] && printf '  Namespace: %s\n' "$k8s_namespace"
  [ -n "$KUBERNETES_SERVICE_HOST" ] &&
    printf '  API server: %s:%s\n' "$KUBERNETES_SERVICE_HOST" "${KUBERNETES_SERVICE_PORT_HTTPS:-443}"
  print_3title 'Kubeconfigs, client keys and kubelet settings' 'T1552.007'
  k8s_scan_kubeconfigs
  k8s_scan_kubelet_config /var/lib/kubelet/config.yaml
  k8s_scan_kubelet_processes
  print_3title 'Node pod Secret and projected-token volumes' 'T1552.007'
  k8s_scan_pod_volumes /var/lib/kubelet/pods
  k8s_scan_host_roots /proc/self/mountinfo
  k8s_scan_kubelet_mounts /proc/self/mountinfo
  print_3title 'Host filesystem and log mounts' 'T1611'
  k8s_scan_mountinfo /proc/self/mountinfo
  k8s_scan_kernel_mounts /proc/self/mountinfo
