echo ''
echo ''
if [ "$WAIT" ]; then echo "Press enter to continue"; read "asd"; fi

if echo $CHECKS | grep -q procs_crons_timers_srvcs_sockets; then
if check_mitre_filter "T1543.002,T1574.010,T1007,T1552.001,T1559,T1571,T1049,T1559.001,T1021.004,T1053.003,T1083,T1574,T1057,T1003.007,T1554,T1134.004,T1543.001"; then
print_title "Processes, Crons, Timers, Services and Sockets"
if check_mitre_filter "T1057,T1552.001"; then
if ! [ "$SEARCH_IN_FOLDER" ]; then
  print_2title "Running processes (cleaned)" "T1057"
  if [ "$NOUSEPS" ]; then
    printf ${BLUE}"[i]$GREEN Looks like ps is not finding processes, going to read from /proc/ and not going to monitor 1min of processes\n"$NC
  fi
  print_info "Check weird & unexpected processes run by root: https://book.hacktricks.wiki/en/linux-hardening/processes-crontab-systemd-dbus/process-enumeration-and-service-paths.html#map-processes-and-ownership"
  if [ -f "/etc/fstab" ] && cat /etc/fstab | grep -q "hidepid=2"; then
    echo "Looks like /etc/fstab has hidepid=2, so ps will not show processes of other users"
  fi
  # Get current process environment variables
  if [ -r "/proc/self/environ" ]; then
    current_env_vars=$(cat /proc/self/environ 2>/dev/null | tr '\0' '\n' | sort)
  else
    current_env_vars=$(env 2>/dev/null | sort)
  fi
  # Get current process mounts
  if [ -r "/proc/self/mountinfo" ]; then
    current_mounts=$(cat /proc/self/mountinfo 2>/dev/null | sort)
  else
    current_mounts=$(mount 2>/dev/null | sort)
  fi
  # Function to check for unusual environment variables
  check_env_vars() {
    local pid="$1"
    local proc_user="$2"
    local proc_cmd="$3"
    local findings=""
    # Skip if we can't read the environment
    [ ! -r "/proc/$pid/environ" ] && return
    # Get process environment variables
    proc_env_vars=$(cat "/proc/$pid/environ" 2>/dev/null | tr '\0' '\n' | sort)
    [ -z "$proc_env_vars" ] && return
    # Find environment variables that the target process has but we don't
    if [ -n "$current_env_vars" ]; then
      echo "$proc_env_vars" | while read -r var; do
        if [ -n "$var" ]; then
          # Escape special regex characters in var
          escaped_var=$(echo "$var" | sed 's/[][^$.*+?(){}|]/\\&/g')
          if ! echo "$current_env_vars" | grep -q "^$escaped_var$"; then
            if [ -z "$findings" ]; then
              findings="Has additional environment variables:"
            fi
            findings="$findings\n  └─ $var"
          fi
        fi
      done
    else
      # If we can't get current env vars, just show all process env vars
      findings="Has environment variables:"
      echo "$proc_env_vars" | while read -r var; do
        if [ -n "$var" ]; then
          findings="$findings\n  └─ $var"
        fi
      done
    fi
    # Return findings if any
    if [ -n "$findings" ]; then
      echo "$findings"
    fi
  }
  # Function to check for unusual security contexts
  check_security_context() {
    local pid="$1"
    local proc_user="$2"
    local proc_cmd="$3"
    local findings=""
    # Check SELinux context
    if [ -r "/proc/$pid/attr/current" ]; then
      selinux_ctx=$(cat "/proc/$pid/attr/current" 2>/dev/null)
      if [ -n "$selinux_ctx" ] && [ "$selinux_ctx" != "unconfined" ]; then
        findings="SELinux context: $selinux_ctx"
      fi
    fi
    # Check AppArmor profile
    if [ -r "/proc/$pid/attr/apparmor/current" ]; then
      apparmor_profile=$(cat "/proc/$pid/attr/apparmor/current" 2>/dev/null)
      if [ -n "$apparmor_profile" ] && [ "$apparmor_profile" != "unconfined" ]; then
        if [ -n "$findings" ]; then
          findings="$findings\n  └─ AppArmor profile: $apparmor_profile"
        else
          findings="AppArmor profile: $apparmor_profile"
        fi
      fi
    fi
    # Return findings if any
    if [ -n "$findings" ]; then
      echo "$findings"
    fi
  }
  # Function to check for unusual mount namespaces
  check_mount_namespace() {
    local pid="$1"
    local proc_user="$2"
    local proc_cmd="$3"
    local findings=""
    # Skip if we can't read the mountinfo
    [ ! -r "/proc/$pid/mountinfo" ] && return
    # Get process mounts
    proc_mounts=$(cat "/proc/$pid/mountinfo" 2>/dev/null | sort)
    [ -z "$proc_mounts" ] && return
    # Find mounts that the target process has but we don't
    if [ -n "$current_mounts" ]; then
      echo "$proc_mounts" | while read -r mount; do
        if [ -n "$mount" ] && ! echo "$current_mounts" | grep -q "^$mount$"; then
          mount_point=$(echo "$mount" | sed "s,.* - \(.*\),\1,")
          if [ -z "$findings" ]; then
            findings="Has additional mounts:"
          fi
          findings="$findings\n  └─ $mount_point"
        fi
      done
    else
      # If we can't get current mounts, just show all process mounts
      findings="Has mounts:"
      echo "$proc_mounts" | while read -r mount; do
        if [ -n "$mount" ]; then
          mount_point=$(echo "$mount" | sed "s,.* - \(.*\),\1,")
          findings="$findings\n  └─ $mount_point"
        fi
      done
    fi
    # Return findings if any
    if [ -n "$findings" ]; then
      echo "$findings"
    fi
  }
  # Function to check for unusual file descriptors
  check_file_descriptors() {
    local pid="$1"
    local proc_user="$2"
    local proc_cmd="$3"
    local findings=""
    # Skip if we can't read the file descriptors
    [ ! -r "/proc/$pid/fd" ] && return
    # Check for interesting file descriptors
    for fd in /proc/$pid/fd/*; do
      # Skip if fd doesn't exist or we can't access it
      [ ! -e "$fd" ] && continue
      # Get fd target
      fd_target=$(readlink "$fd" 2>/dev/null)
      [ -z "$fd_target" ] && continue
      # Skip if target doesn't exist
      [ ! -e "$fd_target" ] && continue
      # Check if we can access the FD but not the target file
      if [ -r "$fd" ] && [ ! -r "$fd_target" ]; then
        if [ -z "$findings" ]; then
          findings="Readable FD to unreadable file: $fd -> $fd_target"
        else
          findings="$findings\n  └─ Readable FD to unreadable file: $fd -> $fd_target"
        fi
      fi
      if [ -w "$fd" ] && [ ! -w "$fd_target" ]; then
        if [ -z "$findings" ]; then
          findings="Writable FD to unwritable file: $fd -> $fd_target"
        else
          findings="$findings\n  └─ Writable FD to unwritable file: $fd -> $fd_target"
        fi
      fi
    done
    # Check for unusual number of file descriptors
    fd_count=$(ls -1 "/proc/$pid/fd" 2>/dev/null | wc -l)
    [ -z "$fd_count" ] && return
    # If process has more than 100 file descriptors, it might be interesting
    if [ "$fd_count" -gt 100 ]; then
      if [ -z "$findings" ]; then
        findings="Unusual number of FDs: $fd_count"
      else
        findings="$findings\n  └─ Unusual number of FDs: $fd_count"
      fi
    fi
    # Return findings if any
    if [ -n "$findings" ]; then
      echo "$findings"
    fi
  }
  # Inspect the already collected process list; do not connect to UNO or probe ports.
  check_privileged_office_uno_sockets() {
    [ -n "$pslist" ] || return
    printf '%s\n' "$pslist" | awk '
      NR > 5000 { exit }
      length($0) > 4096 { next }
      $1 == "root" &&
      /(^|[[:space:]\/])(soffice(\.bin)?|libreoffice|openoffice)([[:space:]]|$)/ &&
      /--accept=/ {
        if (!match($0, /--accept=[^[:space:]]+/)) next
        accept = substr($0, RSTART, RLENGTH)
        sub(/^--accept=/, "", accept)
        sub(/^"/, "", accept)
        sub(/"$/, "", accept)
        if (accept !~ /^socket,host=/ || accept !~ /;urp(;|$)/) next
        if (!match(accept, /host=[^,;[:space:]]+/)) next
        host = substr(accept, RSTART + 5, RLENGTH - 5)
        if (!match(accept, /port=[0-9]+/)) next
        port = substr(accept, RSTART + 5, RLENGTH - 5)
        if (port + 0 < 1 || port + 0 > 65535) next
        endpoint = host ":" port
        if (!seen[endpoint]++) {
          print endpoint
          if (++count >= 5) exit
        }
      }'
  }
  # Reuse the process snapshot; a loopback SPICE option is a guest-console
  # lead, not evidence of a live listener or privilege on the host.
  check_unauthenticated_spice_console() {
    [ -n "$pslist" ] || return
    # The two cached snapshots have different executable columns. Select the
    # actual producer format so argument text cannot impersonate an executable.
    if [ -n "$NOUSEPS" ]; then spice_exec_field=3; else spice_exec_field=11; fi
    printf '%s\n' "$pslist" | awk -v exec_field="$spice_exec_field" '
      NR > 5000 { exit }
      length($0) > 8192 || NF <= exec_field { next }
      {
        if ($(exec_field) !~ /(^|\/)qemu-system-[A-Za-z0-9_]+$/) next
        first_arg = exec_field + 1
        for (i = first_arg; i < NF && i < first_arg + 116; i++) {
          if ($i != "-spice") continue
          spec = $(i + 1)
          gsub(/^"|"$/, "", spec)
          if (length(spec) > 512) continue
          n = split(spec, fields, ",")
          if (n > 32) continue
          addr = port = ""
          noauth = conflicting_auth = 0
          for (j = 1; j <= n; j++) {
            if (fields[j] == "disable-ticketing" || fields[j] == "disable-ticketing=on") noauth = 1
            else if (fields[j] ~ /^disable-ticketing=/ || fields[j] == "sasl=on" ||
                     fields[j] ~ /^password-secret=/ || fields[j] ~ /^x509-/) conflicting_auth = 1
            else if (fields[j] ~ /^addr=/) addr = substr(fields[j], 6)
            else if (fields[j] ~ /^port=/) port = substr(fields[j], 6)
          }
          if (!noauth || conflicting_auth || (addr != "127.0.0.1" && addr != "::1")) continue
          if (port !~ /^[0-9]+$/ || port + 0 < 1 || port + 0 > 65535) continue
          endpoint = (addr == "::1" ? "[::1]" : addr) ":" (port + 0)
          if (!seen[endpoint]++) {
            print endpoint
            if (++count >= 5) exit
          }
        }
      }'
  }
  if [ "$NOUSEPS" ]; then
    print_ps | grep -v 'sed-Es' | sed -${E} "s,$Wfolders,${SED_RED},g" | sed -${E} "s,$sh_usrs,${SED_LIGHT_CYAN}," | sed -${E} "s,$nosh_usrs,${SED_BLUE}," | sed -${E} "s,$rootcommon,${SED_GREEN}," | sed -${E} "s,$knw_usrs,${SED_GREEN}," | sed "s,$USER,${SED_LIGHT_MAGENTA}," | sed "s,root,${SED_RED}," | sed -${E} "s,$processesVB,${SED_RED_YELLOW},g" | sed "s,$processesB,${SED_RED}," | sed -${E} "s,$processesDump,${SED_RED},"
    pslist=$(print_ps)
  else
    (ps fauxwww || ps auxwww | sort ) 2>/dev/null | grep -v "\[" | grep -v "%CPU" | while read psline; do
      echo "$psline"  | sed -${E} "s,$Wfolders,${SED_RED},g" | sed -${E} "s,$sh_usrs,${SED_LIGHT_CYAN}," | sed -${E} "s,$nosh_usrs,${SED_BLUE}," | sed -${E} "s,$rootcommon,${SED_GREEN}," | sed -${E} "s,$knw_usrs,${SED_GREEN}," | sed "s,$USER,${SED_LIGHT_MAGENTA}," | sed "s,root,${SED_RED}," | sed -${E} "s,$processesVB,${SED_RED_YELLOW},g" | sed "s,$processesB,${SED_RED}," | sed -${E} "s,$processesDump,${SED_RED},"
      if [ "$(command -v capsh || echo -n '')" ] && ! echo "$psline" | grep -q "root"; then
        cpid=$(echo "$psline" | awk '{print $2}')
        caphex=0x"$(cat /proc/$cpid/status 2> /dev/null | grep CapEff | awk '{print $2}')"
        if [ "$caphex" ] && [ "$caphex" != "0x" ] && echo "$caphex" | grep -qv '0x0000000000000000'; then
          printf "  └─(${DG}Caps${NC}) "; capsh --decode=$caphex 2>/dev/null | grep -v "WARNING:" | sed -${E} "s,$capsB,${SED_RED},g"
        fi
      fi
    done
    pslist=$(ps auxwww)
    echo ""
  fi
  # Jupyter terminals and kernels run as the server account. Report only
  # cross-user instances; do not print authentication values a second time.
  if [ ! "$MACPEAS" ] && command -v ps >/dev/null 2>&1; then
    jupyter_process_cues=$(ps -eww -o pid=,uid=,args= 2>/dev/null | awk -v my_uid="$(id -u 2>/dev/null)" '
      {
        pid = $1; uid = $2
        if (pid !~ /^[0-9]+$/ || uid !~ /^[0-9]+$/ || uid == my_uid) next
        cmd = $0
        sub(/^[[:space:]]*[0-9]+[[:space:]]+[0-9]+[[:space:]]+/, "", cmd)
        if (cmd !~ /(^|[[:space:]\/])jupyter(-lab|-notebook|-server)?([[:space:]]|$)/ &&
            cmd !~ /-m[[:space:]]+jupyter(lab|_lab|_server|_notebook)?([[:space:]]|$)/) next
        auth = (cmd ~ /--(ServerApp|NotebookApp)\.(token|password)[[:space:]]*=/ ||
                cmd ~ /(^|[[:space:]])JUPYTER_TOKEN=/)
        printf "PID %s (UID %s): Jupyter%s\n", pid, uid,
               auth ? " - authentication setting visible in process arguments" : ""
        if (++count >= 10) exit
      }
    ')
    if [ -n "$jupyter_process_cues" ]; then
      print_2title "Jupyter running as another user (review local access)" "T1552.001"
      printf '%s\n' "$jupyter_process_cues"
      printf '%s\n' 'Check readable systemd unit/environment files and local listeners; a usable token or disabled authentication can allow terminal/kernel execution as the service account.'
      echo ""
    fi
  fi
  office_uno_sockets=$(check_privileged_office_uno_sockets)
  if [ -n "$office_uno_sockets" ]; then
    print_2title "Privileged office automation sockets" "T1068"
    printf 'Root-owned process command advertises a LibreOffice/OpenOffice UNO acceptor at:\n%s\n' "$office_uno_sockets"
    print_info "Confirm the listener and local access; a reachable UNO API can act with the office process identity: https://book.hacktricks.wiki/en/linux-hardening/processes-crontab-systemd-dbus/process-enumeration-and-service-paths.html#privileged-office-automation-sockets"
  fi
  spice_console_endpoints=$(check_unauthenticated_spice_console)
  if [ -n "$spice_console_endpoints" ]; then
    print_2title "Loopback guest-console review candidates" "T1057"
    printf 'QEMU command line advertises SPICE without ticket authentication at:\n%s\n' "$spice_console_endpoints"
    print_info "Verify the live listener, local access, and guest login/boot policy. Guest-console control is not host-root access: https://book.hacktricks.wiki/en/linux-hardening/processes-crontab-systemd-dbus/process-enumeration-and-service-paths.html"
  fi
  checkRootWritableProcessPaths
  # Additional checks for each process
  print_2title "Processes with unusual configurations" "T1057"
  for pid in $(find /proc -maxdepth 1 -regex '/proc/[0-9]+' -printf "%f\n" 2>/dev/null); do
    # Skip if process doesn't exist or we can't access it
    [ ! -d "/proc/$pid" ] && continue
    # Get process user and command
    proc_user=$(stat -c '%U' "/proc/$pid" 2>/dev/null)
    proc_cmd=$(cat "/proc/$pid/cmdline" 2>/dev/null | tr '\0' ' ' | head -c 100)
    [ -z "$proc_user" ] || [ -z "$proc_cmd" ] && continue
    # Run all checks and collect findings
    sec_findings=$(check_security_context "$pid" "$proc_user" "$proc_cmd")
    mount_findings=$(check_mount_namespace "$pid" "$proc_user" "$proc_cmd")
    fd_findings=$(check_file_descriptors "$pid" "$proc_user" "$proc_cmd")
    env_findings=$(check_env_vars "$pid" "$proc_user" "$proc_cmd")
    # If any findings exist, print process info and findings
    if [ -n "$env_findings" ] || [ -n "$sec_findings" ] || [ -n "$mount_findings" ] || [ -n "$fd_findings" ]; then
      echo "Process $pid ($proc_user) - $proc_cmd"
      [ -n "$env_findings" ] && echo "$env_findings"
      [ -n "$sec_findings" ] && echo "$sec_findings"
      [ -n "$mount_findings" ] && echo "$mount_findings"
      [ -n "$fd_findings" ] && echo "$fd_findings"
      echo ""
    fi
  done
  echo ""
fi

fi

if check_mitre_filter "T1003.007"; then
if ! [ "$SEARCH_IN_FOLDER" ]; then
  print_2title "Processes with credentials in memory (root req)" "T1003.007"
  print_info "https://book.hacktricks.wiki/en/linux-hardening/linux-basics/linux-privilege-escalation/index.html#credentials-from-process-memory"
  # Common credential-storing processes
  cred_processes="gdm-password gnome-keyring-daemon lightdm vsftpd apache2 sshd: mysql postgres redis-server mongod memcached elasticsearch jenkins tomcat nginx php-fpm supervisord vncserver xrdp teamviewer"
  # Check for credential-storing processes
  for proc in $cred_processes; do
    if echo "$pslist" | grep -q "$proc"; then
      echo "$proc process found (dump creds from memory as root)" | sed "s,$proc,${SED_RED},"
    else
      echo_not_found "$proc"
    fi
  done
  # Check for processes with open handles to credential files
  echo ""
  print_2title "Opened Files by processes" "T1003.007"
  for pid in $(find /proc -maxdepth 1 -regex '/proc/[0-9]+' -printf "%f\n" 2>/dev/null); do
    # Skip if process doesn't exist or we can't access it
    [ ! -d "/proc/$pid" ] && continue
    [ ! -r "/proc/$pid/fd" ] && continue
    # Get process user and command
    proc_user=$(stat -c '%U' "/proc/$pid" 2>/dev/null)
    proc_cmd=$(cat "/proc/$pid/cmdline" 2>/dev/null | tr '\0' ' ' | head -c 100)
    [ -z "$proc_user" ] || [ -z "$proc_cmd" ] && continue
    # Skip processes that start with "sed " or contain "linpeas.sh"
    echo "$proc_cmd" | grep -q "^sed " && continue
    echo "$proc_cmd" | grep -q "linpeas.sh" && continue
    # Variable to store unique files for this process
    seen_files=""
    found_cred_files=""
    # Check for open credential files
    for fd in /proc/$pid/fd/*; do
      [ ! -e "$fd" ] && continue
      fd_target=$(readlink "$fd" 2>/dev/null)
      [ -z "$fd_target" ] && continue
      [ "$fd_target" = "/dev/null" ] && continue
      echo "$fd_target" | grep -q "^socket:" && continue
      echo "$fd_target" | grep -q "^anon_inode:" && continue
      # Only add if not already seen (using case to check)
      case " $seen_files " in
        *" $fd_target "*) continue ;;
        *)
          seen_files="$seen_files $fd_target"
          if [ -z "$found_cred_files" ]; then
            echo "Process $pid ($proc_user) - $proc_cmd"
            echo "  └─ Has open files:"
            found_cred_files="yes"
          fi
          echo "    └─ $fd_target"
          ;;
      esac
    done
  done | sed -${E} "s,\.(pem|key|cred|db|sqlite|conf|cnf|ini|env|secret|token|auth|passwd|shadow)$,\1${SED_RED},g" | sed -${E} "s,$sh_usrs,${SED_LIGHT_CYAN}," | sed -${E} "s,$nosh_usrs,${SED_BLUE}," | sed -${E} "s,$rootcommon,${SED_GREEN}," | sed -${E} "s,$knw_usrs,${SED_GREEN}," | sed "s,$USER,${SED_LIGHT_MAGENTA}," | sed "s,root,${SED_RED}," | sed -${E} "s,$processesVB,${SED_RED_YELLOW},g" | sed "s,$processesB,${SED_RED}," | sed -${E} "s,$processesDump,${SED_RED},"
  # Check for processes with memory-mapped files that might contain credentials
  echo ""
  print_2title "Processes with memory-mapped credential files" "T1003.007"
  for pid in $(find /proc -maxdepth 1 -regex '/proc/[0-9]+' -printf "%f\n" 2>/dev/null); do
    # Skip if process doesn't exist or we can't access it
    [ ! -d "/proc/$pid" ] && continue
    [ ! -r "/proc/$pid/maps" ] && continue
    # Get process user and command
    proc_user=$(stat -c '%U' "/proc/$pid" 2>/dev/null)
    proc_cmd=$(cat "/proc/$pid/cmdline" 2>/dev/null | tr '\0' ' ' | head -c 100)
    [ -z "$proc_user" ] || [ -z "$proc_cmd" ] && continue
    # Check for memory-mapped files that might contain credentials
    cred_files=$(grep -E '\.(pem|key|cred|db|sqlite|conf|cnf|ini|env|secret|token|auth|passwd|shadow)$' "/proc/$pid/maps" 2>/dev/null)
    if [ -n "$cred_files" ]; then
      echo "Process $pid ($proc_user) - $proc_cmd"
      echo "  └─ Has memory-mapped credential files:"
      echo "$cred_files" | while read -r line; do
        filename=$(echo "$line" | sed "s,.*/\(.*\),\1,")
        echo "    └─ $filename"
      done
    fi
  done
  echo ""
fi

fi

if check_mitre_filter "T1574,T1554"; then
if ! [ "$SEARCH_IN_FOLDER" ]; then
  if [ "$NOUSEPS" ]; then
    print_2title "Binary processes permissions (non 'root root' and not belonging to current user)" "T1574,T1554"
    print_info "https://book.hacktricks.wiki/en/linux-hardening/processes-crontab-systemd-dbus/process-enumeration-and-service-paths.html#map-processes-and-ownership"
    # Get list of writable binaries
    binW=""
    for pid in $(find /proc -maxdepth 1 -regex '/proc/[0-9]+' -printf "%f\n" 2>/dev/null); do
      # Skip if process doesn't exist or we can't access it
      [ ! -r "/proc/$pid/exe" ] && continue
      # Get binary path
      bpath=$(readlink "/proc/$pid/exe" 2>/dev/null)
      [ -z "$bpath" ] && continue
      # Check if binary is writable
      if [ -w "$bpath" ]; then
        if [ -z "$binW" ]; then
          binW="$bpath"
        else
          binW="$binW|$bpath"
        fi
      fi
    done
    # Get and display binary permissions
    for pid in $(find /proc -maxdepth 1 -regex '/proc/[0-9]+' -printf "%f\n" 2>/dev/null); do
      # Skip if process doesn't exist or we can't access it
      [ ! -r "/proc/$pid/exe" ] && continue
      # Get binary path
      bpath=$(readlink "/proc/$pid/exe" 2>/dev/null)
      [ -z "$bpath" ] && continue
      # Display binary permissions if file exists
      if [ -e "$bpath" ]; then
        ls -la "$bpath" 2>/dev/null
      fi
    done | grep -Ev "\sroot\s+root" | grep -v " $USER " | sed -${E} "s,$Wfolders,${SED_RED_YELLOW},g" | sed -${E} "s,$binW,${SED_RED_YELLOW},g" | sed -${E} "s,$sh_usrs,${SED_RED}," | sed -${E} "s,$nosh_usrs,${SED_BLUE}," | sed -${E} "s,$knw_usrs,${SED_GREEN}," | sed "s,$USER,${SED_RED}," | sed "s,root,${SED_GREEN},"
    echo ""
  fi
fi

fi

if check_mitre_filter "T1134.004"; then
if ! [ "$SEARCH_IN_FOLDER" ] && ! [ "$NOUSEPS" ]; then
  print_2title "Processes whose PPID belongs to a different user (not root)" "T1134.004"
  print_info "You will know if a user can somehow spawn processes as a different user"
  # Function to get user by PID using /proc
  get_user_by_pid() {
    if [ -r "/proc/$1/status" ]; then
      grep "^Uid:" "/proc/$1/status" 2>/dev/null | awk '{print $2}'
    fi
  }
  # Function to get username by UID
  get_username_by_uid() {
    if [ -r "/etc/passwd" ]; then
      grep "^[^:]*:[^:]*:$1:" "/etc/passwd" 2>/dev/null | cut -d: -f1
    fi
  }
  # Find processes with PPID and user info, then filter those where PPID's user is different from the process's user
  for pid in $(find /proc -maxdepth 1 -regex '/proc/[0-9]+' -printf "%f\n" 2>/dev/null); do
    # Skip if process doesn't exist or we can't access it
    [ ! -r "/proc/$pid/status" ] && continue
    # Get process user
    user_uid=$(get_user_by_pid "$pid")
    [ -z "$user_uid" ] && continue
    user=$(get_username_by_uid "$user_uid")
    [ -z "$user" ] && continue
    # Get PPID
    ppid=$(grep "^PPid:" "/proc/$pid/status" 2>/dev/null | awk '{print $2}')
    [ -z "$ppid" ] || [ "$ppid" = "0" ] && continue
    # Get PPID user
    ppid_uid=$(get_user_by_pid "$ppid")
    [ -z "$ppid_uid" ] && continue
    ppid_user=$(get_username_by_uid "$ppid_uid")
    [ -z "$ppid_user" ] && continue
    # Check if users are different and PPID user is not root
    if [ "$user" != "$ppid_user" ] && [ "$ppid_user" != "root" ]; then
      echo "Proc $pid with ppid $ppid is run by user $user but the ppid user is $ppid_user" | sed -${E} "s,$sh_usrs,${SED_LIGHT_CYAN}," | sed "s,$USER,${SED_LIGHT_MAGENTA}," | sed -${E} "s,$nosh_usrs,${SED_BLUE}," | sed "s,root,${SED_RED},"
    fi
  done
  echo ""
fi

fi

if check_mitre_filter "T1083"; then
if ! [ "$SEARCH_IN_FOLDER" ]; then
  if ! [ "$IAMROOT" ]; then
    print_2title "Files opened by processes belonging to other users" "T1083"
    print_info "This is usually empty because of the lack of privileges to read other user processes information"
    # Function to get username by UID
    get_username_by_uid() {
      if [ -r "/etc/passwd" ]; then
        grep "^[^:]*:[^:]*:$1:" "/etc/passwd" 2>/dev/null | cut -d: -f1
      fi
    }
    # Check each process
    for pid in $(find /proc -maxdepth 1 -regex '/proc/[0-9]+' -printf "%f\n" 2>/dev/null); do
      # Skip if process doesn't exist or we can't access it
      [ ! -r "/proc/$pid/status" ] && continue
      [ ! -r "/proc/$pid/fd" ] && continue
      # Get process user
      user_uid=$(grep "^Uid:" "/proc/$pid/status" 2>/dev/null | awk '{print $2}')
      [ -z "$user_uid" ] && continue
      user=$(get_username_by_uid "$user_uid")
      [ -z "$user" ] && continue
      # Skip if process belongs to current user
      [ "$user" = "$USER" ] && continue
      # Get process command
      cmd=$(cat "/proc/$pid/cmdline" 2>/dev/null | tr '\0' ' ' | head -c 100)
      [ -z "$cmd" ] && continue
      # Check file descriptors
      for fd in /proc/$pid/fd/*; do
        [ ! -e "$fd" ] && continue
        fd_target=$(readlink "$fd" 2>/dev/null)
        [ -z "$fd_target" ] && continue
        # Skip if target doesn't exist or is a special file
        [ ! -e "$fd_target" ] && continue
        case "$fd_target" in
          /dev/*|/proc/*|/sys/*) continue ;;
        esac
        echo "Process $pid ($user) - $cmd"
        echo "  └─ Has open file: $fd_target" | sed -${E} "s,$sh_usrs,${SED_LIGHT_CYAN}," | sed "s,$USER,${SED_LIGHT_MAGENTA}," | sed -${E} "s,$nosh_usrs,${SED_BLUE}," | sed "s,root,${SED_RED},"
      done
    done
    echo ""
  fi
fi

fi

if check_mitre_filter "T1057"; then
if ! [ "$SEARCH_IN_FOLDER" ]; then
  if ! [ "$FAST" ] && ! [ "$SUPERFAST" ]; then
    print_2title "Different processes executed during 1 min (interesting is low number of repetitions)" "T1057"
    print_info "https://book.hacktricks.wiki/en/linux-hardening/processes-crontab-systemd-dbus/cron-and-systemd-timers.html#observe-short-lived-work"
    temp_file=$(mktemp)
    if [ "$(ps -e -o user,command 2>/dev/null)" ]; then 
      for i in $(seq 1 1210); do 
        ps -e -o user,command >> "$temp_file" 2>/dev/null; sleep 0.05; 
      done;
      sort "$temp_file" 2>/dev/null | uniq -c | grep -v "\[" | sed '/^.\{200\}./d' | sort -r -n | grep -E -v "\s*[1-9][0-9][0-9][0-9]" | sed -${E} "s,$Wfolders,${SED_RED},g" | sed -${E} "s,$sh_usrs,${SED_LIGHT_CYAN}," | sed "s,$USER,${SED_LIGHT_MAGENTA}," | sed -${E} "s,$nosh_usrs,${SED_BLUE}," | sed "s,root,${SED_RED},"; 
      rm "$temp_file";
    fi
    echo ""
  fi
fi

fi

if check_mitre_filter "T1053.003"; then
# Inspect only conventional installed script paths for the old slapper loop
# assignment defect. Never run the script or inspect its temporary-file inputs.
cron_chkrootkit_static_probe() (
  if [ "$#" -eq 0 ]; then
    set -- /usr/sbin/chkrootkit /usr/bin/chkrootkit
  fi
  for chkrootkit_file do
    [ ! -L "$chkrootkit_file" ] && [ -f "$chkrootkit_file" ] && [ -r "$chkrootkit_file" ] || continue
    chkrootkit_size=$(dd if="$chkrootkit_file" bs=65537 count=1 2>/dev/null | wc -c | tr -d '[:space:]') || continue
    case "$chkrootkit_size" in ''|*[!0-9]*) continue ;; esac
    [ "$chkrootkit_size" -gt 0 ] && [ "$chkrootkit_size" -le 65536 ] || continue
    chkrootkit_match=$(dd if="$chkrootkit_file" bs=65536 count=1 2>/dev/null | LC_ALL=C awk '
      NR > 256 { exit }
      /^[[:space:]]*slapper[[:space:]]*\([[:space:]]*\)[[:space:]]*\{/ {
        inside = 1; start = NR; files = loop = guard_line = 0; next
      }
      inside && NR - start > 80 { inside = 0 }
      inside {
        if ($0 ~ /^[[:space:]]*}[[:space:]]*$/) inside = 0
        if (loop && $0 ~ /^[[:space:]]*done([[:space:]]|$)/) { loop = guard_line = 0 }
        if ($0 ~ /^[[:space:]]*SLAPPER_FILES=/ && $0 ~ /tmp\//) files = 1
        if ($0 ~ /^[[:space:]]*for[[:space:]]+i[[:space:]]+in[[:space:]]+\$\{SLAPPER_FILES\};[[:space:]]*do/) loop = 1
        if (loop && $0 ~ /^[[:space:]]*if[[:space:]]+\[[[:space:]]+-f[[:space:]]+\$\{i\}[[:space:]]+\][[:space:]]*;?[[:space:]]*then/) guard_line = NR
        if (files && loop && guard_line && NR - guard_line <= 3 &&
            $0 ~ /^[[:space:]]*file_port=\$file_port[[:space:]]+\$i[[:space:]]*(#.*)?$/) {
          print "yes"; exit
        }
      }
    ' 2>/dev/null) || continue
    [ "$chkrootkit_match" = yes ] || continue
    printf 'Checker script review candidate: %s has an unquoted slapper-loop assignment; verify root scheduling, writable executable temporary path, mount policy and installed patch state.\n' "$chkrootkit_file"
    break
  done
)
# Correlate a literal root cron playbook glob with a directory the current
# user can populate. Never expand the glob, inspect playbooks, or run Ansible.
cron_ansible_glob_probe() {
  cron_ansible_timeout=$(command -v timeout 2>/dev/null || command -v gtimeout 2>/dev/null)
  [ -n "$cron_ansible_timeout" ] || return 0
  "$cron_ansible_timeout" 3 sh -c '
    LC_ALL=C; export LC_ALL
    [ "$(id -u 2>/dev/null)" != 0 ] || exit 0
    files=0
    for cron_file do
      files=$((files + 1))
      if [ "$files" -gt 12 ]; then
        echo "Cron Ansible playbook correlation: incomplete (12-file limit)."
        break
      fi
      [ -f "$cron_file" ] && [ -r "$cron_file" ] && [ ! -L "$cron_file" ] || continue
      schedule=$(dd if="$cron_file" bs=8193 count=1 2>/dev/null) || continue
      if [ "${#schedule}" -ge 8192 ]; then
        echo "Cron Ansible playbook correlation: incomplete (8 KiB schedule limit): $cron_file"
        continue
      fi
      case "$schedule" in *ansible-parallel*) ;; *) continue ;; esac
      case "$cron_file" in */spool/cron/root|*/spool/cron/crontabs/root) spool=1 ;; *) spool=0 ;; esac
      printf "%s\n" "$schedule" | awk -v spool="$spool" '\''
        NR > 32 || length($0) > 512 { partial = 1; next }
        /^[[:space:]]*(#|$)/ { next }
        {
          for (i = 1; i <= 5; i++) if ($i !~ /^[0-9*,\/-]+$/) next
          if (spool) {
            if (NF != 7) next
            helper = $6; glob = $7
          } else {
            if (NF != 8 || $6 != "root") next
            helper = $7; glob = $8
          }
          if (helper !~ /^\/[A-Za-z0-9_.\/+\-]+\/ansible-parallel$/ ||
              glob !~ /^\/[A-Za-z0-9_.\/+\-]+\/\*\.(yml|yaml)$/) next
          print glob "|" NR
        }
        END { if (partial) print "#PARTIAL" }
      '\'' | while IFS="|" read -r glob schedule_line; do
        if [ "$glob" = "#PARTIAL" ]; then
          echo "Cron Ansible playbook correlation: incomplete (line/column limit): $cron_file"
          continue
        fi
        case "$glob" in *"/../"*|*"/./"*|*"//"*) continue ;; esac
        dir=${glob%/*}
        [ -d "$dir" ] && [ -w "$dir" ] && [ -x "$dir" ] || continue
        path=; rest=${dir#/}; safe=1; depth=0
        while [ -n "$rest" ]; do
          depth=$((depth + 1))
          [ "$depth" -le 16 ] || { safe=0; break; }
          part=${rest%%/*}; path=$path/$part
          if [ -L "$path" ]; then safe=0; break; fi
          case "$rest" in */*) rest=${rest#*/} ;; *) rest= ;; esac
        done
        [ "$safe" -eq 1 ] || continue
        mode=$(ls -ld "$dir" 2>/dev/null) || continue
        mode=${mode%% *}
        case $(printf "%s" "$mode" | cut -c 10) in t|T) continue ;; esac
        echo "Cron Ansible playbook review candidate: $cron_file:$schedule_line (root cron passes $glob to helper; current user can create entries in $dir; verify helper behavior, ACLs, mount policy, and scheduler state)"
      done
    done
  ' sh "$@"
  cron_ansible_status=$?
  case "$cron_ansible_status" in
    124|137) echo "Cron Ansible playbook correlation: incomplete (3-second timeout)." ;;
    0) ;;
    *) echo "Cron Ansible playbook correlation: incomplete (metadata error)." ;;
  esac
}
# A read-only cron script may still be replaceable through its parent. Inspect
# only literal script paths in a few visible cron files; no job is run.
cron_replaceable_script_probe() {
  cron_replace_timeout=$(command -v timeout 2>/dev/null || command -v gtimeout 2>/dev/null)
  [ -n "$cron_replace_timeout" ] || return 0
  "$cron_replace_timeout" 3 sh -c '
    LC_ALL=C; export LC_ALL
    current_uid=$(id -u 2>/dev/null) || exit 1
    files=0
    for cron_file do
      files=$((files + 1))
      if [ "$files" -gt 12 ]; then
        echo "Cron script replacement review incomplete (12-file limit)."
        break
      fi
      [ -f "$cron_file" ] && [ -r "$cron_file" ] && [ ! -L "$cron_file" ] || continue
      schedule=$(dd if="$cron_file" bs=8193 count=1 2>/dev/null) || continue
      if [ "${#schedule}" -ge 8192 ]; then
        echo "Cron script replacement review incomplete (8 KiB schedule limit): $cron_file"
        continue
      fi
      spool_owner=
      case "$cron_file" in */spool/cron/root|*/spool/cron/crontabs/root) spool_owner=root ;; esac
      printf "%s\n" "$schedule" | awk -v owner="$spool_owner" '\''
        NR > 32 || length($0) > 512 { partial = 1; next }
        /^[[:space:]]*(#|$)/ { next }
        {
          for (i = 1; i <= 5; i++) if ($i !~ /^[0-9*,\/-]+$/) next
          n = NF
          if (n >= 10 && $(n-2) == ">>" && $(n-1) == "/dev/null" && $n == "2>&1") n -= 3
          if (owner == "") {
            runas = $6; shell = $7; script = $8
            kind = (NF == 8 ? "shell" : (NF == 7 ? "php" : ""))
            if (kind == "php") script = $7
            if ((shell == "php" || shell == "/usr/bin/php" || shell == "/bin/php") &&
                (n == 8 || n == 9) && (n == 8 || $9 ~ /^[A-Za-z0-9_.:-]+$/)) {
              kind = "php_cli"; script = $8
            }
          } else {
            runas = owner; shell = $6; script = $7
            kind = (NF == 7 ? "shell" : (NF == 6 ? "php" : ""))
            if (kind == "php") script = $6
            if ((shell == "php" || shell == "/usr/bin/php" || shell == "/bin/php") &&
                (n == 7 || n == 8) && (n == 7 || $8 ~ /^[A-Za-z0-9_.:-]+$/)) {
              kind = "php_cli"; script = $7
            }
          }
          if (runas !~ /^[A-Za-z_][A-Za-z0-9_-]*$/ || kind == "" ||
              (kind == "shell" && shell != "/bin/sh" && shell != "/usr/bin/sh" &&
               shell != "/bin/bash" && shell != "/usr/bin/bash") ||
              script !~ /^\/[A-Za-z0-9_\/.+-]+$/) next
          print runas "|" script "|" NR "|" kind
        }
        END { if (partial) print "#PARTIAL" }
      '\'' | while IFS="|" read -r runas script schedule_line kind; do
        if [ "$runas" = "#PARTIAL" ]; then
          echo "Cron script replacement review incomplete (line/column limit): $cron_file"
          continue
        fi
        case "$script" in *"/../"*|*"/.."|*"/./"*|*"/."|*"//"*) continue ;; esac
        owner_uid=$(id -u "$runas" 2>/dev/null) || continue
        [ "$owner_uid" != "$current_uid" ] || continue
        if [ "$kind" = php_cli ]; then
          [ "$owner_uid" = 0 ] && [ -f "$script" ] && [ -r "$script" ] &&
            [ -w "$script" ] && [ ! -L "$script" ] || continue
          path=; rest=${script#/}; safe=1
          while [ -n "$rest" ]; do
            part=${rest%%/*}; path=$path/$part
            if [ -L "$path" ]; then safe=0; break; fi
            case "$rest" in */*) rest=${rest#*/} ;; *) rest= ;; esac
          done
          [ "$safe" -eq 1 ] || continue
          echo "Cron PHP script review candidate: $cron_file:$schedule_line (root PHP runs current-user-writable $script; verify scheduler state, script identity, ACLs, and mount policy)"
          continue
        fi
        if [ "$kind" = php ]; then
          [ "$owner_uid" = 0 ] && [ -f "$script" ] && [ -r "$script" ] && [ ! -L "$script" ] || continue
          path=; rest=${script#/}; safe=1
          while [ -n "$rest" ]; do
            part=${rest%%/*}; path=$path/$part
            if [ -L "$path" ]; then safe=0; break; fi
            case "$rest" in */*) rest=${rest#*/} ;; *) rest= ;; esac
          done
          [ "$safe" -eq 1 ] || continue
          wrapper_text=$(dd if="$script" bs=4097 count=1 2>/dev/null) || continue
          [ "${#wrapper_text}" -lt 4096 ] || continue
          printf "%s\n" "$wrapper_text" | awk "NR == 1 { exit !(/^#!\\/(usr\\/bin|bin)\\/php([0-9.]*)?([[:space:]]|$)/) }" || continue
          printf "%s\n" "$wrapper_text" | awk '\''
            NR > 32 || length($0) > 512 { next }
            {
              line = $0
              sub(/^[ \t]*/, "", line)
              if (line !~ /^exec[ \t]*\(/) next
              sub(/^exec[ \t]*\([ \t]*/, "", line)
              quote = substr(line, 1, 1)
              if (quote != sprintf("%c", 39) && quote != "\"") next
              line = substr(line, 2)
              if (match(line, /^\/[A-Za-z0-9_\/.+-]+/) == 0) next
              helper = substr(line, 1, RLENGTH)
              tail = substr(line, RLENGTH + 1)
              if (substr(tail, 1, 1) != quote) next
              tail = substr(tail, 2)
              if (tail !~ /^[ \t]*\)[ \t]*;[ \t]*(\/\/.*)?$/) next
              if (++found > 2) exit
              print helper
            }
          '\'' | while IFS= read -r helper; do
            case "$helper" in *"/../"*|*"/.."|*"/./"*|*"/."|*"//"*) continue ;; esac
            [ ! -e "$helper" ] && [ ! -L "$helper" ] || continue
            parent=${helper%/*}; [ -n "$parent" ] || parent=/
            [ -d "$parent" ] && [ -w "$parent" ] && [ -x "$parent" ] || continue
            path=; rest=${helper#/}; safe=1
            while [ -n "$rest" ]; do
              part=${rest%%/*}; path=$path/$part
              if [ -L "$path" ]; then safe=0; break; fi
              case "$rest" in */*) rest=${rest#*/} ;; *) rest= ;; esac
            done
            [ "$safe" -eq 1 ] || continue
            mode=$(ls -ld "$parent" 2>/dev/null) || continue
            mode=${mode%% *}
            case $(printf "%s" "$mode" | cut -c 10) in t|T) continue ;; esac
            echo "Cron PHP helper review candidate: $cron_file:$schedule_line (root script $script calls absent $helper in current-user-writable $parent; verify scheduler state, PHP policy, ACLs, and mount policy)"
          done
          continue
        fi
        [ -f "$script" ] && [ ! -L "$script" ] && [ ! -w "$script" ] || continue
        parent=${script%/*}; [ -n "$parent" ] || parent=/
        [ -d "$parent" ] && [ -w "$parent" ] && [ -x "$parent" ] || continue
        path=; rest=${script#/}; safe=1
        while [ -n "$rest" ]; do
          part=${rest%%/*}; path=$path/$part
          if [ -L "$path" ]; then safe=0; break; fi
          case "$rest" in */*) rest=${rest#*/} ;; *) rest= ;; esac
        done
        [ "$safe" -eq 1 ] || continue
        mode=$(ls -ld "$parent" 2>/dev/null) || continue
        mode=${mode%% *}
        sticky=$(printf "%s" "$mode" | cut -c 10)
        case "$sticky" in t|T) continue ;; esac
        echo "Cron script replacement review candidate: $cron_file:$schedule_line ($runas runs $script; current user can replace its directory entry in $parent; verify ACLs, mount policy, and scheduler state)"
      done
    done
  ' sh "$@"
  cron_replace_status=$?
  case "$cron_replace_status" in
    124|137) echo 'Cron script replacement review incomplete (3-second timeout).' ;;
    0) ;;
    *) echo 'Cron script replacement review incomplete (metadata error).' ;;
  esac
}
# Inspect only literal, visible root cron commands. The whole probe has a wall-clock
# limit; without timeout, filesystem metadata on an unresponsive mount is unbounded.
cron_log_input_probe() {
  cron_log_timeout=$(command -v timeout 2>/dev/null || command -v gtimeout 2>/dev/null)
  if [ -z "$cron_log_timeout" ]; then
    echo "Cron log input correlation: unknown (timeout unavailable)."
    return
  fi
  "$cron_log_timeout" 3 sh -c '
    LC_ALL=C; export LC_ALL
    files=0
    for cron_file do
      files=$((files + 1))
      if [ "$files" -gt 8 ]; then
        echo "Cron log input correlation: truncated at 8 cron files."
        break
      fi
      if [ -L "$cron_file" ] || [ ! -f "$cron_file" ] || [ ! -r "$cron_file" ]; then
        continue
      fi
      prefix=$(dd if="$cron_file" bs=8193 count=1 2>/dev/null) || continue
      if [ "${#prefix}" -ge 8192 ]; then
        echo "Cron log input correlation: skipped oversized cron file: $cron_file"
        continue
      fi
      case "$cron_file" in
        */root) spool=1 ;;
        *) spool=0 ;;
      esac
      printf "%s\n" "$prefix" | awk -v spool="$spool" '\''NR <= 16 && length($0) <= 512 && $0 !~ /^[[:space:]]*(#|$)/ {
        for (i=1; i<=5; i++) if ($i !~ /^[0-9*,\/-]+$/) next
        if (spool == 0) {
          if (NF != 9 || $6 != "root") next
          bash=$7; script=$8; input=$9
        } else {
          if (NF != 8) next
          bash=$6; script=$7; input=$8
        }
        if (bash != "/bin/bash" && bash != "/usr/bin/bash") next
        if (script !~ /^\/[A-Za-z0-9_.\/-]+$/ || input !~ /^\/[A-Za-z0-9_.\/-]+\.log$/) next
        print bash "|" script "|" input
      }
      END { if (NR > 16) print "#TRUNCATED" }'\'' | while IFS="|" read -r bash script log; do
        if [ "$bash" = "#TRUNCATED" ]; then
          echo "Cron log input correlation: truncated at 16 lines: $cron_file"
          continue
        fi
        case "$script:$log" in *"/../"*|*"/..:"*|*"/./"*|*"//"*) continue ;; esac
        [ -L "$script" ] && continue
        [ -f "$script" ] && [ -r "$script" ] || continue
        [ -L "$log" ] && continue
        [ -f "$log" ] || continue
        parent=${log%/*}; [ -n "$parent" ] || parent=/
        [ -d "$parent" ] || continue
        # Reject symlinks in every ancestor; metadata otherwise describes a
        # different path than the one the privileged command would resolve.
        safe=1
        for candidate in "$script" "$log"; do
          path=; rest=${candidate#/}
          while [ -n "$rest" ]; do
            part=${rest%%/*}; path=$path/$part
            if [ -L "$path" ]; then safe=0; break; fi
            case "$rest" in */*) rest=${rest#*/} ;; *) rest= ;; esac
          done
          [ "$safe" -eq 1 ] || break
        done
        [ "$safe" -eq 1 ] || continue
        route=
        if [ -w "$log" ]; then route="current user can write input file"; fi
        if [ -w "$parent" ] && [ -x "$parent" ]; then
          mode=$(ls -ld "$parent" 2>/dev/null) || continue
          mode=${mode%% *}
          sticky=$(printf "%s" "$mode" | cut -c 10)
          case "$sticky" in t|T) ;; *) route="current user can replace directory entry" ;; esac
        fi
        [ -n "$route" ] || continue
        echo "Cron log input review candidate: $cron_file"
        echo "  Root command: $bash $script $log"
        echo "  Input: $log ($route)"
        ls -ld "$parent" "$log" 2>/dev/null
        echo "  Metadata only; parser behavior and ACL/mount policy need review."
      done
    done
  ' sh "$@"
  cron_log_status=$?
  case "$cron_log_status" in
    124|137) echo "Cron log input correlation: timed out; visibility unknown." ;;
    0) ;;
    *) echo "Cron log input correlation: incomplete; visibility unknown." ;;
  esac
}
# Correlate a visible cron identity with one literal helper and a GNU tar glob.
# This intentionally recognizes only simple, adjacent `cd DIR` and `tar -cf
# ARCHIVE *` lines. Shell expansion, other archivers, and nested helpers need
# manual review; no scheduled command or archive operation is run here.
cron_tar_wildcard_probe() {
  cron_tar_timeout=$(command -v timeout 2>/dev/null || command -v gtimeout 2>/dev/null)
  if [ -z "$cron_tar_timeout" ]; then
    echo "Cron tar wildcard correlation: unknown (timeout unavailable)."
    return
  fi
  "$cron_tar_timeout" 5 sh -c '
    LC_ALL=C; export LC_ALL
    current_uid=$(id -u 2>/dev/null) || exit 1
    [ "$current_uid" -ne 0 ] || exit 0
    files=0
    for cron_file do
      files=$((files + 1))
      if [ "$files" -gt 12 ]; then
        echo "Cron tar wildcard correlation: unknown beyond 12 schedule files."
        break
      fi
      [ -f "$cron_file" ] && [ -r "$cron_file" ] && [ ! -L "$cron_file" ] || continue
      schedule=$(dd if="$cron_file" bs=8193 count=1 2>/dev/null) || continue
      if [ "${#schedule}" -ge 8192 ]; then
        echo "Cron tar wildcard correlation: unknown (oversized schedule: $cron_file)."
        continue
      fi
      spool_owner=
      case "$cron_file" in */spool/cron/*) spool_owner=${cron_file##*/} ;; esac
      printf "%s\n" "$schedule" | awk -v owner="$spool_owner" '\''
        NR > 32 { truncated=1; next }
        length($0) > 512 { truncated=1; next }
        /^[[:space:]]*(#|$)/ { next }
        {
          for (i=1; i<=5; i++) if ($i !~ /^[0-9*,\/-]+$/) next
          if (owner == "") {
            if (NF != 8) next
            runas=$6; interpreter=$7; helper=$8
          } else {
            if (NF != 7) next
            runas=owner; interpreter=$6; helper=$7
          }
          if (interpreter != "/bin/sh" && interpreter != "/usr/bin/sh" &&
              interpreter != "/bin/bash" && interpreter != "/usr/bin/bash") next
          if (helper ~ /^\/[A-Za-z0-9_.\/-]+$/) print runas "|" helper "|" NR
        }
        END { if (truncated) print "#TRUNCATED" }
      '\'' | while IFS="|" read -r runas helper schedule_line; do
        if [ "$runas" = "#TRUNCATED" ]; then
          echo "Cron tar wildcard correlation: unknown beyond schedule line/length cap: $cron_file."
          continue
        fi
        case "$runas" in ""|*[!A-Za-z0-9_-]*) continue ;; esac
        case "$helper" in *"/../"*|*"/.."|*"/./"*|*"/."|*"//"*) continue ;; esac
        owner_uid=$(id -u "$runas" 2>/dev/null) || continue
        [ "$owner_uid" != "$current_uid" ] || continue
        [ -f "$helper" ] && [ -r "$helper" ] && [ ! -L "$helper" ] || continue
        helper_text=$(dd if="$helper" bs=4097 count=1 2>/dev/null) || continue
        if [ "${#helper_text}" -ge 4096 ]; then
          echo "Cron tar wildcard correlation: unknown (oversized helper: $helper)."
          continue
        fi
        printf "%s\n" "$helper_text" | awk '\''
          NR > 24 { truncated=1; next }
          length($0) > 512 { truncated=1; next }
          /^[[:space:]]*(#|$)/ { next }
          {
            if (NF == 2 && $1 == "cd" && $2 ~ /^\/[A-Za-z0-9_.\/-]+$/) {
              dir=$2; next
            }
            if (dir != "" && NF == 4 &&
                ($1 == "tar" || $1 == "/usr/bin/tar" || $1 == "/bin/tar" || $1 == "gtar") &&
                $2 ~ /^-[A-Za-z]+$/ && $2 ~ /c/ && $2 ~ /f/ &&
                $3 ~ /^[A-Za-z0-9_.\/-]+$/ && $4 == "*") {
              print dir "|" $1 "|" NR
            }
            dir=""
          }
          END { if (truncated) print "#TRUNCATED" }
        '\'' | while IFS="|" read -r dir tar_cmd helper_line; do
          if [ "$dir" = "#TRUNCATED" ]; then
            echo "Cron tar wildcard correlation: unknown beyond helper line/length cap: $helper."
            continue
          fi
          case "$dir" in *"/../"*|*"/.."|*"/./"*|*"/."|*"//"*) continue ;; esac
          [ -d "$dir" ] && [ -w "$dir" ] && [ -x "$dir" ] && [ ! -L "$dir" ] || continue
          version=$($tar_cmd --version 2>/dev/null | awk '\''NR == 1 { print; exit }'\'')
          case "$version" in *"GNU tar"*) ;; *) continue ;; esac
          echo "Cron GNU tar wildcard review candidate: $cron_file:$schedule_line"
          echo "  Schedule owner: $runas (uid $owner_uid); helper: $helper:$helper_line"
          echo "  Working directory: $dir (current user can write and enter)"
          echo "  Command: $tar_cmd archive * (unquoted glob, no --); GNU tar version observed"
          echo "  Candidate only; execution context and file ownership need review."
        done
      done
    done
  ' sh "$@"
  cron_tar_status=$?
  case "$cron_tar_status" in
    124|137) echo "Cron tar wildcard correlation: timed out; visibility unknown." ;;
    0) ;;
    *) echo "Cron tar wildcard correlation: incomplete; visibility unknown." ;;
  esac
}
