if check_mitre_filter "T1543.001"; then
if ! [ "$SEARCH_IN_FOLDER" ]; then
  if [ "$MACPEAS" ]; then
    print_2title "Third party LaunchAgents & LaunchDemons" "T1543.001"
    print_info "https://book.hacktricks.wiki/en/macos-hardening/macos-auto-start-locations.html#launchd"
    print_info "Checking for privilege escalation vectors in LaunchAgents & LaunchDaemons:"
    print_info "1. Writable plist files"
    print_info "2. Writable program binaries"
    print_info "3. Environment variables with sensitive data"
    print_info "4. Unsafe program arguments"
    print_info "5. RunAtLoad with elevated privileges"
    print_info "6. KeepAlive with elevated privileges"
    # Function to check plist content for privilege escalation vectors
    check_plist_content() {
      local plist="$1"
      local findings=""
      # Check for environment variables
      if defaults read "$plist" EnvironmentVariables 2>/dev/null | grep -qE '(PASS|SECRET|KEY|TOKEN|CRED)'; then
        findings="${findings}ENV_VARS: Contains sensitive environment variables\n"
      fi
      # Check for RunAtLoad with elevated privileges
      if defaults read "$plist" RunAtLoad 2>/dev/null | grep -q "true"; then
        if [ -w "$plist" ]; then
          findings="${findings}RUN_AT_LOAD: Runs at load and plist is writable\n"
        fi
      fi
      # Check for KeepAlive with elevated privileges
      if defaults read "$plist" KeepAlive 2>/dev/null | grep -q "true"; then
        if [ -w "$plist" ]; then
          findings="${findings}KEEP_ALIVE: Keeps running and plist is writable\n"
        fi
      fi
      # Check for unsafe program arguments
      if defaults read "$plist" ProgramArguments 2>/dev/null | grep -qE '(sudo|su|chmod|chown|chroot|mount)'; then
        findings="${findings}UNSAFE_ARGS: Uses potentially dangerous program arguments\n"
      fi
      # Check for writable working directory
      if defaults read "$plist" WorkingDirectory 2>/dev/null | grep -qE '^/'; then
        local workdir=$(defaults read "$plist" WorkingDirectory 2>/dev/null)
        if [ -w "$workdir" ]; then
          findings="${findings}WRITABLE_WORKDIR: Working directory is writable\n"
        fi
      fi
      # If any findings, print them
      if [ -n "$findings" ]; then
        echo "Potential privilege escalation in: $plist"
        echo "$findings" | while read -r finding; do
          [ -n "$finding" ] && echo "  └─ $finding"
        done
      fi
    }
    # Check system and user LaunchAgents & LaunchDaemons
    for plist_dir in /Library/LaunchAgents/ /Library/LaunchDaemons/ ~/Library/LaunchAgents/ ~/Library/LaunchDaemons/ /System/Library/LaunchAgents/ /System/Library/LaunchDaemons/; do
      [ ! -d "$plist_dir" ] && continue
      echo "Checking $plist_dir..."
      find "$plist_dir" -name "*.plist" 2>/dev/null | while read -r plist; do
        # Check if plist is writable
        if [ -w "$plist" ]; then
          echo "Writable plist: $plist" | sed -${E} "s,.*,${SED_RED_YELLOW},"
        fi
        # Get program path
        program=""
        program=$(defaults read "$plist" Program 2>/dev/null)
        if ! [ "$program" ]; then
          program=$(defaults read "$plist" ProgramArguments 2>/dev/null | grep -Ev "^\(|^\)" | cut -d '"' -f 2)
        fi
        # Check if program is writable
        if [ -n "$program" ] && [ -w "$program" ]; then
          echo "Writable program: $program" | sed -${E} "s,.*,${SED_RED_YELLOW},"
          ls -l "$program" 2>/dev/null
        fi
        # Check plist content for privilege escalation vectors
        check_plist_content "$plist"
      done
    done
    echo ""
    print_2title "StartupItems" "T1543.001"
    print_info "https://book.hacktricks.wiki/en/macos-hardening/macos-auto-start-locations.html#startup-items"
    for startup_dir in /Library/StartupItems/ /System/Library/StartupItems/; do
      [ ! -d "$startup_dir" ] && continue
      echo "Checking $startup_dir..."
      find "$startup_dir" -type f -executable 2>/dev/null | while read -r startup_item; do
        if [ -w "$startup_item" ]; then
          echo "Writable startup item: $startup_item" | sed -${E} "s,.*,${SED_RED_YELLOW},"
          ls -l "$startup_item" 2>/dev/null
        fi
      done
    done
    echo ""
    print_2title "Login Items" "T1543.001"
    print_info "https://book.hacktricks.wiki/en/macos-hardening/macos-auto-start-locations.html#startup-items"
    osascript -e 'tell application "System Events" to get the name of every login item' 2>/dev/null | tr ", " "\n" | while read -r login_item; do
      if [ -n "$login_item" ]; then
        # Try to find the actual binary
        binary_path=$(mdfind "kMDItemDisplayName == '$login_item'" 2>/dev/null | head -n 1)
        if [ -n "$binary_path" ] && [ -w "$binary_path" ]; then
          echo "Writable login item binary: $binary_path" | sed -${E} "s,.*,${SED_RED_YELLOW},"
          ls -l "$binary_path" 2>/dev/null
        fi
      fi
    done
    echo ""
    print_2title "SPStartupItemDataType" "T1543.001"
    system_profiler SPStartupItemDataType 2>/dev/null | while read -r line; do
      if echo "$line" | grep -q "Location:"; then
        location=$(echo "$line" | cut -d: -f2- | xargs)
        if [ -w "$location" ]; then
          echo "Writable startup item location: $location" | sed -${E} "s,.*,${SED_RED_YELLOW},"
          ls -l "$location" 2>/dev/null
        fi
      fi
    done
    echo ""
    print_2title "Emond scripts" "T1543.001"
    print_info "https://book.hacktricks.wiki/en/macos-hardening/macos-auto-start-locations.html#emond"
    if [ -d "/private/var/db/emondClients" ]; then
      find "/private/var/db/emondClients" -type f 2>/dev/null | while read -r emond_script; do
        if [ -w "$emond_script" ]; then
          echo "Writable emond script: $emond_script" | sed -${E} "s,.*,${SED_RED_YELLOW},"
          ls -l "$emond_script" 2>/dev/null
        fi
      done
    fi
    echo ""
    print_2title "Periodic tasks" "T1543.001"
    print_info "Checking periodic tasks for privilege escalation vectors"
    for periodic_dir in /etc/periodic/daily /etc/periodic/weekly /etc/periodic/monthly; do
      [ ! -d "$periodic_dir" ] && continue
      echo "Checking $periodic_dir..."
      find "$periodic_dir" -type f -executable 2>/dev/null | while read -r periodic_script; do
        if [ -w "$periodic_script" ]; then
          echo "Writable periodic script: $periodic_script" | sed -${E} "s,.*,${SED_RED_YELLOW},"
          ls -l "$periodic_script" 2>/dev/null
        fi
      done
    done
    echo ""
  fi
fi

fi

if check_mitre_filter "T1053.003"; then
if ! [ "$SEARCH_IN_FOLDER" ]; then
  print_2title "System timers" "T1053.003"
  print_info "https://book.hacktricks.wiki/en/linux-hardening/processes-crontab-systemd-dbus/cron-and-systemd-timers.html#enumerate-schedules"
  # Function to check timer content for privilege escalation vectors
  check_timer_content() {
    local timer="$1"
    local findings=""
    local restart_target restart_properties restart_user restart_user_seen
    local restart_dynamic_user restart_root_dir restart_root_dir_seen
    local restart_root_image restart_root_image_seen restart_exec
    local restart_exec_path restart_script
    # Get the service unit this timer activates
    local timer_unit_property=$(systemctl show "$timer" -p Unit 2>/dev/null)
    case "$timer_unit_property" in Unit=*) ;; *) return ;; esac
    local service_unit=${timer_unit_property#Unit=}
    if [ -n "$service_unit" ]; then
      # Read the service properties once per timer to keep the check cheap.
      local service_properties=$(systemctl show "$service_unit" -p User -p DynamicUser -p ExecStart 2>/dev/null)
      local service_user="" service_user_seen="" dynamic_user="" exec_start="" property
      while IFS= read -r property; do
        case "$property" in
          User=*) service_user=${property#User=}; service_user_seen=1 ;;
          DynamicUser=*) dynamic_user=${property#DynamicUser=} ;;
          ExecStart=*) exec_start=${property#ExecStart=} ;;
        esac
      done <<EOF
$service_properties
EOF
      # Check if the service runs with elevated privileges
      if [ -n "$service_user_seen" ]; then
        case "$service_user" in
          ""|root|0)
            if [ -n "$service_user" ] || [ "$dynamic_user" != "yes" ]; then
              findings="${findings}RUNS_AS_ROOT: Service runs as root\n"
            fi ;;
        esac
      fi
      # systemctl show commonly formats ExecStart as { path=... ; argv[]=... }.
      local exec_path
      case "$exec_start" in
        *path=*) exec_path=${exec_start#*path=}
                 exec_path=${exec_path%%[[:space:];]*}
                 exec_path=${exec_path%\}} ;;
        *) exec_path=${exec_start%% *} ;;
      esac
      if [ -n "$exec_path" ]; then
        if [ -w "$exec_path" ]; then
          findings="${findings}WRITABLE_EXEC: Executable is writable: $exec_path\n"
        fi
        # Check for relative paths
        case "$exec_path" in
          /*) : ;; # Absolute path, do nothing
          *) findings="${findings}RELATIVE_PATH: Uses relative path: $exec_path\n" ;;
        esac
      fi
      # Check for unsafe configurations
      if printf '%s\n' "$exec_start" | grep -qE '(chmod|chown|mount|sudo|su)'; then
        findings="${findings}UNSAFE_CMD: Uses potentially dangerous commands\n"
      fi
      # Check for weak permissions
      if [ -e "$exec_path" ] && [ "$(stat -c %a "$exec_path" 2>/dev/null)" = "777" ]; then
        findings="${findings}WEAK_PERMS: Executable has 777 permissions\n"
      fi
      # Follow only a literal root timer service -> systemctl restart -> root
      # shell-script edge. Reuse the direct service properties above; query no
      # more than four distinct restart targets, with a one-second deadline.
      if [ -n "$timer_restart_timeout" ] && [ "$timer_restart_queries" -lt 4 ] &&
         [ -n "$service_user_seen" ]; then
        case "$service_user" in
          ''|root|0)
            if [ -n "$service_user" ] || [ "$dynamic_user" != yes ]; then
              case "$exec_path" in
                /bin/systemctl|/usr/bin/systemctl)
                  restart_target=$(printf '%s\n' "$exec_start" | awk -v exe="$exec_path" '
                    {
                      i = index($0, "argv[]=")
                      if (!i) exit
                      args = substr($0, i + 7)
                      if (args !~ /[[:space:]];[[:space:]]/) exit
                      sub(/[[:space:]];[[:space:]].*/, "", args)
                      if (index(args, ";")) exit
                      sub(/^[[:space:]]+/, "", args)
                      sub(/[[:space:]]+$/, "", args)
                      n = split(args, word, /[[:space:]]+/)
                      if (n == 3 && word[1] == exe && word[2] == "restart" &&
                          word[3] ~ /^[A-Za-z0-9_.@-]+\.service$/) print word[3]
                    }
                  ')
                  if [ -n "$restart_target" ]; then
                    case " $timer_restart_targets" in
                      *" $restart_target "*) ;;
                      *)
                        timer_restart_targets="$timer_restart_targets$restart_target "
                        timer_restart_queries=$((timer_restart_queries + 1))
                        if restart_properties=$("$timer_restart_timeout" 1 systemctl show "$restart_target" \
                          -p User -p DynamicUser -p RootDirectory -p RootImage -p ExecStart 2>/dev/null); then
                          restart_user='' restart_user_seen='' restart_dynamic_user=''
                          restart_root_dir='' restart_root_dir_seen=''
                          restart_root_image='' restart_root_image_seen='' restart_exec=''
                          while IFS= read -r property; do
                            case "$property" in
                              User=*) restart_user=${property#User=}; restart_user_seen=1 ;;
                              DynamicUser=*) restart_dynamic_user=${property#DynamicUser=} ;;
                              RootDirectory=*) restart_root_dir=${property#RootDirectory=}; restart_root_dir_seen=1 ;;
                              RootImage=*) restart_root_image=${property#RootImage=}; restart_root_image_seen=1 ;;
                              ExecStart=*) restart_exec=${property#ExecStart=} ;;
                            esac
                          done <<EOF
$restart_properties
EOF
                          if [ -n "$restart_user_seen" ] && [ -n "$restart_root_dir_seen" ] &&
                             [ -n "$restart_root_image_seen" ] && [ "$restart_dynamic_user" != yes ] &&
                             [ -z "$restart_root_image" ] &&
                             { [ -z "$restart_root_dir" ] || [ "$restart_root_dir" = / ]; }; then
                            case "$restart_user" in
                              ''|root|0)
                                restart_exec_path=${restart_exec#*path=}
                                restart_exec_path=${restart_exec_path%%[[:space:];]*}
                                case "$restart_exec_path" in
                                  /bin/bash|/usr/bin/bash|/bin/sh|/usr/bin/sh)
                                    restart_script=$(printf '%s\n' "$restart_exec" | awk -v exe="$restart_exec_path" '
                                      {
                                        i = index($0, "argv[]=")
                                        if (!i) exit
                                        args = substr($0, i + 7)
                                        if (args !~ /[[:space:]];[[:space:]]/) exit
                                        sub(/[[:space:]];[[:space:]].*/, "", args)
                                        if (index(args, ";")) exit
                                        sub(/^[[:space:]]+/, "", args)
                                        sub(/[[:space:]]+$/, "", args)
                                        n = split(args, word, /[[:space:]]+/)
                                        if (n == 2 && word[1] == exe &&
                                            word[2] ~ /^\/[A-Za-z0-9_.\/-]+$/) print word[2]
                                      }
                                    ')
                                    if [ -n "$restart_script" ] && [ -f "$restart_script" ] &&
                                       [ ! -L "$restart_script" ] && [ -w "$restart_script" ]; then
                                      findings="${findings}WRITABLE_TIMER_SCRIPT: $restart_target invokes $restart_script through $restart_exec_path (root review candidate)\n"
                                    fi
                                    ;;
                                esac
                                ;;
                            esac
                          fi
                        fi
                        ;;
                    esac
                  fi
                  ;;
              esac
            fi
            ;;
        esac
      fi
    fi
    # If any findings, print them
    if [ -n "$findings" ]; then
      echo "Potential privilege escalation in timer: $timer"
      echo "$findings" | while read -r finding; do
        [ -n "$finding" ] && echo "  └─ $finding"
      done
    fi
  }
  # Function to check timer file for privilege escalation vectors
  check_timer_file() {
    local timer_file="$1"
    local findings=""
    # Check if timer file is writable (following symlinks)
    if [ -L "$timer_file" ]; then
      # If it's a symlink, check the target file
      local target_file=$(readlink -f "$timer_file")
      if [ -w "$target_file" ]; then
        findings="${findings}WRITABLE_FILE: Timer target file is writable: $target_file\n"
      fi
    elif [ -w "$timer_file" ]; then
      findings="${findings}WRITABLE_FILE: Timer file is writable\n"
    fi
    # Check for weak permissions (following symlinks)
    if [ "$(stat -L -c %a "$timer_file" 2>/dev/null)" = "777" ]; then
      findings="${findings}WEAK_PERMS: Timer file has 777 permissions\n"
    fi
    # Check for relative paths in Unit directive
    if grep -q "^Unit=[^/]" "$timer_file" 2>/dev/null; then
      findings="${findings}RELATIVE_PATH: Uses relative path in Unit directive\n"
    fi
    # Check for writable executables in Unit directive (following symlinks)
    local unit_path=$(sed -n 's/^Unit=//p' "$timer_file" 2>/dev/null | head -n 1)
    if [ -n "$unit_path" ]; then
      if [ -L "$unit_path" ]; then
        local target_unit=$(readlink -f "$unit_path")
        if [ -w "$target_unit" ]; then
          findings="${findings}WRITABLE_UNIT: Unit target file is writable: $target_unit\n"
        fi
      elif [ -w "$unit_path" ]; then
        findings="${findings}WRITABLE_UNIT: Unit file is writable: $unit_path\n"
      fi
    fi
    # If any findings, print them
    if [ -n "$findings" ]; then
      echo "Potential privilege escalation in timer file: $timer_file"
      echo "$findings" | while read -r finding; do
        [ -n "$finding" ] && echo "  └─ $finding"
      done
    fi
  }
  # List all timers and check for privilege escalation vectors
  print_3title "Active timers:" "T1053.003"
  timer_count=0
  timer_restart_queries=0
  timer_restart_targets=''
  timer_restart_timeout=''
  if command -v timeout >/dev/null 2>&1; then
    timer_restart_timeout=$(command -v timeout)
  elif command -v gtimeout >/dev/null 2>&1; then
    timer_restart_timeout=$(command -v gtimeout)
  fi
  systemctl list-timers --all --no-pager --full 2>/dev/null | grep -Ev "(^$|timers listed)" | while IFS= read -r line; do
    # UNIT is the next-to-last column; NEXT can contain several date fields.
    timer_unit=$(printf '%s\n' "$line" | awk '$(NF-1) ~ /\.timer$/ { print $(NF-1) }')
    if [ -n "$timer_unit" ]; then
      timer_count=$(( ${timer_count:-0} + 1 ))
      if [ "$timer_count" -le 200 ]; then
        # Check if timer file is writable
        timer_path=$(systemctl show "$timer_unit" -p FragmentPath 2>/dev/null | cut -d= -f2)
        if [ -n "$timer_path" ]; then
          check_timer_file "$timer_path"
        fi
        # Check timer content for privilege escalation vectors
        check_timer_content "$timer_unit"
      fi
    fi
    # Keep the list output, including its heading, in the existing format.
    echo "$line" | sed -${E} "s,$timersG,${SED_GREEN},"
  done || echo_not_found
  # Check for disabled but available timers
  print_3title "Disabled timers:" "T1053.003"
  timer_count=0
  systemctl list-unit-files --type=timer --state=disabled 2>/dev/null | grep -v "UNIT FILE" | while IFS= read -r line; do
    timer_unit=$(printf '%s\n' "$line" | awk '$1 ~ /\.timer$/ { print $1 }')
    if [ -n "$timer_unit" ]; then
      timer_count=$(( ${timer_count:-0} + 1 ))
      if [ "$timer_count" -le 200 ]; then
        timer_path=$(systemctl show "$timer_unit" -p FragmentPath 2>/dev/null | cut -d= -f2)
        if [ -n "$timer_path" ]; then
          check_timer_file "$timer_path"
        fi
      fi
    fi
  done || echo_not_found
  # Check timer files from PSTORAGE_TIMER
  if [ -n "$PSTORAGE_TIMER" ]; then
    print_3title "Additional timer files:" "T1053.003"
    printf "%s\n" "$PSTORAGE_TIMER" | while read -r timer_file; do
      if [ -n "$timer_file" ] && [ -e "$timer_file" ]; then
        check_timer_file "$timer_file"
      fi
    done
  fi
  echo ""
fi

fi

if check_mitre_filter "T1543.002,T1574.010,T1007"; then
# Read only the small, conventional tftpd-hpa settings file. Configuration is a
# review cue: the running daemon, network access and effective arguments may differ.
check_tftpd_hpa_root_upload_scope() (
  conf="${1:-/etc/default/tftpd-hpa}"
  if [ "$conf" = /etc/default/tftpd-hpa ]; then
    [ ! -L /etc ] && [ ! -L /etc/default ] || return 0
  fi
  [ -f "$conf" ] && [ ! -L "$conf" ] && [ -r "$conf" ] || return 0
  bytes=$(stat -c %s "$conf" 2>/dev/null) ||
    bytes=$(stat -f %z "$conf" 2>/dev/null) || return 0
  case "$bytes" in ''|*[!0-9]*) return 0 ;; esac
  [ "$bytes" -le 4096 ] || return 0
  if awk '
    function setting(line) {
      sub(/^[^=]*=[[:space:]]*/, "", line)
      sub(/[[:space:]]*$/, "", line)
      if (length(line) >= 2 &&
          ((substr(line, 1, 1) == "\"" && substr(line, length(line), 1) == "\"") ||
           (substr(line, 1, 1) == "\047" && substr(line, length(line), 1) == "\047")))
        line = substr(line, 2, length(line) - 2)
      return line
    }
    /^[[:space:]]*(#|$)/ { next }
    /^[[:space:]]*TFTP_USERNAME[[:space:]]*=/ { user = setting($0); next }
    /^[[:space:]]*TFTP_DIRECTORY[[:space:]]*=/ { directory = setting($0); next }
    /^[[:space:]]*TFTP_OPTIONS[[:space:]]*=/ { options = setting($0); next }
    END {
      if (user != "root" || directory != "/") exit 1
      n = split(options, words, /[[:space:]]+/)
      for (i = 1; i <= n; i++) {
        if (words[i] == "--create" || words[i] == "-c") create = 1
        if (words[i] == "--secure" || words[i] == "-s") secure = 1
        if (words[i] == "--read-only" || words[i] == "-r") readonly = 1
      }
      exit !(create && secure && !readonly)
    }
  ' "$conf" 2>/dev/null; then
    print_3title "Root TFTP file-creation scope (review candidate)" "T1543.002"
    echo "Configured tftpd-hpa root user, filesystem-root secure directory and --create: $conf"
    echo "Verify active effective service, listener reachability, TFTP access rules, and whether a privileged job consumes newly created files (for example APT hooks)."
  fi
)
if ! [ "$SEARCH_IN_FOLDER" ]; then
  print_2title "Services and Service Files" "T1543.002,T1007"
  print_info "https://book.hacktricks.wiki/en/linux-hardening/processes-crontab-systemd-dbus/process-enumeration-and-service-paths.html#follow-the-service-execution-chain"
  check_tftpd_hpa_root_upload_scope
  checkSystemdWritableExecPaths
  checkSystemdWritableDropins
  # Function to check service content for privilege escalation vectors
  check_service_content() {
    local service="$1"
    local findings=""
    # Check if service runs with elevated privileges
    if systemctl show "$service" -p User 2>/dev/null | grep -q "root"; then
      findings="${findings}RUNS_AS_ROOT: Service runs as root\n"
    fi
    # Get the executable path and check it
    local exec_path=$(systemctl show "$service" -p ExecStart 2>/dev/null | cut -d= -f2 | cut -d' ' -f1)
    if [ -n "$exec_path" ]; then
      if [ -w "$exec_path" ]; then
        findings="${findings}WRITABLE_EXEC: Executable is writable: $exec_path\n"
      fi
      # Check for relative paths
      #case "$exec_path" in
      #  /*) : ;; # Absolute path, do nothing
      #  *) findings="${findings}RELATIVE_PATH: Uses relative path: $exec_path\n" ;;
      #esac
      # Check for weak permissions
      if [ -e "$exec_path" ] && [ "$(stat -c %a "$exec_path" 2>/dev/null)" = "777" ]; then
        findings="${findings}WEAK_PERMS: Executable has 777 permissions\n"
      fi
    fi
    # Check for unsafe configurations
    if systemctl show "$service" -p ExecStart 2>/dev/null | grep -qE '(chmod|chown|mount|sudo|su)'; then
      findings="${findings}UNSAFE_CMD: Uses potentially dangerous commands\n"
    fi
    # Check for environment variables with sensitive data
    if systemctl show "$service" -p Environment 2>/dev/null | grep -qE '(PASS|SECRET|KEY|TOKEN|CRED)'; then
      findings="${findings}SENSITIVE_ENV: Contains sensitive environment variables\n"
    fi
    # Check for capabilities
    if systemctl show "$service" -p CapabilityBoundingSet 2>/dev/null | grep -qE '(CAP_SYS_ADMIN|CAP_DAC_OVERRIDE|CAP_DAC_READ_SEARCH)'; then
      findings="${findings}DANGEROUS_CAPS: Has dangerous capabilities\n"
    fi
    # If any findings, print them
    if [ -n "$findings" ]; then
      echo "  Potential issue in service: $service"
      echo "$findings" | while read -r finding; do
        [ -n "$finding" ] && echo "  └─ $finding"
      done
    fi
  }
  # Function to check service file for privilege escalation vectors
  check_service_file() {
    local service_file="$1"
    local findings=""
    # Check if service file is writable (following symlinks)
    if [ -L "$service_file" ]; then
      # If it's a symlink, check the target file
      local target_file=$(readlink -f "$service_file")
      if ! [ "$IAMROOT" ] && [ -w "$target_file" ] && [ -f "$target_file" ] && ! [ "$SEARCH_IN_FOLDER" ]; then
        findings="${findings}WRITABLE_FILE: Service target file is writable: $target_file\n"
      fi
    elif ! [ "$IAMROOT" ] && [ -w "$service_file" ] && [ -f "$service_file" ] && ! [ "$SEARCH_IN_FOLDER" ]; then
      findings="${findings}WRITABLE_FILE: Service file is writable\n"
    fi
    # Check for weak permissions (following symlinks)
    if [ "$(stat -L -c %a "$service_file" 2>/dev/null)" = "777" ]; then
      findings="${findings}WEAK_PERMS: Service file has 777 permissions\n"
    fi
    # Check for relative paths in Exec directives - Original logic
    local relpath1=$(grep -E '^Exec.*=(?:[^/]|-[^/]|\+[^/]|![^/]|!![^/]|)[^/@\+!-].*' "$service_file" 2>/dev/null | grep -Iv "=/")
    local relpath2=$(grep -E '^Exec.*=.*/bin/[a-zA-Z0-9_]*sh ' "$service_file" 2>/dev/null)
    if [ "$relpath1" ] || [ "$relpath2" ]; then
      if [ "$WRITABLESYSTEMDPATH" ]; then
        findings="${findings}RELATIVE_PATH: Could be executing some relative path (systemd path is writable)\n"
      else
        findings="${findings}RELATIVE_PATH: Could be executing some relative path\n"
      fi
    fi
    # Check for writable executables (following symlinks)
    local exec_paths=$(grep -Eo '^Exec.*?=[!@+-]*[a-zA-Z0-9_/\-]+' "$service_file" 2>/dev/null | cut -d '=' -f2 | sed 's,^[@\+!-]*,,')
    printf "%s\n" "$exec_paths" | while read -r exec_path; do
      if [ -n "$exec_path" ]; then
        if [ -L "$exec_path" ]; then
          local target_exec=$(readlink -f "$exec_path")
          if [ -w "$target_exec" ]; then
            findings="${findings}WRITABLE_EXEC: Executable target is writable: $target_exec\n"
          fi
        elif [ -w "$exec_path" ]; then
          findings="${findings}WRITABLE_EXEC: Executable is writable: $exec_path\n"
        fi
      fi
    done
    # If any findings, print them
    if [ -n "$findings" ]; then
      echo "  Potential issue in service file: $service_file"
      echo "$findings" | while read -r finding; do
        [ -n "$finding" ] && echo "  └─ $finding"
      done
    fi
  }
  # List all services and check for privilege escalation vectors
  echo ""
  print_3title "Active services:" "T1543.002,T1007"
  systemctl list-units --type=service --state=active 2>/dev/null | grep -v "UNIT" | while read -r line; do
    service_unit=$(echo "$line" | awk '{print $1}')
    if [ -n "$service_unit" ]; then
      # Print the service line with highlighting
      echo "$line" | sed -${E} "s,$service_unit,${SED_GREEN},"
      # Get service file path
      service_path=$(systemctl show "$service_unit" -p FragmentPath 2>/dev/null | cut -d= -f2)
      if [ -n "$service_path" ]; then
        check_service_file "$service_path"
      fi
      # Check service content for privilege escalation vectors
      check_service_content "$service_unit"
    fi
  done || echo_not_found
  # Check for disabled but available services
  echo ""
  print_3title "Disabled services:" "T1543.002,T1007"
  systemctl list-unit-files --type=service --state=disabled 2>/dev/null | grep -v "UNIT FILE" | while read -r line; do
    service_unit=$(echo "$line" | awk '{print $1}')
    if [ -n "$service_unit" ]; then
      # Print the service line with highlighting
      echo "$line" | sed -${E} "s,$service_unit,${SED_GREEN},"
      # Get service file path
      service_path=$(systemctl show "$service_unit" -p FragmentPath 2>/dev/null | cut -d= -f2)
      if [ -n "$service_path" ]; then
        check_service_file "$service_path"
      fi
      # Check service content for privilege escalation vectors
      check_service_content "$service_unit"
    fi
  done || echo_not_found
  # Check service files from PSTORAGE_SYSTEMD
  if [ -n "$PSTORAGE_SYSTEMD" ]; then
    echo ""
    print_3title "Additional service files:" "T1543.002,T1007"
    printf "%s\n" "$PSTORAGE_SYSTEMD" | while read -r service_file; do
      if [ -n "$service_file" ] && [ -e "$service_file" ]; then
        check_service_file "$service_file"
      fi
    done
  fi
  # Check for outdated services if EXTRA_CHECKS is enabled
  if [ "$EXTRA_CHECKS" ]; then
    echo ""
    print_3title "Service versions and status:" "T1543.002,T1007"
    if [ "$TIMEOUT" ]; then
      $TIMEOUT 30 sh -c "(service --status-all || service -e || chkconfig --list || rc-status || launchctl list) 2>/dev/null" || echo_not_found "service|chkconfig|rc-status|launchctl"
    else
      (service --status-all || service -e || chkconfig --list || rc-status || launchctl list) 2>/dev/null || echo_not_found "service|chkconfig|rc-status|launchctl"
    fi
  fi
  # Check systemd path writability
  if [ ! "$WRITABLESYSTEMDPATH" ]; then 
    echo "You can't write on systemd PATH" | sed -${E} "s,.*,${SED_GREEN},"
  else
    echo "You can write on systemd PATH" | sed -${E} "s,.*,${SED_RED},"
    echo "If a relative path is used, it's possible to abuse it."
  fi
  echo ""
fi

fi

if check_mitre_filter "T1543.002,T1552.001"; then
# Inspect only literal EnvironmentFile paths in a service unit. This is an
# indicator of readable credential-like assignments, not evidence that a key
# is used for authentication or provides privilege escalation.
systemd_envfile_candidates() {
    if [ "$1" != "-" ]; then
        [ -f "$1" ] && [ -r "$1" ] || return
        local env_unit_size
        env_unit_size=$(stat -c %s "$1" 2>/dev/null) ||
            env_unit_size=$(stat -f %z "$1" 2>/dev/null) || return
        case "$env_unit_size" in ''|*[!0-9]*) return ;; esac
        [ "$env_unit_size" -le 65536 ] || return
    fi
    awk '
        function add_path(value, path, quoted, optional) {
            sub(/^[[:space:]]*/, "", value)
            sub(/[[:space:]]*$/, "", value)
            if (value == "") { count = 0; return }
            optional = 0
            if (substr(value, 1, 1) == "-") { value = substr(value, 2); optional = 1 }
            quoted = 0
            if ((substr(value, 1, 1) == "\"" && substr(value, length(value), 1) == "\"") ||
                (substr(value, 1, 1) == sprintf("%c", 39) && substr(value, length(value), 1) == sprintf("%c", 39))) {
                quoted = 1
                value = substr(value, 2, length(value) - 2)
            }
            if (!optional && substr(value, 1, 1) == "-") value = substr(value, 2)
            # Skip globs, escapes, unquoted whitespace, and relative paths.
            if (!quoted && value ~ /[[:space:]]/) return
            if (value !~ /^\// || value ~ /[*?\[\]{}\\%$"\047]/ || value ~ /[\r\n]/) return
            for (path = 1; path <= count; path++) if (paths[path] == value) return
            paths[++count] = value
        }
        /^[[:space:]]*\[/ {
            section = $0
            sub(/^[[:space:]]*/, "", section)
            sub(/[[:space:]]*$/, "", section)
            next
        }
        section == "[Service]" && /^[[:space:]]*EnvironmentFile[[:space:]]*=/ {
            value = $0
            sub(/^[[:space:]]*EnvironmentFile[[:space:]]*=/, "", value)
            add_path(value)
        }
        END { for (i = 1; i <= count && i <= 4; i++) print paths[i] }
    ' "$1" 2>/dev/null
}
systemd_envfile_key_names() {
    awk '
        /^[[:space:]]*[#;]/ { next }
        /^[[:space:]]*[A-Za-z_][A-Za-z0-9_]*[[:space:]]*=/ {
            line = $0
            sub(/=.*/, "", line)
            gsub(/[[:space:]]/, "", line)
            value = $0
            sub(/^[^=]*=[[:space:]]*/, "", value)
            if (value == "" || value == "\"\"" || value == sprintf("%c%c", 39, 39)) next
            upper = toupper(line)
            if (upper !~ /(^|_)(SECRET|TOKEN|PASSWORD|PASSWD|APIKEY|KEY)($|_)/) next
            if (seen[line]++) next
            if (found >= 20) exit
            if (found++) printf ","
            printf "%s", line
        }
        END { if (found) printf "\n" }
    ' "$1" 2>/dev/null
}
systemd_envfile_active_units() {
    awk '
        {
            unit = $1
            if (unit == "●") unit = $2
            if (unit !~ /^[A-Za-z0-9_.@-]+[.]service$/ || unit ~ /[.][.]/) next
            print unit
            if (++count >= 200) exit
        }
    '
}
systemd_envfile_findings_for_unit() {
    systemd_envfile_candidates "$1" | while IFS= read -r env_file_path; do
        [ -f "$env_file_path" ] && [ -r "$env_file_path" ] || continue
        env_file_size=$(stat -c %s "$env_file_path" 2>/dev/null) ||
            env_file_size=$(stat -f %z "$env_file_path" 2>/dev/null) || continue
        case "$env_file_size" in ''|*[!0-9]*) continue ;; esac
        [ "$env_file_size" -le 65536 ] || continue
        env_key_names=$(systemd_envfile_key_names "$env_file_path")
        [ "$env_key_names" ] && printf '%s: %s\n' "$env_file_path" "$env_key_names"
    done
}
# systemctl cat includes the loaded unit and its drop-ins, so resets in a
# drop-in cannot leave a stale EnvironmentFile= candidate from the main unit.
# The caller supplies only an active system service and the effective User=.
systemd_wenv_findings_for_unit() {
    [ -n "$1" ] || return 0
    systemd_wenv_properties=$(systemctl show "$1" -p User -p DynamicUser -p RootDirectory -p RootImage 2>/dev/null) || return 0
    systemd_wenv_user= systemd_wenv_dynamic= systemd_wenv_rootdir= systemd_wenv_rootimage=
    # Keep the first value for each property, including an empty value.
    systemd_wenv_seen_user= systemd_wenv_seen_dynamic= systemd_wenv_seen_rootdir= systemd_wenv_seen_rootimage=
    while IFS= read -r systemd_wenv_line; do
        case "$systemd_wenv_line" in
            User=*) if [ ! "$systemd_wenv_seen_user" ]; then
                systemd_wenv_user=${systemd_wenv_line#User=}; systemd_wenv_seen_user=1
            fi ;;
            DynamicUser=*) if [ ! "$systemd_wenv_seen_dynamic" ]; then
                systemd_wenv_dynamic=${systemd_wenv_line#DynamicUser=}; systemd_wenv_seen_dynamic=1
            fi ;;
            RootDirectory=*) if [ ! "$systemd_wenv_seen_rootdir" ]; then
                systemd_wenv_rootdir=${systemd_wenv_line#RootDirectory=}; systemd_wenv_seen_rootdir=1
            fi ;;
            RootImage=*) if [ ! "$systemd_wenv_seen_rootimage" ]; then
                systemd_wenv_rootimage=${systemd_wenv_line#RootImage=}; systemd_wenv_seen_rootimage=1
            fi ;;
        esac
    done <<EOF
$systemd_wenv_properties
EOF
    case "$systemd_wenv_user" in ""|root|0) ;; *) return 0 ;; esac
    [ "$systemd_wenv_dynamic" = "yes" ] && return 0
    [ -z "$systemd_wenv_rootdir" ] && [ -z "$systemd_wenv_rootimage" ] || return 0
    systemctl cat --no-pager "$1" 2>/dev/null | head -c 65536 |
        systemd_envfile_candidates - | while IFS= read -r systemd_wenv_path; do
            [ -f "$systemd_wenv_path" ] && [ -w "$systemd_wenv_path" ] || continue
            printf '%s: %s\n' "$1" "$systemd_wenv_path"
        done
}
if ! [ "$SEARCH_IN_FOLDER" ]; then
    print_2title "Systemd Information" "T1543.002"
    print_info "https://book.hacktricks.wiki/en/linux-hardening/linux-basics/linux-privilege-escalation/index.html#systemd-path---relative-paths"
    # Function to check if systemctl is available
    check_systemctl() {
        if ! command -v systemctl >/dev/null 2>&1; then
            echo_not_found "systemctl"
            return 1
        fi
        return 0
    }
    # Function to list running systemd services
    list_running_services() {
        systemctl list-units --type=service --state=running 2>/dev/null
    }
    # Function to get service file path
    get_service_file() {
        local service="$1"
        local file=""
        for path in "/etc/systemd/system/$service" "/run/systemd/system/$service" "/usr/lib/systemd/system/$service" "/lib/systemd/system/$service"; do
            if [ -f "$path" ]; then
                file="$path"
                break
            fi
        done
        echo "$file"
    }
    # Function to check dangerous capabilities
    check_dangerous_caps() {
        local caps="$1"
        echo "$caps" | grep -qE '(CAP_SYS_ADMIN|CAP_DAC_OVERRIDE|CAP_DAC_READ_SEARCH|CAP_SETUID|CAP_SETGID|CAP_NET_ADMIN)'
        return $?
    }
    # Reuse one active-unit listing without changing the scope of older checks.
    running_services=""
    if check_systemctl; then
        running_services=$(list_running_services)
    fi
    # The upstream release alone does not identify distribution backports or
    # mitigations. PwnKit is a polkit/pkexec issue, not a systemd version issue.
    print_list "Systemd release (verify package fixes)? .......... "$NC
    if check_systemctl; then
        version=$(systemctl --version 2>/dev/null | awk 'NR == 1 && $1 == "systemd" && $2 ~ /^[0-9]+$/ { print $2 }')
        if [ -n "$version" ]; then
            printf '%s\n' "$version"
        fi
    fi
    # Check for systemd services running as root
    print_list "Services running as root? ..... "$NC
    if check_systemctl; then
        printf '%s\n' "$running_services" |
        grep -E "root|0:0" | 
        while read -r line; do
            service=$(echo "$line" | awk '{print $1}')
            user=$(systemctl show "$service" -p User 2>/dev/null | cut -d= -f2)
            echo "$service (User: $user)" | sed -${E} "s,root|0:0,${SED_RED},g"
        done
        echo ""
    else
        echo ""
    fi
    # Check for systemd services with dangerous capabilities
    print_list "Running services with dangerous capabilities? ... "$NC
    if check_systemctl; then
        printf '%s\n' "$running_services" |
        grep -E "\.service" | 
        while read -r line; do
            service=$(echo "$line" | awk '{print $1}')
            caps=$(systemctl show "$service" -p CapabilityBoundingSet 2>/dev/null | cut -d= -f2)
            if [ -n "$caps" ] && check_dangerous_caps "$caps"; then
                echo "$service: $caps" | sed -${E} "s,.*,${SED_RED},g"
            fi
        done
        echo ""
    else
        echo ""
    fi
    # Check for systemd services with writable paths
    print_list "Services with writable paths? . "$NC
    if check_systemctl; then
        printf '%s\n' "$running_services" |
        grep -E "\.service" | 
        while read -r line; do
            service=$(echo "$line" | awk '{print $1}')
            service_file=$(get_service_file "$service")
            if [ -n "$service_file" ]; then
                # Check service-specific PATH entries (Environment=PATH=...)
                svc_writable_path=$(grep -E '^Environment=.*PATH=' "$service_file" 2>/dev/null | sed -E 's/^Environment=//; s/^"//; s/"$//; s/^PATH=//' | tr ':' '\n' | while read -r svc_path_entry; do
                    [ -z "$svc_path_entry" ] && continue
                    if [ -d "$svc_path_entry" ] && [ -w "$svc_path_entry" ]; then
                        echo "$svc_path_entry"
                    fi
                done)
                if [ "$svc_writable_path" ]; then
                    for svc_path_entry in $svc_writable_path; do
                        echo "$service: Writable service PATH entry '$svc_path_entry'" | sed -${E} "s,.*,${SED_RED_YELLOW},g"
                    done
                fi
                # Check ExecStart paths
                grep -E "ExecStart|ExecStartPre|ExecStartPost" "$service_file" 2>/dev/null | 
                while read -r exec_line; do
                    # Extract command from the right side of Exec*=, not from argv
                    exec_value="${exec_line#*=}"
                    exec_value=$(echo "$exec_value" | sed 's/^[[:space:]]*//')
                    cmd=$(echo "$exec_value" | awk '{print $1}' | tr -d '"')
                    # Strip systemd command prefixes (-, @, :, +, !) before path checks
                    cmd_path=$(echo "$cmd" | sed -E 's/^[-@:+!]+//')
                    # Only check the command path, not arguments
                    if [ -n "$cmd_path" ] && [ -w "$cmd_path" ]; then
                        echo "$service: $cmd_path (from $exec_line)" | sed -${E} "s,.*,${SED_RED},g"
                    fi
                    # Check for relative paths only in the command, not arguments
                    if [ -n "$cmd_path" ] && [ "${cmd_path#/}" = "$cmd_path" ] && [ "${cmd_path#\$}" = "$cmd_path" ]; then
                        echo "$service: Uses relative path '$cmd_path' (from $exec_line)" | sed -${E} "s,.*,${SED_RED},g"
                        if [ "$svc_writable_path" ]; then
                            echo "$service: Relative Exec path + writable service PATH can allow path hijacking" | sed -${E} "s,.*,${SED_RED_YELLOW},g"
                        fi
                    fi
                done
            fi
        done
    else
        echo ""
    fi
    echo ""
    # Unit files may point at files outside the usual .env naming convention.
    # Keep this passive and print key names only, never environment values.
    if ! [ "$IAMROOT" ]; then
        env_file_findings=$(
            printf '%s\n' "$running_services" | systemd_envfile_active_units | while IFS= read -r service; do
                service_file=$(get_service_file "$service")
                [ "$service_file" ] || continue
                systemd_envfile_findings_for_unit "$service_file"
            done | sort -u
        )
        if [ "$env_file_findings" ]; then
            print_2title "Readable systemd EnvironmentFile credential-like keys (possible exposure)" "T1552.001"
            printf '%s\n' "$env_file_findings"
            echo ""
        fi
        systemd_wenv_findings=$(
            printf '%s\n' "$running_services" | systemd_envfile_active_units | while IFS= read -r service; do
                systemd_wenv_findings_for_unit "$service"
            done | sort -u
        )
        if [ "$systemd_wenv_findings" ]; then
            print_2title "Writable EnvironmentFile in active root systemd service (environment injection candidate)" "T1543.002"
            print_info "https://man7.org/linux/man-pages/man5/systemd.exec.5.html"
            printf '%s\n' "$systemd_wenv_findings" | sed -${E} "s,.*,${SED_RED_YELLOW},"
            printf '%s\n' 'The service manager reads these files before execution; review effective unit overrides, UnsetEnvironment, executable type, and restart conditions.'
            echo ""
        fi
    fi
    print_2title "Systemd PATH" "T1543.002"
    print_info "https://book.hacktricks.wiki/en/linux-hardening/linux-basics/linux-privilege-escalation/index.html#systemd-path---relative-paths"
    if check_systemctl; then
        systemctl show-environment 2>/dev/null | 
        grep "PATH" | 
        while read -r path_line; do
            echo "$path_line" | sed -${E} "s,$Wfolders\|\./\|\.:\|:\.,${SED_RED_YELLOW},g"
            # Store writable paths for later use
            if echo "$path_line" | grep -qE "$Wfolders"; then
                WRITABLESYSTEMDPATH="$path_line"
            fi
        done
    fi
    echo ""
fi

fi

if check_mitre_filter "T1559"; then
if ! [ "$IAMROOT" ]; then
    print_2title "Analyzing .socket files" "T1559"
    print_info "https://book.hacktricks.wiki/en/linux-hardening/network-information/local-network-and-socket-triage.html#unix-socket-interaction-and-command-injection"
    # Function to check if path is relative
    is_relative_path() {
        local lpath="$1"
        case "$lpath" in
            /*) return 1 ;; # Absolute path
            *) return 0 ;;  # Relative path
        esac
    }
    # Function to check socket file content
    check_socket_file() {
        local socket_file="$1"
        local findings=""
        # Check if socket file is writable (following symlinks)
        if [ -L "$socket_file" ]; then
            # If it's a symlink, check the target file
            local target_file=$(readlink -f "$socket_file")
            if ! [ "$IAMROOT" ] && [ -w "$target_file" ] && [ -f "$target_file" ] && ! [ "$SEARCH_IN_FOLDER" ]; then
                findings="${findings}WRITABLE_FILE: Socket target file is writable: $target_file\n"
            fi
        elif ! [ "$IAMROOT" ] && [ -w "$socket_file" ] && [ -f "$socket_file" ] && ! [ "$SEARCH_IN_FOLDER" ]; then
            findings="${findings}WRITABLE_FILE: Socket file is writable\n"
        fi
        # Check for weak permissions (following symlinks)
        if [ "$(stat -L -c %a "$socket_file" 2>/dev/null)" = "777" ]; then
            findings="${findings}WEAK_PERMS: Socket file has 777 permissions\n"
        fi
        # Check for executables (following symlinks)
        local exec_paths=$(grep -Eo '^(Exec).*?=[!@+-]*/[a-zA-Z0-9_/\-]+' "$socket_file" 2>/dev/null | cut -d '=' -f2 | sed 's,^[@\+!-]*,,')
        printf "%s\n" "$exec_paths" | while read -r exec_path; do
            if [ -n "$exec_path" ]; then
                # Check if executable is writable (following symlinks)
                if [ -L "$exec_path" ]; then
                    local target_exec=$(readlink -f "$exec_path")
                    if [ -w "$target_exec" ]; then
                        findings="${findings}WRITABLE_EXEC: Executable target is writable: $target_exec\n"
                    fi
                    # Check for weak permissions on target
                    if [ -e "$target_exec" ] && [ "$(stat -L -c %a "$target_exec" 2>/dev/null)" = "777" ]; then
                        findings="${findings}WEAK_EXEC_PERMS: Executable target has 777 permissions: $target_exec\n"
                    fi
                else
                    if [ -w "$exec_path" ]; then
                        findings="${findings}WRITABLE_EXEC: Executable is writable: $exec_path\n"
                    fi
                    # Check for weak permissions
                    if [ -e "$exec_path" ] && [ "$(stat -L -c %a "$exec_path" 2>/dev/null)" = "777" ]; then
                        findings="${findings}WEAK_EXEC_PERMS: Executable has 777 permissions: $exec_path\n"
                    fi
                fi
                # Check for relative paths
                if is_relative_path "$exec_path"; then
                    findings="${findings}RELATIVE_PATH: Uses relative path: $exec_path\n"
                fi
            fi
        done
        # Check for listeners (following symlinks)
        local listen_paths=$(grep -Eo '^(Listen).*?=[!@+-]*/[a-zA-Z0-9_/\-]+' "$socket_file" 2>/dev/null | cut -d '=' -f2 | sed 's,^[@\+!-]*,,')
        printf "%s\n" "$listen_paths" | while read -r listen_path; do
            if [ -n "$listen_path" ]; then
                # Check if listener path is writable (following symlinks)
                if [ -L "$listen_path" ]; then
                    local target_listen=$(readlink -f "$listen_path")
                    if [ -w "$target_listen" ]; then
                        findings="${findings}WRITABLE_LISTENER: Listener target path is writable: $target_listen\n"
                    fi
                    # Check for weak permissions on target
                    if [ -e "$target_listen" ] && [ "$(stat -L -c %a "$target_listen" 2>/dev/null)" = "777" ]; then
                        findings="${findings}WEAK_LISTENER_PERMS: Listener target path has 777 permissions: $target_listen\n"
                    fi
                else
                    if [ -w "$listen_path" ]; then
                        findings="${findings}WRITABLE_LISTENER: Listener path is writable: $listen_path\n"
                    fi
                    # Check for weak permissions
                    if [ -e "$listen_path" ] && [ "$(stat -L -c %a "$listen_path" 2>/dev/null)" = "777" ]; then
                        findings="${findings}WEAK_LISTENER_PERMS: Listener path has 777 permissions: $listen_path\n"
                    fi
                fi
                # Check for relative paths
                if is_relative_path "$listen_path"; then
                    findings="${findings}RELATIVE_LISTENER: Uses relative path: $listen_path\n"
                fi
            fi
        done
        # Check for unsafe configurations
        if grep -qE '^(User|Group)=root' "$socket_file" 2>/dev/null; then
            findings="${findings}ROOT_USER: Socket runs as root\n"
        fi
        if grep -qE '^(CapabilityBoundingSet).*CAP_SYS_ADMIN' "$socket_file" 2>/dev/null; then
            findings="${findings}DANGEROUS_CAPS: Has dangerous capabilities\n"
        fi
        if grep -qE '^(BindIP|BindIPv6Only)=yes' "$socket_file" 2>/dev/null; then
            findings="${findings}NETWORK_BIND: Can bind to network interfaces\n"
        fi
        # If any findings, print them
        if [ -n "$findings" ]; then
            echo "Potential privilege escalation in socket file: $socket_file"
            echo "$findings" | while read -r finding; do
                [ -n "$finding" ] && echo "  └─ $finding" | sed -${E} "s,WRITABLE.*,${SED_RED},g" | sed -${E} "s,RELATIVE.*,${SED_RED_YELLOW},g"
            done
        fi
    }
    # Process each socket file
    if [ -n "$PSTORAGE_SOCKET" ]; then
        printf "%s\n" "$PSTORAGE_SOCKET" | while read -r socket_file; do
            if [ -n "$socket_file" ] && [ -e "$socket_file" ]; then
                check_socket_file "$socket_file"
            fi
        done
    else
        print_list "No socket files found" "$NC"
    fi
    echo ""
fi

fi

if check_mitre_filter "T1571,T1049"; then
if ! [ "$IAMROOT" ]; then
    if ! [ "$SEARCH_IN_FOLDER" ]; then
        print_2title "Unix Sockets Analysis" "T1571,T1049"
        print_info "https://book.hacktricks.wiki/en/linux-hardening/network-information/local-network-and-socket-triage.html#unix-socket-interaction-and-command-injection"
        # Function to get socket permissions
        get_socket_perms() {
            local socket="$1"
            local mode="$2"
            local read_access="$3"
            local write_access="$4"
            local perms=""
            # Check read permission
            if [ "$read_access" = "yes" ]; then
                perms="Read "
            fi
            # Check write permission
            if [ "$write_access" = "yes" ]; then
                perms="${perms}Write "
            fi
            # Check execute permission
            if [ -x "$socket" ]; then
                perms="${perms}Execute "
            fi
            if [ "$mode" = "777" ] || [ "$mode" = "666" ]; then
                perms="${perms}(Weak Permissions: $mode) "
            fi
            echo "$perms"
        }
        # Function to check socket connectivity
        check_socket_connectivity() {
            local socket="$1"
            local perms="$2"
            if [ "$EXTRA_CHECKS" ] && command -v curl >/dev/null 2>&1; then
                # Try to connect to the socket
                if curl -v --unix-socket "$socket" --max-time 1 http:/linpeas 2>&1 | grep -iq "Permission denied"; then
                    perms="${perms} - Cannot Connect"
                else
                    perms="${perms} - Can Connect"
                fi
            fi
            echo "$perms"
        }
        # Function to analyze socket protocol
        analyze_socket_protocol() {
            local socket="$1"
            local owner="$2"
            local response=""
            # Try to get HTTP response
            if command -v curl >/dev/null 2>&1; then
                response=$(curl --max-time 2 --unix-socket "$socket" http:/index 2>/dev/null)
                if [ $? -eq 0 ]; then
                    echo "  └─ HTTP Socket (owned by $owner):" | sed -${E} "s,$groupsB,${SED_RED},g" | sed -${E} "s,$groupsVB,${SED_RED},g" | sed -${E} "s,$sh_usrs,${SED_LIGHT_CYAN},g" | sed "s,$USER,${SED_LIGHT_MAGENTA},g" | sed -${E} "s,$nosh_usrs,${SED_BLUE},g" | sed -${E} "s,$knw_usrs,${SED_GREEN},g" | sed "s,root,${SED_RED}," | sed -${E} "s,$knw_grps,${SED_GREEN},g" | sed -${E} "s,$idB,${SED_RED},g"
                    echo "     └─ Response to /index (limit 30):"
                    echo "$response" | head -n 30 | sed 's/^/       /'
                fi
            fi
        }
        # Collect listening sockets using multiple methods
        unix_scks_list=""
        ss_metadata=""
        for cmd in "ss -xlp -H state listening" "ss -l -p -A 'unix'" "netstat -a -p --unix"; do
            if [ -z "$unix_scks_list" ]; then
                case "$cmd" in
                    ss\ *)
                        socket_listing=$($cmd 2>/dev/null)
                        unix_scks_list=$(printf '%s\n' "$socket_listing" | grep -Eo "/[a-zA-Z0-9\._/\-]+" | grep -v " " | sort -u)
                        if [ -n "$unix_scks_list" ]; then
                            # Reuse the ss output already collected; never query processes per socket.
                            ss_metadata=$(printf '%s\n' "$socket_listing" | awk '
                                match($0, /\/[a-zA-Z0-9._\/-]+/) {
                                    path = substr($0, RSTART, RLENGTH)
                                    pid = ""; uid = ""
                                    if (match($0, /pid=[0-9]+/)) pid = substr($0, RSTART + 4, RLENGTH - 4)
                                    if (match($0, /uid[:=][0-9]+/)) uid = substr($0, RSTART + 4, RLENGTH - 4)
                                    print path "|" pid "|" uid
                                }')
                            ss_metadata="
$ss_metadata"
                        fi
                        ;;
                    *)
                        unix_scks_list=$($cmd 2>/dev/null | grep -Eo "/[a-zA-Z0-9\._/\-]+" | grep -v " " | sort -u)
                        ;;
                esac
            fi
        done
        # Get additional socket information
        if [ -z "$unix_scks_list" ]; then
            unix_scks_list=$(lsof -U 2>/dev/null | awk '{print $9}' | grep "/" | sort -u)
        fi
        # Find socket files
        if ! [ "$SEARCH_IN_FOLDER" ]; then
            unix_scks_list2=$(find / -type s 2>/dev/null)
        else
            unix_scks_list2=$(find "$SEARCH_IN_FOLDER" -type s 2>/dev/null)
        fi
        # Process all found sockets
        (printf "%s\n" "$unix_scks_list" && printf "%s\n" "$unix_scks_list2") | sort -u | while read -r socket; do
            if [ -n "$socket" ] && [ -e "$socket" ]; then
                # Get socket information
                socket_info=$(stat -c '%a|%U|%G|%u' "$socket" 2>/dev/null)
                [ -n "$socket_info" ] || socket_info=$(stat -f '%Lp|%Su|%Sg|%u' "$socket" 2>/dev/null)
                if [ -n "$socket_info" ]; then
                    mode=${socket_info%%|*}
                    socket_info=${socket_info#*|}
                    owner=${socket_info%%|*}
                    socket_info=${socket_info#*|}
                    group=${socket_info%%|*}
                    owner_uid=${socket_info#*|}
                else
                    mode="unknown"
                    owner="unknown"
                    group="unknown"
                    owner_uid=""
                fi
                owner_info="$owner:$group"
                read_access="no"
                write_access="no"
                [ -r "$socket" ] && read_access="yes"
                [ -w "$socket" ] && write_access="yes"
                perms=$(get_socket_perms "$socket" "$mode" "$read_access" "$write_access")
                perms=$(check_socket_connectivity "$socket" "$perms")
                echo "Path: $socket"
                echo "  └─ Mode: $mode; Owner/Group: $owner_info"
                echo "  └─ Current user access: read=$read_access, write=$write_access"
                if [ -n "$perms" ]; then
                    echo "  └─ $perms" | sed -${E} "s,Cannot Connect,${SED_GREEN},g"
                fi
                # A discovered socket file can remain after its listener exits.
                listener_is_active=no
                case "
$unix_scks_list
" in
                    *"
$socket
"*) listener_is_active=yes ;;
                esac
                # Only display listener details that came with the existing ss listing.
                case "$ss_metadata" in
                    *"
$socket|"*)
                        listener_info=${ss_metadata#*"
$socket|"}
                        listener_info=${listener_info%%"
"*}
                        listener_pid=${listener_info%%|*}
                        listener_uid=${listener_info#*|}
                        [ -n "$listener_pid" ] && echo "  └─ ss listener PID: $listener_pid"
                        [ -n "$listener_uid" ] && echo "  └─ ss socket UID: $listener_uid"
                        ;;
                esac
                # Access alone does not establish what a service executes.
                if [ "$listener_is_active" = "yes" ] && [ "$owner_uid" = "0" ] && [ "$write_access" = "yes" ]; then
                    echo "  └─ Review lead: current user can write to a root-owned Unix socket; inspect service behavior and privileges."
                fi
                # Preserve the optional protocol check when EXTRA_CHECKS found connectivity.
                if echo "$perms" | grep -q "Can Connect"; then
                    analyze_socket_protocol "$socket" "$owner_info"
                fi
            fi
        done
    fi
    echo ""
fi

fi

if check_mitre_filter "T1559.001"; then
if ! [ "$SEARCH_IN_FOLDER" ]; then
    print_2title "D-Bus Analysis" "T1559.001"
    print_info "https://book.hacktricks.wiki/en/linux-hardening/processes-crontab-systemd-dbus/d-bus-enumeration-and-command-injection-privilege-escalation.html"
    # Function to check for dangerous methods
    check_dangerous_methods() {
        service="$1"
        interface="$2"
        dangerous=0
        dangerous_methods=""
        # Common dangerous method patterns - using space-separated string instead of array
        patterns="StartUnit StopUnit RestartUnit EnableUnit DisableUnit SetProperty SetUser SetPassword CreateUser DeleteUser ModifyUser Execute Run Spawn Shell Command Exec Authenticate Login Logout Reboot Shutdown PowerOff Suspend Hibernate Update Install Uninstall Configure Modify Change Delete Remove Add Create Write Read Access Grant Revoke Allow Deny"
        # Get methods for the interface
        methods=$(busctl introspect "$service" "$interface" 2>/dev/null | grep "method" | awk '{print $2}')
        # Check each method against dangerous patterns
        for method in $methods; do
            for pattern in $patterns; do
                if echo "$method" | grep -qi "$pattern"; then
                    dangerous=1
                    dangerous_methods="${dangerous_methods}${method} "
                fi
            done
        done
        if [ "$dangerous" -eq 1 ]; then
            echo "  └─(${RED}Potentially dangerous methods found${NC})"
            echo "     └─ $dangerous_methods" | sed 's/^/        /'
        fi
        return $dangerous
    }
    # Function to check for dangerous properties
    check_dangerous_properties() {
        service="$1"
        interface="$2"
        dangerous=0
        dangerous_props=""
        # Common dangerous property patterns - using space-separated string instead of array
        patterns="Executable Command Path User Group Permission Access Auth Password Secret Key Token Credential Config Setting Policy Rule Allow Deny Write Read Execute"
        # Get properties for the interface
        properties=$(busctl introspect "$service" "$interface" 2>/dev/null | grep "property" | awk '{print $2}')
        # Check each property against dangerous patterns
        for prop in $properties; do
            for pattern in $patterns; do
                if echo "$prop" | grep -qi "$pattern"; then
                    dangerous=1
                    dangerous_props="${dangerous_props}${prop} "
                fi
            done
        done
        if [ "$dangerous" -eq 1 ]; then
            echo "  └─(${RED}Potentially dangerous properties found${NC})"
            echo "     └─ $dangerous_props" | sed 's/^/        /'
        fi
        return $dangerous
    }
    # Function to analyze service object
    analyze_service_object() {
        dbusservice="$1"
        info=""
        dangerous=0
        # Get service status
        info=$(busctl status "$dbusservice" 2>/dev/null)
        # Check for root ownership
        if echo "$info" | grep -qE "^(UID|EUID|OwnerUID)=0"; then
            echo "  └─(${RED}Running as root${NC})"
            dangerous=1
        fi
        # Get service interfaces
        interfaces=$(busctl tree "$dbusservice" 2>/dev/null)
        if [ -n "$interfaces" ]; then
            echo "  └─ Interfaces:"
            echo "$interfaces" | sed 's/^/     /'
            # Check each interface for dangerous methods and properties
            echo "$interfaces" | while read -r interface; do
                if [ -n "$interface" ]; then
                    if check_dangerous_methods "$dbusservice" "$interface"; then
                        dangerous=1
                    fi
                    if check_dangerous_properties "$dbusservice" "$interface"; then
                        dangerous=1
                    fi
                fi
            done
        fi
        # Check for known dangerous services - using space-separated string instead of array
        dangerous_services="org.freedesktop.systemd1 org.freedesktop.PolicyKit1 org.freedesktop.Accounts org.freedesktop.login1 org.freedesktop.hostname1 org.freedesktop.timedate1 org.freedesktop.locale1 org.freedesktop.machine1 org.freedesktop.portable1 org.freedesktop.resolve1 org.freedesktop.timesync1 org.freedesktop.import1 org.freedesktop.export1 org.gnome.SettingsDaemon org.gnome.Shell org.gnome.SessionManager org.gnome.DisplayManager org.gnome.ScreenSaver"
        for dangerous_service in $dangerous_services; do
            if echo "$dbusservice" | grep -qi "$dangerous_service"; then
                echo "  └─(${RED}Known dangerous service: $dangerous_service${NC})"
                dangerous=1
            fi
        done
        # If service is dangerous, provide exploitation hints
        if [ "$dangerous" -eq 1 ]; then
            echo "  └─(${RED}Potential privilege escalation vector${NC})"
            echo "     └─ Try: busctl call $dbusservice / [Interface] [Method] [Arguments]"
            echo "     └─ Or: dbus-send --session --dest=$dbusservice / [Interface] [Method] [Arguments]"
        fi
    }
    # Function to analyze policy file
    analyze_policy_file() {
        file="$1"
        weak_policies=0
        # Check file permissions
        if ! [ "$IAMROOT" ] && [ -w "$file" ]; then
            echo "  └─(${RED}Writable policy file${NC})"
            weak_policies=$((weak_policies + 1))
        fi
        # Check general policy
        genpol=$(grep "<policy>" "$file" 2>/dev/null)
        if [ -n "$genpol" ]; then
            echo "  └─(${RED}Weak general policy found${NC})"
            echo "     └─ $genpol" | sed 's/^/        /'
            weak_policies=$((weak_policies + 1))
        fi
        # Check user policies
        userpol=$(grep "<policy user=" "$file" 2>/dev/null | grep -v "root")
        if [ -n "$userpol" ]; then
            echo "  └─(${RED}Weak user policy found${NC})"
            echo "     └─ $userpol" | sed -${E} "s,$sh_usrs,${SED_LIGHT_CYAN},g" | sed "s,$USER,${SED_RED},g" | sed -${E} "s,$nosh_usrs,${SED_BLUE},g"
            weak_policies=$((weak_policies + 1))
        fi
        # Check group policies
        grppol=$(grep "<policy group=" "$file" 2>/dev/null | grep -v "root")
        if [ -n "$grppol" ]; then
            echo "  └─(${RED}Weak group policy found${NC})"
            echo "     └─ $grppol" | sed -${E} "s,$sh_usrs,${SED_LIGHT_CYAN},g" | sed "s,$USER,${SED_RED},g" | sed -${E} "s,$nosh_usrs,${SED_BLUE},g" | sed -${E} "s,$mygroups,${SED_RED},g"
            weak_policies=$((weak_policies + 1))
        fi
        # Check for allow rules in default context
        allow_rules=$(grep -A 5 "context=\"default\"" "$file" 2>/dev/null | grep "allow")
        if [ -n "$allow_rules" ]; then
            echo "  └─(${RED}Allow rules in default context${NC})"
            echo "     └─ $allow_rules" | sed 's/^/        /'
            weak_policies=$((weak_policies + 1))
        fi
        # Check for specific dangerous policy patterns - using space-separated string instead of array
        dangerous_patterns="allow_any allow_all allow_root allow_user allow_group allow_anonymous allow_any_user allow_any_group allow_any_uid allow_any_gid allow_any_pid allow_any_connection allow_any_method allow_any_property allow_any_signal allow_any_interface allow_any_path allow_any_destination allow_any_sender allow_any_receiver"
        for pattern in $dangerous_patterns; do
            if grep -qi "$pattern" "$file" 2>/dev/null; then
                echo "  └─(${RED}Dangerous policy pattern found: $pattern${NC})"
                weak_policies=$((weak_policies + 1))
            fi
        done
        return $weak_policies
    }
    # Analyze D-Bus Service Objects
    dbuslist=$(busctl list 2>/dev/null)
    if [ -n "$dbuslist" ]; then
        echo "$dbuslist" | while read -r dbus_service; do
            # Print service name with highlighting
            echo "$dbus_service" | sed -${E} "s,$dbuslistG,${SED_GREEN},g" | sed -${E} "s,$nosh_usrs,${SED_BLUE}," | sed -${E} "s,$rootcommon,${SED_GREEN}," | sed -${E} "s,$knw_usrs,${SED_GREEN}," | sed "s,$USER,${SED_LIGHT_MAGENTA}," | sed "s,root,${SED_RED},"
            # Analyze service if it's not in the known list
            if ! echo "$dbus_service" | grep -qE "$dbuslistG"; then
                dbussrvc_object=$(echo "$dbus_service" | cut -d " " -f1)
                analyze_service_object "$dbussrvc_object"
            fi
        done
    else
        echo_not_found "busctl"
    fi
    # Analyze D-Bus Configuration Files
    if [ "$PSTORAGE_DBUS" ]; then
        echo ""
        print_2title "D-Bus Configuration Files" "T1559.001"
        echo "$PSTORAGE_DBUS" | while read -r dir; do
            [ -n "$dir" ] || continue
            if [ -f "$dir" ]; then
                echo "Analyzing $dir:"
                if analyze_policy_file "$dir"; then
                    echo "  └─(${RED}Multiple weak policies found${NC})"
                fi
                continue
            fi
            [ -d "$dir" ] || continue
            case "$dir" in
                */system-services|*/services)
                    echo "Activation definitions in $dir:"
                    grep -RInE '^(Name|Exec|User)=' "$dir" 2>/dev/null | sed -${E} "s,$Wfolders,${SED_RED_YELLOW},g" | sed "s,Exec=,${SED_RED}Exec=${NC},g" | sed "s,User=,${SED_RED}User=${NC},g"
                    ;;
                *)
                    for dbus_file in "$dir"/*; do
                        if [ -f "$dbus_file" ]; then
                            echo "Analyzing $dbus_file:"
                            if analyze_policy_file "$dbus_file"; then
                                echo "  └─(${RED}Multiple weak policies found${NC})"
                            fi
                        fi
                    done
                    ;;
            esac
        done
    fi
    # Check for D-Bus session bus
    if command -v dbus-send >/dev/null 2>&1; then
        echo ""
        print_3title "D-Bus Session Bus Analysis" "T1559.001"
        if dbus-send --session --dest=org.freedesktop.DBus --type=method_call --print-reply /org/freedesktop/DBus org.freedesktop.DBus.ListNames 2>/dev/null | grep -q "Error"; then
            echo "(${RED}No access to session bus${NC})"
        else
            echo "(${GREEN}Access to session bus available${NC})"
            # List available services on session bus
            session_services=$(dbus-send --session --dest=org.freedesktop.DBus --type=method_call --print-reply /org/freedesktop/DBus org.freedesktop.DBus.ListNames 2>/dev/null | grep "string" | sed 's/^/     /')
            echo "$session_services"
            # Check for known dangerous session services - using space-separated string instead of array
            dangerous_session_services="org.gnome.SettingsDaemon org.gnome.Shell org.gnome.SessionManager org.gnome.DisplayManager org.gnome.ScreenSaver org.freedesktop.Notifications org.freedesktop.ScreenSaver org.freedesktop.PowerManagement org.freedesktop.UPower org.freedesktop.NetworkManager org.freedesktop.Avahi org.freedesktop.UDisks2 org.freedesktop.ModemManager1 org.freedesktop.PackageKit org.freedesktop.PolicyKit1 org.freedesktop.systemd1 org.freedesktop.Accounts org.freedesktop.login1"
            for dangerous_service in $dangerous_session_services; do
                if echo "$session_services" | grep -qi "$dangerous_service"; then
                    echo "  └─(${RED}Known dangerous session service: $dangerous_service${NC})"
                    echo "     └─ Try: dbus-send --session --dest=$dangerous_service / [Interface] [Method] [Arguments]"
                fi
            done
        fi
    fi
fi
echo ""

fi

if check_mitre_filter "T1021.004"; then
rcommands_trust_metadata() {
  # GNU and BSD/OpenBSD stat use different format flags.
  stat -c '%a %U %s' "$1" 2>/dev/null || stat -f '%Lp %Su %z' "$1" 2>/dev/null
}
rcommands_trust_group_other_writable() {
  case "$1" in
    [0-7][0-7][0-7]|[0-7][0-7][0-7][0-7])
      [ "$((0${1} & 0022))" -ne 0 ]
      ;;
    *) return 1 ;;
  esac
}
rcommands_trust_entries() {
  # Read at most 64 KiB and stop after one extra non-comment entry.
  dd if="$1" bs=65536 count=1 2>/dev/null | LC_ALL=C awk -v size="$2" '
    /^[[:space:]]*(#|$)/ { next }
    {
      entries++
      if (entries > 64) {
        print "    [!] Trust entries truncated after 64 lines"
        exit
      }
      if (length($0) > 512) print "    " substr($0, 1, 512) " ... [line shortened]"
      else print "    " $0
      if ($1 !~ /^[-+@]/ && $1 !~ /:/ && $1 ~ /[[:alpha:]]/) hostname = 1
      if ($2 == "+") any_user = 1
      if ($1 == "+" || $2 == "+") wildcard = 1
    }
    END {
      if (size == "" || size + 0 > 65536) print "    [!] Trust-file input limited to first 64 KiB"
      if (hostname) print "    [!] Hostname-based trust candidate: review control of DNS and local name mappings"
      if (any_user) print "    [!] Remote-user + may broaden trust (service and PAM policy still apply)"
      if (wildcard) print "    [!] Wildcard '\''+'\'' trust found"
    }
  '
}
if ! [ "$SEARCH_IN_FOLDER" ]; then
  print_2title "Legacy r-commands (rsh/rlogin/rexec) and host-based trust" "T1021.004"
  echo ""
  print_3title "Listening r-services (TCP 512-514)" "T1021.004"
  if command -v ss >/dev/null 2>&1; then
    ss -ltnp 2>/dev/null | awk '$1 ~ /^LISTEN$/ && $4 ~ /:(512|513|514)$/ {print}' || echo_not_found "ss"
  elif command -v netstat >/dev/null 2>&1; then
    netstat -ltnp 2>/dev/null | awk '$6 ~ /LISTEN/ && $4 ~ /:(512|513|514)$/ {print}' || echo_not_found "netstat"
  else
    echo_not_found "ss|netstat"
  fi
  echo ""
  print_3title "systemd units exposing r-services" "T1021.004"
  if command -v systemctl >/dev/null 2>&1; then
    systemctl list-unit-files 2>/dev/null | grep -E '^(rlogin|rsh|rexec)\.(socket|service)\b' || echo_not_found "rlogin|rsh|rexec units"
    systemctl list-sockets 2>/dev/null | grep -E '\b(rlogin|rsh|rexec)\.socket\b' || true
  else
    echo_not_found "systemctl"
  fi
  echo ""
  print_3title "inetd/xinetd configuration for r-services" "T1021.004"
  if [ -f /etc/inetd.conf ]; then
    grep -vE '^\s*#|^\s*$' /etc/inetd.conf 2>/dev/null | grep -Ei '\b(shell|login|exec|rsh|rlogin|rexec)\b' 2>/dev/null || echo "  No r-services found in /etc/inetd.conf"
  else
    echo_not_found "/etc/inetd.conf"
  fi
  if [ -d /etc/xinetd.d ]; then
    # Print enabled r-services in xinetd
    for f in /etc/xinetd.d/*; do
      [ -f "$f" ] || continue
      if grep -qiE '\b(service|disable)\b' "$f" 2>/dev/null; then
        if grep -qiE 'service\s+(rsh|rlogin|rexec|shell|login|exec)\b' "$f" 2>/dev/null; then
          # Only warn if not disabled
          if ! grep -qiE '^\s*disable\s*=\s*yes\b' "$f" 2>/dev/null; then
            echo "  $(basename "$f") may enable r-services:"; grep -iE '^(\s*service|\s*disable)' "$f" 2>/dev/null | sed 's/^/    /'
          fi
        fi
      fi
    done
  else
    echo_not_found "/etc/xinetd.d"
  fi
  echo ""
  print_3title "Installed r-service server packages" "T1021.004"
  if command -v dpkg >/dev/null 2>&1; then
    dpkg -l 2>/dev/null | grep -E '\b(rsh-server|rsh-redone-server|krb5-rsh-server|inetutils-inetd|openbsd-inetd|xinetd|netkit-rsh)\b' || echo "  No related packages found via dpkg"
  elif command -v rpm >/dev/null 2>&1; then
    rpm -qa 2>/dev/null | grep -Ei '\b(rsh|rlogin|rexec|xinetd)\b' || echo "  No related packages found via rpm"
  else
    echo_not_found "dpkg|rpm"
  fi
  echo ""
  print_3title "/etc/hosts.equiv and /etc/shosts.equiv" "T1021.004"
  for f in /etc/hosts.equiv /etc/shosts.equiv; do
    if [ -f "$f" ]; then
      metadata=$(rcommands_trust_metadata "$f")
      if [ -n "$metadata" ]; then
        perms=${metadata%% *}
        metadata_rest=${metadata#* }
        owner=${metadata_rest%% *}
        size=${metadata_rest##* }
        echo "  $f (perm $perms, owner $owner)"
      else
        size=
        echo "  $f (metadata unavailable)"
      fi
      rcommands_trust_entries "$f" "$size"
    fi
  done
  echo ""
  print_3title "Per-user .rhosts files" "T1021.004"
  any_rhosts=false
  rhosts_scanned=0
  for rfile in /root/.rhosts /home/*/.rhosts; do
    if [ -f "$rfile" ]; then
      rhosts_scanned=$((rhosts_scanned + 1))
      if [ "$rhosts_scanned" -gt 64 ]; then
        echo "  [!] .rhosts discovery limited to first 64 files; coverage is partial"
        break
      fi
      any_rhosts=true
      metadata=$(rcommands_trust_metadata "$rfile")
      if [ -n "$metadata" ]; then
        perms=${metadata%% *}
        metadata_rest=${metadata#* }
        owner=${metadata_rest%% *}
        size=${metadata_rest##* }
        echo "  $rfile (perm $perms, owner $owner)"
      else
        perms=
        size=
        echo "  $rfile (metadata unavailable)"
      fi
      rcommands_trust_entries "$rfile" "$size"
      # Warn on insecure perms (group/other write)
      if rcommands_trust_group_other_writable "$perms"; then
        echo "    [!] Insecure permissions (group/other write)"
      fi
    fi
  done
  if ! $any_rhosts; then echo_not_found ".rhosts"; fi
  echo ""
  print_3title "PAM rhosts authentication" "T1021.004"
  shown=false
  for p in /etc/pam.d/rlogin /etc/pam.d/rsh; do
    if [ -f "$p" ]; then
      shown=true
      echo "  $p:"
      (grep -nEi 'pam_rhosts|pam_rhosts_auth' "$p" 2>/dev/null || echo "    no pam_rhosts* lines") | sed 's/^/    /'
    fi
  done
  if ! $shown; then echo_not_found "/etc/pam.d/rlogin|rsh"; fi
  echo ""
  print_3title "SSH HostbasedAuthentication" "T1021.004"
  if [ -f /etc/ssh/sshd_config ]; then
    if grep -qiE '^[^#]*HostbasedAuthentication\s+yes' /etc/ssh/sshd_config 2>/dev/null; then
      echo "  HostbasedAuthentication yes (check /etc/shosts.equiv or ~/.shosts)"
    else
      echo "  HostbasedAuthentication no or not set"
    fi
  else
    echo_not_found "/etc/ssh/sshd_config"
  fi
  echo ""
  print_3title "Potential DNS control indicators (local)" "T1021.004"
  (ps -eo comm,args 2>/dev/null | grep -Ei '(^|/)(pdns|pdns_server|pdns_recursor|powerdns-admin)( |$)' | grep -Ev 'grep|bash' || echo "  Not detected")
  echo ""
fi

fi

if check_mitre_filter "T1053.003"; then
if ! [ "$SEARCH_IN_FOLDER" ]; then
  print_2title "Crontab UI scheduler checks" "T1053.003"
  print_info "https://book.hacktricks.wiki/en/linux-hardening/processes-crontab-systemd-dbus/cron-and-systemd-timers.html#enumerate-schedules"
  candidates=""
  has_service=""
  has_process=""
  has_binary=""
  if command -v systemctl >/dev/null 2>&1; then
    candidates=$(systemctl list-units --type=service --all --no-legend 2>/dev/null | awk '$1 ~ /[Cc]rontab[-_][Uu][Ii].*\.service$/ { print $1 }')
    found=$(systemctl list-unit-files --type=service --no-legend 2>/dev/null | awk '$1 ~ /[Cc]rontab[-_][Uu][Ii].*\.service$/ { print $1 }')
    candidates=$(printf '%s\n%s\n' "$candidates" "$found" | sed '/^$/d' | sort -u)
  fi
  # Search only service units; grep -E is required for the alternation below.
  for dir in /etc/systemd/system /lib/systemd/system /usr/lib/systemd/system; do
    [ -d "$dir" ] || continue
    found=$(find "$dir" -type f -name '*.service' -exec grep -Eil -e '^[[:space:]]*ExecStart(Pre|Post)?[[:space:]]*=[^#]*crontab-ui' {} + 2>/dev/null | while IFS= read -r unit_file; do basename "$unit_file"; done)
    candidates=$(printf '%s\n%s\n' "$candidates" "$found" | sed '/^$/d' | sort -u)
  done
  [ -n "$candidates" ] && has_service=1
  if command -v crontab-ui >/dev/null 2>&1; then
    has_binary=1
    print_list "crontab-ui binary found"
  else
    echo_not_found "crontab-ui"
  fi
  # Use the executable name, not arbitrary arguments containing 'crontab-ui'.
  # Never print full process arguments: they may contain credentials.
  processes=$(ps -eo user=,comm=,args= 2>/dev/null | awk '
    {
      user=$1; comm=$2; exe=$3; argpath=$4; arg=$4
      sub(/^.*\//, "", comm)
      sub(/^.*\//, "", exe)
      sub(/^.*\//, "", arg)
      if (comm == "crontab-ui" || (comm == "node" && exe == "node" && (arg == "crontab-ui" || argpath ~ /(^|\/)crontab-ui(\/|$)/)))
        print user " crontab-ui"
    }' | sort -u)
  if [ -n "$processes" ]; then
    has_process=1
    printf 'Process evidence (owner and executable only): %s\n' "$processes"
  fi
  if [ -n "$candidates" ]; then
    printf '%s\n' "$candidates" | head -n 20 | while IFS= read -r svc; do
      [ -n "$svc" ] || continue
      state=unknown
      loadstate=unknown
      user=unknown
      envvals=""
      if command -v systemctl >/dev/null 2>&1; then
        state=$(systemctl is-active "$svc" 2>/dev/null) || state=unknown
        loadstate=$(systemctl show "$svc" -p LoadState 2>/dev/null | cut -d= -f2-)
        user=$(systemctl show "$svc" -p User 2>/dev/null | cut -d= -f2-)
        envvals=$(systemctl show "$svc" -p Environment 2>/dev/null | cut -d= -f2-)
      fi
      [ -n "$state" ] || state=unknown
      if [ "$loadstate" = loaded ] && [ -z "$user" ]; then
        user='root (systemd default; configuration evidence)'
      elif [ -z "$user" ]; then
        user=unknown
      fi
      printf 'Service evidence: %s (state: %s, User: %s)\n' "$svc" "$state" "$user"
      if printf '%s\n' "$envvals" | grep -Eq '(^|[[:space:]])BASIC_AUTH_USER='; then
        printf '  BASIC_AUTH_USER is set (value redacted)\n'
      fi
      if printf '%s\n' "$envvals" | grep -Eq '(^|[[:space:]])BASIC_AUTH_PWD='; then
        printf '  BASIC_AUTH_PWD is set (value redacted)\n'
      fi
      printf '\n'
    done
  fi
  # systemctl Environment may be hidden; the exact conventional store is still
  # useful when independent service, binary, or process evidence exists.
  if [ -n "$has_service$has_process$has_binary" ]; then
    dbpath=""
    if [ -n "$candidates" ] && command -v systemctl >/dev/null 2>&1; then
      svc=$(printf '%s\n' "$candidates" | head -n 1)
      envvals=$(systemctl show "$svc" -p Environment 2>/dev/null | cut -d= -f2-)
      dbpath=$(printf '%s\n' "$envvals" | tr ' ' '\n' | sed -n 's/^CRON_DB_PATH=//p' | head -n 1)
    fi
    if [ -n "$dbpath" ]; then
      case "$dbpath" in
        */crontab.db) dbfile=$dbpath ;;
        *) dbfile=${dbpath%/}/crontab.db ;;
      esac
    else
      dbfile=/opt/crontabs/crontab.db
    fi
    if [ -f "$dbfile" ]; then
      if [ ! -r "$dbfile" ]; then
        printf 'DB candidate: %s (unreadable; contents unknown)\n' "$dbfile"
      else
        dbsize=$(stat -L -c %s "$dbfile" 2>/dev/null) || dbsize=$(stat -L -f %z "$dbfile" 2>/dev/null)
        case "$dbsize" in
          ''|*[!0-9]*) printf 'DB candidate: %s (size unknown; contents not inspected)\n' "$dbfile" ;;
          *)
            if [ "$dbsize" -gt 1048576 ]; then
              printf 'DB candidate: %s (readable, oversized: %s bytes; contents not inspected)\n' "$dbfile" "$dbsize"
            else
              printf 'DB candidate: %s (readable, %s bytes; writable by current user: ' "$dbfile" "$dbsize"
              if [ -w "$dbfile" ]; then printf 'yes)\n'; else printf 'no)\n'; fi
              dbsummary=$(LC_ALL=C awk '
                /^[[:space:]]*\{/ && /"command"[[:space:]]*:[[:space:]]*"/ {
                  jobs++
                  command=$0
                  sub(/^.*"command"[[:space:]]*:[[:space:]]*"/, "", command)
                  sub(/".*$/, "", command)
                  if (command ~ /(^|[[:space:]])zip[[:space:]]+[^"]*[[:space:]]-P[[:space:]]+[^[:space:]"\\]+/)
                    credentials++
                }
                END { printf "%d %d", jobs, credentials }
              ' "$dbfile" 2>/dev/null)
              if [ -n "$dbsummary" ]; then
                jobcount=${dbsummary%% *}
                credcount=${dbsummary#* }
                if [ "$jobcount" -eq 0 ]; then
                  printf '  Job store shape unrecognized; contents unknown\n'
                else
                  printf '  Jobs with command fields: %s; inline zip -P credential candidates: %s (values redacted)\n' "$jobcount" "$credcount"
                fi
              else
                printf '  Job store inspection failed; contents unknown\n'
              fi
            fi
            ;;
        esac
      fi
    elif [ -e "$dbfile" ]; then
      printf 'DB candidate: %s (not a regular file; contents unknown)\n' "$dbfile"
    else
      printf 'DB candidate: %s (not found; contents unknown)\n' "$dbfile"
    fi
  fi
  if [ -n "$has_service$has_process" ]; then
    printf 'Review existing Open ports output for a loopback listener; no service binding or credential reuse was verified.\n'
  fi
fi

fi

if check_mitre_filter "T1083"; then
if [ "$(command -v lsof 2>/dev/null || echo -n '')" ] || [ "$DEBUG" ]; then
    print_2title "Deleted files still open" "T1083"
    print_info "Open deleted files can hide tools and still consume disk space"
    lsof +L1 2>/dev/null | sed -${E} "s,\\(deleted\\),${SED_RED},g"
    echo ""
    print_2title "Deleted executables still running" "T1083"
    print_info "A deleted /proc/<PID>/exe may indicate tampering, cleanup, or a useful runtime-only binary"
    ls -l /proc/[0-9]*/exe 2>/dev/null | grep "(deleted)" | sed -${E} "s,\\(deleted\\),${SED_RED},g" | head -n 200
    echo ""
elif [ "$EXTRA_CHECKS" ] || [ "$DEBUG" ]; then
    print_2title "Deleted files still open" "T1083"
    print_info "lsof not found, scanning /proc for deleted file descriptors"
    ls -l /proc/[0-9]*/fd 2>/dev/null | grep "(deleted)" | sed -${E} "s,\\(deleted\\),${SED_RED},g" | head -n 200
    echo ""
    print_2title "Deleted executables still running" "T1083"
    print_info "Scanning /proc/<PID>/exe for deleted runtime binaries"
    ls -l /proc/[0-9]*/exe 2>/dev/null | grep "(deleted)" | sed -${E} "s,\\(deleted\\),${SED_RED},g" | head -n 200
    echo ""
fi

fi

if check_mitre_filter "T1574"; then
if [ "$MACPEAS" ] && ! [ "$SEARCH_IN_FOLDER" ] && ! [ "$IAMROOT" ]; then
  # Return absolute paths found in a defaults/plist dump. Quoted paths retain
  # spaces. The remaining expressions cover unquoted defaults output.
  mupt_paths_from_plist() {
    printf '%s\n' "$1" |
      sed -n \
        -e 's/^[[:space:]]*"\(file:\/\/\/[^"?]*\)"[,;]*[[:space:]]*$/\1/p' \
        -e 's/.*"\(file:\/\/\/[^"?]*\)".*/\1/p' \
        -e 's/^[[:space:]]*"\(\/[^"?]*\)"[,;]*[[:space:]]*$/\1/p' \
        -e 's/.*"\(\/[^"?]*\)".*/\1/p' \
        -e 's/.*=>[[:space:]]*\(\/[^,;)]*\).*/\1/p' \
        -e 's/.*=[[:space:]]*\(\/[^,;)]*\).*/\1/p' \
        -e 's/^[[:space:]]*\(\/[^,;)]*\)[,;]*[[:space:]]*$/\1/p' |
      sort -u
  }
  # Print one record when the configured update path, its payload, or one of
  # its existing parent components is controlled by the current user. Sticky
  # directories are not enough on their own to replace another user's entry,
  # but a directly writable/user-owned payload remains attacker-controlled.
  mupt_check_path() {
    mupt_job="$1"
    mupt_source="$2"
    mupt_path="$3"
    case "$mupt_path" in
      file://*) mupt_path="${mupt_path#file://}" ;;
    esac
    case "$mupt_path" in
      /*) ;;
      *) return 0 ;;
    esac
    mupt_lower_path="$(printf '%s' "$mupt_path" | tr '[:upper:]' '[:lower:]')"
    case "$mupt_lower_path" in
      *cache*|*download*|*electron*|*shipit*|*squirrel*|*stag*|*temp*|*tmp*|*updat*) ;;
      *) return 0 ;;
    esac
    mupt_user_id="$(id -u 2>/dev/null)"
    if [ -e "$mupt_path" ]; then
      mupt_path_owner="$(stat -f '%u' "$mupt_path" 2>/dev/null)"
      if [ -w "$mupt_path" ] || { [ -n "$mupt_user_id" ] && [ "$mupt_path_owner" = "$mupt_user_id" ]; }; then
        printf '%s|%s|%s|%s\n' "$mupt_job" "$mupt_source" "$mupt_path" "$mupt_path"
        return 0
      fi
    fi
    if [ -d "$mupt_path" ]; then
      mupt_dir="$mupt_path"
    else
      mupt_dir="${mupt_path%/*}"
      [ -n "$mupt_dir" ] || mupt_dir="/"
      while [ ! -d "$mupt_dir" ] && [ "$mupt_dir" != "/" ]; do
        mupt_dir="${mupt_dir%/*}"
        [ -n "$mupt_dir" ] || mupt_dir="/"
      done
    fi
    while [ -d "$mupt_dir" ]; do
      if [ -w "$mupt_dir" ] && [ -x "$mupt_dir" ]; then
        mupt_dir_mode="$(stat -f '%Sp' "$mupt_dir" 2>/dev/null)"
        case "$mupt_dir_mode" in
          *t|*T) ;;
          *)
            printf '%s|%s|%s|%s\n' "$mupt_job" "$mupt_source" "$mupt_path" "$mupt_dir"
            return 0
            ;;
        esac
      fi
      [ "$mupt_dir" = "/" ] && break
      mupt_dir="${mupt_dir%/*}"
      [ -n "$mupt_dir" ] || mupt_dir="/"
    done
  }
  mupt_launchdaemons_dir="${ROOT_FOLDER:-}/Library/LaunchDaemons"
  # Keep the collector body outside command-substitution syntax. macOS still
  # ships Bash 3.2, whose parser can miscount parentheses inside quoted EREs
  # when they appear directly in a multiline $(...) body.
  mupt_collect_records() {
    # System LaunchDaemons run as root unless UserName says otherwise. Ignore
    # user-writable plists because existing launchd checks already report that
    # stronger, direct privilege-escalation condition.
    for mupt_plist in "$mupt_launchdaemons_dir"/*.plist; do
      [ -f "$mupt_plist" ] || continue
      [ -w "$mupt_plist" ] && continue
      mupt_plist_owner="$(stat -f '%u' "$mupt_plist" 2>/dev/null)"
      [ "$mupt_plist_owner" = "0" ] || continue
      mupt_plist_data="$(defaults read "$mupt_plist" 2>/dev/null)"
      [ -n "$mupt_plist_data" ] || continue
      printf '%s\n%s\n' "$mupt_plist" "$mupt_plist_data" |
        grep -Eiq '(electron|install|patch|shipit|squirrel|updat(e|er)|upgrade)' || continue
      mupt_user="$(defaults read "$mupt_plist" UserName 2>/dev/null | head -n 1)"
      case "$mupt_user" in
        ""|0|root) ;;
        *) continue ;;
      esac
      mupt_paths_from_plist "$mupt_plist_data" | while IFS= read -r mupt_path; do
        [ -n "$mupt_path" ] || continue
        mupt_check_path "$mupt_plist" "root LaunchDaemon metadata" "$mupt_path"
      done
    done
    # A privileged helper or an updater inside an application bundle may only
    # expose its staging path while running. Inspect only root updater commands;
    # do not scan every writable temporary directory on the host and never eval
    # process arguments.
    # pgrep cannot emit the user, PID, and full command together portably.
    # shellcheck disable=SC2009
    ps -axo user=,pid=,command= 2>/dev/null |
      grep -Ei '^[[:space:]]*root[[:space:]]+[0-9]+[[:space:]].*(electron|install|patch|shipit|squirrel|updat(e|er)|upgrade)' |
      while IFS= read -r mupt_candidate; do
        mupt_pid="$(printf '%s\n' "$mupt_candidate" | awk '{print $2}')"
        printf '%s\n' "$mupt_candidate" |
          grep -Eo '/[^()[:space:]",;]+' 2>/dev/null |
          sort -u |
          while IFS= read -r mupt_path; do
            mupt_check_path "PID $mupt_pid" "root updater command line" "$mupt_path"
          done
      done
  }
  mupt_records="$(mupt_collect_records | sort -u)"
  if [ -n "$mupt_records" ]; then
    print_3title "Potential privileged updater TOCTOU paths" "T1574"
    print_info "https://blog.doyensec.com/2026/02/16/electron-safe-updater.html"
    print_info "Root updater candidates reference paths controlled by the current user. Manually verify whether an update is checked by pathname and later reopened for privileged installation instead of using the same descriptor or another immutable handle."
    printf '%s\n' "$mupt_records" | while IFS='|' read -r mupt_job mupt_source mupt_path mupt_dir; do
      mupt_details="$mupt_job: $mupt_path ($mupt_source; writable path or component: $mupt_dir)"
      printf '%s\n' "$mupt_details" | sed -"${E}" "s,.*,${SED_RED_YELLOW},"
      ls -ld "$mupt_path" "$mupt_dir" 2>/dev/null
    done
    echo ""
  fi
fi

fi

if check_mitre_filter "T1552.001"; then
lp_xvfb_fbdir_from_cmdline() {
  tr '\000' '\n' < "$1" 2>/dev/null | awk '
    NR == 1 {
      name = $0
      sub(/^.*\//, "", name)
      if (name != "Xvfb") exit
    }
    want_dir { if ($0 != "") print; exit }
    $0 == "-fbdir" { want_dir = 1 }
  '
}
lp_xvfb_candidate_pids() {
  local proc_root="$1" proc comm found=0
  if [ "$proc_root" = /proc ] && command -v pgrep >/dev/null 2>&1; then
    pgrep -x Xvfb 2>/dev/null | head -n 8
    return
  fi
  # Fallback for systems without pgrep. Inspect only comm for other processes;
  # stop after eight actual Xvfb candidates, regardless of PID ordering.
  for proc in "$proc_root"/[0-9]*; do
    [ -r "$proc/comm" ] || continue
    IFS= read -r comm < "$proc/comm" || continue
    [ "$comm" = Xvfb ] || continue
    printf '%s\n' "${proc##*/}"
    found=$((found + 1))
    [ "$found" -lt 8 ] || break
  done
}
lp_check_xvfb_fbdir() {
  local proc_root="${1:-/proc}" current_uid="${2:-$(id -u)}"
  local proc pid fbdir comm process_uid metadata owner_uid mode screen screens cwd printed=0
  [ -d "$proc_root" ] || return 0
  # Root can normally read every user's framebuffer, so this is useful for
  # unprivileged cross-user access only.
  [ "$current_uid" = 0 ] && return 0
  for pid in $(lp_xvfb_candidate_pids "$proc_root"); do
    proc="$proc_root/$pid"
    [ -r "$proc/comm" ] && [ -r "$proc/cmdline" ] && [ -r "$proc/status" ] || continue
    IFS= read -r comm < "$proc/comm" || continue
    [ "$comm" = Xvfb ] || continue
    process_uid=$(awk '$1 == "Uid:" { print $3; exit }' "$proc/status" 2>/dev/null)
    case "$process_uid" in ''|*[!0-9]*) continue ;; esac
    [ "$process_uid" != "$current_uid" ] || continue
    fbdir=$(lp_xvfb_fbdir_from_cmdline "$proc/cmdline")
    [ -n "$fbdir" ] || continue
    case "$fbdir" in
      /*) ;;
      *) cwd=$(readlink "$proc/cwd" 2>/dev/null) || continue
         [ -n "$cwd" ] || continue
         fbdir="$cwd/$fbdir" ;;
    esac
    [ -d "$fbdir" ] || continue
    screens=$(find "$fbdir" -maxdepth 1 -type f -name 'Xvfb_screen*' -print 2>/dev/null | head -n 8)
    [ -n "$screens" ] || continue
    while IFS= read -r screen; do
      [ -f "$screen" ] && [ -r "$screen" ] || continue
      metadata=$(stat -c '%u %a' -- "$screen" 2>/dev/null) || continue
      owner_uid=${metadata%% *}
      mode=${metadata#* }
      [ "$owner_uid" = "$process_uid" ] || continue
      [ "$owner_uid" != "$current_uid" ] || continue
      if [ "$printed" -eq 0 ]; then
        print_2title "Readable cross-user Xvfb framebuffer files" "T1552.001"
        printed=1
      fi
      printf 'Review: running Xvfb PID %s exposes readable framebuffer: %s (owner UID %s, mode 0%s)\n' "$pid" "$screen" "$owner_uid" "$mode"
    done <<EOF
$screens
EOF
  done
  [ "$printed" -eq 0 ] || echo ""
}
if ! [ "$SEARCH_IN_FOLDER" ] && ! [ "$MACPEAS" ] && [ -d /proc ]; then
  lp_check_xvfb_fbdir
fi

fi

if check_mitre_filter "T1552.001"; then
lp_erlang_ssh_source_from_ps() {
  printf '%s\n' "$1" | awk '
    {
      n = split($0, a, /[[:space:]]+/)
      executable = a[1]
      sub(/^.*\//, "", executable)
      if (executable != "escript") exit
      for (i = 2; i <= n; i++)
        if (a[i] ~ /^\/[^[:space:]]+\.(escript|erl)$/) { print a[i]; exit }
    }'
}
lp_erlang_ssh_source_from_proc() {
  [ -r "$1" ] || return 1
  tr '\000' '\n' < "$1" 2>/dev/null | awk '
    NR == 1 {
      executable = $0
      sub(/^.*\//, "", executable)
      if (executable != "escript") exit
      next
    }
    /^\/.*\.(escript|erl)$/ { print; exit }'
}
lp_erlang_ssh_markers() {
  awk '
    NR > 4096 { exit }
    {
      # Ignore comments and quoted strings, including markers placed in examples.
      line = $0 "\n"
      for (i = 1; i <= length(line); i++) {
        c = substr(line, i, 1)
        if (comment) { if (c == "\n") comment = 0; continue }
        if (quoted) {
          if (escape) { escape = 0; continue }
          if (c == "\\") { escape = 1; continue }
          if (c == quote) quoted = 0
          continue
        }
        if (c == "%") { comment = 1; continue }
        if (c == "\"" || c == "\047") { quoted = 1; quote = c; continue }
        code = code c
      }
    }
    END {
      gsub(/[[:space:]]+/, " ", code)
      if (code !~ /ssh[[:space:]]*:[[:space:]]*daemon[[:space:]]*\(/) exit
      auth = "none"
      if (code ~ /[{][[:space:]]*user_passwords[[:space:]]*,[[:space:]]*\[/) auth = "literal_user_passwords"
      else if (code ~ /[{][[:space:]]*(user_passwords|password|pwdfun|user_dir_fun|publickey|public_key)[[:space:]]*,/) auth = "auth_option"
      shell = "unknown"
      if (code ~ /[{][[:space:]]*shell[[:space:]]*,[[:space:]]*disabled/ || code ~ /[{][[:space:]]*ssh_cli[[:space:]]*,[[:space:]]*no_cli/) shell = "disabled_marker"
      else if (code ~ /[{][[:space:]]*(shell|ssh_cli)[[:space:]]*,/) shell = "explicit_option"
      print auth, shell
    }' "$1" 2>/dev/null
}
lp_check_erlang_ssh_daemons() {
  # Optional arguments let focused fixtures supply a ps snapshot and proc root.
  local snapshot="$1" proc_root="${2:-/proc}" ps_rows pid uid command source physical_dir canonical size markers auth shell
  local candidates=0 files=0 printed=0 unknowns=0 seen_files='|'
  if [ -n "$snapshot" ]; then
    [ -r "$snapshot" ] || return 0
    ps_rows=$(cat "$snapshot" 2>/dev/null)
  else
    ps_rows=$(ps -eo pid=,uid=,args= 2>/dev/null) || ps_rows=$(ps -axo pid=,uid=,command= 2>/dev/null) || return 0
  fi
  [ -n "$ps_rows" ] || return 0
  while read -r pid uid command; do
    case "$pid:$uid" in *[!0-9:]*|:*|*:) continue ;; esac
    case "$command" in
      erl|erlang|escript|beam|beam.smp|*/erl|*/erlang|*/escript|*/beam|*/beam.smp|erl\ *|erlang\ *|escript\ *|beam\ *|beam.smp\ *|*/erl\ *|*/erlang\ *|*/escript\ *|*/beam\ *|*/beam.smp\ *) ;;
      *) continue ;;
    esac
    candidates=$((candidates + 1))
    [ "$candidates" -le 64 ] || break
    source=''
    if [ -r "$proc_root/$pid/cmdline" ]; then
      source=$(lp_erlang_ssh_source_from_proc "$proc_root/$pid/cmdline")
    fi
    [ -n "$source" ] || source=$(lp_erlang_ssh_source_from_ps "$command")
    if [ -z "$source" ]; then
      if [ "$unknowns" -lt 8 ]; then
        [ "$printed" -eq 1 ] || { print_2title 'Running Erlang SSH source candidates' 'T1552.001'; printed=1; }
        printf 'Candidate: Erlang PID %s UID %s; absolute launched source unavailable (SSH status unknown).\n' "$pid" "$uid"
        unknowns=$((unknowns + 1))
      fi
      continue
    fi
    # Resolve parent directories physically; refuse a symlink at the final component.
    case "$source" in /*.escript|/*.erl) ;; *) continue ;; esac
    if [ -L "$source" ]; then
      canonical=''
    else
      physical_dir=$(cd -P "${source%/*}" 2>/dev/null && pwd -P) || physical_dir=''
      canonical="$physical_dir/${source##*/}"
    fi
    if [ -z "$physical_dir" ] || [ ! -f "$canonical" ] || [ ! -r "$canonical" ]; then
      if [ "$unknowns" -lt 8 ]; then
        [ "$printed" -eq 1 ] || { print_2title 'Running Erlang SSH source candidates' 'T1552.001'; printed=1; }
        printf 'Candidate: Erlang PID %s UID %s; launched source inaccessible or symlinked: %s (SSH status unknown).\n' "$pid" "$uid" "$source"
        unknowns=$((unknowns + 1))
      fi
      continue
    fi
    case "$seen_files" in
      *"|$canonical|"*) ;;
      *) seen_files="$seen_files$canonical|"
         files=$((files + 1))
         [ "$files" -le 32 ] || break ;;
    esac
    size=$(wc -c < "$canonical" 2>/dev/null) || continue
    case "$size" in ''|*[!0-9]*) continue ;; esac
    if [ "$size" -gt 131072 ]; then
      if [ "$unknowns" -lt 8 ]; then
        [ "$printed" -eq 1 ] || { print_2title 'Running Erlang SSH source candidates' 'T1552.001'; printed=1; }
        printf 'Candidate: Erlang PID %s UID %s; launched source exceeds 128 KiB: %s (SSH status unknown).\n' "$pid" "$uid" "$canonical"
        unknowns=$((unknowns + 1))
      fi
      continue
    fi
    markers=$(lp_erlang_ssh_markers "$canonical")
    [ -n "$markers" ] || continue
    auth=${markers%% *}
    shell=${markers#* }
    [ "$auth" != none ] || [ "$shell" != unknown ] || continue
    [ "$printed" -eq 1 ] || { print_2title 'Running Erlang SSH source candidates' 'T1552.001'; printed=1; }
    printf 'Candidate: Erlang SSH PID %s UID %s source %s; auth=%s, shell=%s.\n' "$pid" "$uid" "$canonical" "$auth" "$shell"
  done <<EOF
$ps_rows
EOF
  if [ "$printed" -eq 1 ]; then
    printf '%s\n' 'Review the live daemon options and OTP version: readable source markers do not prove accepted credentials or an Erlang shell. No authentication was attempted.'
    echo ''
  fi
}
if ! [ "$SEARCH_IN_FOLDER" ]; then
  lp_check_erlang_ssh_daemons
fi

fi

if check_mitre_filter "T1559"; then
# This is a single snapshot. Short-lived segments can disappear before it runs;
# absence is not evidence that a privileged IPC consumer is safe. Never attach
# to a segment or launch a privileged helper to make one appear.
if [ ! "$SEARCH_IN_FOLDER" ] && command -v ipcs >/dev/null 2>&1; then
  sysv_shm_report=$(LC_ALL=C ipcs -m 2>/dev/null | awk '
    NR > 512 { limited = 1; exit }
    {
      if (tolower($1) == "key" && tolower($2) == "shmid" &&
          tolower($3) == "owner" && tolower($4) == "perms") {
        format = "linux"
        next
      }
      if (toupper($1) == "T" && toupper($2) == "ID" &&
          toupper($3) == "KEY" && toupper($4) == "MODE" &&
          toupper($5) == "OWNER") {
        format = "bsd"
        next
      }
      if (format == "linux" && NF >= 5) {
        id = $2; key = $1; owner = $3; perms = $4; size = $5
      } else if (format == "bsd" && NF >= 6 && $1 == "m") {
        id = $2; key = $3; perms = $4; owner = $5; size = "unknown"
      } else next
      if (owner != "root" && owner != "0") next
      other_writable = 0
      if (perms ~ /^[0-7]+$/ && length(perms) >= 3) {
        last = substr(perms, length(perms), 1)
        if (last ~ /[2367]/) other_writable = 1
      } else if (perms ~ /^[-a-zA-Z][-a-zA-Z][r-][w-][xstST-][r-][w-][xstST-][r-][w-][xstST-]$/) {
        if (substr(perms, length(perms) - 1, 1) == "w") other_writable = 1
      }
      if (!other_writable) next
      if (shown < 20) {
        printf "Root-owned System V shared memory writable by others: id=%s key=%s mode=%s size=%s\n", id, key, perms, size
        shown++
      } else limited = 1
    }
    END { if (limited) print "System V shared-memory review incomplete (512-line/20-candidate limit)" }
  ')
  if [ "$sysv_shm_report" ]; then
    print_2title "Writable privileged System V shared memory (review candidates)" "T1559"
    print_info "https://book.hacktricks.wiki/en/linux-hardening/processes-crontab-systemd-dbus/process-enumeration-and-service-paths.html#system-v-shared-memory-consumed-by-privileged-processes"
    printf '%s\n' "$sysv_shm_report"
    printf '%s\n' "A writable segment needs a privileged consumer that trusts it to be exploitable; this snapshot can miss transient segments."
  fi
fi

fi

fi

fi
echo ''
echo ''
if [ "$WAIT" ]; then echo "Press enter to continue"; read "asd"; fi

if echo $CHECKS | grep -q network_information; then
if check_mitre_filter "T1016,T1590,T1018,T1040,T1049"; then
print_title "Network Information"
if check_mitre_filter "T1016"; then
# Function to parse network interfaces from /proc/net/dev and other sources
parse_network_interfaces() {
    # Try to get interfaces from /proc/net/dev
    if [ -f "/proc/net/dev" ]; then
        echo "Network Interfaces from /proc/net/dev:"
        echo "----------------------------------------"
        # Skip header lines and format output
        grep -v "^Inter\|^ face" /proc/net/dev | while read -r line; do
            iface=$(echo "$line" | awk -F: '{print $1}' | tr -d ' ')
            if [ -n "$iface" ]; then
                echo "Interface: $iface"
                # Try to get IP address from /sys/class/net
                if [ -f "/sys/class/net/$iface/address" ]; then
                    mac=$(cat "/sys/class/net/$iface/address" 2>/dev/null)
                    echo "  MAC: $mac"
                fi
                # Try to get IP from /sys/class/net
                if [ -d "/sys/class/net/$iface/ipv4" ]; then
                    for ip_file in /sys/class/net/$iface/ipv4/addr_*; do
                        if [ -f "$ip_file" ]; then
                            ip=$(cat "$ip_file" 2>/dev/null)
                            echo "  IP: $ip"
                        fi
                    done
                fi
                # Get interface state
                if [ -f "/sys/class/net/$iface/operstate" ]; then
                    state=$(cat "/sys/class/net/$iface/operstate" 2>/dev/null)
                    echo "  State: $state"
                fi
                echo ""
            fi
        done
    fi
    # Try to get additional info from /proc/net/fib_trie
    if [ -f "/proc/net/fib_trie" ]; then
        echo "Additional IP Information from fib_trie:"
        echo "----------------------------------------"
        grep -A1 "Main" /proc/net/fib_trie | grep -v "\-\-" | while read -r line; do
            if echo "$line" | grep -q "Main"; then
                echo "Network: $(echo "$line" | awk '{print $2}')"
            elif echo "$line" | grep -q "/"; then
                echo "  IP: $(echo "$line" | awk '{print $2}')"
            fi
        done
    fi
}
print_2title "Interfaces" "T1016"
cat /etc/networks 2>/dev/null
