awk -F: '$6 ~ /^\// && $7 !~ /(nologin|false)$/ && $6 != "/" && $6 != "/nonexistent" && !seen[$6]++ { print $6; if (++n == 64) exit }' /etc/passwd 2>/dev/null | pgp_private_key_candidates
