    /^[[:space:]]*\([^)]*\)[[:space:]]/ {
      previous_rule = 1
      line = $0
      sub(/^[[:space:]]*\(/, "", line)
      runas = line
      sub(/\).*/, "", runas)
      split(runas, parts, ":")
      users = parts[1]
      root_capable = users ~ /(^|[[:space:],])(ALL|root|#0)([[:space:],]|$)/ &&
                     users !~ /(^|[[:space:],])!(ALL|root|#0)([[:space:],]|$)/
      sub(/^[^)]*\)[[:space:]]*/, "", line)
      review(line, root_capable)
      next
    }
    previous_rule && /^[[:space:]]+[^[:space:]]/ { ambiguous = 1; exit }
