              ;;
          esac
        done <<EOF
$doas_test_commands
EOF
      else
        echo "doas rejected or could not validate $conf_file with -C; inspect its syntax and security properties" | sed -${E} "s,.*,${SED_RED_YELLOW},g"
      fi
    fi
  done <<EOF
$doas_conf_candidates
EOF
  if [ "$doas_conf_found" = "no" ]; then
