if [ -n "$pkexec_bin" ]; then
  echo "Pkexec binary found at: $pkexec_bin" | sed -${E} "s,.*,${SED_LIGHT_CYAN},g"
  if [ -u "$pkexec_bin" ]; then
    echo "Pkexec binary has SUID bit set!" | sed -${E} "s,.*,${SED_RED},g"
  fi
  ls -l "$pkexec_bin" 2>/dev/null
  # The local escalation requires an executable root-owned SUID pkexec.
  pkexec_owner=$(LC_ALL=C ls -ldnL "$pkexec_bin" 2>/dev/null | awk 'NR == 1 { print $3 }')
  if [ -f "$pkexec_bin" ] && [ -x "$pkexec_bin" ] && [ -u "$pkexec_bin" ] && [ "$pkexec_owner" = 0 ]; then
    pkexec_version_output=$(pkexec --version 2>/dev/null)
    if [ -n "$pkexec_version_output" ]; then printf '%s\n' "$pkexec_version_output"; fi
    pkexec_version=$(printf '%s\n' "$pkexec_version_output" | awk 'match($0, /[0-9]+([.][0-9]+)+/) { print substr($0, RSTART, RLENGTH); exit }')
    pkexec_major=${pkexec_version%%.*}
    pkexec_minor=${pkexec_version#*.}
    pkexec_minor=${pkexec_minor%%.*}
    case "$pkexec_major:$pkexec_minor" in
      *[!0-9:]*|:|*:) ;;
      *) if [ "$pkexec_major" -eq 0 ] && [ "$pkexec_minor" -lt 120 ]; then
           echo "CVE-2021-4034 candidate: root-owned SUID pkexec with older upstream version; verify distro package fixes and mitigations" | sed -${E} "s,.*,${SED_RED_YELLOW},"
         fi ;;
    esac
  else
    echo "Pkexec is not an executable root-owned SUID binary; local SUID exploit candidate suppressed"
  fi
fi
# Check polkit policies
echo ""
print_3title "Polkit Policies" "T1548.003"
for policy_dir in "/etc/polkit-1/localauthority.conf.d/" "/etc/polkit-1/rules.d/" "/usr/share/polkit-1/rules.d/"; do
  if [ -d "$policy_dir" ]; then
    echo "Checking $policy_dir:" | sed -${E} "s,.*,${SED_LIGHT_CYAN},g"
    if [ -w "$policy_dir" ]; then
      echo "WARNING: $policy_dir is writable!" | sed -${E} "s,.*,${SED_RED},g"
    fi
    for policy_file in "$policy_dir"/*; do
      if [ -f "$policy_file" ]; then
        if [ -w "$policy_file" ]; then
          echo "WARNING: $policy_file is writable!" | sed -${E} "s,.*,${SED_RED},g"
        fi
        cat "$policy_file" 2>/dev/null | grep -v "^#" | grep -Ev "\W+\#|^#" 2>/dev/null | sed -${E} "s,$groupsB,${SED_RED},g" | sed -${E} "s,$groupsVB,${SED_RED},g" | sed -${E} "s,$sh_usrs,${SED_LIGHT_CYAN},g" | sed -${E} "s,$nosh_usrs,${SED_BLUE},g" | sed "s,$USER,${SED_RED},g" | sed -${E} "s,$Groups,${SED_RED},g"
      fi
    done
  fi
done
# Check for polkit authentication agent
echo ""
print_3title "Polkit Authentication Agent" "T1548.004"
ps aux 2>/dev/null | grep -i "polkit" | grep -v "grep"
echo ""

fi

if check_mitre_filter "T1087.001"; then
# Collect the existing UID 0 inventory and a bounded local duplicate-UID cue
# in one read of /etc/passwd. A shared UID is a review lead, not root access.
summarize_local_passwd() {
  awk -F: '
    $3 ~ /^[0-9]+$/ && $3 + 0 == 0 { print "R\t" $0 }
    NR == 4097 { print "P" }
    NR <= 4096 && $1 != "" && $3 ~ /^[0-9]+$/ && $3 + 0 > 0 {
        uid = $3 + 0
        if (uid in first) {
            if (++duplicates <= 32) print "D\t" uid "\t" first[uid] "\t" $1
            else if (duplicates == 33) print "L"
        } else first[uid] = $1
    }
  ' "$1" 2>/dev/null
}
print_2title "Superusers and UID 0 Users" "T1087.001"
print_info "https://book.hacktricks.wiki/en/linux-hardening/user-information/interesting-groups-linux-pe/index.html"
passwd_identity_rows=$(summarize_local_passwd /etc/passwd)
echo ""
print_3title "Users with UID 0 in /etc/passwd" "T1087.001"
printf '%s\n' "$passwd_identity_rows" | awk -F '\t' '$1 == "R" { sub(/^R\t/, ""); print }' | sed -${E} "s,$sh_usrs,${SED_LIGHT_CYAN},g" | sed -${E} "s,$nosh_usrs,${SED_BLUE},g" | sed -${E} "s,$knw_usrs,${SED_GREEN},g" | sed "s,$USER,${SED_RED_YELLOW},g" | sed "s,root,${SED_RED},g"
shared_uid_rows=$(printf '%s\n' "$passwd_identity_rows" | awk -F '\t' '
    $1 == "D" { printf "UID %s: %s, %s\n", $2, $3, $4 }
    $1 == "L" { print "Partial: first 32 shared-UID pairs shown." }
')
if [ -n "$shared_uid_rows" ]; then
    echo ""
    print_3title "Accounts sharing nonzero local UIDs (review candidate)" "T1087.001"
    printf '%s\n' "$shared_uid_rows"
    echo "Shared UIDs can be intentional; verify account ownership, authentication, and local policy."
fi
if printf '%s\n' "$passwd_identity_rows" | grep -q '^P$'; then
    echo "Shared-UID comparison partial: only the first 4096 local accounts were compared."
fi
if command -v getent >/dev/null 2>&1; then
    for group in sudo wheel adm docker lxd lxc root shadow disk video; do
        if group_entry=$(getent group "$group" 2>/dev/null) && [ -n "$group_entry" ]; then
            echo "- Users in group '$group':"
            printf '%s\n' "$group_entry" | sed -${E} "s,$sh_usrs,${SED_LIGHT_CYAN},g" | sed -${E} "s,$nosh_usrs,${SED_BLUE},g" | sed -${E} "s,$knw_usrs,${SED_GREEN},g" | sed "s,$USER,${SED_RED},g" | sed "s,root,${SED_RED},g"
        fi
    done
fi
# Check for users with sudo privileges in sudoers
echo ""
print_3title "Users with sudo privileges in sudoers" "T1087.001"
grep -v "^#" /etc/sudoers 2>/dev/null | grep -v "^$" | grep -v "^Defaults" | sed -${E} "s,$sh_usrs,${SED_LIGHT_CYAN},g" | sed -${E} "s,$nosh_usrs,${SED_BLUE},g" | sed -${E} "s,$knw_usrs,${SED_GREEN},g" | sed "s,$USER,${SED_RED_YELLOW},g" | sed "s,root,${SED_RED},g"
echo ""

fi

if check_mitre_filter "T1087.001"; then
print_2title "Users with console" "T1087.001"
if [ "$MACPEAS" ]; then
  dscl . list /Users | while read un; do
    ushell=$(dscl . -read "/Users/$un" UserShell | cut -d " " -f2)
    if grep -q "$ushell" /etc/shells; then #Shell user
      dscl . -read "/Users/$un" UserShell RealName RecordName Password NFSHomeDirectory 2>/dev/null | sed -${E} "s,$sh_usrs,${SED_LIGHT_CYAN}," | sed "s,$USER,${SED_LIGHT_MAGENTA}," | sed "s,root,${SED_RED},"
      echo ""
    fi
  done
else
  no_shells=$(grep -Ev "sh$" /etc/passwd 2>/dev/null | cut -d ':' -f 7 | sort | uniq)
  unexpected_shells=""
  printf "%s\n" "$no_shells" | while read f; do
    if [ -x "$f" ]; then
      if [ "$TIMEOUT" ]; then
        if $TIMEOUT 1 "$f" -c 'whoami' 2>/dev/null | grep -q "$USER"; then
          unexpected_shells="$f\n$unexpected_shells"
        fi
      else
        if "$f" -c 'whoami' 2>/dev/null | grep -q "$USER"; then
          unexpected_shells="$f\n$unexpected_shells"
        fi
      fi
    fi
  done
  grep "sh$" /etc/passwd 2>/dev/null | sort | sed -${E} "s,$sh_usrs,${SED_LIGHT_CYAN}," | sed "s,$USER,${SED_LIGHT_MAGENTA}," | sed "s,root,${SED_RED},"
  if [ "$unexpected_shells" ]; then
    printf "%s" "These unexpected binaries are acting like shells:\n$unexpected_shells" | sed -${E} "s,/.*,${SED_RED},g"
    echo "Unexpected users with shells:"
    printf "%s\n" "$unexpected_shells" | while read f; do
      if [ "$f" ]; then
        grep -E "${f}$" /etc/passwd | sed -${E} "s,/.*,${SED_RED},g"
      fi
    done
  fi
fi
echo ""

fi

