    if [ -f "$lp_below_candidate" ] && [ -x "$lp_below_candidate" ]; then
      lp_below_binary="$lp_below_candidate"
      break
    fi
  done
  [ -n "$lp_below_binary" ] && lp_below_check_log_directory "$lp_below_binary" /var/log/below /var/log/below/error_root.log
fi

fi

