            if [ "$consul_writable_dirs" ]; then
              consul_writable_dirs="$consul_writable_dirs
$consul_config_path"
            else
              consul_writable_dirs=$consul_config_path
            fi
          fi
          set -- "$consul_config_path"/*.json "$consul_config_path"/*.hcl
        else
