    if ! [ "`echo \"$PSTORAGE_DUPLICATI_SERVER_STATE\" | grep -E \"Duplicati-server\.sqlite$\"`" ]; then if [ "$DEBUG" ]; then echo_not_found "Duplicati-server.sqlite"; fi; fi; printf "%s" "$PSTORAGE_DUPLICATI_SERVER_STATE" | grep -E "Duplicati-server\.sqlite$" | while read f; do ls -ld "$f" 2>/dev/null | sed -${E} "s,Duplicati-server\.sqlite$,${SED_RED},"; done; echo "";
fi


