    if ! [ "`echo \"$PSTORAGE_ROUNDCUBE\" | grep -E \"roundcube$\"`" ]; then if [ "$DEBUG" ]; then echo_not_found "roundcube"; fi; fi; printf "%s" "$PSTORAGE_ROUNDCUBE" | grep -E "roundcube$" | while read f; do ls -ld "$f" 2>/dev/null | sed -${E} "s,roundcube$,${SED_RED},"; find "$f" -name "config.inc.php" | while read ff; do ls -ld "$ff" | sed -${E} "s,config.inc.php,${SED_RED},"; cat "$ff" 2>/dev/null | grep -IEv "^$" | grep -E 'db_dsnw|des_key|cipher_method|session_storage' | awk 'match($0, /^[[:space:]]*\$config[[:space:]]*\[[[:space:]]*["\047](db_dsnw|des_key|cipher_method|session_storage)["\047][[:space:]]*\][[:space:]]*=/) {
  key = $0;
  sub(/^[[:space:]]*\$config[[:space:]]*\[[[:space:]]*["\047]/, "", key);
  sub(/["\047][[:space:]]*\].*$/, "", key);
  print key ": present (value redacted)"
}' | sort -u | head -n 4; done; echo "";done; echo "";
fi


