    if ! [ "`echo \"$PSTORAGE_FREEIPA\" | grep -E \"ipa$\"`" ]; then if [ "$DEBUG" ]; then echo_not_found "ipa"; fi; fi; printf "%s" "$PSTORAGE_FREEIPA" | grep -E "ipa$" | while read f; do ls -ld "$f" 2>/dev/null | sed -${E} "s,ipa$,${SED_RED},"; find "$f" -name "default.conf" | while read ff; do ls -ld "$ff" | sed -${E} "s,default.conf,${SED_RED},"; cat "$ff" 2>/dev/null | grep -IEv "^$"; done; echo "";done; echo "";
    if ! [ "`echo \"$PSTORAGE_FREEIPA\" | grep -E \"dirsrv$\"`" ]; then if [ "$DEBUG" ]; then echo_not_found "dirsrv"; fi; fi; printf "%s" "$PSTORAGE_FREEIPA" | grep -E "dirsrv$" | while read f; do ls -ld "$f" 2>/dev/null | sed -${E} "s,dirsrv$,${SED_RED},"; find "$f" -name "id2rntry.db" | while read ff; do ls -ld "$ff" | sed -${E} "s,id2rntry.db,${SED_RED},"; done; echo "";done; echo "";
fi


fi

if check_mitre_filter "T1552.001"; then
if [ "$(command -v gitlab-rails || echo -n '')" ] || [ "$(command -v gitlab-backup || echo -n '')" ] || [ "$PSTORAGE_GITLAB" ] || [ "$DEBUG" ]; then
  print_2title "Searching GitLab related files" "T1552.001"
  #Check gitlab-rails
  if [ "$(command -v gitlab-rails || echo -n '')" ]; then
    echo "gitlab-rails was found. Trying to dump users..."
    gitlab-rails runner 'User.where.not(username: "peasssssssss").each { |u| pp u.attributes }' | sed -${E} "s,email|password,${SED_RED},"
    echo "If you have enough privileges, you can make an account under your control administrator by running: gitlab-rails runner 'user = User.find_by(email: \"youruser@example.com\"); user.admin = TRUE; user.save!'"
    echo "Alternatively, you could change the password of any user by running: gitlab-rails runner 'user = User.find_by(email: \"admin@example.com\"); user.password = \"pass_peass_pass\"; user.password_confirmation = \"pass_peass_pass\"; user.save!'"
    echo ""
  fi
  if [ "$(command -v gitlab-backup || echo -n '')" ]; then
    echo "If you have enough privileges, you can create a backup of all the repositories inside gitlab using 'gitlab-backup create'"
    echo "Then you can get the plain-text with something like 'git clone \@hashed/19/23/14348274[...]38749234.bundle'"
    echo ""
  fi
  #Check gitlab files
  printf "%s\n" "$PSTORAGE_GITLAB" | sort | uniq | while IFS= read -r f; do
    if [ "${f##*/}" = "secrets.yml" ]; then
      echo "Found $f" | sed "s,$f,${SED_RED},"
      cat "$f" 2>/dev/null | grep -Iv "^$" | grep -v "^#"
    elif [ "${f##*/}" = "gitlab.yml" ]; then
      echo "Found $f" | sed "s,$f,${SED_RED},"
      if [ ! -f "$f" ] || [ -L "$f" ] || [ ! -r "$f" ]; then
        echo "Repository preview skipped (unreadable, non-regular, or symlink); inspect path manually"
      else
        gitlab_bytes=$(dd if="$f" bs=262145 count=1 2>/dev/null | wc -c | tr -d '[:space:]')
        if [ "$gitlab_bytes" -le 262144 ] 2>/dev/null; then
          dd if="$f" bs=262144 count=1 2>/dev/null |
            grep -A 4 '^[[:space:]]*repositories:' | head -n 20 | cut -c 1-256
        else
          echo "Repository preview skipped (larger than 256 KiB); inspect path manually"
        fi
      fi
    elif [ "${f##*/}" = "gitlab.rb" ]; then
      echo "Found $f" | sed "s,$f,${SED_RED},"
      if [ ! -f "$f" ] || [ -L "$f" ] || [ ! -r "$f" ]; then
        echo "Config preview skipped (unreadable, non-regular, or symlink); inspect path manually"
      else
        gitlab_bytes=$(dd if="$f" bs=262145 count=1 2>/dev/null | wc -c | tr -d '[:space:]')
        if [ "$gitlab_bytes" -le 262144 ] 2>/dev/null; then
          dd if="$f" bs=262144 count=1 2>/dev/null | grep -Eiv '^[[:space:]]*(#|$)' | grep -Ei 'smtp_|password|user|token|secret|database|redis|external_url' | head -n 40 | cut -c 1-256 | sed -${E} "s,email|user|password,${SED_RED},"
        else
          echo "Config preview skipped (larger than 256 KiB); inspect path manually"
        fi
      fi
    fi
    echo ""
  done
  echo ""
fi

fi

if check_mitre_filter "T1068"; then
if ! [ "$SEARCH_IN_FOLDER" ] && ! [ "$MACPEAS" ]; then
  # Keep the process format stable: user, PID, command name, full command line.
  gogs_processes="$(ps -eo user=,pid=,comm=,args= 2>/dev/null | awk '
    $3 == "gogs" {
      for (i = 4; i <= NF; i++) {
        if ($i == "web") {
          print
          break
        }
      }
    }
  ')"
  gogs_pid="$(printf "%s\n" "$gogs_processes" | awk 'NR == 1 { print $2 }')"
  gogs_cmd="$(printf "%s\n" "$gogs_processes" | awk 'NR == 1 { for (i = 4; i <= NF; i++) printf "%s%s", (i == 4 ? "" : " "), $i; print "" }')"
  gogs_bin=""
  if [ "$gogs_pid" ] && [ -e "/proc/$gogs_pid/exe" ]; then
    gogs_bin="$(readlink "/proc/$gogs_pid/exe" 2>/dev/null)"
  fi
  if ! [ -x "$gogs_bin" ] && [ "$gogs_cmd" ]; then
    gogs_bin="$(printf "%s\n" "$gogs_cmd" | awk '{ print $1 }')"
  fi
  if ! [ -x "$gogs_bin" ]; then
    gogs_bin="$(command -v gogs 2>/dev/null || echo -n '')"
  fi
  if [ "$gogs_processes" ] || [ "$gogs_bin" ] || [ -r /etc/gogs/conf/app.ini ] || [ -r /etc/gogs/app.ini ] || [ "$DEBUG" ]; then
    print_2title "Gogs privileged file-write checks" "T1068"
    print_info "Gogs <= 0.13.3 is vulnerable to authenticated symlink-based file writes through the PutContents API (CVE-2025-8110): https://github.com/advisories/GHSA-mq8m-42gh-wq7r"
    gogs_root_process="$(printf "%s\n" "$gogs_processes" | awk '$1 == "root" { print "yes"; exit }')"
    if [ "$gogs_processes" ]; then
      echo "Gogs web processes:"
      printf "%s\n" "$gogs_processes" | while read -r gogs_config_line; do
        case "$gogs_config_line" in
          root*) echo "$gogs_config_line" | sed -${E} "s,.*,${SED_RED_YELLOW}," ;;
          *) echo "$gogs_config_line" ;;
        esac
      done
    else
      echo "Gogs web process not found"
    fi
    gogs_version_output=""
    gogs_version=""
    if [ -x "$gogs_bin" ]; then
      gogs_version_output="$("$gogs_bin" --version 2>/dev/null | head -n 1)"
      gogs_version="$(printf "%s\n" "$gogs_version_output" | grep -oE '[0-9]+\.[0-9]+\.[0-9]+' | head -n 1)"
      echo "Gogs executable: $gogs_bin"
      [ "$gogs_version_output" ] && echo "Gogs version: $gogs_version_output"
    fi
    if [ "$gogs_version" ]; then
      gogs_major="$(printf "%s" "$gogs_version" | cut -d. -f1)"
      gogs_minor="$(printf "%s" "$gogs_version" | cut -d. -f2)"
      gogs_patch="$(printf "%s" "$gogs_version" | cut -d. -f3)"
      if [ "$gogs_major" -eq 0 ] 2>/dev/null && { [ "$gogs_minor" -lt 13 ] 2>/dev/null || { [ "$gogs_minor" -eq 13 ] 2>/dev/null && [ "$gogs_patch" -le 3 ] 2>/dev/null; }; }; then
        if [ "$gogs_root_process" ]; then
          echo "Gogs $gogs_version is vulnerable to CVE-2025-8110 and is running as root; an authenticated repository writer may obtain root code execution" | sed -${E} "s,.*,${SED_RED_YELLOW},"
        else
          echo "Gogs $gogs_version is vulnerable to CVE-2025-8110; successful exploitation executes as the Gogs service user" | sed -${E} "s,.*,${SED_YELLOW},"
        fi
      else
        echo "Gogs $gogs_version is not in the CVE-2025-8110 vulnerable range (<= 0.13.3)" | sed -${E} "s,.*,${SED_GREEN},"
      fi
    elif [ "$gogs_root_process" ]; then
      echo "Gogs is running as root, but its version could not be determined; verify that it is newer than 0.13.3" | sed -${E} "s,.*,${SED_RED_YELLOW},"
    fi
    # Gogs accepts --config/-c. Add only bounded standard locations derived from
    # the active process; do not recursively search the filesystem or repositories.
    gogs_config_arg="$(printf "%s\n" "$gogs_cmd" | awk '
      {
        for (i = 1; i <= NF; i++) {
          if (($i == "--config" || $i == "-c") && i < NF) {
            print $(i + 1)
            exit
          }
          if ($i ~ /^--config=/) {
            sub(/^--config=/, "", $i)
            print $i
            exit
          }
        }
      }
    ')"
    gogs_bin_dir=""
    [ "$gogs_bin" ] && gogs_bin_dir="$(dirname "$gogs_bin" 2>/dev/null)"
    gogs_cwd=""
    if [ "$gogs_pid" ] && [ -e "/proc/$gogs_pid/cwd" ]; then
      gogs_cwd="$(readlink "/proc/$gogs_pid/cwd" 2>/dev/null)"
    fi
    gogs_config_candidates="$gogs_config_arg
$gogs_bin_dir/custom/conf/app.ini
$gogs_cwd/custom/conf/app.ini
/etc/gogs/conf/app.ini
/etc/gogs/app.ini
/var/lib/gogs/custom/conf/app.ini
/home/git/gogs/custom/conf/app.ini
/opt/gogs/custom/conf/app.ini"
    gogs_seen_configs="|"
    printf "%s\n" "$gogs_config_candidates" | while read -r gogs_config; do
      [ "$gogs_config" ] || continue
      case "$gogs_seen_configs" in
        *"|$gogs_config|"*) continue ;;
      esac
      gogs_seen_configs="${gogs_seen_configs}${gogs_config}|"
      [ -r "$gogs_config" ] || continue
      echo "Privilege-relevant Gogs configuration: $gogs_config"
      gogs_config_summary="$(awk '
        /^[[:space:]]*[#;]/ || /^[[:space:]]*$/ { next }
        /^[[:space:]]*\[/ {
          section = tolower($0)
          gsub(/[[:space:]\[\]]/, "", section)
          next
        }
        index($0, "=") {
          key = substr($0, 1, index($0, "=") - 1)
          value = substr($0, index($0, "=") + 1)
          gsub(/^[[:space:]]+|[[:space:]]+$/, "", key)
          gsub(/^[[:space:]]+|[[:space:]]+$/, "", value)
          key = toupper(key)
          if ((section == "" && (key == "RUN_USER" || key == "APP_DATA_PATH")) ||
              (section == "repository" && (key == "ROOT" || key == "ROOT_PATH")) ||
              (section == "server" && (key == "HTTP_ADDR" || key == "HTTP_PORT" || key == "EXTERNAL_URL" || key == "ROOT_URL")) ||
              ((section == "auth" || section == "service") && key == "DISABLE_REGISTRATION") ||
              (section == "attachment" && key == "PATH") ||
              (section == "repository.upload" && key == "TEMP_PATH")) {
            printf "[%s] %s = %s\n", section, key, value
          }
        }
      ' "$gogs_config" 2>/dev/null)"
      if [ "$gogs_config_summary" ]; then
        printf "%s\n" "$gogs_config_summary" | while read -r gogs_config_line; do
          case "$gogs_config_line" in
            *"RUN_USER = root"*|*"ROOT = /root"*|*"ROOT_PATH = /root"*)
              echo "$gogs_config_line" | sed -${E} "s,.*,${SED_RED_YELLOW},"
              ;;
            *"DISABLE_REGISTRATION = false"*)
              echo "$gogs_config_line" | sed -${E} "s,.*,${SED_YELLOW},"
              ;;
            *) echo "$gogs_config_line" ;;
          esac
        done
      fi
    done
    echo ""
  fi
fi

fi

if check_mitre_filter "T1555.001"; then
if [ "$PSTORAGE_KCPASSWORD" ] || [ "$DEBUG" ]; then
  print_2title "Analyzing kcpassword files" "T1555.001"
  print_info "https://book.hacktricks.wiki/en/macos-hardening/macos-security-and-privilege-escalation/macos-files-folders-and-binaries/macos-sensitive-locations.html#kcpassword"
  printf "%s\n" "$PSTORAGE_KCPASSWORD" | while read f; do
    echo "$f" | sed -${E} "s,.*,${SED_RED},"
    base64 "$f" 2>/dev/null | sed -${E} "s,.*,${SED_RED},"
  done
  echo ""
fi

fi

if check_mitre_filter "T1558.003"; then
kadmin_exists="$(command -v kadmin || echo -n '')"
klist_exists="$(command -v klist || echo -n '')"
kinit_exists="$(command -v kinit || echo -n '')"
if [ "$kadmin_exists" ] || [ "$klist_exists" ] || [ "$kinit_exists" ] || [ "$PSTORAGE_KERBEROS" ] || [ "$DEBUG" ]; then
  print_2title "Searching kerberos conf files and tickets" "T1558.003"
  print_info "https://book.hacktricks.wiki/en/linux-hardening/user-information/linux-active-directory.html#linux-active-directory"
  if [ "$kadmin_exists" ]; then echo "kadmin was found on $kadmin_exists" | sed "s,$kadmin_exists,${SED_RED},"; fi
  if [ "$kinit_exists" ]; then echo "kadmin was found on $kinit_exists" | sed "s,$kinit_exists,${SED_RED},"; fi
  if [ "$klist_exists" ] && [ -x "$klist_exists" ]; then echo "klist execution"; klist; fi
  ptrace_scope="$(cat /proc/sys/kernel/yama/ptrace_scope 2>/dev/null)"
  if [ "$ptrace_scope" ] && [ "$ptrace_scope" -eq 0 ]; then echo "ptrace protection is disabled (0), you might find tickets inside processes memory" | sed "s,is disabled,${SED_RED},g";
  else echo "ptrace protection is enabled ($ptrace_scope), you need to disable it to search for tickets inside processes memory" | sed "s,is enabled,${SED_GREEN},g";
  fi
  (env || printenv) 2>/dev/null | grep -E "^KRB5" | sed -${E} "s,KRB5,${SED_RED},g"
  printf "%s\n" "$PSTORAGE_KERBEROS" | while IFS= read -r f; do
    if [ "${f##*/}" = ".k5users" ] && [ -f "$f" ]; then
      echo ".k5users authorization file (principal and command rights require review)"
      ls -ld "$f" 2>/dev/null
    elif [ -r "$f" ]; then
      if [ "${f##*/}" = ".k5login" ]; then
        echo ".k5login file (users with access to the user who has this file in his home)"
        cat "$f" 2>/dev/null | sed -${E} "s,.*,${SED_RED},g"
      elif echo "$f" | grep -q keytab; then
        echo ""
        echo "keytab file found, you may be able to impersonate some kerberos principals and add users or modify passwords"
        klist -k "$f" 2>/dev/null | sed -${E} "s,.*,${SED_RED},g"
        printf "$(klist -k $f 2>/dev/null)\n" | awk '{print $2}' | while read l; do
          if [ "$l" ] && echo "$l" | grep -q "@"; then
            printf "$ITALIC  --- Impersonation command: ${NC}kadmin -k -t /etc/krb5.keytab -p \"$l\"\n" | sed -${E} "s,$l,${SED_RED},g"
            #kadmin -k -t /etc/krb5.keytab -p "$l" -q getprivs 2>/dev/null #This should show the permissions of each impersoanted user, the thing is that in a test it showed that every user had the same permissions (even if they didn't). So this test isn't valid
            #We could also try to create a new user or modify a password, but I'm not user if linpeas should do that
          fi
        done
      elif echo "$f" | grep -q krb5.conf; then
        ls -l "$f"
        cat "$f" 2>/dev/null | sed -${E} "s,default_ccache_name,${SED_RED},";
      elif echo "$f" | grep -q kadm5.acl; then
        ls -l "$f" 
        cat "$f" 2>/dev/null
      elif echo "$f" | grep -q sssd.conf; then
        ls -l "$f"
        cat "$f" 2>/dev/null | sed -${E} "s,cache_credentials ?= ?[tT][rR][uU][eE],${SED_RED},";
      elif echo "$f" | grep -q secrets.ldb; then
        echo "You could use SSSDKCMExtractor to extract the tickets stored here" | sed -${E} "s,SSSDKCMExtractor,${SED_RED},";
        ls -l "$f"
      elif echo "$f" | grep -q .secrets.mkey; then
        echo "This is the secrets file to use with SSSDKCMExtractor" | sed -${E} "s,SSSDKCMExtractor,${SED_RED},";
        ls -l "$f"
      fi
    fi
  done
  ls -l "/tmp/krb5cc*" "/var/lib/sss/db/ccache_*" "/etc/opt/quest/vas/host.keytab" 2>/dev/null || echo_not_found "tickets kerberos"
  klist 2>/dev/null || echo_not_found "klist"
  echo ""
fi

fi

if check_mitre_filter "T1190"; then
if [ "$PSTORAGE_LOG4SHELL" ] || [ "$DEBUG" ]; then
  print_2title "Searching Log4Shell vulnerable libraries" "T1190"
  printf "%s\n" "$PSTORAGE_LOG4SHELL" | while read f; do
    echo "$f" | grep -E "log4j\-core\-(1\.[^0]|2\.[0-9][^0-9]|2\.1[0-6])" | sed -${E} "s,log4j\-core\-(1\.[^0]|2\.[0-9][^0-9]|2\.1[0-6]),${SED_RED},";
  done
  echo ""
fi

fi

if check_mitre_filter "T1552.001"; then
# Cached storage inputs (builder): $PSTORAGE_LOGSTASH
if [ "$PSTORAGE_LOGSTASH" ] || [ "$DEBUG" ]; then
  print_2title "Searching logstash files" "T1552.001"
  printf '%s\n' "$PSTORAGE_LOGSTASH"
  ls_root_count=0
  printf '%s\n' "$PSTORAGE_LOGSTASH" | while IFS= read -r d; do
    [ -n "$d" ] && [ -d "$d" ] || continue
    ls_root_count=$((ls_root_count + 1))
    if [ -r "$d/startup.options" ]; then
      echo "Logstash startup.options account setting (verify running identity):"
      cat "$d/startup.options" 2>/dev/null | grep "LS_USER\|LS_GROUP" | sed -${E} "s,$sh_usrs,${SED_LIGHT_CYAN}," | sed -${E} "s,$nosh_usrs,${SED_BLUE}," | sed -${E} "s,$knw_usrs,${SED_GREEN}," | sed -${E} "s,${USER:-^$},${SED_LIGHT_MAGENTA}," | sed -${E} "s,root,${SED_RED},"
    fi
    # Preserve full-file output/filter coverage, including extensionless names.
    # Keep the directory component quoted while allowing the filename glob.
    for ls_config in "$d"/conf.d/out*; do
      [ -f "$ls_config" ] && [ -r "$ls_config" ] || continue
      grep -E 'exec[[:space:]]*\{|command[[:space:]]*=>' "$ls_config" 2>/dev/null |
        sed -${E} "s,exec\W*\{|command\W*=>,${SED_RED},"
    done
    for ls_config in "$d"/conf.d/filt*; do
      [ -f "$ls_config" ] && [ -r "$ls_config" ] || continue
      grep -E 'path[[:space:]]*=>|code[[:space:]]*=>|match[[:space:]]*=>|ruby[[:space:]]*\{' "$ls_config" 2>/dev/null |
        sed -${E} "s,path\W*=>|code\W*=>|match\W*=>|ruby\W*\{,${SED_RED},"
    done
    # Input-path cues are a separate bounded pass over already-known dirs.
    if [ "$ls_root_count" -le 8 ]; then
      ls_count=0
      for ls_config in "$d"/conf.d/in*; do
        [ -f "$ls_config" ] && [ -r "$ls_config" ] && [ ! -L "$ls_config" ] || continue
        ls_count=$((ls_count + 1))
        if [ "$ls_count" -gt 16 ]; then
          echo '  Additional input-named Logstash files not inspected (16-file cap).'
          break
        fi
        ls_lines=$(dd if="$ls_config" bs=8192 count=1 2>/dev/null |
          grep -E '^[[:space:]]*path[[:space:]]*=>' | head -n 16)
        if [ -n "$ls_lines" ]; then
          printf '  Input path directive lead in %s (verify file input and permissions):\n' "$ls_config"
          printf '%s\n' "$ls_lines"
        fi
      done
    fi
  done
fi
echo ""

fi

if check_mitre_filter "T1552.001,T1068"; then
lp_motion_readable() {
  [ -r "$1" ]
}
lp_motion_check_config() {
  local motion_config="$1" motion_dir motion_camera motion_camera_count=0
  local motion_hook=0 motion_filename=0 motion_camera_unreadable=0 motion_camera_flags
  [ -e "$motion_config" ] || return 0
  print_2title "Motion configuration: $motion_config" "T1552.001"
  if [ ! -f "$motion_config" ] || ! lp_motion_readable "$motion_config"; then
    echo "Configuration exists but is not readable by the current user"
    echo ""
    return 0
  fi
  # Values are reduced to fixed labels or validated numbers. In particular,
  # motionEye stores the admin hash in a comment, which must never be printed.
  dd if="$motion_config" bs=65536 count=1 2>/dev/null | awk '
    /^[[:space:]]*#[[:space:]]*@admin_password([[:space:]]|$)/ {
      admin_seen = 1
      admin_present = ($3 != "")
      next
    }
    /^[[:space:]]*#/ { next }
    $1 == "webcontrol_port" { port = ($2 ~ /^[0-9]+$/ && $2 + 0 <= 65535 ? $2 : "invalid") }
    $1 == "webcontrol_parms" { parms = ($2 ~ /^[0-3]$/ ? $2 : "invalid") }
    $1 == "webcontrol_auth_method" {
      method = tolower($2)
      if (method == "0" || method == "none") auth = "disabled"
      else if (method == "1" || method == "2" || method == "basic" || method == "digest") auth = "enabled"
      else auth = "unknown"
    }
    $1 == "webcontrol_localhost" { local_only = ($2 == "on" || $2 == "off" ? $2 : "invalid") }
    END {
      if (admin_seen) print "motionEye admin hash: " (admin_present ? "present (redacted)" : "empty")
      print "Motion webcontrol port: " (port == "" ? "not configured" : port)
      print "Motion webcontrol parameter level: " (parms == "" ? "default (0)" : parms)
      print "Motion webcontrol authentication: " (auth == "" ? "disabled/default" : auth)
      print "Motion webcontrol localhost restriction: " (local_only == "" ? "default (on)" : local_only)
      if (port ~ /^[0-9]+$/ && port + 0 > 0 && parms ~ /^[2-3]$/ && (auth == "" || auth == "disabled"))
        print "Review: Motion webcontrol may expose advanced settings without authentication to local users"
    }
  ' 2>/dev/null
  # motionEye normally places per-camera settings beside motion.conf. Bound
  # this local glob so an unusual directory cannot turn the check into a scan.
  motion_dir="${motion_config%/*}"
  for motion_camera in "$motion_dir"/camera-*.conf; do
    [ -e "$motion_camera" ] || continue
    motion_camera_count=$((motion_camera_count + 1))
    [ "$motion_camera_count" -le 10 ] || break
    if [ ! -f "$motion_camera" ] || ! lp_motion_readable "$motion_camera"; then
      motion_camera_unreadable=1
      continue
    fi
    motion_camera_flags="$(dd if="$motion_camera" bs=65536 count=1 2>/dev/null | awk '
      /^[[:space:]]*#/ { next }
      $1 == "on_picture_save" && NF > 1 { hook = 1 }
      $1 == "picture_filename" && NF > 1 { filename = 1 }
      END { print hook + 0, filename + 0 }
    ' 2>/dev/null)"
    case "$motion_camera_flags" in "1 "*) motion_hook=1 ;; esac
    case "$motion_camera_flags" in *" 1") motion_filename=1 ;; esac
  done
  [ "$motion_hook" -eq 1 ] && echo "Camera picture-save event hook: configured (value redacted)"
  [ "$motion_filename" -eq 1 ] && echo "Camera picture filename: configured (value redacted)"
  [ "$motion_camera_unreadable" -eq 1 ] && echo "Some camera configuration files are not readable"
  echo "Configuration alone does not establish that Motion is running or its service user"
  echo ""
}
if ! [ "$SEARCH_IN_FOLDER" ] && ! [ "$MACPEAS" ]; then
  lp_motion_conf_dir="/etc/motioneye"
  if lp_motion_readable /etc/motioneye/motioneye.conf; then
    lp_motion_custom_dir="$(awk '$1 == "conf_path" { path = $2 } END { print path }' /etc/motioneye/motioneye.conf 2>/dev/null)"
    case "$lp_motion_custom_dir" in /*) lp_motion_conf_dir="$lp_motion_custom_dir" ;; esac
  fi
  lp_motion_check_config "$lp_motion_conf_dir/motion.conf"
  lp_motion_check_config /etc/motion/motion.conf
  lp_motion_check_config /usr/local/etc/motion/motion.conf
fi

fi

if check_mitre_filter "T1552.001"; then
if [ "$PSTORAGE_MYSQL" ] || [ "$DEBUG" ]; then
  print_2title "Searching mysql credentials and exec" "T1552.001"
  printf "%s\n" "$PSTORAGE_MYSQL" | while read d; do
    if [ -f "$d" ] && ! [ "$(basename $d)" = "mysql" ]; then # Only interested in "mysql" that are folders (filesaren't the ones with creds)
      echo "Potential file containing credentials:"
      ls -l "$d"
      if [ "$STRINGS" ]; then
        strings "$d"
      else
        echo "Strings not found, cat the file and check it to get the creds"
      fi
    else
      for f in $(find $d -name debian.cnf 2>/dev/null); do
        if [ -r "$f" ]; then
          echo "We can read the mysql debian.cnf. You can use this username/password to log in MySQL" | sed -${E} "s,.*,${SED_RED},"
          cat "$f"
        fi
      done
      for f in $(find $d -name user.MYD 2>/dev/null); do
        if [ -r "$f" ]; then
          echo "We can read the Mysql Hashes from $f" | sed -${E} "s,.*,${SED_RED},"
          grep -oaE "[-_\.\*a-zA-Z0-9]{3,}" "$f" | grep -v "mysql_native_password"
        fi
      done
      for f in $(grep -lr "user\s*=" $d 2>/dev/null | grep -v "debian.cnf"); do
        if [ -r "$f" ]; then
          u=$(cat "$f" | grep -v "#" | grep "user" | grep "=" 2>/dev/null)
          echo "From '$f' Mysql user: $u" | sed -${E} "s,$sh_usrs,${SED_LIGHT_CYAN}," | sed -${E} "s,$nosh_usrs,${SED_BLUE}," | sed -${E} "s,$knw_usrs,${SED_GREEN}," | sed "s,$USER,${SED_LIGHT_MAGENTA}," | sed "s,root,${SED_RED},"
        fi
      done
      for f in $(find $d -name my.cnf 2>/dev/null); do
        if [ -r "$f" ]; then
          echo "Found readable $f"
          grep -v "^#" "$f" | grep -Ev "\W+\#|^#" 2>/dev/null | grep -Iv "^$" | sed "s,password.*,${SED_RED},"
        fi
      done
    fi
    mysqlexec=$(whereis lib_mysqludf_sys.so 2>/dev/null | grep -Ev '^lib_mysqludf_sys.so:$' | grep "lib_mysqludf_sys\.so")
    if [ "$mysqlexec" ]; then
      echo "Found $mysqlexec. $(whereis lib_mysqludf_sys.so)"
      echo "If you can login in MySQL you can execute commands doing: SELECT sys_eval('id');" | sed -${E} "s,.*,${SED_RED},"
    fi
  done
fi
echo ""
#-- SI) Mysql version
if [ "$(command -v mysql || echo -n '')" ] || [ "$(command -v mysqladmin || echo -n '')" ] || [ "$DEBUG" ]; then
  print_2title "MySQL version" "T1552.001"
  mysql --version 2>/dev/null || echo_not_found "mysql"
  mysqluser=$(systemctl status mysql 2>/dev/null | grep -o ".\{0,0\}user.\{0,50\}" | cut -d '=' -f2 | cut -d ' ' -f1)
  if [ "$mysqluser" ]; then
    echo "MySQL user: $mysqluser" | sed -${E} "s,$sh_usrs,${SED_LIGHT_CYAN}," | sed -${E} "s,$nosh_usrs,${SED_BLUE}," | sed -${E} "s,$knw_usrs,${SED_GREEN}," | sed "s,$USER,${SED_LIGHT_MAGENTA}," | sed "s,root,${SED_RED},"
  fi
  echo ""
  echo ""
  #-- SI) Mysql connection root/root
  print_list "MySQL connection using default root/root ........... "
  mysqlconnect=$(mysqladmin -uroot -proot version 2>/dev/null)
  if [ "$mysqlconnect" ]; then
    echo "Yes" | sed -${E} "s,.*,${SED_RED},"
    mysql -u root --password=root -e "SELECT User,Host,authentication_string FROM mysql.user;" 2>/dev/null | sed -${E} "s,.*,${SED_RED},"
  else echo_no
  fi
  #-- SI) Mysql connection root/toor
  print_list "MySQL connection using root/toor ................... "
  mysqlconnect=$(mysqladmin -uroot -ptoor version 2>/dev/null)
  if [ "$mysqlconnect" ]; then
    echo "Yes" | sed -${E} "s,.*,${SED_RED},"
    mysql -u root --password=toor -e "SELECT User,Host,authentication_string FROM mysql.user;" 2>/dev/null | sed -${E} "s,.*,${SED_RED},"
  else echo_no
  fi
  #-- SI) Mysql connection root/NOPASS
  mysqlconnectnopass=$(mysqladmin -uroot version 2>/dev/null)
  print_list "MySQL connection using root/NOPASS ................. "
  if [ "$mysqlconnectnopass" ]; then
    echo "Yes" | sed -${E} "s,.*,${SED_RED},"
    mysql -u root -e "SELECT User,Host,authentication_string FROM mysql.user;" 2>/dev/null | sed -${E} "s,.*,${SED_RED},"
    mysql -u root -e "SELECT User,Host,plugin FROM mysql.user;" 2>/dev/null | sed -${E} "s,auth_socket|unix_socket|plugin,${SED_RED},g"
    mysql -u root -e "SHOW VARIABLES LIKE 'secure_file_priv'; SHOW VARIABLES LIKE 'local_infile';" 2>/dev/null | sed -${E} "s,secure_file_priv|local_infile,${SED_RED},g"
  else echo_no
  fi
  echo ""
fi
### Review the MySQL/MariaDB service identity without assuming a version is exploitable. ###
# Find the mysqld process
process_info=$(ps aux 2>/dev/null | grep -E '[m]ysqld|[m]ariadbd' | head -n1)
if [ -z "$process_info" ]; then
  echo "MySQL/MariaDB process not visible to this user (it may be stopped or /proc may hide other users)."
  # A fixed, small unit-file review can still expose an explicitly configured
  # root context when hidepid prevents process enumeration. Never run the unit.
  if [ -d /run/systemd/system ]; then
    mysql_unit_count=0
    for mysql_unit_dir in /etc/systemd/system /usr/lib/systemd/system /lib/systemd/system; do
      [ -d "$mysql_unit_dir" ] || continue
      mysql_unit_parent=$mysql_unit_dir
      while [ "$mysql_unit_parent" != / ] && [ ! -L "$mysql_unit_parent" ]; do
        mysql_unit_parent=${mysql_unit_parent%/*}
        [ "$mysql_unit_parent" ] || mysql_unit_parent=/
      done
      [ "$mysql_unit_parent" = / ] || continue
      for mysql_unit_file in "$mysql_unit_dir"/*mysql*.service "$mysql_unit_dir"/*mariadb*.service; do
        [ -f "$mysql_unit_file" ] && [ -r "$mysql_unit_file" ] && [ ! -L "$mysql_unit_file" ] || continue
        mysql_unit_count=$((mysql_unit_count + 1))
        if [ "$mysql_unit_count" -gt 12 ]; then
          echo "MySQL/MariaDB unit review incomplete (12-file limit)."
          break 2
        fi
        mysql_unit_size=$(stat -c %s "$mysql_unit_file" 2>/dev/null) ||
          mysql_unit_size=$(stat -f %z "$mysql_unit_file" 2>/dev/null) || continue
        case "$mysql_unit_size" in ''|*[!0-9]*) continue ;; esac
        [ "${#mysql_unit_size}" -le 6 ] && [ "$mysql_unit_size" -le 65536 ] || continue
        mysql_unit_signal=$(head -c 65537 "$mysql_unit_file" 2>/dev/null | awk '
          /^\[Service\][[:space:]]*$/ { service = 1; next }
          /^\[/ { service = 0; next }
          !service || /^[[:space:]]*[#;]/ { next }
          {
            line = $0
            sub(/^[[:space:]]*/, "", line)
            if (line ~ /^User[[:space:]]*=/) {
              sub(/^User[[:space:]]*=[[:space:]]*/, "", line)
              sub(/[[:space:]]*$/, "", line)
              user = line
            } else if (line ~ /^DynamicUser[[:space:]]*=/) {
              sub(/^DynamicUser[[:space:]]*=[[:space:]]*/, "", line)
              sub(/[[:space:]]*$/, "", line)
              dynamic = tolower(line)
            } else if (line ~ /^ExecStart[[:space:]]*=/) {
              sub(/^ExecStart[[:space:]]*=[[:space:]]*[-+!@]*/, "", line)
              direct = (line ~ /^\/[^[:space:]]+\/(mysqld|mariadbd)([[:space:]]|$)/ &&
                line !~ /(^|[[:space:]])--user([=[:space:]]|$)/)
            }
          }
          END {
            if (direct && (user == "" || user == "root") && dynamic !~ /^(yes|true|1)$/)
              print (user == "root" ? "explicit root" : "default root")
          }
        ' 2>/dev/null)
        if [ "$mysql_unit_signal" ]; then
          printf 'MySQL/MariaDB unit root-context review candidate: %s (%s; process state, drop-ins, SQL FILE/UDF rights and plugin directory unverified)\n' "$mysql_unit_file" "$mysql_unit_signal"
        fi
      done
    done
  fi
else
  # Extract the process user
  mysqluser=$(echo "$process_info" | awk '{print $1}')
  # Get the MySQL version string
  version_output=$(mysqld --version 2>&1)
  # Extract the version number (expects format like X.Y.Z)
  version=$(echo "$version_output" | grep -oE '[0-9]+\.[0-9]+\.[0-9]+' | head -n1)
  if [ "$mysqluser" = "root" ]; then
    printf 'MySQL/MariaDB process runs as root%s; review SQL access, FILE/UDF rights, plugin directory, and effective service policy.\n' "${version:+ (binary version $version)}" | sed -${E} "s,.*,${SED_RED},"
  else
    printf "MySQL/MariaDB process runs as user '%s'%s.\n" "$mysqluser" "${version:+ (binary version $version)}" | sed -${E} "s,.*,${SED_GREEN},"
  fi
fi

fi

if check_mitre_filter "T1068"; then
omi_bounded() {
  if [ -n "$omi_timeout" ]; then
    "$omi_timeout" 2 "$@"
  else
    "$@"
  fi
}
omi_process_user() {
  LC_ALL=C awk '
    NR > 4096 { print "#limit"; exit }
    $2 == "omiengine" { print $1; exit }
  '
}
omi_listener() {
  LC_ALL=C awk '
    NR > 4096 { print "#limit"; exit }
    /LISTEN/ {
      local_address = $4
      if (local_address ~ /[.:]598[56]$/) { print local_address; exit }
    }
  '
}
omi_report_evidence() {
  printf 'OMI package version: %s (vendor backports/build provenance unverified).\n' "${3:-unknown}"
  case "$1" in
    '#limit') echo 'OMI process context: unknown (4,096-line process limit).' ;;
    '') echo 'OMI process context: not visible; service may be stopped or hidden.' ;;
    *) printf 'OMI process owner: %s (effective service identity needs confirmation).\n' "$1" ;;
  esac
  case "$2" in
    '#limit') echo 'WS-Management listener: unknown (4,096-line socket limit).' ;;
    '') echo 'WS-Management listener on 5985/5986: not visible; custom ports or Unix socket remain possible.' ;;
    *) printf 'WS-Management listener co-observed: %s (socket ownership unproven).\n' "$2" ;;
  esac
  if [ "$1" = root ] && [ -n "$2" ] && [ "$2" != '#limit' ]; then
    echo 'OMI review candidate: root-owned omiengine and a 5985/5986 listener are visible; verify socket ownership, installed security fix/backports, access policy, and actual SSRF/network reachability.'
  fi
}
check_omi_exposure() {
  # Fixed standard paths gate all commands; no directory walk or service request.
  [ -e /opt/omi/bin/omiengine ] || [ -e /etc/opt/omi/conf/omiserver.conf ] || return 0
  print_3title 'OMI management listener review' 'T1068'
  print_info 'https://github.com/microsoft/omi/security/advisories/GHSA-fmh7-p6gp-8xpj'
  print_info 'https://book.hacktricks.wiki/en/network-services-pentesting/5985-5986-pentesting-omi.html'
  omi_timeout=$(command -v timeout 2>/dev/null || command -v gtimeout 2>/dev/null)
  omi_proc=$(omi_bounded ps -eo user=,comm= 2>/dev/null | omi_process_user)
  if command -v ss >/dev/null 2>&1; then
    omi_port=$(omi_bounded ss -ltn 2>/dev/null | omi_listener)
  elif command -v netstat >/dev/null 2>&1; then
    omi_port=$(omi_bounded netstat -an 2>/dev/null | omi_listener)
  else
    omi_port=
  fi
  omi_pkg=
  if command -v dpkg-query >/dev/null 2>&1; then
    omi_pkg=$(omi_bounded dpkg-query -W -f='$''{Version}\n' omi 2>/dev/null | LC_ALL=C head -n1 | cut -c1-64)
  elif command -v rpm >/dev/null 2>&1; then
    omi_pkg=$(omi_bounded rpm -q --qf '%{VERSION}-%{RELEASE}\n' omi 2>/dev/null | LC_ALL=C head -n1 | cut -c1-64)
  fi
  case "$omi_pkg" in [0-9]* ) ;; * ) omi_pkg= ;; esac
  omi_report_evidence "$omi_proc" "$omi_port" "$omi_pkg"
}
check_omi_exposure

fi

