echo ''
if [ "$WAIT" ]; then echo "Press enter to continue"; read "asd"; fi

if echo $CHECKS | grep -q interesting_perms_files; then
if check_mitre_filter "T1552.001,T1083,T1574.009,T1574.010,T1548.001,T1222,T1068,T1574.006,T1546.004,T1543.002,T1518.001"; then
print_title "Files with Interesting Permissions"
if check_mitre_filter "T1548.001"; then
print_2title "SUID - Check easy privesc, exploits and write perms" "T1548.001"
print_info "https://book.hacktricks.wiki/en/linux-hardening/interesting-files-permissions/suid-sgid-and-acl-triage.html#enumerate-privileged-executables"
if ! [ "$STRINGS" ]; then
  echo_not_found "strings"
fi
if ! [ "$STRACE" ]; then
  echo_not_found "strace"
fi
# Compare only small, installed shell binaries; never execute a discovered SUID file.
suid_shell_refs=""
if command -v cmp >/dev/null 2>&1; then
  for suid_shell_name in sh dash bash zsh ksh; do
    for suid_shell_path in "${ROOT_FOLDER%/}/bin/$suid_shell_name" "${ROOT_FOLDER%/}/usr/bin/$suid_shell_name"; do
      [ -f "$suid_shell_path" ] && [ -r "$suid_shell_path" ] || continue
      suid_shell_size=$(stat -c '%s' "$suid_shell_path" 2>/dev/null || stat -f '%z' "$suid_shell_path" 2>/dev/null)
      case "$suid_shell_size" in ''|*[!0-9]*) continue ;; esac
      [ "$suid_shell_size" -le 4194304 ] || continue
      suid_shell_refs="${suid_shell_refs}${suid_shell_size} ${suid_shell_path}
"
    done
  done
fi
suids_files=$(find $ROOT_FOLDER -perm -4000 -type f ! -path "/dev/*" 2>/dev/null)
printf "%s\n" "$suids_files" | while IFS= read -r sfile; do
  [ -z "$sfile" ] && continue
  s=$(ls -lahtr "$sfile")
  #If starts like "total 332K" then no SUID bin was found and xargs just executed "ls" in the current folder
  if echo "$s" | grep -qE "^total"; then break; fi
  # Keep the path returned by find: parsing it from ls output breaks on whitespace.
  sname="$sfile"
  sowner="$(echo "$s" | awk '{print $3}')"
  if [ -n "$suid_shell_refs" ]; then
    suid_file_stat=$(stat -c '%u %s' "$sname" 2>/dev/null || stat -f '%u %z' "$sname" 2>/dev/null)
    case "$suid_file_stat" in
      '0 '*)
        suid_file_size=${suid_file_stat#0 }
        while read -r suid_shell_size suid_shell_path; do
          [ "$suid_file_size" = "$suid_shell_size" ] || continue
          if cmp -s "$sname" "$suid_shell_path" 2>/dev/null; then
            echo "Root-owned SUID file matches a system shell: $sname (matches $suid_shell_path; verify SUID policy and shell behavior)" | sed -${E} "s,.*,${SED_RED},"
            break
          fi
        done <<EOF_SUID_SHELL_REFS
$suid_shell_refs
EOF_SUID_SHELL_REFS
        ;;
    esac
  fi
  if [ "${sname##*/}" = "pinns" ] && [ "$(uname -s 2>/dev/null)" = "Linux" ]; then
    # The privileged CRI-O helper is a lead only; never invoke it to test.
    pinns_uid=$(stat -c '%u' "$sname" 2>/dev/null || stat -f '%u' "$sname" 2>/dev/null)
    if [ "$IAMROOT" ] || [ "$pinns_uid" != "0" ] || ! [ -u "$sname" ] || ! [ -x "$sname" ]; then
      echo "  pinns: no local privilege-escalation candidate for this user (requires root ownership, SUID, and execute access)."
    else
      pinns_nnp=$(awk '/^NoNewPrivs:/ {print $2; exit}' /proc/self/status 2>/dev/null)
      pinns_mount_options=$(findmnt -no OPTIONS -T "$sname" 2>/dev/null | head -n 1)
      if [ "$pinns_nnp" = "1" ]; then
        echo "  pinns: SUID transition blocked by NoNewPrivs for this process tree."
      elif echo ",$pinns_mount_options," | grep -q ',nosuid,'; then
        echo "  pinns: SUID transition blocked by nosuid mount options."
      else
        pinns_uncertainty=""
        [ "$pinns_nnp" = "0" ] || pinns_uncertainty="NoNewPrivs unknown; "
        [ -n "$pinns_mount_options" ] || pinns_uncertainty="${pinns_uncertainty}mount SUID policy unknown; "
        echo "  pinns review candidate (CVE-2022-0811): root-owned SUID executable by current user; NoNewPrivs=${pinns_nnp:-unknown}; mount options=${pinns_mount_options:-unknown}."
        echo "  ${pinns_uncertainty}Installed helper build and vendor fixes unknown; verify the exact binary and host sysctl policy. No helper execution performed."
      fi
    fi
  fi
  if [ "$sname" = "."  ] || [ "$sname" = ".."  ]; then
    true #Don't do nothing
  elif echo "$sname" | grep -qE '/netdata/plugins[.]d/ndsudo$'; then
    # Keep this branch passive: even the generic non-FAST SUID probe must not run ndsudo.
    echo "$s"
    ndsudo_uid=$(stat -c '%u' "$sname" 2>/dev/null || stat -f '%u' "$sname" 2>/dev/null)
    if [ "$ndsudo_uid" != "0" ] || ! [ -u "$sname" ] || ! [ -x "$sname" ]; then
      echo "  ndsudo: no privilege-escalation candidate for this user (requires root ownership, SUID, and execute access)."
    else
      ndsudo_nnp=$(awk '/^NoNewPrivs:/ {print $2; exit}' /proc/self/status 2>/dev/null)
      ndsudo_mount_options=$(findmnt -no OPTIONS -T "$sname" 2>/dev/null | head -n 1)
      if [ "$ndsudo_nnp" = "1" ]; then
        echo "  ndsudo: SUID transition blocked by NoNewPrivs for this process tree."
      elif echo ",$ndsudo_mount_options," | grep -q ',nosuid,'; then
        echo "  ndsudo: SUID transition blocked by nosuid mount options."
      else
        ndsudo_uncertainty=""
        [ "$ndsudo_nnp" = "0" ] || ndsudo_uncertainty="NoNewPrivs unknown; "
        [ -n "$ndsudo_mount_options" ] || ndsudo_uncertainty="${ndsudo_uncertainty}mount SUID policy unknown; "
        echo "  ndsudo candidate (CVE-2024-32019): root-owned SUID executable by current user; NoNewPrivs=${ndsudo_nnp:-unknown}; mount options=${ndsudo_mount_options:-unknown}."
        echo "  ${ndsudo_uncertainty}Installed build and vendor backports unknown; confirm affected version and PATH lookup manually. Vendor fixes: v1.45.3 and v1.45.0-169. No helper execution performed."
      fi
    fi
  elif ! [ "$IAMROOT" ] && [ -O "$sname" ]; then
    echo "You own the SUID file: $sname" | sed -${E} "s,.*,${SED_RED},"
  elif ! [ "$IAMROOT" ] && [ -w "$sname" ]; then #If write permision, win found (no check exploits)
    echo "You can write SUID file: $sname" | sed -${E} "s,.*,${SED_RED_YELLOW},"
  elif [ "${sname##*/}" = jjs ] && [ ! "$IAMROOT" ] &&
       [ -u "$sname" ] && [ -x "$sname" ] &&
       [ "$(stat -c '%u' "$sname" 2>/dev/null || stat -f '%u' "$sname" 2>/dev/null)" = 0 ]; then
    # Nashorn's file APIs can retain the SUID identity even if a spawned shell
    # drops it. Check only the exact executable; never run the JVM here.
    echo "$s"
    jjs_nnp=$(awk '/^NoNewPrivs:/ {print $2; exit}' /proc/self/status 2>/dev/null)
    jjs_mount_options=$(findmnt -no OPTIONS -T "$sname" 2>/dev/null | head -n 1)
    if [ "$jjs_nnp" = 1 ]; then
      echo "  jjs: SUID transition blocked by NoNewPrivs for this process tree."
    elif echo ",$jjs_mount_options," | grep -q ',nosuid,'; then
      echo "  jjs: SUID transition blocked by nosuid mount options."
    else
      echo "  jjs SUID file-access review candidate: root-owned and caller-executable; verify effective UID, mount/NoNewPrivs policy, and installed JVM behavior without running it."
    fi
  elif [ "${sname##*/}" = gosu ] && [ ! "$IAMROOT" ] &&
       [ -u "$sname" ] && [ -x "$sname" ] &&
       [ "$(stat -c '%u' "$sname" 2>/dev/null || stat -f '%u' "$sname" 2>/dev/null)" = 0 ]; then
    # A SUID identity-switching helper is a lead; never invoke it to test.
    echo "$s"
    gosu_nnp=$(awk '/^NoNewPrivs:/ {print $2; exit}' /proc/self/status 2>/dev/null)
    gosu_mount_options=$(findmnt -no OPTIONS -T "$sname" 2>/dev/null | head -n 1)
    if [ "$gosu_nnp" = 1 ]; then
      echo "  gosu: SUID transition blocked by NoNewPrivs for this process tree."
    elif echo ",$gosu_mount_options," | grep -q ',nosuid,'; then
      echo "  gosu: SUID transition blocked by nosuid mount options."
    else
      echo "  gosu SUID review candidate: root-owned and caller-executable; NoNewPrivs=${gosu_nnp:-unknown}; mount options=${gosu_mount_options:-unknown}."
      echo "  Verify effective identity, user-namespace mapping, and installed helper behavior; this does not establish host-root access. No helper execution performed."
    fi
  else
    c="a"
    for b in $sidB; do
      if echo "$sname" | grep -q $(echo $b | cut -d % -f 1); then
        echo "$s" | sed -${E} "s,$(echo $b | cut -d % -f 1),${C}[1;31m&  --->  $(echo $b | cut -d % -f 2)${C}[0m,"
        c=""
        break;
      fi
    done;
    if [ "$c" ]; then
      if echo "$sname" | grep -qE "$sidG1" || echo "$sname" | grep -qE "$sidG2" || echo "$sname" | grep -qE "$sidG3" || echo "$sname" | grep -qE "$sidG4" || echo "$sname" | grep -qE "$sidVB" || echo "$sname" | grep -qE "$sidVB2"; then
        echo "$s" | sed -${E} "s,$sidG1,${SED_GREEN}," | sed -${E} "s,$sidG2,${SED_GREEN}," | sed -${E} "s,$sidG3,${SED_GREEN}," | sed -${E} "s,$sidG4,${SED_GREEN}," | sed -${E} "s,$sidVB,${SED_RED_YELLOW}," | sed -${E} "s,$sidVB2,${SED_RED_YELLOW},"
      else
        echo "$s (Unknown SUID binary!)" | sed -${E} "s,/.*,${SED_RED},"
        printf $ITALIC
        if ! [ "$FAST" ]; then
          if [ "$STRINGS" ]; then
            $STRINGS "$sname" 2>/dev/null | sort | uniq | while read sline; do
              sline_first="$(echo "$sline" | cut -d ' ' -f1)"
              if echo "$sline_first" | grep -qEv "$cfuncs"; then
                if echo "$sline_first" | grep -q "/" && [ -f "$sline_first" ]; then #If a path
                  if [ -O "$sline_first" ] || [ -w "$sline_first" ]; then #And modifiable
                    printf "$ITALIC  --- It looks like $RED$sname$NC$ITALIC is using $RED$sline_first$NC$ITALIC and you can modify it (strings line: $sline) (https://tinyurl.com/suidpath)\n"
                  fi
                elif echo "$sline_first" | grep -q "/" && [ -d "$(dirname "$sline_first")" ] && [ -w "$(dirname "$sline_first")" ]; then #If path does not exist but can be created
                  printf "$ITALIC  --- It looks like $RED$sname$NC$ITALIC is using $RED$sline_first$NC$ITALIC and you can create it inside writable dir $RED$(dirname "$sline_first")$NC$ITALIC (strings line: $sline) (https://tinyurl.com/suidpath)\n"
                else #If not a path
                  if [ ${#sline_first} -gt 2 ] && command -v "$sline_first" 2>/dev/null | grep -q '/' && echo "$sline_first" | grep -Eqv "\.\."; then #Check if existing binary
                    printf "$ITALIC  --- It looks like $RED$sname$NC$ITALIC is executing $RED$sline_first$NC$ITALIC and you can impersonate it (strings line: $sline) (https://tinyurl.com/suidpath)\n"
                  fi
                fi
              fi
            done
          fi
          if [ "$LDD" ] || [ "$READELF" ]; then
            echo "$ITALIC  --- Checking for writable dependencies of $sname...$NC"
          fi
          if [ "$LDD" ]; then
            "$LDD" "$sname" | grep -E "$Wfolders" | sed -${E} "s,$Wfolders,${SED_RED_YELLOW},g"
          fi
          if [ "$READELF" ]; then
            "$READELF" -d "$sname" | grep PATH | sed -${E} "s,$Wfolders,${SED_RED_YELLOW},g"
          fi
          if [ "$TIMEOUT" ] && [ "$STRACE" ] && [ -x "$sname" ]; then
            printf $ITALIC
            echo "----------------------------------------------------------------------------------------"
            echo "  --- Trying to execute $sname with strace in order to look for hijackable libraries..."
            OLD_LD_LIBRARY_PATH=$LD_LIBRARY_PATH
            export LD_LIBRARY_PATH=""
            timeout 2 "$STRACE" "$sname" 2>&1 | grep -i -E "open|access|no such file" | sed -${E} "s,open|access|No such file,${SED_RED}$ITALIC,g"
            printf $NC
            export LD_LIBRARY_PATH=$OLD_LD_LIBRARY_PATH
            echo "----------------------------------------------------------------------------------------"
            echo ""
          fi
        fi
      fi
    fi
  fi
  # Reuse this enumeration for the shared privileged-file placement checks.
  check_privileged_file_location "SUID" "$sname" "$sowner"
done;
echo ""

fi

if check_mitre_filter "T1548.001"; then
print_2title "SGID" "T1548.001"
print_info "https://book.hacktricks.wiki/en/linux-hardening/interesting-files-permissions/suid-sgid-and-acl-triage.html#enumerate-privileged-executables"
sgids_files=$(find $ROOT_FOLDER -perm -2000 -type f ! -path "/dev/*" 2>/dev/null)
printf "%s\n" "$sgids_files" | while IFS= read -r sfile; do
  [ -z "$sfile" ] && continue
  s=$(ls -lahtr "$sfile")
  #If starts like "total 332K" then no SUID bin was found and xargs just executed "ls" in the current folder
  if echo "$s" | grep -qE "^total";then break; fi
  # Keep the path returned by find: parsing it from ls output breaks on whitespace.
  sname="$sfile"
  sowner="$(echo "$s" | awk '{print $3}')"
  if [ "$sname" = "."  ] || [ "$sname" = ".."  ]; then
    true #Don't do nothing
  elif ! [ "$IAMROOT" ] && [ -O "$sname" ]; then
    echo "You own the SGID file: $sname" | sed -${E} "s,.*,${SED_RED},"
  elif ! [ "$IAMROOT" ] && [ -w "$sname" ]; then #If write permision, win found (no check exploits)
    echo "You can write SGID file: $sname" | sed -${E} "s,.*,${SED_RED_YELLOW},"
  else
    c="a"
    for b in $sidB; do
      if echo "$s" | grep -q $(echo $b | cut -d % -f 1); then
        echo "$s" | sed -${E} "s,$(echo $b | cut -d % -f 1),${C}[1;31m&  --->  $(echo $b | cut -d % -f 2)${C}[0m,"
        c=""
        break;
      fi
    done;
    if [ "$c" ]; then
      if echo "$s" | grep -qE "$sidG1" || echo "$s" | grep -qE "$sidG2" || echo "$s" | grep -qE "$sidG3" || echo "$s" | grep -qE "$sidG4" || echo "$s" | grep -qE "$sidVB" || echo "$s" | grep -qE "$sidVB2"; then
        echo "$s" | sed -${E} "s,$sidG1,${SED_GREEN}," | sed -${E} "s,$sidG2,${SED_GREEN}," | sed -${E} "s,$sidG3,${SED_GREEN}," | sed -${E} "s,$sidG4,${SED_GREEN}," | sed -${E} "s,$sidVB,${SED_RED_YELLOW}," | sed -${E} "s,$sidVB2,${SED_RED_YELLOW},"
      else
        echo "$s (Unknown SGID binary)" | sed -${E} "s,/.*,${SED_RED},"
        printf $ITALIC
        if ! [ "$FAST" ]; then
          if [ "$STRINGS" ]; then
            $STRINGS "$sname" | sort | uniq | while read sline; do
              sline_first="$(echo $sline | cut -d ' ' -f1)"
              if echo "$sline_first" | grep -qEv "$cfuncs"; then
                if echo "$sline_first" | grep -q "/" && [ -f "$sline_first" ]; then #If a path
                  if [ -O "$sline_first" ] || [ -w "$sline_first" ]; then #And modifiable
                    printf "$ITALIC  --- It looks like $RED$sname$NC$ITALIC is using $RED$sline_first$NC$ITALIC and you can modify it (strings line: $sline)\n"
                  fi
                elif echo "$sline_first" | grep -q "/" && [ -d "$(dirname "$sline_first")" ] && [ -w "$(dirname "$sline_first")" ]; then #If path does not exist but can be created
                  printf "$ITALIC  --- It looks like $RED$sname$NC$ITALIC is using $RED$sline_first$NC$ITALIC and you can create it inside writable dir $RED$(dirname "$sline_first")$NC$ITALIC (strings line: $sline)\n"
                else #If not a path
                  if [ ${#sline_first} -gt 2 ] && command -v "$sline_first" 2>/dev/null | grep -q '/'; then #Check if existing binary
                    printf "$ITALIC  --- It looks like $RED$sname$NC$ITALIC is executing $RED$sline_first$NC$ITALIC and you can impersonate it (strings line: $sline)\n"
                  fi
                fi
              fi
            done
          fi
          if [ "$LDD" ] || [ "$READELF" ]; then
            echo "$ITALIC  --- Checking for writable dependencies of $sname...$NC"
          fi
          if [ "$LDD" ]; then
            "$LDD" "$sname" | grep -E "$Wfolders" | sed -${E} "s,$Wfolders,${SED_RED_YELLOW},g"
          fi
          if [ "$READELF" ]; then
            "$READELF" -d "$sname" | grep PATH | grep -E "$Wfolders" | sed -${E} "s,$Wfolders,${SED_RED_YELLOW},g"
          fi
          if [ "$TIMEOUT" ] && [ "$STRACE" ] && [ -x "$sname" ]; then
            printf $ITALIC
            echo "----------------------------------------------------------------------------------------"
            echo "  --- Trying to execute $sname with strace in order to look for hijackable libraries..."
            OLD_LD_LIBRARY_PATH=$LD_LIBRARY_PATH
            export LD_LIBRARY_PATH=""
            timeout 2 "$STRACE" "$sname" 2>&1 | grep -i -E "open|access|no such file" | sed -${E} "s,open|access|No such file,${SED_RED}$ITALIC,g"
            printf $NC
            export LD_LIBRARY_PATH=$OLD_LD_LIBRARY_PATH
            echo "----------------------------------------------------------------------------------------"
            echo ""
          fi
        fi
      fi
    fi
  fi
  # Reuse this enumeration for the shared privileged-file placement checks.
  check_privileged_file_location "SGID" "$sname" "$sowner"
done;
echo ""

fi

if check_mitre_filter "T1222"; then
print_2title "Files with ACLs (limited to 50)" "T1222"
print_info "https://book.hacktricks.wiki/en/linux-hardening/interesting-files-permissions/suid-sgid-and-acl-triage.html#inspect-acls-and-sensitive-paths"
if ! [ "$SEARCH_IN_FOLDER" ]; then
  ( (getfacl -t -s -R -p /bin /etc $HOMESEARCH /opt /sbin /usr /tmp /root 2>/dev/null) || echo_not_found "files with acls in searched folders" ) | head -n 70 | sed -${E} "s,$sh_usrs,${SED_LIGHT_CYAN}," | sed -${E} "s,$nosh_usrs,${SED_BLUE}," | sed -${E} "s,$knw_usrs,${SED_GREEN}," | sed "s,$USER,${SED_RED}," | sed -${E} "s,$writeVB,${SED_RED_YELLOW},g" | sed -${E} "s,$writeB,${SED_RED},g"
else
  ( (getfacl -t -s -R -p $SEARCH_IN_FOLDER 2>/dev/null) || echo_not_found "files with acls in searched folders" ) | head -n 70 | sed -${E} "s,$sh_usrs,${SED_LIGHT_CYAN}," | sed -${E} "s,$nosh_usrs,${SED_BLUE}," | sed -${E} "s,$knw_usrs,${SED_GREEN}," | sed "s,$USER,${SED_RED}," | sed -${E} "s,$writeVB,${SED_RED_YELLOW},g" | sed -${E} "s,$writeB,${SED_RED},g"
fi
if [ "$MACPEAS" ] && ! [ "$FAST" ] && ! [ "$SUPERFAST" ] && ! [ "$(command -v getfacl || echo -n '')" ]; then  #Find ACL files in macos (veeeery slow)
  ls -RAle / 2>/dev/null | grep -v "group:everyone deny delete" | grep -E -B1 "\d: " | head -n 70 | sed -${E} "s,$sh_usrs,${SED_LIGHT_CYAN}," | sed -${E} "s,$nosh_usrs,${SED_BLUE}," | sed -${E} "s,$knw_usrs,${SED_GREEN}," | sed "s,$USER,${SED_RED}," | sed -${E} "s,$writeVB,${SED_RED_YELLOW},g" | sed -${E} "s,$writeB,${SED_RED},g"
fi
echo ""

fi

if check_mitre_filter "T1548.001,T1068"; then
if ! [ "$SEARCH_IN_FOLDER" ]; then
  print_2title "Capabilities" "T1548.001"
  print_info "https://book.hacktricks.wiki/en/linux-hardening/interesting-files-permissions/linux-capabilities.html"
  if [ "$(command -v capsh || echo -n '')" ]; then
    is_hex_cap_value() {
      case "$1" in
        ""|*[!0-9a-fA-F]*)
          return 1
          ;;
      esac
      return 0
    }
    print_cap_status() {
      cap_status_file="$1"
      cap_default_sep="$2"
      cat "$cap_status_file" | grep Cap | while read -r cap_line; do
        cap_name=$(echo "$cap_line" | awk '{print $1}')
        cap_value=$(echo "$cap_line" | awk '{print $2}')
        cap_sep="$cap_default_sep"
        cap_color="$SED_RED"
        if [ "$cap_name" = "CapEff:" ]; then
          cap_sep="	 "
          cap_color="$SED_RED_YELLOW"
        fi
        if is_hex_cap_value "$cap_value"; then
          # Memory errors can occur with certain values (e.g., ffffffffffffffff)
          # so we redirect stderr to prevent error propagation
          echo "$cap_name$cap_sep$(capsh --decode=0x"$cap_value" 2>/dev/null | sed -${E} "s,$capsB,${cap_color},")"
        else
          echo "$cap_name${cap_sep}[Invalid capability format]"
        fi
      done
    }
    print_3title "Current shell capabilities" "T1548.001"
    print_cap_status "/proc/$$/status" "  "
    echo ""
    print_info "Parent process capabilities"
    print_cap_status "/proc/$PPID/status" "	 "
    echo ""
    print_3title "Processes with capability sets (non-zero CapEff/CapAmb, limit 40)" "T1548.001"
    find /proc -maxdepth 2 -path "/proc/[0-9]*/status" 2>/dev/null | head -n 400 | while read -r proc_status; do
      proc_pid=$(echo "$proc_status" | cut -d/ -f3)
      proc_name=$(awk '/^Name:/{print $2}' "$proc_status" 2>/dev/null)
      proc_uid=$(awk '/^Uid:/{print $2}' "$proc_status" 2>/dev/null)
      user_name=$(awk -F: -v uid="$proc_uid" '$3==uid{print $1; exit}' /etc/passwd 2>/dev/null)
      [ -z "$user_name" ] && user_name="$proc_uid"
      proc_inh=$(awk '/^CapInh:/{print $2}' "$proc_status" 2>/dev/null)
      proc_prm=$(awk '/^CapPrm:/{print $2}' "$proc_status" 2>/dev/null)
      proc_eff=$(awk '/^CapEff:/{print $2}' "$proc_status" 2>/dev/null)
      proc_bnd=$(awk '/^CapBnd:/{print $2}' "$proc_status" 2>/dev/null)
      proc_amb=$(awk '/^CapAmb:/{print $2}' "$proc_status" 2>/dev/null)
      [ -z "$proc_eff" ] && continue
      if [ "$proc_eff" != "0000000000000000" ] || [ "$proc_amb" != "0000000000000000" ]; then
        echo "PID $proc_pid ($proc_name) user=$user_name"
        proc_inh_dec=$(capsh --decode=0x"$proc_inh" 2>/dev/null)
        proc_prm_dec=$(capsh --decode=0x"$proc_prm" 2>/dev/null)
        proc_eff_dec=$(capsh --decode=0x"$proc_eff" 2>/dev/null)
        proc_bnd_dec=$(capsh --decode=0x"$proc_bnd" 2>/dev/null)
        proc_amb_dec=$(capsh --decode=0x"$proc_amb" 2>/dev/null)
        echo "  CapInh: $proc_inh_dec" | sed -${E} "s,$capsB,${SED_RED},g"
        echo "  CapPrm: $proc_prm_dec" | sed -${E} "s,$capsB,${SED_RED},g"
        echo "  CapEff: $proc_eff_dec" | sed -${E} "s,$capsB,${SED_RED_YELLOW},g"
        echo "  CapBnd: $proc_bnd_dec" | sed -${E} "s,$capsB,${SED_RED},g"
        echo "  CapAmb: $proc_amb_dec" | sed -${E} "s,$capsB,${SED_RED_YELLOW},g"
        echo ""
      fi
    done | head -n 240
    echo ""
  else
    print_3title "Current shell capabilities" "T1548.001"
    (cat "/proc/$$/status" | grep Cap | sed -${E} "s,.*0000000000000000|CapBnd:	0000003fffffffff,${SED_GREEN},") 2>/dev/null || echo_not_found "/proc/$$/status"
    echo ""
    print_3title "Parent proc capabilities" "T1548.001"
    (cat "/proc/$PPID/status" | grep Cap | sed -${E} "s,.*0000000000000000|CapBnd:	0000003fffffffff,${SED_GREEN},") 2>/dev/null || echo_not_found "/proc/$PPID/status"
    echo ""
  fi
  echo ""
  echo "Files with capabilities (limited to 50):"
  binfmt_probe_count=0
  cap_inventory_count=0
  getcap -r / 2>/dev/null | head -n 51 | while read cb; do
    cap_inventory_count=$((cap_inventory_count + 1))
    if [ "$cap_inventory_count" -gt 50 ]; then
      echo "Capability inventory is partial: more than 50 files have capabilities."
      break
    fi
    capsVB_vuln=""
    # Match the executable basename exactly; broad capsVB patterns also match wrappers.
    case "$cb" in
      */gdb\ *cap_sys_ptrace*)
        echo "$cb" | sed -${E} "s,.*,${SED_RED_YELLOW},"
        continue
        ;;
    esac
    for capVB in $capsVB; do
      capname="$(echo $capVB | cut -d ':' -f 1)"
      capbins="$(echo $capVB | cut -d ':' -f 2)"
      if [ "$(echo $cb | grep -Ei $capname)" ] && [ "$(echo $cb | grep -E $capbins)" ]; then
        echo "$cb" | sed -${E} "s,.*,${SED_RED_YELLOW},"
        capsVB_vuln="1"
        break
      fi
    done
    if ! [ "$capsVB_vuln" ]; then
      echo "$cb" | sed -${E} "s,$capsB,${SED_RED},"
    fi
    # Reuse the capped getcap results. A helper that embeds the exact
    # registration path is only a static lead; never run it or read its input.
    cap_path=${cb%% *}
    cap_rights=${cb#* }
    cap_rights=${cap_rights#= }
    if [ "$binfmt_probe_count" -lt 8 ] && [ ! "$IAMROOT" ] && [ "$STRINGS" ] &&
       [ -f "$cap_path" ] && [ ! -L "$cap_path" ] &&
       [ -r "$cap_path" ] && [ -x "$cap_path" ] &&
       printf '%s\n' "$cap_rights" | grep -Eq '(^|[ ,])cap_dac_override(,cap_[a-z0-9_]+)*[+=][eip]*e[eip]*($|[[:space:]])'; then
      cap_size=$(stat -c %s "$cap_path" 2>/dev/null || stat -f %z "$cap_path" 2>/dev/null)
      case "$cap_size" in
        ''|*[!0-9]*) ;;
        *)
          if [ "$cap_size" -le 1048576 ]; then
            binfmt_probe_count=$((binfmt_probe_count + 1))
            if LC_ALL=C "$STRINGS" -a "$cap_path" 2>/dev/null | grep -Fxq '/proc/sys/fs/binfmt_misc/register'; then
              printf '  binfmt_misc helper review candidate: %s (file cap_dac_override effective flag and embedded register path; effective helper privilege, caller control, writable proc mount, kernel policy, interpreter access, and SUID transition unverified).\n' "$cap_path"
            fi
          fi
          ;;
      esac
    fi
    if ! [ "$IAMROOT" ] && [ -w "$(echo $cb | cut -d" " -f1)" ]; then
      echo "$cb is writable" | sed -${E} "s,.*,${SED_RED},"
    fi
  done
  echo ""
  checkSnapConfineCVE20268933
  checkSnapConfineCVE20263888
fi

fi

if check_mitre_filter "T1548.001"; then
if [ -f "/etc/security/capability.conf" ] || [ "$DEBUG" ] || grep -Rqs "pam_cap\.so" /etc/pam.d /etc/pam.conf 2>/dev/null; then
  print_2title "Users with capabilities" "T1548.001"
  print_info "https://book.hacktricks.wiki/en/linux-hardening/interesting-files-permissions/linux-capabilities.html"
  if [ -f "/etc/security/capability.conf" ]; then
    grep -v '^#\|none\|^$' /etc/security/capability.conf 2>/dev/null | sed -${E} "s,$sh_usrs,${SED_LIGHT_CYAN}," | sed -${E} "s,$nosh_usrs,${SED_BLUE}," | sed -${E} "s,$knw_usrs,${SED_GREEN}," | sed "s,$USER,${SED_RED}," | sed -${E} "s,$capsB,${SED_RED},g"
  else echo_not_found "/etc/security/capability.conf"
  fi
  echo ""
  print_info "Checking if PAM loads pam_cap.so"
  pam_cap_lines=$(grep -RIn "pam_cap\.so" /etc/pam.d /etc/pam.conf 2>/dev/null)
  if [ "$pam_cap_lines" ]; then
    printf "%s\n" "$pam_cap_lines" | sed -${E} "s,pam_cap\\.so,${SED_RED_YELLOW},g"
  else
    echo_not_found "pam_cap.so in /etc/pam.d or /etc/pam.conf"
  fi
  echo ""
fi

fi

if check_mitre_filter "T1574.006"; then
if ! [ "$SEARCH_IN_FOLDER" ] && ! [ "$IAMROOT" ]; then
  print_2title "Checking misconfigurations of ld.so" "T1574.006"
  print_info "https://book.hacktricks.wiki/en/linux-hardening/interesting-files-permissions/ld.so.conf-example.html"
  if [ -f "/etc/ld.so.conf" ] && [ -w "/etc/ld.so.conf" ]; then 
    echo "You have write privileges over /etc/ld.so.conf" | sed -${E} "s,.*,${SED_RED_YELLOW},"; 
    printf $RED$ITALIC"/etc/ld.so.conf\n"$NC;
  else
    printf $GREEN$ITALIC"/etc/ld.so.conf\n"$NC;
  fi
  echo "Content of /etc/ld.so.conf:"
  cat /etc/ld.so.conf 2>/dev/null | sed -${E} "s,$Wfolders,${SED_RED_YELLOW},g"
  # Check each configured folder and include directives
  cat /etc/ld.so.conf 2>/dev/null | while IFS= read -r l; do
    l=$(echo "$l" | sed 's/#.*$//' | xargs 2>/dev/null)
    [ -z "$l" ] && continue
    if echo "$l" | grep -qE '^include[[:space:]]+'; then
      ini_path=$(echo "$l" | cut -d " " -f 2)
      fpath=$(dirname "$ini_path")
      if [ -d "$fpath" ] && [ -w "$fpath" ]; then
        echo "You have write privileges over $fpath" | sed -${E} "s,.*,${SED_RED_YELLOW},";
        printf $RED_YELLOW$ITALIC"$fpath\n"$NC;
      else
        printf $GREEN$ITALIC"$fpath\n"$NC;
      fi
      ldso_writable_files=$(find "$fpath" -type f '(' '(' -user "$USER" ')' -or '(' -perm -o=w ')' -or '(' -perm -g=w -and '(' $wgroups ')' ')' ')' 2>/dev/null) || :
      if [ "$ldso_writable_files" ]; then
        echo "You have write privileges over $ldso_writable_files" | sed -${E} "s,.*,${SED_RED_YELLOW},";
      fi
      for f in $ini_path; do
        [ -f "$f" ] || continue
        if [ -w "$f" ]; then
          echo "You have write privileges over $f" | sed -${E} "s,.*,${SED_RED_YELLOW},";
          printf $RED_YELLOW$ITALIC"$f\n"$NC;
        else
          printf $GREEN$ITALIC"  $f\n"$NC;
        fi
        cat "$f" 2>/dev/null | grep -v "^#" | while IFS= read -r l2; do
          l2=$(echo "$l2" | xargs 2>/dev/null)
          [ -z "$l2" ] && continue
          if [ -d "$l2" ] && [ -w "$l2" ]; then
            echo "You have write privileges over $l2" | sed -${E} "s,.*,${SED_RED_YELLOW},";
            printf $RED_YELLOW$ITALIC"  - $l2\n"$NC;
          elif [ -d "$l2" ]; then
            echo $ITALIC"  - $l2"$NC | sed -${E} "s,$ldsoconfdG,${SED_GREEN},g" | sed -${E} "s,$Wfolders,${SED_RED_YELLOW},g";
          fi
        done
      done
    elif [ -d "$l" ] && [ -w "$l" ]; then
      echo "You have write privileges over $l" | sed -${E} "s,.*,${SED_RED_YELLOW},";
      printf $RED_YELLOW$ITALIC"$l\n"$NC;
    else
      echo $ITALIC"$l"$NC | sed -${E} "s,$ldsoconfdG,${SED_GREEN},g" | sed -${E} "s,$Wfolders,${SED_RED_YELLOW},g";
    fi
  done
  echo ""
  if [ -f "/etc/ld.so.preload" ] && [ -w "/etc/ld.so.preload" ]; then 
    echo "You have write privileges over /etc/ld.so.preload" | sed -${E} "s,.*,${SED_RED_YELLOW},"; 
  else
    printf $ITALIC$GREEN"/etc/ld.so.preload\n"$NC;
  fi
  cat /etc/ld.so.preload 2>/dev/null | sed -${E} "s,$Wfolders,${SED_RED_YELLOW},g"
  cat /etc/ld.so.preload 2>/dev/null | while read l; do
    if [ -f "$l" ] && [ -w "$l" ]; then echo "You have write privileges over $l" | sed -${E} "s,.*,${SED_RED_YELLOW},"; fi
  done
fi

fi

if check_mitre_filter "T1546.004"; then
check_global_venv_activation() {
  global_startup=$1
  [ -f "$global_startup" ] && [ -r "$global_startup" ] || return 0
  # Read only the first 64 KiB of each fixed startup file. Emit paths, never
  # source lines: a startup file may contain credentials alongside commands.
  dd if="$global_startup" bs=65536 count=1 2>/dev/null |
    awk '($1 == "source" || $1 == ".") && NF >= 2 {
      path = $2
      if (path ~ /^".*"$/ || path ~ /^\047.*\047$/)
        path = substr(path, 2, length(path) - 2)
      if (path ~ /^\/[[:alnum:]_.+\/-]+\/bin\/activate$/ && ++hits <= 8)
        print path
    }' |
    while IFS= read -r global_activation; do
      printf '  %s sources %s (review who runs this startup file and whether the target is writable)\n' "$global_startup" "$global_activation"
      ls -ld "$global_activation" 2>/dev/null || :
    done
}
if ! [ "$SEARCH_IN_FOLDER" ]; then
  print_2title "Files (scripts) in /etc/profile.d/" "T1546.004"
  print_info "https://book.hacktricks.wiki/en/linux-hardening/linux-basics/shell-startup-aliases-and-history.html#review-startup-and-history-files"
  if [ ! "$MACPEAS" ] && ! [ "$IAMROOT" ]; then #Those folders don´t exist on a MacOS
    (ls -la /etc/profile.d/ 2>/dev/null | sed -${E} "s,$profiledG,${SED_GREEN},") || echo_not_found "/etc/profile.d/"
    check_critial_root_path "/etc/profile"
    check_critial_root_path "/etc/profile.d/"
    for global_startup in /etc/profile /etc/bash.bashrc /etc/bashrc; do
      check_global_venv_activation "$global_startup"
    done
  fi
  echo ""
fi

fi

